def calculate_tax(state, income):
    """
    Calculate state tax based on the given state and income.

    Parameters:
        state (str): The US state abbreviation (e.g., 'CA', 'TX', 'NY').
        income (float): The taxable income.

    Returns:
        float: The calculated tax amount.
    """
    if income < 0:
        raise ValueError("Income cannot be negative.")

    state = state.strip().upper()

    if state == "CA":
        # California - progressive tax simplified
        if income <= 10000:
            tax = income * 0.01
        elif income <= 50000:
            tax = 10000 * 0.01 + (income - 10000) * 0.04
        elif income <= 100000:
            tax = 10000 * 0.01 + 40000 * 0.04 + (income - 50000) * 0.08
        else:
            tax = 10000 * 0.01 + 40000 * 0.04 + 50000 * 0.08 + (income - 100000) * 0.12

    elif state == "TX":
        # Texas has no state income tax
        tax = 0.0

    elif state == "NY":
        # New York - progressive tax simplified
        if income <= 8500:
            tax = income * 0.04
        elif income <= 11700:
            tax = 8500 * 0.04 + (income - 8500) * 0.045
        elif income <= 13900:
            tax = 8500 * 0.04 + 3200 * 0.045 + (income - 11700) * 0.0525
        else:
            tax = 8500 * 0.04 + 3200 * 0.045 + 2200 * 0.0525 + (income - 13900) * 0.059

    elif state == "FL":
        # Florida has no state income tax
        tax = 0.0

    elif state == "WA":
        # Washington has no state income tax
        tax = 0.0

    elif state == "IL":
        # Illinois - flat tax rate
        tax = income * 0.0495

    elif state == "PA":
        # Pennsylvania - flat tax rate
        tax = income * 0.0307

    elif state == "OH":
        # Ohio - progressive tax simplified
        if income <= 25000:
            tax = income * 0.02765
        elif income <= 44250:
            tax = 25000 * 0.02765 + (income - 25000) * 0.03226
        else:
            tax = 25000 * 0.02765 + 19250 * 0.03226 + (income - 44250) * 0.03688

    elif state == "GA":
        # Georgia - flat tax rate
        tax = income * 0.0549

    elif state == "NC":
        # North Carolina - flat tax rate
        tax = income * 0.045

    elif state == "MI":
        # Michigan - flat tax rate
        tax = income * 0.0425

    else:
        raise ValueError(f"Tax calculation rules not defined for state: {state}")

    return round(tax, 2)

