    VALIDATED = "VALIDATED"
    PRICED = "PRICED"
    PAID = "PAID"
    SHIPPED = "SHIPPED"
    CANCELLED = "CANCELLED"
    FAILED = "FAILED"


class OrderProcessingError(Exception):
    pass


class ValidationError(OrderProcessingError):
    pass


class InventoryError(OrderProcessingError):
    pass


class PaymentError(OrderProcessingError):
    pass


class ShippingError(OrderProcessingError):
    pass


class InventoryManager:
    def __init__(self, stock=None):
        # stock: dict of sku -> quantity available
        self.stock = stock if stock is not None else {}
        self._reservations = {}  # order_id -> dict(sku -> qty)

    def check_availability(self, items):
        for item in items:
            sku = item["sku"]
            qty = item["quantity"]
            available = self.stock.get(sku, 0)
            if available < qty:
                raise InventoryError(
                    f"Insufficient stock for SKU {sku}: requested {qty}, available {available}"
                )
        return True

    def reserve(self, order_id, items):
        self.check_availability(items)
        reserved = {}
        for item in items:
            sku = item["sku"]
            qty = item["quantity"]
            self.stock[sku] -= qty
            reserved[sku] = reserved.get(sku, 0) + qty
        self._reservations[order_id] = reserved
        return reserved

    def release(self, order_id):
        reserved = self._reservations.pop(order_id, None)
        if reserved:
            for sku, qty in reserved.items():
                self.stock[sku] = self.stock.get(sku, 0) + qty
        return reserved


class PaymentGateway:
    def __init__(self, decline_amount_over=None):
        self.decline_amount_over = decline_amount_over
        self.transactions = {}

    def charge(self, order_id, amount, payment_info):
        if amount <= 0:
            raise PaymentError("Charge amount must be positive.")
        if not payment_info or "card_number" not in payment_info:
            raise PaymentError("Invalid payment information.")
        if self.decline_amount_over is not None and amount > self.decline_amount_over:
            raise PaymentError(f"Payment declined for amount {amount}.")
        txn_id = str(uuid.uuid4())
        self.transactions[order_id] = {
            "txn_id": txn_id,
            "amount": amount,
            "status": "CHARGED",
        }
        return txn_id

    def refund(self, order_id):
        txn = self.transactions.get(order_id)
        if not txn:
            raise PaymentError(f"No transaction found for order {order_id}.")
        txn["status"] = "REFUNDED"
        return True


class ShippingService:
    def __init__(self):
        self.shipments = {}

    def create_shipment(self, order_id, address, items):
        if not address or "street" not in address or "city" not in address:
            raise ShippingError("Invalid shipping address.")
        tracking_number = f"TRK-{uuid.uuid4().hex[:10].upper()}"
        self.shipments[order_id] = {
