            "recipient": recipient,
            "subject": subject,
            "message": message,
            "timestamp": datetime.datetime.utcnow().isoformat(),
        }
        self.sent_notifications.append(notification)
        return notification


class OrderProcessor:
    def __init__(
        self,
        inventory_manager=None,
        payment_gateway=None,
        shipping_service=None,
        notification_service=None,
        tax_rate=0.0,
        shipping_flat_fee=0.0,
    ):
        self.inventory_manager = inventory_manager or InventoryManager()
        self.payment_gateway = payment_gateway or PaymentGateway()
        self.shipping_service = shipping_service or ShippingService()
        self.notification_service = notification_service or NotificationService()
        self.tax_rate = tax_rate
        self.shipping_flat_fee = shipping_flat_fee
        self.orders = {}

    def create_order(self, customer, items, payment_info, shipping_address):
        order_id = str(uuid.uuid4())
        order = {
            "order_id": order_id,
            "customer": customer,
            "items": items,
            "payment_info": payment_info,
            "shipping_address": shipping_address,
            "status": OrderStatus.PENDING,
            "created_at": datetime.datetime.utcnow().isoformat(),
            "subtotal": 0.0,
            "tax": 0.0,
            "shipping_fee": 0.0,
            "total": 0.0,
            "transaction_id": None,
            "tracking_number": None,
            "history": [],
        }
        self.orders[order_id] = order
        self._log(order, "Order created.")
        return order_id

    def _log(self, order, message):
        order["history"].append(
            {"timestamp": datetime.datetime.utcnow().isoformat(), "message": message}
        )

    def _get_order(self, order_id):
        order = self.orders.get(order_id)
        if not order:
            raise OrderProcessingError(f"Order {order_id} not found.")
        return order

    def validate_order(self, order_id):
        order = self._get_order(order_id)

        customer = order["customer"]
        if not customer or "email" not in customer or "name" not in customer:
            self._fail_order(order, "Invalid customer information.")
            raise ValidationError("Invalid customer information.")

        items = order["items"]
        if not items or not isinstance(items, list):
            self._fail_order(order, "Order must contain at least one item.")
            raise ValidationError("Order must contain at least one item.")

        for item in items:
            if "sku" not in item or "quantity" not in item or "price" not in item:
                self._fail_order(order, "Invalid item structure.")
                raise ValidationError("Each item must have sku, quantity, and price.")
            if item["quantity"] <= 0:
                self._fail_order(order, f"Invalid quantity for SKU {item['sku']}.")
                raise ValidationError(f"Quantity must be positive for SKU {item['sku']}.")
            if item["price"] < 0:
                self._fail_order(order, f"Invalid price for SKU {item['sku']}.")
                raise ValidationError(f"Price cannot be negative for SKU {item['sku']}.")

        address = order["shipping_address"]
        if not address or "street" not in address or "city" not in address:
            self._fail_order(order, "Invalid shipping address.")
            raise ValidationError("Invalid shipping address.")

        try:
            self.inventory_manager.check_availability(items)
        except InventoryError as e:
            self._fail_order(order, str(e))
            raise ValidationError(str(e))

        order["status"] = OrderStatus.VALIDATED
        self._log(order, "Order validated successfully.")
        return True

    def calculate_pricing(self, order_id):
        order = self._get_order(order_id)
        if order["status"] != OrderStatus.VALIDATED:
            raise OrderProcessingError("Order must be validated before pricing.")

        subtotal = sum(item["price"] * item["quantity"] for item in order["items"])
        tax = round(subtotal * self.tax_rate, 2)
        shipping_fee = self.shipping_flat_fee
        total = round(subtotal + tax + shipping_fee, 2)

        order["subtotal"] = round(subtotal, 2)
        order["tax"] = tax
        order["shipping_fee"] = shipping_fee
        order["total"] = total
        order["status"] = OrderStatus.PRICED

        self._log(order, f"Pricing calculated: subtotal={subtotal}, tax={tax}, total={total}.")
        return {
            "subtotal": order["subtotal"],
            "tax": order["tax"],
            "shipping_fee": order["shipping_fee"],
            "total": order["total"],
        }

    def process_payment(self, order_id):
        order = self._get_order(order_id)
        if order["status"] != OrderStatus.PRICED:
            raise OrderProcessingError("Order must be priced before payment processing.")

        try:
            self.inventory_manager.reserve(order_id, order["items"])
        except InventoryError as e:
            self._fail_order(order, str(e))
            raise

        try:
            txn_id = self.payment_gateway.charge(
                order_id, order["total"], order["payment_info"]
            )
        except PaymentError as e:
            self.inventory_manager.release(order_id)
            self._fail_order(order, str(e))
            raise

        order["transaction_id"] = txn_id
        order["status"] = OrderStatus.PAID
        self._log(order, f"Payment processed successfully. Transaction ID: {txn_id}.")

        self.notification_service.send(
            order["customer"]["email"],
            "Payment Confirmation",
            f"Your payment of {order['total']} for order {order_id} was successful.",
        )
        return txn_id

    def coordinate_shipping(self, order_id):
        order = self._get_order(order_id)
        if order["status"] != OrderStatus.PAID:
            raise OrderProcessingError("Order must be paid before shipping.")

        try:
            tracking_number = self.shipping_service.create_shipment(
                order_id, order["shipping_address"], order["items"]
            )
        except ShippingError as e:
            self._fail_order(order, str(e))
            raise

        order["tracking_number"] = tracking_number
        order["status"] = OrderStatus.SHIPPED
        self._log(order, f"Shipment created. Tracking number: {tracking_number}.")

        self.notification_service.send(
            order["customer"]["email"],
            "Order Shipped",
            f"Your order {order_id} has been shipped. Tracking number: {tracking_number}.",
        )
        return tracking_number

    def _fail_order(self, order, reason):
        order["status"] = OrderStatus.FAILED
        self._log(order, f"Order failed: {reason}")
        try:
            self.notification_service.send(
                order["customer"].get("email", "unknown"),
                "Order Failed",
                f"Your order {order['order_id']} could not be processed: {reason}",
            )
        except Exception:
            pass

    def cancel_order(self, order_id, reason="Cancelled by request"):
        order = self._get_order(order_id)
        if order["status"] in (OrderStatus.SHIPPED, OrderStatus.CANCELLED):
            raise OrderProcessingError(
                f"Cannot cancel order in status {order['status'].value}."
            )

