            "Order Cancelled",
            f"Your order {order_id} has been cancelled. Reason: {reason}",
        )
        return True

    def process_full_order(self, customer, items, payment_info, shipping_address):
        order_id = self.create_order(customer, items, payment_info, shipping_address)
        try:
            self.validate_order(order_id)
