                                trail=trail)

        decision = org.get_decision(ctx.permission)
        trail.append(f"organization '{org.name}': {decision.value}")
        if decision == Decision.DENY:
            return CheckResult(False, f"organization:{org.name}", trail)
        if decision == Decision.ALLOW:
            last_decision, last_decision_level = decision, f"organization:{org.name}"

        # --- Department level ---
        department: Optional[Department] = None
        if ctx.department_name:
            department = org.get_department(ctx.department_name)
            if department is None:
                trail.append(f"department '{ctx.department_name}' not found")
            else:
                decision = department.get_decision(ctx.permission)
                trail.append(f"department '{department.name}': {decision.value}")
                if decision == Decision.DENY:
                    return CheckResult(False, f"department:{department.name}", trail)
                if decision == Decision.ALLOW:
                    last_decision, last_decision_level = decision, f"department:{department.name}"

        # --- Team level ---
        team: Optional[Team] = None
        if department and ctx.team_name:
            team = department.get_team(ctx.team_name)
            if team is None:
                trail.append(f"team '{ctx.team_name}' not found")
            else:
                decision = team.get_decision(ctx.permission)
                trail.append(f"team '{team.name}': {decision.value}")
                if decision == Decision.DENY:
                    return CheckResult(False, f"team:{team.name}", trail)
                if decision == Decision.ALLOW:
                    last_decision, last_decision_level = decision, f"team:{team.name}"

        # --- Role level ---
        role: Optional[Role] = None
        if team and ctx.role_name:
            role = team.get_role(ctx.role_name)
            if role is None:
                trail.append(f"role '{ctx.role_name}' not found")
            else:
                decision = role.get_decision(ctx.permission)
                trail.append(f"role '{role.name}': {decision.value}")
                if decision == Decision.DENY:
                    return CheckResult(False, f"role:{role.name}", trail)
                if decision == Decision.ALLOW:
                    last_decision, last_decision_level = decision, f"role:{role.name}"

        # --- Specific permission level ---
        # This is the most granular override: a permission may itself be
        # keyed with a qualified name (e.g. "role:admin:can_edit") that
        # takes precedence over everything above if present on the role,
        # or checked directly against context if provided separately.
        specific_key = ctx.permission
        specific_decision = Decision.UNSET
        if role is not None:
            specific_decision = role.get_decision(f"specific:{specific_key}")
        elif team is not None:
            specific_decision = team.get_decision(f"specific:{specific_key}")
        elif department is not None:
            specific_decision = department.get_decision(f"specific:{specific_key}")
        else:
