            customer_data, key=lambda c: c.get("total_spent", 0), reverse=True
        )[:10]

        churn_risk = []
        today = datetime.now()
        for c in customer_data:
            last_purchase = c.get("last_purchase_date")
            if last_purchase:
                try:
                    if isinstance(last_purchase, str):
                        last_date = datetime.strptime(last_purchase, "%Y-%m-%d")
                    else:
                        last_date = last_purchase
                    days_since = (today - last_date).days
                    if days_since > 90:
                        churn_risk.append({
                            "customer_id": c.get("customer_id"),
                            "name": c.get("name"),
                            "days_since_last_purchase": days_since,
                        })
                except (ValueError, TypeError):
                    continue

        segments = {"high_value": 0, "medium_value": 0, "low_value": 0}
        for c in customer_data:
            spent = c.get("total_spent", 0)
            if spent >= avg_spent * 1.5:
                segments["high_value"] += 1
            elif spent >= avg_spent * 0.5:
                segments["medium_value"] += 1
            else:
                segments["low_value"] += 1

        report = {
            "report_type": "Customer Insights",
            "company": self.company_name,
            "generated_at": self._now(),
            "summary": {
                "total_customers": len(customer_data),
                "total_revenue": self._round(total_spent_all),
                "average_spend_per_customer": self._round(avg_spent),
                "median_spend_per_customer": self._round(median_spent),
                "average_orders_per_customer": self._round(avg_orders),
            },
            "customer_segments": segments,
            "top_customers": [
                {
                    "customer_id": c.get("customer_id"),
                    "name": c.get("name"),
                    "total_spent": self._round(c.get("total_spent", 0)),
                    "orders_count": c.get("orders_count", 0),
                }
                for c in top_customers
            ],
            "churn_risk_customers": churn_risk,
        }
        return self._register_report(report)

    # -------------------------------------------------------------------
    # Performance Dashboard
    # -------------------------------------------------------------------

    def generate_performance_dashboard(self, metrics_data, targets=None):
        """
        metrics_data: dict of metric_name -> value
        targets: dict of metric_name -> target_value (optional)
        """
        targets = targets or {}
        performance = {}

        for metric, value in metrics_data.items():
            target = targets.get(metric)
            entry = {"actual": self._round(value)}
            if target is not None:
                achievement = self._safe_div(value, target) * 100
                entry["target"] = self._round(target)
                entry["achievement_percent"] = self._round(achievement)
                if achievement >= 100:
                    entry["status"] = "On Target"
                elif achievement >= 80:
                    entry["status"] = "Near Target"
                else:
                    entry["status"] = "Below Target"
            performance[metric] = entry

        overall_scores = [
            v["achievement_percent"] for v in performance.values() if "achievement_percent" in v
        ]
        overall_score = self._round(statistics.mean(overall_scores)) if overall_scores else None

        report = {
            "report_type": "Performance Dashboard",
            "company": self.company_name,
            "generated_at": self._now(),
            "metrics": performance,
            "overall_performance_score": overall_score,
        }
        return self._register_report(report)

    # -------------------------------------------------------------------
    # Export Functionality
    # -------------------------------------------------------------------

    def export_to_json(self, report, filepath=None):
        json_str = json.dumps(report, indent=2, default=str)
        if filepath:
            with open(filepath, "w", encoding="utf-8") as f:
                f.write(json_str)
        return json_str

    def export_to_csv(self, report, filepath=None):
        output = io.StringIO()
        writer = csv.writer(output)

        flat_data = self._flatten_dict(report)
        writer.writerow(["Field", "Value"])
        for key, value in flat_data.items():
            writer.writerow([key, value])

        csv_str = output.getvalue()
        if filepath:
            with open(filepath, "w", newline="", encoding="utf-8") as f:
                f.write(csv_str)
        return csv_str

    def export_to_text(self, report, filepath=None):
        lines = []
        lines.append("=" * 60)
        lines.append(f"{report.get('report_type', 'Report')} - {self.company_name}")
        lines.append(f"Generated: {report.get('generated_at', self._now())}")
        lines.append("=" * 60)

        def render(data, indent=0):
            prefix = "  " * indent
            if isinstance(data, dict):
                for key, value in data.items():
                    if isinstance(value, (dict, list)):
                        lines.append(f"{prefix}{key}:")
                        render(value, indent + 1)
                    else:
                        lines.append(f"{prefix}{key}: {value}")
            elif isinstance(data, list):
                for item in data:
                    if isinstance(item, dict):
                        render(item, indent)
                        lines.append(f"{prefix}" + "-" * 20)
                    else:
                        lines.append(f"{prefix}- {item}")

        render({k: v for k, v in report.items() if k not in ("report_type", "generated_at")})

        text_str = "\n".join(lines)
        if filepath:
            with open(filepath, "w", encoding="utf-8") as f:
                f.write(text_str)
        return text_str

    def _flatten_dict(self, d, parent_key="", sep="."):
        items = {}
        if isinstance(d, dict):
            for k, v in d.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else str(k)
                if isinstance(v, (dict, list)):
                    items.update(self._flatten_dict(v, new_key, sep))
                else:
                    items[new_key] = v
        elif isinstance(d, list):
            for i, v in enumerate(d):
                new_key = f"{parent_key}[{i}]"
                if isinstance(v, (dict, list)):
                    items.update(self._flatten_dict(v, new_key, sep))
                else:
                    items[new_key] = v
        return items

    # -------------------------------------------------------------------
    # Report History
    # -------------------------------------------------------------------

    def get_report_history(self):
        return self.generated_reports

    def clear_report_history(self):
        self.generated_reports = []
