class Policy:
    VALID_STATUSES = {"active", "pending", "cancelled", "expired", "lapsed"}

    def __init__(self, policy_number, effective_date, expiration_date, premium,
                 coverage_limits=None, deductibles=None, status="pending",
                 policyholder_info=None):
        self.policy_number = str(policy_number)
        self.effective_date = self._validate_date(effective_date, "effective_date")
        self.expiration_date = self._validate_date(expiration_date, "expiration_date")

        if self._to_datetime(self.expiration_date) <= self._to_datetime(self.effective_date):
            raise ValueError("expiration_date must be after effective_date")

        self.premium = self._validate_float(premium, "premium", non_negative=True)

        self.coverage_limits = self._validate_dict_of_floats(
            coverage_limits or {}, "coverage_limits"
        )
        self.deductibles = self._validate_dict_of_floats(
            deductibles or {}, "deductibles"
        )

        self.status = self._validate_status(status)

        self.policyholder_info = self._validate_nested_string_dict(
            policyholder_info or {}, "policyholder_info"
        )

    @staticmethod
    def _to_datetime(date_str):
        return datetime.strptime(date_str, "%Y-%m-%d")

    def _validate_date(self, date_str, field_name):
        if not isinstance(date_str, str):
            raise TypeError(f"{field_name} must be a string")
        try:
            self._to_datetime(date_str)
        except ValueError:
            raise ValueError(f"{field_name} must be in YYYY-MM-DD format")
        return date_str

    @staticmethod
    def _validate_float(value, field_name, non_negative=False):
        try:
            value = float(value)
        except (TypeError, ValueError):
            raise TypeError(f"{field_name} must be a float")
