            order_id = f"order_{uuid.uuid4().hex[:12]}"
            order = OrderResult(
                order_id=order_id,
                status="confirmed",
                items=cart_items,
                subtotal=subtotal,
                shipping_cost=shipping_cost,
                tax_amount=tax_amount,
                total_amount=total_amount,
                payment_transaction_id=transaction_id,
                reservation_id=reservation_id,
                created_at=datetime.utcnow().isoformat(),
                customer_email=customer_email,
                metadata={"country": shipping_address.country},
            )
            order_repository.save(order)
            inventory_service.confirm(reservation_id)
        except Exception as e:
            payment_processor.refund(transaction_id, total_amount)
            inventory_service.release(reservation_id)
            raise CheckoutError(f"Order creation failed: {str(e)}", code="ORDER_CREATION_FAILED")

        # 8. Email notification (non-fatal on failure)
        try:
            email_service.send_order_confirmation(customer_email, order)
        except Exception as e:
            logger.warning(f"Failed to send confirmation email for order {order_id}: {e}")

        # 9. Analytics tracking (non-fatal on failure)
        try:
            analytics_tracker.track_event(
                "order_completed",
                {
                    "order_id": order_id,
                    "customer_email": customer_email,
                    "total_amount": total_amount,
                    "item_count": sum(i.quantity for i in cart_items),
                    "country": shipping_address.country,
                    "timestamp": time.time(),
                },
            )
        except Exception as e:
            logger.warning(f"Failed to track analytics for order {order_id}: {e}")

        return order

    except CheckoutError:
        raise
    except Exception as e:
        raise CheckoutError(f"Unexpected checkout failure: {str(e)}", code="UNKNOWN_ERROR")

