class OrderRepository:
    def __init__(self):
        self._orders: Dict[str, OrderResult] = {}

    def save(self, order: OrderResult) -> None:
        self._orders[order.order_id] = order

    def get(self, order_id: str) -> Optional[OrderResult]:
        return self._orders.get(order_id)


def validate_cart(items: List[CartItem]) -> float:
    if not items:
        raise CartValidationError("Cart is empty.")

    subtotal = 0.0
    for item in items:
        if item.quantity <= 0:
            raise CartValidationError(f"Invalid quantity for product '{item.product_id}'.")
        if item.unit_price < 0:
            raise CartValidationError(f"Invalid price for product '{item.product_id}'.")
        subtotal += item.unit_price * item.quantity

    return round(subtotal, 2)


def process_checkout(
    cart_items: List[CartItem],
    shipping_address: Address,
    payment_info: Dict[str, Any],
    customer_email: str,
    inventory_service: InventoryService,
    shipping_calculator: Optional[ShippingCalculator] = None,
    tax_calculator: Optional[TaxCalculator] = None,
    payment_processor: Optional[PaymentProcessor] = None,
    email_service: Optional[EmailService] = None,
    analytics_tracker: Optional[AnalyticsTracker] = None,
    order_repository: Optional[OrderRepository] = None,
) -> OrderResult:
    """
    Orchestrates the full e-commerce checkout flow:
    cart validation -> inventory reservation -> shipping calc ->
    tax calc -> payment processing -> order creation -> email -> analytics.

    Rolls back inventory reservation and refunds payment on failure where applicable.
    """
    shipping_calculator = shipping_calculator or ShippingCalculator()
    tax_calculator = tax_calculator or TaxCalculator()
    payment_processor = payment_processor or PaymentProcessor()
    email_service = email_service or EmailService()
    analytics_tracker = analytics_tracker or AnalyticsTracker()
    order_repository = order_repository or OrderRepository()

    reservation_id = None
    transaction_id = None

    try:
        # 1. Cart validation
        subtotal = validate_cart(cart_items)

        # 2. Inventory reservation
        reservation_id = inventory_service.reserve(cart_items)

        # 3. Shipping calculation
        shipping_cost = shipping_calculator.calculate(cart_items, subtotal, shipping_address)

        # 4. Tax computation
        tax_amount = tax_calculator.calculate(subtotal, shipping_cost, shipping_address)

        # 5. Compute total
        total_amount = round(subtotal + shipping_cost + tax_amount, 2)

        # 6. Payment processing
        try:
            transaction_id = payment_processor.charge(payment_info, total_amount)
        except PaymentError:
            inventory_service.release(reservation_id)
            raise

        # 7. Order creation
        try:
            order_id = f"order_{uuid.uuid4().hex[:12]}"
            order = OrderResult(
                order_id=order_id,
                status="confirmed",
                items=cart_items,
                subtotal=subtotal,
                shipping_cost=shipping_cost,
                tax_amount=tax_amount,
                total_amount=total_amount,
                payment_transaction_id=transaction_id,
                reservation_id=reservation_id,
                created_at=datetime.utcnow().isoformat(),
                customer_email=customer_email,
                metadata={"country": shipping_address.country},
            )
            order_repository.save(order)
            inventory_service.confirm(reservation_id)
        except Exception as e:
            payment_processor.refund(transaction_id, total_amount)
            inventory_service.release(reservation_id)
            raise CheckoutError(f"Order creation failed: {str(e)}", code="ORDER_CREATION_FAILED")

        # 8. Email notification (non-fatal on failure)
        try:
            email_service.send_order_confirmation(customer_email, order)
        except Exception as e:
            logger.warning(f"Failed to send confirmation email for order {order_id}: {e}")

        # 9. Analytics tracking (non-fatal on failure)
        try:
            analytics_tracker.track_event(
                "order_completed",
                {
                    "order_id": order_id,
                    "customer_email": customer_email,
                    "total_amount": total_amount,
                    "item_count": sum(i.quantity for i in cart_items),
                    "country": shipping_address.country,
                    "timestamp": time.time(),
                },
            )
        except Exception as e:
            logger.warning(f"Failed to track analytics for order {order_id}: {e}")

        return order

    except CheckoutError:
        raise
    except Exception as e:
        raise CheckoutError(f"Unexpected checkout failure: {str(e)}", code="UNKNOWN_ERROR")
