    def check_eligibility(self, patient: Patient, claim: Claim) -> (bool, Optional[str]):
        if not patient.is_active_member:
            return False, "Patient membership is inactive"

        if patient.insurance_type == InsuranceType.PRIVATE:
            return self._check_private(patient, claim)
        elif patient.insurance_type == InsuranceType.MEDICARE:
