        for service in claim.services:
            if service.requires_preauth and not claim.preauth_obtained:
                return False, f"Preauthorization required for {service.code}"
        return True, None

    def _check_medicare(self, patient: Patient, claim: Claim) -> (bool, Optional[str]):
        age = self._calculate_age(patient.date_of_birth, claim.date_of_service)
        if age < 65:
            return False, "Patient does not meet Medicare age requirement"
        return True, None

    def _check_medicaid(self, patient: Patient, claim: Claim) -> (bool, Optional[str]):
        # Medicaid generally covers all in-network services without preauth
        return True, None

    def _check_hmo(self, patient: Patient, claim: Claim) -> (bool, Optional[str]):
        if Coverage.requires_referral(patient.insurance_type) and not patient.referral_on_file:
            return False, "HMO requires referral on file"
        return True, None

    def _check_ppo(self, patient: Patient, claim: Claim) -> (bool, Optional[str]):
        for service in claim.services:
            if service.requires_preauth and not claim.preauth_obtained:
                return False, f"Preauthorization required for {service.code}"
        return True, None

    @staticmethod
    def _calculate_age(dob: date, as_of: date) -> int:
        years = as_of.year - dob.year
        if (as_of.month, as_of.day) < (dob.month, dob.day):
            years -= 1
        return years


# ---------------------------------------------------------------------------
# Claim Processor
# ---------------------------------------------------------------------------

class ClaimProcessor:
    """
    Processes claims according to insurance-type-specific approval logic.
    New insurance types require a new branch/handler here.
    """

    def __init__(self, eligibility_checker: EligibilityChecker):
        self.eligibility_checker = eligibility_checker

    def process_claim(self, claim: Claim) -> Claim:
        eligible, reason = self.eligibility_checker.check_eligibility(claim.patient, claim)
        if not eligible:
            claim.status = ClaimStatus.DENIED
            claim.denied_reason = reason
            claim.approved_amount = 0.0
            return claim

        insurance_type = claim.patient.insurance_type
        if insurance_type == InsuranceType.PRIVATE:
            return self._process_private(claim)
        elif insurance_type == InsuranceType.MEDICARE:
            return self._process_medicare(claim)
        elif insurance_type == InsuranceType.MEDICAID:
            return self._process_medicaid(claim)
        elif insurance_type == InsuranceType.HMO:
            return self._process_hmo(claim)
        elif insurance_type == InsuranceType.PPO:
            return self._process_ppo(claim)
        else:
            claim.status = ClaimStatus.DENIED
            claim.denied_reason = f"Unsupported insurance type: {insurance_type}"
            return claim

    def _total_service_amount(self, claim: Claim) -> float:
        return sum(s.amount for s in claim.services)

    def _process_private(self, claim: Claim) -> Claim:
        total = self._total_service_amount(claim)
        claim.approved_amount = total
        claim.status = ClaimStatus.APPROVED
        return claim

    def _process_medicare(self, claim: Claim) -> Claim:
        total = self._total_service_amount(claim)
        claim.approved_amount = total
        claim.status = ClaimStatus.APPROVED
        return claim

    def _process_medicaid(self, claim: Claim) -> Claim:
        total = self._total_service_amount(claim)
        claim.approved_amount = total
        claim.status = ClaimStatus.APPROVED
        return claim

    def _process_hmo(self, claim: Claim) -> Claim:
        approved_total = 0.0
        any_denied = False
        for service in claim.services:
            if service.requires_preauth and not claim.preauth_obtained:
                any_denied = True
                continue
            approved_total += service.amount

        claim.approved_amount = approved_total
        if approved_total == 0:
            claim.status = ClaimStatus.DENIED
            claim.denied_reason = "No services approved under HMO rules"
        elif any_denied:
            claim.status = ClaimStatus.PARTIALLY_APPROVED
        else:
            claim.status = ClaimStatus.APPROVED
        return claim

    def _process_ppo(self, claim: Claim) -> Claim:
        total = self._total_service_amount(claim)
        claim.approved_amount = total
        claim.status = ClaimStatus.APPROVED
        return claim


# ---------------------------------------------------------------------------
# Billing Calculator
# ---------------------------------------------------------------------------

class BillingCalculator:
    """
    Calculates patient responsibility (out-of-pocket cost) based on
    insurance-type-specific copay/coinsurance/deductible rules.
    """

    def calculate_patient_responsibility(self, claim: Claim) -> float:
        insurance_type = claim.patient.insurance_type

        if insurance_type == InsuranceType.PRIVATE:
            return self._calc_private(claim)
        elif insurance_type == InsuranceType.MEDICARE:
            return self._calc_medicare(claim)
        elif insurance_type == InsuranceType.MEDICAID:
            return self._calc_medicaid(claim)
        elif insurance_type == InsuranceType.HMO:
            return self._calc_hmo(claim)
        elif insurance_type == InsuranceType.PPO:
            return self._calc_ppo(claim)
        else:
            raise ValueError(f"Unsupported insurance type: {insurance_type}")

    def _preventive_adjusted_total(self, claim: Claim) -> float:
        covers_full = Coverage.covers_preventive_full(claim.patient.insurance_type)
        total = 0.0
        for service in claim.services:
            if service.is_preventive and covers_full:
                continue
            total += service.amount
        return total

    def _calc_private(self, claim: Claim) -> float:
        rules = Coverage.get_rules(claim.patient.insurance_type)
        billable = self._preventive_adjusted_total(claim)
        after_deductible = max(0.0, billable - rules["deductible"])
        coinsurance_owed = after_deductible * rules["coinsurance"]
        return rules["copay"] + coinsurance_owed

    def _calc_medicare(self, claim: Claim) -> float:
        rules = Coverage.get_rules(claim.patient.insurance_type)
        billable = self._preventive_adjusted_total(claim)
        after_deductible = max(0.0, billable - rules["deductible"])
        coinsurance_owed = after_deductible * rules["coinsurance"]
        return rules["copay"] + coinsurance_owed

    def _calc_medicaid(self, claim: Claim) -> float:
        # Medicaid patients typically owe nothing
        return 0.0

    def _calc_hmo(self, claim: Claim) -> float:
        rules = Coverage.get_rules(claim.patient.insurance_type)
        if claim.approved_amount == 0:
            return 0.0
        return rules["copay"]

    def _calc_ppo(self, claim: Claim) -> float:
        rules = Coverage.get_rules(claim.patient.insurance_type)
        billable = self._preventive_adjusted_total(claim)
        after_deductible = max(0.0, billable - rules["deductible"])
        coinsurance_owed = after_deductible * rules["coinsurance"]
        return rules["copay"] + coinsurance_owed


# ---------------------------------------------------------------------------
# Statement Generator
# ---------------------------------------------------------------------------

class StatementGenerator:
    """
    Generates patient-facing billing statements. Presentation/wording
    differs by insurance type, so new types require a new formatting
    branch here as well.
    """

    def __init__(self, billing_calculator: BillingCalculator):
        self.billing_calculator = billing_calculator

    def generate_statement(self, claim: Claim) -> str:
        insurance_type = claim.patient.insurance_type
        responsibility = self.billing_calculator.calculate_patient_responsibility(claim)

        if insurance_type == InsuranceType.PRIVATE:
            return self._statement_private(claim, responsibility)
        elif insurance_type == InsuranceType.MEDICARE:
            return self._statement_medicare(claim, responsibility)
        elif insurance_type == InsuranceType.MEDICAID:
            return self._statement_medicaid(claim, responsibility)
        elif insurance_type == InsuranceType.HMO:
            return self._statement_hmo(claim, responsibility)
        elif insurance_type == InsuranceType.PPO:
            return self._statement_ppo(claim, responsibility)
        else:
            raise ValueError(f"Unsupported insurance type: {insurance_type}")

    def _header(self, claim: Claim) -> str:
        return (
            f"Statement for Claim {claim.claim_id}\n"
            f"Patient: {claim.patient.name}\n"
            f"Date of Service: {claim.date_of_service}\n"
            f"Status: {claim.status.value}\n"
        )

    def _statement_private(self, claim: Claim, responsibility: float) -> str:
        return (
            self._header(claim)
            + f"Insurance Type: Private\n"
            + f"Approved Amount: ${claim.approved_amount:.2f}\n"
            + f"Patient Responsibility: ${responsibility:.2f}\n"
        )

    def _statement_medicare(self, claim: Claim, responsibility: float) -> str:
        return (
            self._header(claim)
            + f"Insurance Type: Medicare\n"
            + f"Approved Amount: ${claim.approved_amount:.2f}\n"
            + f"Medicare Patient Responsibility: ${responsibility:.2f}\n"
        )

    def _statement_medicaid(self, claim: Claim, responsibility: float) -> str:
        return (
            self._header(claim)
            + f"Insurance Type: Medicaid\n"
            + f"Approved Amount: ${claim.approved_amount:.2f}\n"
            + f"Patient Responsibility: $0.00 (Medicaid covers full cost)\n"
        )

    def _statement_hmo(self, claim: Claim, responsibility: float) -> str:
        return (
            self._header(claim)
            + f"Insurance Type: HMO\n"
            + f"Approved Amount: ${claim.approved_amount:.2f}\n"
            + f"Copay Due: ${responsibility:.2f}\n"
        )

    def _statement_ppo(self, claim: Claim, responsibility: float) -> str:
        return (
            self._header(claim)
            + f"Insurance Type: PPO\n"
            + f"Approved Amount: ${claim.approved_amount:.2f}\n"
            + f"Patient Responsibility: ${responsibility:.2f}\n"
        )


# ---------------------------------------------------------------------------
# Report Classes
# ---------------------------------------------------------------------------

class ClaimsSummaryReport:
    """
    Aggregates claim counts and totals by insurance type. Must be updated
    with new insurance type buckets when a type is added.
    """

    def generate(self, claims: List[Claim]) -> Dict[str, Dict]:
        summary = {
            InsuranceType.PRIVATE.value: {"count": 0, "total_approved": 0.0},
            InsuranceType.MEDICARE.value: {"count": 0, "total_approved": 0.0},
            InsuranceType.MEDICAID.value: {"count": 0, "total_approved": 0.0},
            InsuranceType.HMO.value: {"count": 0, "total_approved": 0.0},
            InsuranceType.PPO.value: {"count": 0, "total_approved": 0.0},
        }

        for claim in claims:
            key = claim.patient.insurance_type.value
            if key not in summary:
                raise ValueError(f"Report not configured for insurance type: {key}")
            summary[key]["count"] += 1
            summary[key]["total_approved"] += claim.approved_amount

        return summary


class DenialRateReport:
    """
    Computes denial rates per insurance type. Requires updates for new
    insurance types to include them in the breakdown.
    """

    def generate(self, claims: List[Claim]) -> Dict[str, float]:
        totals: Dict[str, int] = {t.value: 0 for t in InsuranceType}
        denials: Dict[str, int] = {t.value: 0 for t in InsuranceType}

        for claim in claims:
            key = claim.patient.insurance_type.value
            totals[key] += 1
            if claim.status == ClaimStatus.DENIED:
                denials[key] += 1

        rates = {}
        for insurance_value in totals:
            if totals[insurance_value] == 0:
                rates[insurance_value] = 0.0
            else:
                rates[insurance_value] = denials[insurance_value] / totals[insurance_value]
        return rates


class RevenueByInsuranceReport:
    """
    Reports total patient-collected revenue broken down by insurance type.
    New insurance types must be added to the initial breakdown dict.
    """

    def __init__(self, billing_calculator: BillingCalculator):
        self.billing_calculator = billing_calculator

    def generate(self, claims: List[Claim]) -> Dict[str, float]:
        revenue = {
            InsuranceType.PRIVATE.value: 0.0,
            InsuranceType.MEDICARE.value: 0.0,
            InsuranceType.MEDICAID.value: 0.0,
            InsuranceType.HMO.value: 0.0,
            InsuranceType.PPO.value: 0.0,
        }

        for claim in claims:
            key = claim.patient.insurance_type.value
            if key not in revenue:
                raise ValueError(f"Report not configured for insurance type: {key}")
            responsibility = self.billing_calculator.calculate_patient_responsibility(claim)
            revenue[key] += responsibility

        return revenue


