    def _get_internal_shipment(self, tracking_number):
        shipment = self._shipments.get(tracking_number)
        if shipment is None:
            raise ShipmentNotFoundError(
                f"Shipment '{tracking_number}' not found."
            )
        return shipment

    @staticmethod
    def _copy_shipment(shipment):
        return {
