                    count = 0
                    for row in reader:
                        row["_source_file"] = os.path.basename(path)
                        all_records.append(row)
                        count += 1
                    logger.info(f"Extracted {count} records from {path}")
            except Exception as e:
                logger.error(f"Failed to read {path}: {e}")

        self.raw_records = all_records
        logger.info(f"Total extracted records: {len(self.raw_records)}")
        return self.raw_records

    # ---------------------------------------------------------------
    # CLEAN / NORMALIZE
    # ---------------------------------------------------------------
    def _normalize_key(self, key):
        return key.strip().lower().replace(" ", "_") if key else key

    def _clean_string(self, value):
        if value is None:
            return None
        value = str(value).strip()
        value = re.sub(r"\s+", " ", value)
        return value if value != "" else None

    def _try_cast(self, value, target_type):
        if value is None:
            return None
        try:
            if target_type == int:
                return int(float(value))
            if target_type == float:
                return float(value)
            if target_type == bool:
                if isinstance(value, bool):
                    return value
                val_str = str(value).strip().lower()
                if val_str in ("true", "1", "yes", "y"):
                    return True
                if val_str in ("false", "0", "no", "n"):
                    return False
                return None
            if target_type == datetime:
                for fmt in ("%Y-%m-%d", "%Y-%m-%d %H:%M:%S", "%m/%d/%Y", "%d-%m-%Y"):
                    try:
                        return datetime.strptime(str(value), fmt)
                    except ValueError:
                        continue
                return None
            if target_type == str:
                return self._clean_string(value)
        except (ValueError, TypeError):
            return None
        return value

    def clean(self):
        """Clean raw records: normalize keys, strip whitespace, cast types."""
        cleaned = []
        for record in self.raw_records:
            new_record = {}
            for key, value in record.items():
                norm_key = self._normalize_key(key)
                if norm_key in self.schema:
                    target_type = self.schema[norm_key].get("type", str)
                    cleaned_val = self._clean_string(value) if isinstance(value, str) else value
                    new_record[norm_key] = self._try_cast(cleaned_val, target_type)
                else:
                    new_record[norm_key] = self._clean_string(value) if isinstance(value, str) else value

            for field in self.schema:
                if field not in new_record:
                    new_record[field] = None

            cleaned.append(new_record)

        self.clean_records = cleaned
        logger.info(f"Cleaned {len(self.clean_records)} records")
        return self.clean_records

    # ---------------------------------------------------------------
    # HANDLE MISSING VALUES
    # ---------------------------------------------------------------
    def handle_missing_values(self):
        """Fill or drop missing values based on the configured strategy."""
        if not self.clean_records:
            return self.clean_records

        numeric_fields = [
            f for f, spec in self.schema.items()
            if spec.get("type") in (int, float)
        ]

        fill_values = {}
        if self.missing_value_strategy in ("mean", "median", "mode"):
            for field in numeric_fields:
                values = [
                    r[field] for r in self.clean_records
                    if r.get(field) is not None
                ]
                if not values:
                    continue
                if self.missing_value_strategy == "mean":
                    fill_values[field] = statistics.mean(values)
                elif self.missing_value_strategy == "median":
                    fill_values[field] = statistics.median(values)
                elif self.missing_value_strategy == "mode":
                    try:
                        fill_values[field] = statistics.mode(values)
                    except statistics.StatisticsError:
                        fill_values[field] = values[0]

        result = []
        for record in self.clean_records:
            drop_record = False
            for field, spec in self.schema.items():
                value = record.get(field)
                if value is None:
                    if "default" in spec:
                        record[field] = spec["default"]
                    elif self.missing_value_strategy == "drop":
                        if spec.get("required", False):
                            drop_record = True
                            break
                    elif field in fill_values:
                        record[field] = fill_values[field]
                    elif self.missing_value_strategy not in ("mean", "median", "mode", "drop"):
                        record[field] = self.missing_value_strategy
                    else:
                        if spec.get("type") == str:
                            record[field] = "unknown"
                        elif spec.get("type") in (int, float):
                            record[field] = 0
                        elif spec.get("type") == bool:
                            record[field] = False
                        else:
                            record[field] = None
            if not drop_record:
                result.append(record)

        dropped_count = len(self.clean_records) - len(result)
        if dropped_count:
            logger.info(f"Dropped {dropped_count} records due to missing required fields")

        self.clean_records = result
        return self.clean_records

    # ---------------------------------------------------------------
    # VALIDATE
    # ---------------------------------------------------------------
    def validate(self):
        """Validate cleaned records against the schema."""
        valid, invalid = [], []
        for record in self.clean_records:
            errors = []
            for field, spec in self.schema.items():
                value = record.get(field)
                required = spec.get("required", False)
                expected_type = spec.get("type", str)

                if value is None:
                    if required:
                        errors.append(f"Missing required field: {field}")
                    continue

                if expected_type == int and not isinstance(value, int):
                    errors.append(f"Field {field} expected int, got {type(value).__name__}")
                elif expected_type == float and not isinstance(value, (int, float)):
                    errors.append(f"Field {field} expected float, got {type(value).__name__}")
                elif expected_type == bool and not isinstance(value, bool):
                    errors.append(f"Field {field} expected bool, got {type(value).__name__}")
                elif expected_type == str and not isinstance(value, str):
                    errors.append(f"Field {field} expected str, got {type(value).__name__}")
                elif expected_type == datetime and not isinstance(value, datetime):
                    errors.append(f"Field {field} expected datetime, got {type(value).__name__}")

                if "min" in spec and isinstance(value, (int, float)) and value < spec["min"]:
                    errors.append(f"Field {field} value {value} below minimum {spec['min']}")
                if "max" in spec and isinstance(value, (int, float)) and value > spec["max"]:
                    errors.append(f"Field {field} value {value} above maximum {spec['max']}")
                if "allowed_values" in spec and value not in spec["allowed_values"]:
                    errors.append(f"Field {field} value {value} not in allowed values")

            if errors:
                invalid.append({"record": record, "errors": errors})
            else:
                valid.append(record)

        self.valid_records = valid
        self.invalid_records = invalid
        logger.info(f"Validation complete: {len(valid)} valid, {len(invalid)} invalid")
        return self.valid_records, self.invalid_records

    # ---------------------------------------------------------------
    # AGGREGATE
    # ---------------------------------------------------------------
    def aggregate(self, group_by=None, agg_fields=None):
        """
        Perform aggregation on valid records.
        group_by: list of field names to group by
        agg_fields: dict of {field_name: [list of agg functions]} e.g. {"amount": ["sum", "mean"]}
        """
        if not self.valid_records:
            self.aggregates = {}
            return self.aggregates

        group_by = group_by or []
        agg_fields = agg_fields or {}

        groups = defaultdict(list)
        for record in self.valid_records:
            key = tuple(record.get(field) for field in group_by) if group_by else ("all",)
            groups[key].append(record)

        results = {}
        for key, records in groups.items():
            group_result = {}
            if group_by:
                group_result["group"] = dict(zip(group_by, key))
            group_result["count"] = len(records)

            for field, funcs in agg_fields.items():
                values = [r[field] for r in records if isinstance(r.get(field), (int, float))]
                field_result = {}
                for func in funcs:
                    if not values:
                        field_result[func] = None
                        continue
                    if func == "sum":
                        field_result[func] = sum(values)
                    elif func == "mean":
                        field_result[func] = statistics.mean(values)
                    elif func == "median":
                        field_result[func] = statistics.median(values)
                    elif func == "min":
                        field_result[func] = min(values)
                    elif func == "max":
                        field_result[func] = max(values)
                    elif func == "stdev":
                        field_result[func] = statistics.stdev(values) if len(values) > 1 else 0.0
                    elif func == "count":
                        field_result[func] = len(values)
                group_result[field] = field_result

            results[key] = group_result

        self.aggregates = results
        logger.info(f"Aggregation produced {len(results)} groups")
        return self.aggregates

    # ---------------------------------------------------------------
    # TRANSFORM
    # ---------------------------------------------------------------
    def transform(self, field_mapping=None, computed_fields=None):
        """
        Transform valid records into the target format.
        field_mapping: dict of {source_field: target_field}
        computed_fields: dict of {target_field: callable(record) -> value}
        """
        field_mapping = field_mapping or {}
        computed_fields = computed_fields or {}

        transformed = []
        for record in self.valid_records:
            new_record = {}
            for src_field, value in record.items():
                target_field = field_mapping.get(src_field, src_field)
                if isinstance(value, datetime):
                    new_record[target_field] = value.isoformat()
                else:
                    new_record[target_field] = value

            for target_field, func in computed_fields.items():
                try:
                    new_record[target_field] = func(record)
                except Exception as e:
                    logger.warning(f"Computed field '{target_field}' failed: {e}")
                    new_record[target_field] = None

            transformed.append(new_record)

        self.transformed_records = transformed
        logger.info(f"Transformed {len(transformed)} records")
        return self.transformed_records

    # ---------------------------------------------------------------
    # LOAD
    # ---------------------------------------------------------------
    def load(self, table_name="etl_data", if_exists="replace"):
        """Load transformed records into a SQLite database."""
        if not self.transformed_records:
            logger.warning("No transformed records to load")
            return

        conn = sqlite3.connect(self.db_path)
        cursor = conn.cursor()

        columns = set()
        for record in self.transformed_records:
            columns.update(record.keys())
        columns = sorted(columns)

        def infer_sql_type(field):
            for record in self.transformed_records:
                if record.get(field) is not None:
                    val = record[field]
                    if isinstance(val, bool):
                        return "INTEGER"
                    if isinstance(val, int):
                        return "INTEGER"
                    if isinstance(val, float):
                        return "REAL"
                    return "TEXT"
            return "TEXT"

        col_defs = ", ".join(f'"{col}" {infer_sql_type(col)}' for col in columns)

        if if_exists == "replace":
            cursor.execute(f'DROP TABLE IF EXISTS "{table_name}"')

        cursor.execute(f'CREATE TABLE IF NOT EXISTS "{table_name}" ({col_defs})')

        placeholders = ", ".join("?" for _ in columns)
        col_names = ", ".join(f'"{c}"' for c in columns)
        insert_sql = f'INSERT INTO "{table_name}" ({col_names}) VALUES ({placeholders})'

        rows = []
        for record in self.transformed_records:
            row = []
            for col in columns:
                val = record.get(col)
                if isinstance(val, bool):
                    val = int(val)
                row.append(val)
            rows.append(tuple(row))

        cursor.executemany(insert_sql, rows)
        conn.commit()
        conn.close()

        logger.info(f"Loaded {len(rows)} records into table '{table_name}' at {self.db_path}")

    # ---------------------------------------------------------------
    # RUN FULL PIPELINE
    # ---------------------------------------------------------------
    def run(self, csv_paths, group_by=None, agg_fields=None,
             field_mapping=None, computed_fields=None,
             table_name="etl_data", if_exists="replace"):
        """Execute the full ETL pipeline end-to-end."""
        logger.info("Starting ETL pipeline run")
        self.extract(csv_paths)
        self.clean()
        self.handle_missing_values()
        self.validate()
        self.aggregate(group_by=group_by, agg_fields=agg_fields)
        self.transform(field_mapping=field_mapping, computed_fields=computed_fields)
        self.load(table_name=table_name, if_exists=if_exists)
        logger.info("ETL pipeline run complete")

        return {
            "raw_count": len(self.raw_records),
            "clean_count": len(self.clean_records),
            "valid_count": len(self.valid_records),
            "invalid_count": len(self.invalid_records),
            "aggregates": self.aggregates,
            "transformed_count": len(self.transformed_records),
        }


def run_etl_pipeline(csv_paths, schema, db_path="etl_output.db",
                      missing_value_strategy="mean", group_by=None,
                      agg_fields=None, field_mapping=None,
                      computed_fields=None, table_name="etl_data",
                      if_exists="replace"):
    """
    Convenience wrapper function to run the full ETL pipeline in one call.

