            "diagnoses": [],
            "treatments": [],
            "appointments": [],
            "prescriptions": [],
            "billing_items": [],
            "notes": [],
            "discharge_summary": None,
        }
        records_db[patient_id] = record
        result["status"] = "success"
        result["message"] = f"Patient {record['name']} admitted successfully."
        result["data"] = {"patient_id": patient_id, "record": record}
        return {**result, "_records_db": records_db}

    # All actions below require a patient_id referencing an existing record
    patient_id = patient_data.get("patient_id")
    if action != "get_record" or patient_id is not None:
        if not patient_id:
            result["message"] = "patient_id is required for this action."
            return {**result, "_records_db": records_db}
        record = _get_patient(patient_id)
        if record is None:
            result["message"] = f"No patient record found for ID {patient_id}."
            return {**result, "_records_db": records_db}
        _ensure_lists(record)

    # ---------------- DIAGNOSE ----------------
    if action == "diagnose":
        condition = patient_data.get("condition")
        custom_code = patient_data.get("icd10_code")
        description = patient_data.get("description", "")

        if not condition and not custom_code:
            result["message"] = "Either 'condition' or 'icd10_code' must be provided."
            return {**result, "_records_db": records_db}

        code = custom_code or ICD10_CODES.get(condition.lower().replace(" ", "_")) if condition else custom_code
        if code is None:
            code = "R69"  # illness, unspecified fallback

        diagnosis_entry = {
            "diagnosis_id": _generate_id("DX"),
            "condition": condition,
            "icd10_code": code,
            "description": description,
            "diagnosed_date": _now(),
            "physician": patient_data.get("physician", "Unknown"),
        }
        record["diagnoses"].append(diagnosis_entry)
        result["status"] = "success"
        result["message"] = f"Diagnosis recorded with code {code}."
        result["data"] = {"diagnosis": diagnosis_entry}
        return {**result, "_records_db": records_db}

    # ---------------- PLAN TREATMENT ----------------
    if action == "plan_treatment":
        icd10_code = patient_data.get("icd10_code")
        if not icd10_code:
            if record["diagnoses"]:
                icd10_code = record["diagnoses"][-1]["icd10_code"]
            else:
                result["message"] = "No diagnosis available to base treatment plan on."
                return {**result, "_records_db": records_db}

        default_steps = TREATMENT_LIBRARY.get(icd10_code, ["General supportive care", "Follow-up as needed"])
        custom_steps = patient_data.get("custom_steps", [])
        steps = custom_steps if custom_steps else default_steps

        treatment_entry = {
            "treatment_id": _generate_id("TX"),
            "icd10_code": icd10_code,
            "steps": steps,
            "start_date": patient_data.get("start_date", _now()),
            "estimated_duration_days": patient_data.get("estimated_duration_days", 7),
            "assigned_physician": patient_data.get("physician", "Unknown"),
            "status": "active",
        }
        record["treatments"].append(treatment_entry)
        result["status"] = "success"
        result["message"] = "Treatment plan created."
        result["data"] = {"treatment": treatment_entry}
        return {**result, "_records_db": records_db}

    # ---------------- VERIFY INSURANCE ----------------
    if action == "verify_insurance":
        provider = patient_data.get("provider") or (record.get("insurance") or {}).get("provider")
        policy_number = patient_data.get("policy_number") or (record.get("insurance") or {}).get("policy_number")

        if not provider:
            result["message"] = "Insurance provider not specified."
            return {**result, "_records_db": records_db}

        provider_key = provider.lower().replace(" ", "_")
        provider_info = INSURANCE_PROVIDERS.get(provider_key)

        if provider_info is None:
            verification_status = "unverified"
            message = f"Unknown insurance provider '{provider}'. Treated as self-pay."
            provider_info = INSURANCE_PROVIDERS["self_pay"]
            provider_key = "self_pay"
        else:
            verification_status = "verified" if policy_number else "pending_policy_number"
            message = f"Insurance provider '{provider}' verified." if policy_number else \
                "Provider recognized but policy number missing."

        record["insurance"] = {
            "provider": provider_key,
            "policy_number": policy_number,
            "coverage_rate": provider_info["coverage_rate"],
            "copay": provider_info["copay"],
            "verification_status": verification_status,
            "verified_date": _now(),
        }
        result["status"] = "success" if verification_status != "unverified" else "warning"
        result["message"] = message
        result["data"] = {"insurance": record["insurance"]}
        return {**result, "_records_db": records_db}

    # ---------------- CALCULATE BILL ----------------
    if action == "calculate_bill":
        services = patient_data.get("services", [])
        if not services:
            result["message"] = "No services provided for billing."
            return {**result, "_records_db": records_db}

        insurance = record.get("insurance") or {
            "coverage_rate": 0.0, "copay": 0, "provider": "self_pay"
        }
        coverage_rate = insurance.get("coverage_rate", 0.0)
        copay = insurance.get("copay", 0)

        line_items = []
        subtotal = 0.0

        for service in services:
            if isinstance(service, dict):
                s_type = service.get("type")
                quantity = service.get("quantity", 1)
                custom_cost = service.get("cost")
            else:
                s_type = service
                quantity = 1
                custom_cost = None

            unit_cost = custom_cost if custom_cost is not None else BASE_SERVICE_COSTS.get(s_type, 100.0)
            line_total = unit_cost * quantity
            subtotal += line_total
            line_items.append({
                "service": s_type,
                "quantity": quantity,
                "unit_cost": unit_cost,
                "line_total": round(line_total, 2),
            })

        insurance_covered = round(subtotal * coverage_rate, 2)
        patient_responsibility = round(subtotal - insurance_covered + copay, 2)

        bill = {
            "bill_id": _generate_id("BILL"),
            "date": _now(),
            "line_items": line_items,
            "subtotal": round(subtotal, 2),
            "insurance_provider": insurance.get("provider", "self_pay"),
            "coverage_rate": coverage_rate,
            "insurance_covered_amount": insurance_covered,
            "copay": copay,
            "patient_responsibility": patient_responsibility,
        }
        record["billing_items"].append(bill)
        result["status"] = "success"
        result["message"] = "Bill calculated successfully."
        result["data"] = {"bill": bill}
        return {**result, "_records_db": records_db}

    # ---------------- SCHEDULE APPOINTMENT ----------------
    if action == "schedule_appointment":
        appointment_date = patient_data.get("appointment_date")
        purpose = patient_data.get("purpose", "General follow-up")
        physician = patient_data.get("physician", "Unassigned")
        duration_minutes = patient_data.get("duration_minutes", 30)

        if not appointment_date:
            appointment_date = (datetime.now() + timedelta(days=7)).isoformat()

        # Basic conflict check
        for appt in record["appointments"]:
            if appt["appointment_date"] == appointment_date and appt["status"] == "scheduled":
                result["message"] = "An appointment already exists at this exact time."
                return {**result, "_records_db": records_db}

        appointment_entry = {
            "appointment_id": _generate_id("APT"),
            "appointment_date": appointment_date,
            "purpose": purpose,
            "physician": physician,
            "duration_minutes": duration_minutes,
            "status": "scheduled",
            "created_date": _now(),
        }
        record["appointments"].append(appointment_entry)
        result["status"] = "success"
        result["message"] = "Appointment scheduled successfully."
        result["data"] = {"appointment": appointment_entry}
        return {**result, "_records_db": records_db}

    # ---------------- MANAGE PRESCRIPTION ----------------
    if action == "manage_prescription":
        sub_action = patient_data.get("sub_action", "add")

        if sub_action == "add":
            medication = patient_data.get("medication")
            dosage = patient_data.get("dosage")
            frequency = patient_data.get("frequency")
            duration_days = patient_data.get("duration_days", 7)

            if not medication:
                result["message"] = "Medication name is required."
                return {**result, "_records_db": records_db}

            prescription_entry = {
                "prescription_id": _generate_id("RX"),
                "medication": medication,
                "dosage": dosage or "as directed",
                "frequency": frequency or "once daily",
                "duration_days": duration_days,
                "prescribed_date": _now(),
                "prescribing_physician": patient_data.get("physician", "Unknown"),
                "status": "active",
                "refills_remaining": patient_data.get("refills", 0),
            }
            record["prescriptions"].append(prescription_entry)
            result["status"] = "success"
            result["message"] = f"Prescription for {medication} added."
            result["data"] = {"prescription": prescription_entry}

        elif sub_action == "refill":
            prescription_id = patient_data.get("prescription_id")
            target = next((p for p in record["prescriptions"] if p["prescription_id"] == prescription_id), None)
            if not target:
                result["message"] = f"Prescription {prescription_id} not found."
                return {**result, "_records_db": records_db}
            if target["refills_remaining"] <= 0:
                result["status"] = "error"
                result["message"] = "No refills remaining. Physician approval required."
                return {**result, "_records_db": records_db}
            target["refills_remaining"] -= 1
            target["last_refill_date"] = _now()
            result["status"] = "success"
            result["message"] = f"Prescription {prescription_id} refilled."
            result["data"] = {"prescription": target}

        elif sub_action == "discontinue":
            prescription_id = patient_data.get("prescription_id")
            target = next((p for p in record["prescriptions"] if p["prescription_id"] == prescription_id), None)
            if not target:
                result["message"] = f"Prescription {prescription_id} not found."
                return {**result, "_records_db": records_db}
            target["status"] = "discontinued"
            target["discontinued_date"] = _now()
            result["status"] = "success"
            result["message"] = f"Prescription {prescription_id} discontinued."
            result["data"] = {"prescription": target}

        else:
            result["message"] = f"Unknown prescription sub_action '{sub_action}'."

        return {**result, "_records_db": records_db}

    # ---------------- DISCHARGE ----------------
    if action == "discharge":
        if record["status"] == "discharged":
            result["message"] = "Patient has already been discharged."
            return {**result, "_records_db": records_db}

        discharge_summary = {
            "discharge_id": _generate_id("DIS"),
            "discharge_date": _now(),
            "final_diagnoses": [d["icd10_code"] for d in record["diagnoses"]],
            "treatments_completed": [t["treatment_id"] for t in record["treatments"]],
            "active_prescriptions": [
                p["medication"] for p in record["prescriptions"] if p["status"] == "active"
            ],
            "follow_up_appointments": [
                a["appointment_id"] for a in record["appointments"] if a["status"] == "scheduled"
            ],
            "discharge_notes": patient_data.get("discharge_notes", "Patient discharged in stable condition."),
            "discharge_condition": patient_data.get("discharge_condition", "stable"),
            "discharging_physician": patient_data.get("physician", "Unknown"),
            "total_billed": round(sum(b["subtotal"] for b in record["billing_items"]), 2),
            "total_patient_responsibility": round(
                sum(b["patient_responsibility"] for b in record["billing_items"]), 2
            ),
        }

        record["discharge_summary"] = discharge_summary
        record["status"] = "discharged"
        record["discharge_date"] = discharge_summary["discharge_date"]

        result["status"] = "success"
        result["message"] = "Patient discharged successfully."
        result["data"] = {"discharge_summary": discharge_summary}
        return {**result, "_records_db": records_db}

    # ---------------- GET RECORD ----------------
    if action == "get_record":
        if not patient_id:
            result["message"] = "patient_id is required to retrieve a record."
            return {**result, "_records_db": records_db}
        record = _get_patient(patient_id)
        if record is None:
            result["message"] = f"No patient record found for ID {patient_id}."
            return {**result, "_records_db": records_db}
        result["status"] = "success"
        result["message"] = "Record retrieved successfully."
        result["data"] = {"record": record}
        return {**result, "_records_db": records_db}

    # ---------------- UNKNOWN ACTION ----------------
    result["message"] = f"Unknown action '{action}'. Valid actions: {sorted(VALID_ACTIONS)}"
    return {**result, "_records_db": records_db}
