        self.id = str(uuid.uuid4())
        self.name = name
        self.price = float(price)
        self.category = category
        self.quantity = quantity
        self.description = description
        self.tags = set(tags) if tags else set()
        self.created_at = datetime.now()
        self.updated_at = datetime.now()
        self.sales_count = 0
        self.view_count = 0
        self.price_history = [(self.created_at, self.price)]
        self.active = True

    def to_dict(self):
        return {
            "id": self.id,
            "name": self.name,
            "price": self.price,
            "category": self.category,
            "quantity": self.quantity,
            "description": self.description,
            "tags": list(self.tags),
            "sales_count": self.sales_count,
            "view_count": self.view_count,
            "active": self.active,
            "created_at": self.created_at.isoformat(),
            "updated_at": self.updated_at.isoformat(),
        }

    def __repr__(self):
        return f"<Product {self.name} (${self.price:.2f}) x{self.quantity}>"


class ProductCatalog:
    def __init__(self):
        self.products = {}  # id -> Product
        self.categories = defaultdict(set)  # category -> set of product ids
        self.tags_index = defaultdict(set)  # tag -> set of product ids
        self.low_stock_threshold = 5
        self.sales_log = []  # list of dicts: product_id, quantity, price, timestamp
        self.view_log = []  # list of dicts: product_id, timestamp

    # ---------------------- Product Creation ----------------------
    def create_product(self, name, price, category, quantity=0, description="", tags=None):
        if price < 0:
            raise ValueError("Price cannot be negative")
        if quantity < 0:
            raise ValueError("Quantity cannot be negative")

        product = Product(name, price, category, quantity, description, tags)
        self.products[product.id] = product
        self.categories[category].add(product.id)
        for tag in product.tags:
            self.tags_index[tag].add(product.id)
        return product

    def delete_product(self, product_id):
        product = self.products.pop(product_id, None)
        if not product:
            raise KeyError(f"Product {product_id} not found")
        self.categories[product.category].discard(product_id)
        for tag in product.tags:
            self.tags_index[tag].discard(product_id)
        return True

    def get_product(self, product_id):
        product = self.products.get(product_id)
        if not product:
            raise KeyError(f"Product {product_id} not found")
        return product

    # ---------------------- Categorization ----------------------
    def add_category(self, product_id, category):
        product = self.get_product(product_id)
        old_category = product.category
        self.categories[old_category].discard(product_id)
        product.category = category
        self.categories[category].add(product_id)
        product.updated_at = datetime.now()
        return product

    def add_tags(self, product_id, tags):
        product = self.get_product(product_id)
        for tag in tags:
            product.tags.add(tag)
            self.tags_index[tag].add(product_id)
        product.updated_at = datetime.now()
        return product

    def remove_tags(self, product_id, tags):
        product = self.get_product(product_id)
        for tag in tags:
            product.tags.discard(tag)
            self.tags_index[tag].discard(product_id)
        product.updated_at = datetime.now()
        return product

    def get_products_by_category(self, category):
        return [self.products[pid] for pid in self.categories.get(category, set())]

    def get_products_by_tag(self, tag):
        return [self.products[pid] for pid in self.tags_index.get(tag, set())]

    def list_categories(self):
        return list(self.categories.keys())

    # ---------------------- Pricing ----------------------
    def update_price(self, product_id, new_price):
        if new_price < 0:
            raise ValueError("Price cannot be negative")
        product = self.get_product(product_id)
        product.price = float(new_price)
        product.updated_at = datetime.now()
        product.price_history.append((product.updated_at, product.price))
        return product

    def apply_discount(self, product_id, percent_off):
        if not (0 <= percent_off <= 100):
            raise ValueError("Discount percent must be between 0 and 100")
        product = self.get_product(product_id)
        new_price = product.price * (1 - percent_off / 100.0)
        return self.update_price(product_id, round(new_price, 2))

    def bulk_price_update(self, category, percent_change):
        updated = []
        for product in self.get_products_by_category(category):
            new_price = product.price * (1 + percent_change / 100.0)
            self.update_price(product.id, round(max(new_price, 0), 2))
            updated.append(product)
        return updated

    def get_price_history(self, product_id):
        product = self.get_product(product_id)
        return product.price_history

    # ---------------------- Inventory Tracking ----------------------
    def restock(self, product_id, quantity):
        if quantity < 0:
            raise ValueError("Restock quantity cannot be negative")
        product = self.get_product(product_id)
        product.quantity += quantity
        product.updated_at = datetime.now()
        return product

    def sell(self, product_id, quantity):
        product = self.get_product(product_id)
        if quantity <= 0:
            raise ValueError("Sale quantity must be positive")
        if product.quantity < quantity:
            raise ValueError("Insufficient stock")
        product.quantity -= quantity
        product.sales_count += quantity
        product.updated_at = datetime.now()
        self.sales_log.append({
            "product_id": product_id,
            "quantity": quantity,
            "price": product.price,
            "timestamp": datetime.now(),
        })
        return product

    def get_low_stock_products(self, threshold=None):
        threshold = threshold if threshold is not None else self.low_stock_threshold
        return [p for p in self.products.values() if p.quantity <= threshold]

    def get_out_of_stock_products(self):
        return [p for p in self.products.values() if p.quantity == 0]

    def total_inventory_value(self):
        return sum(p.price * p.quantity for p in self.products.values())

    # ---------------------- Search ----------------------
    def search(self, query="", category=None, min_price=None, max_price=None,
               tags=None, in_stock_only=False):
        query = query.lower().strip()
        results = []
        for product in self.products.values():
            if not product.active:
                continue
            if query:
                haystack = f"{product.name} {product.description}".lower()
                if query not in haystack and not any(query in t.lower() for t in product.tags):
                    continue
            if category and product.category != category:
                continue
            if min_price is not None and product.price < min_price:
                continue
            if max_price is not None and product.price > max_price:
                continue
            if tags and not set(tags).issubset(product.tags):
                continue
            if in_stock_only and product.quantity <= 0:
                continue
            results.append(product)
            product.view_count += 1
            self.view_log.append({"product_id": product.id, "timestamp": datetime.now()})
        return results

    def record_view(self, product_id):
        product = self.get_product(product_id)
        product.view_count += 1
        self.view_log.append({"product_id": product_id, "timestamp": datetime.now()})
        return product

    # ---------------------- Recommendation Engine ----------------------
    def recommend_similar(self, product_id, limit=5):
        target = self.get_product(product_id)
        scores = []
        for pid, product in self.products.items():
            if pid == product_id or not product.active:
                continue
            score = 0
            if product.category == target.category:
                score += 3
            common_tags = target.tags.intersection(product.tags)
            score += len(common_tags) * 2
            price_diff = abs(product.price - target.price)
            if target.price > 0:
                proximity = max(0, 1 - (price_diff / target.price))
                score += proximity
            if score > 0:
                scores.append((score, product))
        scores.sort(key=lambda x: x[0], reverse=True)
        return [p for _, p in scores[:limit]]

    def recommend_trending(self, limit=5, days=30):
        cutoff = datetime.now().timestamp() - days * 86400
        sales_counter = Counter()
        for entry in self.sales_log:
            if entry["timestamp"].timestamp() >= cutoff:
                sales_counter[entry["product_id"]] += entry["quantity"]
        ranked = sales_counter.most_common(limit)
        return [self.products[pid] for pid, _ in ranked if pid in self.products]

    def recommend_frequently_bought_together(self, product_id, limit=5):
        co_occurrence = Counter()
        order_map = defaultdict(set)
        for entry in self.sales_log:
            order_map[entry["timestamp"].date()].add(entry["product_id"])

        for _, product_ids in order_map.items():
            if product_id in product_ids:
                for pid in product_ids:
                    if pid != product_id:
                        co_occurrence[pid] += 1

        ranked = co_occurrence.most_common(limit)
        return [self.products[pid] for pid, _ in ranked if pid in self.products]

    def recommend_for_category_browsers(self, category, limit=5):
        products = self.get_products_by_category(category)
        products.sort(key=lambda p: (p.sales_count, p.view_count), reverse=True)
        return products[:limit]

    # ---------------------- Analytics ----------------------
    def total_revenue(self):
        return sum(entry["quantity"] * entry["price"] for entry in self.sales_log)

    def revenue_by_category(self):
        revenue = defaultdict(float)
        for entry in self.sales_log:
            product = self.products.get(entry["product_id"])
            if product:
                revenue[product.category] += entry["quantity"] * entry["price"]
        return dict(revenue)

    def best_sellers(self, limit=5):
        sorted_products = sorted(self.products.values(), key=lambda p: p.sales_count, reverse=True)
        return sorted_products[:limit]

    def most_viewed(self, limit=5):
        sorted_products = sorted(self.products.values(), key=lambda p: p.view_count, reverse=True)
        return sorted_products[:limit]

    def conversion_rate(self, product_id):
        product = self.get_product(product_id)
        if product.view_count == 0:
            return 0.0
        return product.sales_count / product.view_count

    def average_price_by_category(self):
        averages = {}
        for category, pids in self.categories.items():
            prices = [self.products[pid].price for pid in pids if pid in self.products]
            if prices:
                averages[category] = statistics.mean(prices)
        return averages

    def category_performance(self):
        performance = {}
        revenue_map = self.revenue_by_category()
        for category, pids in self.categories.items():
            products = [self.products[pid] for pid in pids if pid in self.products]
            total_sales = sum(p.sales_count for p in products)
            total_views = sum(p.view_count for p in products)
            performance[category] = {
                "product_count": len(products),
                "total_sales": total_sales,
                "total_views": total_views,
                "revenue": revenue_map.get(category, 0.0),
                "avg_price": statistics.mean([p.price for p in products]) if products else 0.0,
            }
        return performance

    def sales_over_time(self, granularity="day"):
        buckets = defaultdict(float)
        for entry in self.sales_log:
            ts = entry["timestamp"]
            if granularity == "day":
                key = ts.strftime("%Y-%m-%d")
            elif granularity == "month":
                key = ts.strftime("%Y-%m")
            elif granularity == "year":
                key = ts.strftime("%Y")
            else:
                raise ValueError("granularity must be 'day', 'month', or 'year'")
            buckets[key] += entry["quantity"] * entry["price"]
        return dict(sorted(buckets.items()))

    def inventory_summary(self):
        return {
            "total_products": len(self.products),
            "total_quantity": sum(p.quantity for p in self.products.values()),
            "total_value": self.total_inventory_value(),
            "low_stock_count": len(self.get_low_stock_products()),
            "out_of_stock_count": len(self.get_out_of_stock_products()),
        }

    def deactivate_product(self, product_id):
        product = self.get_product(product_id)
        product.active = False
        product.updated_at = datetime.now()
        return product

    def activate_product(self, product_id):
        product = self.get_product(product_id)
        product.active = True
        product.updated_at = datetime.now()
        return product
