            self.agents[agent_id]["active"] = False

    def _find_available_agent(self, category=None):
        candidates = [
            a for a in self.agents.values()
            if a["active"] and (category is None or category in a["skills"] or not a["skills"])
        ]
        if not candidates:
            candidates = [a for a in self.agents.values() if a["active"]]
        if not candidates:
