            results = [t for t in results if t.assigned_agent == agent_id]
        return results

    # ---------------- Escalation Workflow ----------------
    def escalate_ticket(self, ticket_id, reason=""):
        ticket = self.get_ticket(ticket_id)
        current_level = ticket.escalation_level
        if current_level >= len(self.ESCALATION_CHAIN) - 1:
            raise ValueError("Ticket already at highest escalation level")

        next_level = current_level + 1
        next_role = self.ESCALATION_CHAIN[next_level]
        new_agent = self._find_available_agent_by_level(next_role)

        ticket.escalation_history.append({
            "from_level": current_level,
            "to_level": next_level,
            "reason": reason,
            "timestamp": datetime.datetime.now(),
            "previous_agent": ticket.assigned_agent,
            "new_agent": new_agent
        })
        ticket.escalation_level = next_level
        ticket.status = TicketStatus.ESCALATED
        if new_agent:
            if ticket.assigned_agent:
                self.agent_ticket_counts[ticket.assigned_agent] -= 1
            ticket.assigned_agent = new_agent
            self.agent_ticket_counts[new_agent] += 1
        ticket.priority = TicketPriority(min(4, ticket.priority.value + 1))
        ticket.updated_at = datetime.datetime.now()
        return ticket

    def _find_available_agent_by_level(self, level):
        candidates = [a for a in self.agents.values() if a["active"] and a["level"] == level]
