        for ticket in self.tickets.values():
            if ticket.status in (TicketStatus.OPEN, TicketStatus.IN_PROGRESS):
                age = (now - ticket.updated_at).total_seconds() / 3600
                if age >= hours_threshold and ticket.escalation_level < len(self.ESCALATION_CHAIN) - 1:
                    self.escalate_ticket(ticket.id, reason="Auto-escalated due to inactivity")
                    escalated.append(ticket.id)
