        self.agent_ticket_counts[new_agent_id] += 1
        return chat

    def end_chat(self, chat_id, create_survey=True):
        chat = self.chat_sessions.get(chat_id)
        if not chat:
            raise KeyError(f"Chat {chat_id} not found")
        chat.end()
        if chat.agent_id:
            self.agent_ticket_counts[chat.agent_id] -= 1
        if create_survey:
            return self.create_satisfaction_survey(chat.customer_id, chat_id=chat.id)
        return None

    def convert_chat_to_ticket(self, chat_id, subject=None, priority=TicketPriority.MEDIUM):
        chat = self.chat_sessions.get(chat_id)
