            fees += self.MONTHLY_MAINTENANCE_FEE
        if account.balance < Decimal("0.00"):
            fees += self.OVERDRAFT_FEE
        return fees


class SavingsFeeCalculator(FeeCalculator):
    EXCESS_WITHDRAWAL_FEE = Decimal("5.00")
    FREE_WITHDRAWALS_PER_PERIOD = 6

    def calculate_fees(self, account: "SavingsAccount") -> Decimal:
        withdrawals = account.withdrawal_count_this_period
        excess = max(0, withdrawals - self.FREE_WITHDRAWALS_PER_PERIOD)
        return self.EXCESS_WITHDRAWAL_FEE * excess


class InvestmentFeeCalculator(FeeCalculator):
    ANNUAL_MANAGEMENT_FEE_RATE = Decimal("0.0075")  # 0.75% annually
    TRADE_COMMISSION = Decimal("4.95")

    def calculate_fees(self, account: "InvestmentAccount") -> Decimal:
        monthly_rate = self.ANNUAL_MANAGEMENT_FEE_RATE / Decimal("12")
        management_fee = account.balance * monthly_rate
        trade_fees = self.TRADE_COMMISSION * account.trade_count_this_period
        return (management_fee + trade_fees).quantize(Decimal("0.01"))


