# Interest Calculator Hierarchy
# ---------------------------------------------------------------------------

class InterestCalculator(ABC):
    """Strategy for computing periodic interest for an account."""

    @abstractmethod
    def calculate_interest(self, account: "Account") -> Decimal:
        raise NotImplementedError


class CheckingInterestCalculator(InterestCalculator):
    ANNUAL_RATE = Decimal("0.0001")  # negligible interest

    def calculate_interest(self, account: "Account") -> Decimal:
        if account.balance <= Decimal("0.00"):
            return Decimal("0.00")
        monthly_rate = self.ANNUAL_RATE / Decimal("12")
        return (account.balance * monthly_rate).quantize(Decimal("0.01"))


class SavingsInterestCalculator(InterestCalculator):
    ANNUAL_RATE = Decimal("0.025")
    TIERED_RATE_BONUS = Decimal("0.005")
    TIER_THRESHOLD = Decimal("10000.00")

    def calculate_interest(self, account: "SavingsAccount") -> Decimal:
        rate = self.ANNUAL_RATE
        if account.balance >= self.TIER_THRESHOLD:
            rate += self.TIERED_RATE_BONUS
        monthly_rate = rate / Decimal("12")
        return (account.balance * monthly_rate).quantize(Decimal("0.01"))


class InvestmentInterestCalculator(InterestCalculator):
    """Represents dividend/interest income on cash balance in an investment account."""

    CASH_YIELD_RATE = Decimal("0.015")

    def calculate_interest(self, account: "InvestmentAccount") -> Decimal:
        monthly_rate = self.CASH_YIELD_RATE / Decimal("12")
        return (account.cash_balance * monthly_rate).quantize(Decimal("0.01"))


# ---------------------------------------------------------------------------
# Statement Hierarchy
# ---------------------------------------------------------------------------

class Statement(ABC):
    """Represents a periodic account statement."""

    def __init__(self, account: "Account", period_start: datetime, period_end: datetime):
        self.account = account
        self.period_start = period_start
        self.period_end = period_end
        self.transactions: List[Transaction] = [
            t for t in account.transactions
            if period_start <= t.timestamp <= period_end
        ]
        self.interest_earned: Decimal = Decimal("0.00")
        self.fees_charged: Decimal = Decimal("0.00")

    def generate(self) -> str:
        self.interest_earned = self.account.interest_calculator.calculate_interest(self.account)
        self.fees_charged = self.account.fee_calculator.calculate_fees(self.account)
        return self._render()

    @abstractmethod
    def _render(self) -> str:
        raise NotImplementedError

    def _base_header(self) -> str:
        return (
            f"Statement for {self.account.owner_name} - {self.account.__class__.__name__}\n"
            f"Account #: {self.account.account_number}\n"
            f"Period: {self.period_start:%Y-%m-%d} to {self.period_end:%Y-%m-%d}\n"
            f"{'-' * 50}\n"
        )

    def _transaction_lines(self) -> str:
        if not self.transactions:
            return "No transactions this period.\n"
        return "\n".join(str(t) for t in self.transactions) + "\n"


class CheckingStatement(Statement):
    def _render(self) -> str:
        lines = [self._base_header(), "Transactions:", self._transaction_lines()]
        lines.append(f"Interest Earned: {self.interest_earned}")
        lines.append(f"Fees Charged: {self.fees_charged}")
        lines.append(f"Ending Balance: {self.account.balance}")
        return "\n".join(lines)


class SavingsStatement(Statement):
    def _render(self) -> str:
        lines = [self._base_header(), "Transactions:", self._transaction_lines()]
        lines.append(f"Withdrawals this period: {self.account.withdrawal_count_this_period}")
        lines.append(f"Interest Earned: {self.interest_earned}")
        lines.append(f"Fees Charged: {self.fees_charged}")
        lines.append(f"Ending Balance: {self.account.balance}")
        return "\n".join(lines)


class InvestmentStatement(Statement):
    def _render(self) -> str:
        lines = [self._base_header(), "Transactions:", self._transaction_lines()]
        lines.append(f"Trades executed this period: {self.account.trade_count_this_period}")
        lines.append(f"Cash Balance: {self.account.cash_balance}")
        lines.append(f"Holdings Value: {self.account.holdings_value}")
        lines.append(f"Dividend/Interest Income: {self.interest_earned}")
        lines.append(f"Fees Charged: {self.fees_charged}")
        lines.append(f"Total Account Value: {self.account.balance}")
        return "\n".join(lines)


# ---------------------------------------------------------------------------
# Account Hierarchy
# ---------------------------------------------------------------------------

class InsufficientFundsError(Exception):
    pass


class Account(ABC):
    def __init__(self, account_number: str, owner_name: str, initial_balance: Decimal = Decimal("0.00")):
        self.account_number = account_number
        self.owner_name = owner_name
        self.balance: Decimal = initial_balance
        self.transactions: List[Transaction] = []
        self.interest_calculator: InterestCalculator = self._create_interest_calculator()
        self.fee_calculator: FeeCalculator = self._create_fee_calculator()

    @abstractmethod
    def _create_interest_calculator(self) -> InterestCalculator:
        raise NotImplementedError

    @abstractmethod
    def _create_fee_calculator(self) -> FeeCalculator:
        raise NotImplementedError

    @abstractmethod
    def create_statement(self, period_start: datetime, period_end: datetime) -> Statement:
        raise NotImplementedError

    def deposit(self, amount: Decimal, description: str = "Deposit") -> None:
        if amount <= Decimal("0.00"):
            raise ValueError("Deposit amount must be positive.")
        self.balance += amount
        self.transactions.append(Transaction(datetime.now(), description, amount))

    def withdraw(self, amount: Decimal, description: str = "Withdrawal") -> None:
        if amount <= Decimal("0.00"):
            raise ValueError("Withdrawal amount must be positive.")
        if amount > self.balance and not self._allows_overdraft():
            raise InsufficientFundsError(
                f"Insufficient funds: balance {self.balance}, requested {amount}"
            )
        self.balance -= amount
        self.transactions.append(Transaction(datetime.now(), description, -amount))

    def _allows_overdraft(self) -> bool:
        return False

    def apply_monthly_cycle(self) -> None:
        """Apply interest and fees for the period; typically called at period end."""
        interest = self.interest_calculator.calculate_interest(self)
        if interest > Decimal("0.00"):
            self.deposit(interest, description="Interest Earned")

        fees = self.fee_calculator.calculate_fees(self)
        if fees > Decimal("0.00"):
            self.balance -= fees
            self.transactions.append(Transaction(datetime.now(), "Fees Charged", -fees))


class CheckingAccount(Account):
    OVERDRAFT_LIMIT = Decimal("500.00")

    def _create_interest_calculator(self) -> InterestCalculator:
        return CheckingInterestCalculator()

    def _create_fee_calculator(self) -> FeeCalculator:
        return CheckingFeeCalculator()

    def _allows_overdraft(self) -> bool:
        return True

    def withdraw(self, amount: Decimal, description: str = "Withdrawal") -> None:
        if amount <= Decimal("0.00"):
            raise ValueError("Withdrawal amount must be positive.")
        if self.balance - amount < -self.OVERDRAFT_LIMIT:
            raise InsufficientFundsError(
                f"Overdraft limit exceeded: balance {self.balance}, requested {amount}"
            )
        self.balance -= amount
        self.transactions.append(Transaction(datetime.now(), description, -amount))

    def create_statement(self, period_start: datetime, period_end: datetime) -> Statement:
        return CheckingStatement(self, period_start, period_end)


class SavingsAccount(Account):
    def __init__(self, account_number: str, owner_name: str, initial_balance: Decimal = Decimal("0.00")):
        super().__init__(account_number, owner_name, initial_balance)
        self.withdrawal_count_this_period: int = 0

    def _create_interest_calculator(self) -> InterestCalculator:
        return SavingsInterestCalculator()

    def _create_fee_calculator(self) -> FeeCalculator:
        return SavingsFeeCalculator()

    def withdraw(self, amount: Decimal, description: str = "Withdrawal") -> None:
        super().withdraw(amount, description)
        self.withdrawal_count_this_period += 1

    def create_statement(self, period_start: datetime, period_end: datetime) -> Statement:
        statement = SavingsStatement(self, period_start, period_end)
        return statement

    def apply_monthly_cycle(self) -> None:
        super().apply_monthly_cycle()
        self.withdrawal_count_this_period = 0


class InvestmentAccount(Account):
    def __init__(self, account_number: str, owner_name: str, initial_cash: Decimal = Decimal("0.00")):
        super().__init__(account_number, owner_name, initial_cash)
        self.cash_balance: Decimal = initial_cash
        self.holdings_value: Decimal = Decimal("0.00")
        self.trade_count_this_period: int = 0

    def _create_interest_calculator(self) -> InterestCalculator:
        return InvestmentInterestCalculator()

    def _create_fee_calculator(self) -> FeeCalculator:
        return InvestmentFeeCalculator()

    @property
    def balance(self) -> Decimal:  # total account value overrides base balance
        return self.cash_balance + self.holdings_value

    @balance.setter
    def balance(self, value: Decimal) -> None:
        # Keep compatibility with base class initializer; treat as cash balance.
        self.cash_balance = value

    def deposit(self, amount: Decimal, description: str = "Deposit") -> None:
        if amount <= Decimal("0.00"):
            raise ValueError("Deposit amount must be positive.")
        self.cash_balance += amount
        self.transactions.append(Transaction(datetime.now(), description, amount))

    def withdraw(self, amount: Decimal, description: str = "Withdrawal") -> None:
        if amount <= Decimal("0.00"):
            raise ValueError("Withdrawal amount must be positive.")
        if amount > self.cash_balance:
            raise InsufficientFundsError(
                f"Insufficient cash: cash balance {self.cash_balance}, requested {amount}"
            )
        self.cash_balance -= amount
        self.transactions.append(Transaction(datetime.now(), description, -amount))

    def execute_trade(self, description: str, cash_delta: Decimal, holdings_delta: Decimal) -> None:
        """Record a trade that moves value between cash and holdings."""
        self.cash_balance += cash_delta
        self.holdings_value += holdings_delta
        self.trade_count_this_period += 1
        self.transactions.append(Transaction(datetime.now(), description, cash_delta))

    def create_statement(self, period_start: datetime, period_end: datetime) -> Statement:
        return InvestmentStatement(self, period_start, period_end)

    def apply_monthly_cycle(self) -> None:
        interest = self.interest_calculator.calculate_interest(self)
        if interest > Decimal("0.00"):
            self.deposit(interest, description="Dividend/Interest Income")

        fees = self.fee_calculator.calculate_fees(self)
        if fees > Decimal("0.00"):
            self.cash_balance -= fees
            self.transactions.append(Transaction(datetime.now(), "Fees Charged", -fees))

        self.trade_count_this_period = 0
