def _coerce_value(raw):
    if not isinstance(raw, str):
        return raw
    lowered = raw.strip().lower()
    if lowered in ("true", "yes", "on"):
        return True
    if lowered in ("false", "no", "off"):
        return False
    if lowered in ("null", "none", ""):
        return None if lowered != "" else raw
    try:
        if re.match(r"^[+-]?\d+$", raw.strip()):
            return int(raw)
