def _xml_element_to_dict(elem):
    result = {}
    for child in elem:
        child_data = _xml_element_to_dict(child) if len(child) else _coerce_value(child.text)
        if child.tag in result:
            if not isinstance(result[child.tag], list):
                result[child.tag] = [result[child.tag]]
            result[child.tag].append(child_data)
        else:
            result[child.tag] = child_data
    for attr_key, attr_val in elem.attrib.items():
        result[f"@{attr_key}"] = _coerce_value(attr_val)
    if not result and elem.text is not None:
        return _coerce_value(elem.text)
    return result


