class ConfigLoader:
    """Loads configuration data from a single file, dispatching by extension."""

    SUPPORTED_EXTENSIONS = (".json", ".yaml", ".yml", ".xml", ".ini", ".cfg", ".toml")

    @staticmethod
    def load(path):
        if not os.path.isfile(path):
            raise ConfigError(f"Config file not found: {path}")

        ext = os.path.splitext(path)[1].lower()

        if ext == ".json":
            return ConfigLoader._load_json(path)
        elif ext in (".yaml", ".yml"):
            return ConfigLoader._load_yaml(path)
        elif ext == ".xml":
            return ConfigLoader._load_xml(path)
        elif ext in (".ini", ".cfg"):
            return ConfigLoader._load_ini(path)
        elif ext == ".toml":
            return ConfigLoader._load_toml(path)
        else:
            raise ConfigFormatError(f"Unsupported config file extension: {ext}")

    @staticmethod
    def _load_json(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except json.JSONDecodeError as e:
            raise ConfigFormatError(f"Invalid JSON in {path}: {e}")

    @staticmethod
    def _load_yaml(path):
        if not _HAS_YAML:
            raise ConfigFormatError(
                "YAML support requires PyYAML. Install with `pip install pyyaml`."
            )
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
            return data if data is not None else {}
        except yaml.YAMLError as e:
            raise ConfigFormatError(f"Invalid YAML in {path}: {e}")

    @staticmethod
    def _load_xml(path):
        try:
            tree = ElementTree.parse(path)
            root = tree.getroot()
            return {root.tag: _xml_element_to_dict(root)}
        except ElementTree.ParseError as e:
            raise ConfigFormatError(f"Invalid XML in {path}: {e}")

    @staticmethod
    def _load_ini(path):
        parser = ConfigParser()
        try:
            parser.read(path, encoding="utf-8")
        except Exception as e:
            raise ConfigFormatError(f"Invalid INI in {path}: {e}")
        return _ini_to_dict(parser)

    @staticmethod
    def _load_toml(path):
        if not _HAS_TOML:
            raise ConfigFormatError(
                "TOML support requires `tomllib` (Python 3.11+) or `pip install toml`."
            )
        try:
            if _TOML_MODE == "read_binary":
                with open(path, "rb") as f:
                    return _toml_reader.load(f)
            else:
                with open(path, "r", encoding="utf-8") as f:
                    return _toml_reader.load(f)
        except Exception as e:
            raise ConfigFormatError(f"Invalid TOML in {path}: {e}")


class RemoteConfigClient:
    """Fetches JSON configuration from a remote HTTP(S) server."""

    def __init__(self, url, timeout=5, headers=None, retries=3, retry_delay=1.0):
        self.url = url
        self.timeout = timeout
        self.headers = headers or {}
        self.retries = retries
        self.retry_delay = retry_delay

    def fetch(self):
        last_error = None
        for attempt in range(1, self.retries + 1):
            try:
                req = urllib.request.Request(self.url, headers=self.headers)
                with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                    body = resp.read().decode("utf-8")
                    return json.loads(body)
            except (urllib.error.URLError, urllib.error.HTTPError, TimeoutError) as e:
                last_error = e
            except json.JSONDecodeError as e:
                raise RemoteConfigError(f"Remote config server returned invalid JSON: {e}")
            if attempt < self.retries:
                time.sleep(self.retry_delay)
        raise RemoteConfigError(
            f"Failed to fetch remote config from {self.url} after {self.retries} attempts: {last_error}"
        )


class EnvOverrideResolver:
    """Applies environment variable overrides onto a config dict."""

    def __init__(self, prefix="APP_", separator="__"):
        self.prefix = prefix
        self.separator = separator

    def apply(self, config):
        result = json.loads(json.dumps(config)) if config else {}
        for env_key, env_val in os.environ.items():
            if not env_key.startswith(self.prefix):
                continue
            remainder = env_key[len(self.prefix):]
            if not remainder:
                continue
            dotted_key = ".".join(
                part.lower() for part in remainder.split(self.separator) if part
            )
            if not dotted_key:
                continue
            _set_nested(result, dotted_key, _coerce_value(env_val))
        return result


class ConfigManager:
    """
    Central configuration manager.

    - Supports loading and merging multiple config files (JSON, YAML, XML, INI, TOML).
    - Applies environment variable overrides on top of file-based config.
    - If ALL provided config sources are JSON files (or no files, only remote),
      remote config server(s) may also be queried and merged in, with the
      highest priority given to remote > env > later files > earlier files.
    """

    def __init__(
        self,
        paths=None,
        env_prefix="APP_",
        env_separator="__",
        remote_urls=None,
        remote_timeout=5,
        remote_headers=None,
        remote_retries=3,
        auto_reload_interval=None,
    ):
        self.paths = list(paths) if paths else []
        self.env_resolver = EnvOverrideResolver(prefix=env_prefix, separator=env_separator)
        self.remote_urls = list(remote_urls) if remote_urls else []
        self.remote_timeout = remote_timeout
        self.remote_headers = remote_headers
        self.remote_retries = remote_retries

        self._lock = threading.RLock()
        self._config = {}
        self._auto_reload_interval = auto_reload_interval
        self._stop_event = threading.Event()
        self._reload_thread = None

        self.reload()

        if self._auto_reload_interval:
            self._start_auto_reload()

    def _all_sources_json(self):
        if not self.paths:
            return True
        for p in self.paths:
            if os.path.splitext(p)[1].lower() != ".json":
                return False
        return True

    def _load_file_configs(self):
        merged = {}
        for path in self.paths:
            data = ConfigLoader.load(path)
            if not isinstance(data, dict):
                raise ConfigFormatError(
                    f"Top-level config in {path} must be a mapping/object, got {type(data)}"
                )
            merged = _deep_merge(merged, data)
        return merged

    def _load_remote_configs(self):
        merged = {}
        for url in self.remote_urls:
            client = RemoteConfigClient(
                url,
                timeout=self.remote_timeout,
                headers=self.remote_headers,
                retries=self.remote_retries,
            )
            data = client.fetch()
            if not isinstance(data, dict):
                raise RemoteConfigError(
                    f"Remote config at {url} must be a JSON object, got {type(data)}"
                )
            merged = _deep_merge(merged, data)
        return merged

    def reload(self):
        with self._lock:
            merged = self._load_file_configs()

            if self.remote_urls:
                if not self._all_sources_json():
                    raise ConfigError(
                        "Remote config servers are only supported when all local "
                        "config files are JSON. Mixed formats detected."
                    )
                remote_data = self._load_remote_configs()
                merged = _deep_merge(merged, remote_data)

            merged = self.env_resolver.apply(merged)

            self._config = merged
            return self._config

    def _start_auto_reload(self):
        def _loop():
            while not self._stop_event.wait(self._auto_reload_interval):
                try:
                    self.reload()
                except ConfigError:
                    pass

        self._reload_thread = threading.Thread(target=_loop, daemon=True)
        self._reload_thread.start()

    def stop_auto_reload(self):
        self._stop_event.set()
        if self._reload_thread:
            self._reload_thread.join(timeout=1)

    def get(self, dotted_key, default=None):
        with self._lock:
            cur = self._config
            for part in dotted_key.split("."):
                if isinstance(cur, dict) and part in cur:
                    cur = cur[part]
                else:
                    return default
            return cur

    def set(self, dotted_key, value):
        with self._lock:
            _set_nested(self._config, dotted_key, value)

    def as_dict(self):
        with self._lock:
            return json.loads(json.dumps(self._config))

    def flattened(self):
        with self._lock:
            return _flatten_keys(self._config)

    def __getitem__(self, key):
        value = self.get(key, default=_MISSING)
        if value is _MISSING:
            raise KeyError(key)
        return value

    def __contains__(self, key):
        return self.get(key, default=_MISSING) is not _MISSING

    def __repr__(self):
        return f"<ConfigManager sources={self.paths} remote={self.remote_urls}>"


_MISSING = object()


def load_config(
    paths=None,
    env_prefix="APP_",
    env_separator="__",
    remote_urls=None,
    remote_timeout=5,
    remote_headers=None,
    remote_retries=3,
    auto_reload_interval=None,
):
    """Convenience factory function to build a ConfigManager."""
    return ConfigManager(
        paths=paths,
        env_prefix=env_prefix,
        env_separator=env_separator,
        remote_urls=remote_urls,
        remote_timeout=remote_timeout,
        remote_headers=remote_headers,
        remote_retries=remote_retries,
        auto_reload_interval=auto_reload_interval,
