class Policy(ABC):
    def __init__(self, policy_id: str, holder: Applicant, base_premium: float,
                 start_date: Optional[date] = None, term_days: int = 365):
        self.policy_id = policy_id
        self.holder = holder
        self.base_premium = base_premium
        self.start_date = start_date or date.today()
        self.term_days = term_days
        self.active = True
        self.coverage_amount: float = 0.0

    @property
    def end_date(self) -> date:
        return self.start_date + timedelta(days=self.term_days)

    @abstractmethod
    def policy_type(self) -> PolicyType:
        ...

    def __repr__(self):
        return f"<{self.__class__.__name__} {self.policy_id} holder={self.holder.name}>"


class AutoPolicy(Policy):
    def __init__(self, policy_id: str, holder: Applicant, base_premium: float,
                 vehicle_make: str, vehicle_year: int, **kwargs):
        super().__init__(policy_id, holder, base_premium, **kwargs)
        self.vehicle_make = vehicle_make
        self.vehicle_year = vehicle_year

    def policy_type(self) -> PolicyType:
        return PolicyType.AUTO


class HomePolicy(Policy):
    def __init__(self, policy_id: str, holder: Applicant, base_premium: float,
                 dwelling_value: float, construction_year: int, **kwargs):
        super().__init__(policy_id, holder, base_premium, **kwargs)
        self.dwelling_value = dwelling_value
        self.construction_year = construction_year

    def policy_type(self) -> PolicyType:
        return PolicyType.HOME


class HealthPolicy(Policy):
    def __init__(self, policy_id: str, holder: Applicant, base_premium: float,
                 deductible: float, network_tier: str = "standard", **kwargs):
