    def assess_risk(self, policy: AutoPolicy) -> RiskLevel:
        points = policy.holder.driving_record_points
        age_factor = policy.holder.age < 21 or policy.holder.age > 70
        if points >= 6 or (age_factor and points >= 3):
            return RiskLevel.HIGH
        if points >= 3 or age_factor:
            return RiskLevel.MEDIUM
        return RiskLevel.LOW

    def approve(self, policy: AutoPolicy) -> bool:
        return self._finalize(self.assess_risk(policy))


class HomeUnderwriter(Underwriter):
    def assess_risk(self, policy: HomePolicy) -> RiskLevel:
        age_of_home = date.today().year - policy.construction_year
        if age_of_home > 60 or policy.holder.prior_claims > 3:
            return RiskLevel.HIGH
        if age_of_home > 30 or policy.holder.prior_claims > 1:
            return RiskLevel.MEDIUM
        return RiskLevel.LOW

    def approve(self, policy: HomePolicy) -> bool:
        return self._finalize(self.assess_risk(policy))


