    def assess_risk(self, policy: HealthPolicy) -> RiskLevel:
        score = policy.holder.health_score
        if policy.holder.smoker and score < 60:
            return RiskLevel.HIGH
        if score < 50:
            return RiskLevel.HIGH
        if score < 75 or policy.holder.smoker:
            return RiskLevel.MEDIUM
        return RiskLevel.LOW

    def approve(self, policy: HealthPolicy) -> bool:
