class ClaimProcessor(ABC):
    @abstractmethod
    def max_payout_ratio(self) -> float:
        ...

    def process(self, policy: Policy, claim: Claim) -> Claim:
        cap = self._payout_cap(policy)
        if claim.amount_requested <= 0:
            claim.approved = False
            claim.notes = "Invalid claim amount"
            return claim
        approved_amount = min(claim.amount_requested, cap)
        claim.amount_approved = approved_amount
        claim.approved = approved_amount > 0
        claim.notes = self._extra_notes(policy, claim)
        return claim

    @abstractmethod
    def _payout_cap(self, policy: Policy) -> float:
        ...

    def _extra_notes(self, policy: Policy, claim: Claim) -> str:
        return "Processed"


