class HealthClaimProcessor(ClaimProcessor):
    def max_payout_ratio(self) -> float:
        return 1.0

    def _payout_cap(self, policy: HealthPolicy) -> float:
        remaining_after_deductible = max(policy.coverage_amount - policy.deductible, 0)
