# ---------------------------------------------------------------------------
# PremiumCalculator hierarchy
# ---------------------------------------------------------------------------

class PremiumCalculator(ABC):
    RISK_MULTIPLIER = {
        RiskLevel.LOW: 1.0,
        RiskLevel.MEDIUM: 1.3,
        RiskLevel.HIGH: 1.75,
    }

    def calculate(self, policy: Policy, risk: RiskLevel) -> float:
        base = policy.base_premium
        adjusted = base * self.RISK_MULTIPLIER[risk]
        return round(self._apply_type_factors(policy, adjusted), 2)

    @abstractmethod
    def _apply_type_factors(self, policy: Policy, amount: float) -> float:
        ...


class AutoPremiumCalculator(PremiumCalculator):
    def _apply_type_factors(self, policy: AutoPolicy, amount: float) -> float:
        vehicle_age = date.today().year - policy.vehicle_year
        if vehicle_age < 3:
            amount *= 1.1
        elif vehicle_age > 15:
            amount *= 0.9
        return amount


class HomePremiumCalculator(PremiumCalculator):
    def _apply_type_factors(self, policy: HomePolicy, amount: float) -> float:
        amount += policy.dwelling_value * 0.001
        return amount


class HealthPremiumCalculator(PremiumCalculator):
    def _apply_type_factors(self, policy: HealthPolicy, amount: float) -> float:
        if policy.holder.smoker:
            amount *= 1.5
        amount += max(0, (60 - policy.holder.age) * -0.5 + (policy.holder.age - 60) * 2) \
            if policy.holder.age > 60 else 0
        return amount


class LifePremiumCalculator(PremiumCalculator):
    def _apply_type_factors(self, policy: LifePolicy, amount: float) -> float:
        amount *= (1 + policy.term_years / 100)
        if policy.holder.smoker:
            amount *= 1.6
        return amount


# ---------------------------------------------------------------------------
# RenewalHandler hierarchy
# ---------------------------------------------------------------------------

class RenewalHandler(ABC):
    def __init__(self, calculator: PremiumCalculator, underwriter: Underwriter):
        self.calculator = calculator
        self.underwriter = underwriter

    def renew(self, policy: Policy) -> Policy:
        if not self.is_eligible(policy):
            policy.active = False
            return policy
        risk = self.underwriter.assess_risk(policy)
        new_premium = self.calculator.calculate(policy, risk)
        policy.base_premium = new_premium
        policy.start_date = policy.end_date
        policy.term_days = self._renewal_term()
        return policy

    def is_eligible(self, policy: Policy) -> bool:
        return policy.active and self.underwriter.assess_risk(policy) != RiskLevel.HIGH

    def _renewal_term(self) -> int:
        return 365


class AutoRenewalHandler(RenewalHandler):
    def is_eligible(self, policy: AutoPolicy) -> bool:
