            rendered_body = rendered_body[: self.MAX_LENGTH - 3] + "..."
        return rendered_body


class PushTemplate(Template):
    """Template specialized for Push notifications (title + short body)."""

    def __init__(self, title: str, body: str, icon: Optional[str] = None):
        super().__init__(subject=title, body=body)
        self.icon = icon

    def render(self, **kwargs) -> str:
        rendered_title = self._format(self.subject, **kwargs)
        rendered_body = self._format(self.body, **kwargs)
        return f"{rendered_title}: {rendered_body}"


# ---------------------------
# Notification Hierarchy
# ---------------------------

class Notification(ABC):
    """Base class for all notifications."""

    def __init__(self, recipient: str, template: Template):
        self.recipient = recipient
        self.template = template
        self.sent_at: Optional[datetime] = None
        self.status: str = "pending"

    @abstractmethod
    def send(self, **kwargs) -> bool:
        """Send the notification, rendering the template with kwargs."""
        raise NotImplementedError

    def _mark_sent(self):
        self.sent_at = datetime.now()
        self.status = "sent"

    def _mark_failed(self):
        self.status = "failed"

    def __repr__(self):
        return (f"<{self.__class__.__name__} to={self.recipient} "
                f"status={self.status}>")


class Email(Notification):
    """Email notification, requires an EmailTemplate."""

    def __init__(self, recipient: str, template: EmailTemplate, sender: str = "noreply@example.com"):
        if not isinstance(template, EmailTemplate):
            raise TypeError("Email notification requires an EmailTemplate")
        super().__init__(recipient, template)
        self.sender = sender

    def send(self, **kwargs) -> bool:
        try:
            content = self.template.render(**kwargs)
            html_content = self.template.render_html(**kwargs)
            print(f"[EMAIL] From: {self.sender} To: {self.recipient}")
            print(content)
            if html_content:
                print(f"[HTML VERSION]\n{html_content}")
            self._mark_sent()
            return True
        except Exception as e:
            print(f"Failed to send email: {e}")
            self._mark_failed()
            return False


