class ComplianceEngine:
    def __init__(self):
        self.violations = []
        self.restricted_symbols = set()
        self.max_notional_per_order = 5_000_000

    def restrict_symbol(self, symbol):
        self.restricted_symbols.add(symbol)

    def check_order(self, client, order, price):
        if not client.is_active:
            return False, "Client is not active"
        if not client.kyc_verified:
            return False, "Client KYC not verified"
        if order.symbol in self.restricted_symbols:
            return False, f"Symbol {order.symbol} is restricted"
        if order.symbol in client.blacklisted_symbols:
            return False, f"Symbol {order.symbol} is blacklisted for client"
        if order.quantity <= 0:
            return False, "Invalid order quantity"
        if order.quantity > client.max_order_size:
            return False, "Order exceeds max order size"
        notional = order.quantity * (price or 0)
        if notional > self.max_notional_per_order:
            return False, "Order exceeds max notional limit"
        return True, None

    def log_violation(self, client_id, reason, order_id=None):
        self.violations.append({
