class RiskManager:
    def __init__(self):
        self.position_limits = defaultdict(lambda: float("inf"))

    def set_position_limit(self, symbol, limit):
        self.position_limits[symbol] = limit

    def check_risk(self, client, order, price):
        notional = order.quantity * (price or 0)

        if order.side == OrderSide.BUY:
            required_cash = notional
            if required_cash > client.cash_balance:
                return False, "Insufficient cash balance"

        current_position = client.positions[order.symbol]
        projected_position = current_position + (
            order.quantity if order.side == OrderSide.BUY else -order.quantity
        )
        limit = self.position_limits[order.symbol]
        if abs(projected_position) > limit:
            return False, "Position limit exceeded"

        exposure = sum(
            abs(qty) * (price if sym == order.symbol else client.avg_cost.get(sym, 0))
            for sym, qty in client.positions.items()
        )
        if exposure + notional > client.risk_limit:
            return False, "Risk limit exceeded"

        return True, None


