            total += qty * price
        return total

    @staticmethod
    def get_unrealized_pnl(client, market_data):
        pnl = 0.0
        for symbol, qty in client.positions.items():
            price = market_data.get_price(symbol)
            if price is None:
                continue
            cost = client.avg_cost.get(symbol, 0)
            pnl += (price - cost) * qty
        return pnl

