class TradingPlatform:
    def __init__(self):
        self.market_data = MarketData()
        self.fee_schedule = FeeSchedule()
        self.compliance = ComplianceEngine()
        self.risk_manager = RiskManager()
        self.clients = {}
        self.orders = {}
        self.fills = []
        self.lock = threading.RLock()
        self.audit_log = []
        self.reconciliation_breaks = []

    # ---------- Client Management ----------
    def register_client(self, name, cash_balance=0.0, risk_limit=1_000_000.0,
                         max_order_size=100_000):
        client_id = str(uuid.uuid4())
        client = Client(client_id, name, cash_balance, risk_limit, max_order_size)
        self.clients[client_id] = client
        self._log(f"Client registered: {client_id} ({name})")
        return client_id

    def deactivate_client(self, client_id):
        client = self._get_client(client_id)
        client.is_active = False
        self._log(f"Client deactivated: {client_id}")

    def activate_client(self, client_id):
        client = self._get_client(client_id)
        client.is_active = True
        self._log(f"Client activated: {client_id}")

    def deposit_funds(self, client_id, amount):
        client = self._get_client(client_id)
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")
        client.cash_balance += amount
        self._log(f"Deposit {amount} for client {client_id}")

    def withdraw_funds(self, client_id, amount):
        client = self._get_client(client_id)
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")
        if amount > client.cash_balance:
            raise ValueError("Insufficient balance for withdrawal")
        client.cash_balance -= amount
        self._log(f"Withdrawal {amount} for client {client_id}")

    def blacklist_symbol_for_client(self, client_id, symbol):
        client = self._get_client(client_id)
        client.blacklisted_symbols.add(symbol)

    def _get_client(self, client_id):
        client = self.clients.get(client_id)
        if client is None:
            raise ValueError(f"Unknown client_id: {client_id}")
        return client

    # ---------- Market Data ----------
    def update_market_data(self, symbol, price, bid=None, ask=None):
        self.market_data.update_price(symbol, price, bid, ask)

    def get_market_price(self, symbol):
        return self.market_data.get_price(symbol)

    # ---------- Order Routing & Execution ----------
    def submit_order(self, client_id, symbol, side, quantity, order_type=OrderType.MARKET,
                      price=None, stop_price=None):
        with self.lock:
            client = self._get_client(client_id)
            side_enum = side if isinstance(side, OrderSide) else OrderSide(side)
            type_enum = order_type if isinstance(order_type, OrderType) else OrderType(order_type)

            order = Order(client_id, symbol, side_enum, quantity, type_enum, price, stop_price)
            self.orders[order.order_id] = order
            client.orders[order.order_id] = order

            ref_price = self._determine_reference_price(order)

            passed_compliance, reason = self.compliance.check_order(client, order, ref_price)
            if not passed_compliance:
                order.status = OrderStatus.REJECTED
                order.reject_reason = reason
                self.compliance.log_violation(client_id, reason, order.order_id)
                self._log(f"Order {order.order_id} rejected (compliance): {reason}")
                return order.order_id

            passed_risk, risk_reason = self.risk_manager.check_risk(client, order, ref_price)
            if not passed_risk:
                order.status = OrderStatus.REJECTED
                order.reject_reason = risk_reason
                self.compliance.log_violation(client_id, risk_reason, order.order_id)
                self._log(f"Order {order.order_id} rejected (risk): {risk_reason}")
                return order.order_id

            order.status = OrderStatus.ACCEPTED
            self._log(f"Order {order.order_id} accepted")
            self._route_order(order)
            return order.order_id

    def _determine_reference_price(self, order):
        if order.order_type == OrderType.LIMIT and order.price:
            return order.price
        market_price = self.market_data.get_price(order.symbol)
        if market_price:
            return market_price
        return order.price or order.stop_price or 0.0

    def _route_order(self, order):
        market_price = self.market_data.get_price(order.symbol)

        if order.order_type == OrderType.MARKET:
            if market_price is None:
                order.status = OrderStatus.REJECTED
                order.reject_reason = "No market price available"
                self._log(f"Order {order.order_id} rejected: no market data")
                return
            self._execute_fill(order, order.quantity, market_price, is_maker=False)

        elif order.order_type == OrderType.LIMIT:
            if market_price is None:
                return  # remains accepted, awaiting market data
            can_fill = (
                (order.side == OrderSide.BUY and market_price <= order.price) or
                (order.side == OrderSide.SELL and market_price >= order.price)
            )
            if can_fill:
                self._execute_fill(order, order.quantity, market_price, is_maker=True)

        elif order.order_type == OrderType.STOP:
            if market_price is None:
                return
            triggered = (
                (order.side == OrderSide.BUY and market_price >= order.stop_price) or
                (order.side == OrderSide.SELL and market_price <= order.stop_price)
            )
            if triggered:
                self._execute_fill(order, order.quantity, market_price, is_maker=False)

    def _execute_fill(self, order, quantity, price, is_maker=False):
        client = self._get_client(order.client_id)
        notional = quantity * price
        fee = self.fee_schedule.calculate_fee(notional, is_maker)

        fill = Fill(order.order_id, order.symbol, order.side, quantity, price, fee)
        self.fills.append(fill)
        order.fills.append(fill)

        if order.side == OrderSide.BUY:
            total_cost_before = client.avg_cost[order.symbol] * client.positions[order.symbol]
            new_position = client.positions[order.symbol] + quantity
            total_cost = total_cost_before + notional
            client.avg_cost[order.symbol] = (total_cost / new_position) if new_position != 0 else 0
            client.positions[order.symbol] = new_position
            client.cash_balance -= (notional + fee)
        else:
            client.positions[order.symbol] -= quantity
            client.cash_balance += (notional - fee)

        order.filled_quantity += quantity
        order.remaining_quantity -= quantity
        total_filled_notional = order.avg_fill_price * (order.filled_quantity - quantity) + notional
        order.avg_fill_price = total_filled_notional / order.filled_quantity if order.filled_quantity else 0
        order.updated_at = datetime.utcnow()

        if order.remaining_quantity <= 0:
            order.status = OrderStatus.FILLED
        else:
            order.status = OrderStatus.PARTIALLY_FILLED

        client.trade_history.append(fill)
        self._log(f"Fill executed: order={order.order_id}, qty={quantity}, price={price}, fee={fee}")

    def cancel_order(self, order_id):
        with self.lock:
            order = self.orders.get(order_id)
            if order is None:
                raise ValueError(f"Unknown order_id: {order_id}")
            if order.status in (OrderStatus.FILLED, OrderStatus.CANCELLED, OrderStatus.REJECTED):
                return False
            order.status = OrderStatus.CANCELLED
            order.updated_at = datetime.utcnow()
            self._log(f"Order {order_id} cancelled")
            return True

    def process_pending_orders(self):
        """Re-evaluate accepted/partially-filled limit and stop orders against latest market data."""
        with self.lock:
            for order in list(self.orders.values()):
                if order.status in (OrderStatus.ACCEPTED, OrderStatus.PARTIALLY_FILLED):
                    if order.order_type in (OrderType.LIMIT, OrderType.STOP):
                        self._route_order(order)

    # ---------- Portfolio Tracking ----------
    def get_portfolio_summary(self, client_id):
        client = self._get_client(client_id)
        return {
            "client_id": client_id,
            "cash_balance": client.cash_balance,
            "positions": dict(client.positions),
            "position_value": Portfolio.get_position_value(client, self.market_data),
            "unrealized_pnl": Portfolio.get_unrealized_pnl(client, self.market_data),
            "total_equity": Portfolio.get_total_equity(client, self.market_data),
        }

    def get_position(self, client_id, symbol):
        client = self._get_client(client_id)
        return client.positions.get(symbol, 0.0)

    # ---------- Reporting ----------
    def generate_client_report(self, client_id):
        client = self._get_client(client_id)
        orders_report = [
            {
                "order_id": o.order_id,
                "symbol": o.symbol,
                "side": o.side.value,
                "quantity": o.quantity,
                "filled_quantity": o.filled_quantity,
                "status": o.status.value,
                "avg_fill_price": o.avg_fill_price,
            }
            for o in client.orders.values()
        ]
        fills_report = [
            {
                "fill_id": f.fill_id,
                "order_id": f.order_id,
                "symbol": f.symbol,
                "side": f.side.value,
                "quantity": f.quantity,
                "price": f.price,
                "fee": f.fee,
                "timestamp": f.timestamp.isoformat(),
            }
            for f in client.trade_history
        ]
        return {
            "client_id": client_id,
            "name": client.name,
            "portfolio": self.get_portfolio_summary(client_id),
            "orders": orders_report,
            "fills": fills_report,
        }

    def generate_platform_report(self):
        total_clients = len(self.clients)
        total_orders = len(self.orders)
        total_fills = len(self.fills)
        total_fees_collected = sum(f.fee for f in self.fills)
        total_notional = sum(f.quantity * f.price for f in self.fills)
        return {
            "total_clients": total_clients,
            "total_orders": total_orders,
            "total_fills": total_fills,
            "total_fees_collected": total_fees_collected,
            "total_notional_traded": total_notional,
            "compliance_violations": len(self.compliance.violations),
        }

    # ---------- Compliance Monitoring ----------
    def get_compliance_violations(self, client_id=None):
        if client_id:
            return [v for v in self.compliance.violations if v["client_id"] == client_id]
        return list(self.compliance.violations)

    def restrict_symbol(self, symbol):
        self.compliance.restrict_symbol(symbol)
        self._log(f"Symbol restricted globally: {symbol}")

    def set_client_kyc_status(self, client_id, verified):
        client = self._get_client(client_id)
        client.kyc_verified = verified

    # ---------- Fee Calculation ----------
    def set_fee_schedule(self, maker_fee_bps, taker_fee_bps, min_fee=0.01):
        self.fee_schedule = FeeSchedule(maker_fee_bps, taker_fee_bps, min_fee)

    def calculate_order_fee(self, notional, is_maker=False):
        return self.fee_schedule.calculate_fee(notional, is_maker)

    def get_total_fees_for_client(self, client_id):
        client = self._get_client(client_id)
        return sum(f.fee for f in client.trade_history)

    # ---------- Risk Management ----------
    def set_position_limit(self, symbol, limit):
        self.risk_manager.set_position_limit(symbol, limit)

    def set_client_risk_limit(self, client_id, risk_limit):
        client = self._get_client(client_id)
        client.risk_limit = risk_limit

    def set_client_max_order_size(self, client_id, max_order_size):
        client = self._get_client(client_id)
        client.max_order_size = max_order_size

    # ---------- Reconciliation ----------
    def reconcile(self):
        """
        Reconcile computed positions from fills against tracked client positions,
        and reconcile cash balances against expected cash flows from fills.
        """
        with self.lock:
            self.reconciliation_breaks.clear()
            for client_id, client in self.clients.items():
                computed_positions = defaultdict(float)
                computed_cash_delta = 0.0

                for fill in client.trade_history:
                    if fill.side == OrderSide.BUY:
                        computed_positions[fill.symbol] += fill.quantity
                        computed_cash_delta -= (fill.quantity * fill.price + fill.fee)
                    else:
                        computed_positions[fill.symbol] -= fill.quantity
                        computed_cash_delta += (fill.quantity * fill.price - fill.fee)

                for symbol, computed_qty in computed_positions.items():
                    actual_qty = client.positions.get(symbol, 0.0)
                    if abs(computed_qty - actual_qty) > 1e-6:
                        self.reconciliation_breaks.append({
                            "client_id": client_id,
                            "type": "position",
                            "symbol": symbol,
                            "computed": computed_qty,
                            "actual": actual_qty,
                        })

            self._log(f"Reconciliation completed with {len(self.reconciliation_breaks)} breaks")
            return list(self.reconciliation_breaks)

    def get_reconciliation_breaks(self):
        return list(self.reconciliation_breaks)

    # ---------- Audit / Logging ----------
    def _log(self, message):
        entry = {"timestamp": datetime.utcnow().isoformat(), "message": message}
        self.audit_log.append(entry)

    def get_audit_log(self):
