    def maintenance_margin(self, instrument: Future, quantity: float) -> float:
        return self.initial_margin(instrument, quantity) * 0.80


class ForexMarginCalculator(MarginCalculator):
    def initial_margin(self, instrument: Forex, quantity: float, leverage: float = 50.0) -> float:
        return instrument.notional_value(quantity) / leverage

    def maintenance_margin(self, instrument: Forex, quantity: float) -> float:
        return self.initial_margin(instrument, quantity) * 0.50


# =========================================================================
# SettlementProcessor hierarchy
# =========================================================================

class SettlementProcessor(ABC):
    @abstractmethod
    def settlement_days(self) -> int:
        ...

    def settlement_date(self, trade_date: date) -> date:
        days = self.settlement_days()
        result = trade_date
        added = 0
        while added < days:
            result = date.fromordinal(result.toordinal() + 1)
            if result.weekday() < 5:
                added += 1
        return result

    @abstractmethod
    def process(self, order: Order) -> None:
        ...


class StockSettlementProcessor(SettlementProcessor):
    def settlement_days(self) -> int:
        return 2  # T+2

    def process(self, order: Order) -> None:
        order.status = OrderStatus.SETTLED


class OptionSettlementProcessor(SettlementProcessor):
    def settlement_days(self) -> int:
        return 1  # T+1

    def process(self, order: Order) -> None:
        instrument: Option = order.instrument  # type: ignore
        if instrument.is_itm():
            # simulate exercise/assignment cash settlement
            pass
        order.status = OrderStatus.SETTLED


class FutureSettlementProcessor(SettlementProcessor):
    def settlement_days(self) -> int:
        return 1  # daily mark-to-market, next day settlement

    def process(self, order: Order) -> None:
        # daily variation margin settlement
        order.status = OrderStatus.SETTLED


class ForexSettlementProcessor(SettlementProcessor):
    def settlement_days(self) -> int:
        return 2  # T+2 spot settlement

    def process(self, order: Order) -> None:
        order.status = OrderStatus.SETTLED


# =========================================================================
# ReportGenerator hierarchy
# =========================================================================

class ReportGenerator(ABC):
    def generate_report(self, order: Order) -> str:
        header = self.header(order)
        body = self.body(order)
        return f"{header}\n{body}"

    def header(self, order: Order) -> str:
        return (f"=== {self.__class__.__name__} ===\n"
                f"Order ID: {order.order_id} | Symbol: {order.instrument.symbol} | "
                f"Status: {order.status.value}")

    @abstractmethod
    def body(self, order: Order) -> str:
        ...


class StockReportGenerator(ReportGenerator):
    def body(self, order: Order) -> str:
        inst: Stock = order.instrument  # type: ignore
        return (f"Side: {order.side.value}, Qty: {order.quantity}, "
                f"Fill Price: {order.fill_price}, Dividend Yield: {inst.dividend_yield}")


class OptionReportGenerator(ReportGenerator):
    def body(self, order: Order) -> str:
        inst: Option = order.instrument  # type: ignore
        return (f"Side: {order.side.value}, Qty: {order.quantity}, "
                f"Fill Price: {order.fill_price}, Strike: {inst.strike}, "
                f"Expiry: {inst.expiry}, Type: {inst.option_type.value}, "
                f"ITM: {inst.is_itm()}")


class FutureReportGenerator(ReportGenerator):
    def body(self, order: Order) -> str:
        inst: Future = order.instrument  # type: ignore
        return (f"Side: {order.side.value}, Qty: {order.quantity}, "
                f"Fill Price: {order.fill_price}, Expiry: {inst.expiry}, "
                f"Multiplier: {inst.multiplier}")


class ForexReportGenerator(ReportGenerator):
    def body(self, order: Order) -> str:
        inst: Forex = order.instrument  # type: ignore
        return (f"Side: {order.side.value}, Qty: {order.quantity}, "
                f"Fill Price: {order.fill_price}, Pair: {inst.base_currency}/{inst.quote_currency}")


# =========================================================================
# Factory to wire parallel hierarchies together
# =========================================================================

class TradingComponentFactory:
    _registry = {
        Stock: (StockOrderHandler, StockRiskCalculator, StockMarginCalculator,
                StockSettlementProcessor, StockReportGenerator),
        Option: (OptionOrderHandler, OptionRiskCalculator, OptionMarginCalculator,
                 OptionSettlementProcessor, OptionReportGenerator),
        Future: (FutureOrderHandler, FutureRiskCalculator, FutureMarginCalculator,
                 FutureSettlementProcessor, FutureReportGenerator),
        Forex: (ForexOrderHandler, ForexRiskCalculator, ForexMarginCalculator,
                ForexSettlementProcessor, ForexReportGenerator),
    }

    @classmethod
    def create_suite(cls, instrument_type: type):
        if instrument_type not in cls._registry:
            raise ValueError(f"No components registered for {instrument_type}")
        handler_cls, risk_cls, margin_cls, settle_cls, report_cls = cls._registry[instrument_type]
        return {
            "order_handler": handler_cls(),
            "risk_calculator": risk_cls(),
            "margin_calculator": margin_cls(),
            "settlement_processor": settle_cls(),
            "report_generator": report_cls(),
        }


# =========================================================================
# Example orchestration
# =========================================================================

class TradingWorkflow:
    def __init__(self, instrument: Instrument):
        self.instrument = instrument
        suite = TradingComponentFactory.create_suite(type(instrument))
        self.order_handler: OrderHandler = suite["order_handler"]
        self.risk_calculator: RiskCalculator = suite["risk_calculator"]
        self.margin_calculator: MarginCalculator = suite["margin_calculator"]
        self.settlement_processor: SettlementProcessor = suite["settlement_processor"]
        self.report_generator: ReportGenerator = suite["report_generator"]

    def execute(self, order: Order) -> str:
        order = self.order_handler.handle(order)
        if order.status == OrderStatus.REJECTED:
            return self.report_generator.generate_report(order)

        risk = self.risk_calculator.calculate_risk(order.instrument, order.quantity)
        margin = self.margin_calculator.initial_margin(order.instrument, order.quantity)
        self.settlement_processor.process(order)

        report = self.report_generator.generate_report(order)
        report += f"\nRisk: {risk:.2f} | Initial Margin: {margin:.2f}"
        return report
