        elif len(digits_only) > 15:
            self.errors.append("Phone number is too long.")
        elif not re.match(r"^[\d\s\-\+\(\)]+$", phone):
            self.errors.append("Phone number contains invalid characters.")
        return len(self.errors) == 0

    def validate_address(self, address):
        self.errors = []
        address = self.sanitize_string(address)
        if not address:
            self.errors.append("Address is required.")
        elif len(address) < 5:
            self.errors.append("Address must be at least 5 characters long.")
        elif len(address) > 255:
            self.errors.append("Address must not exceed 255 characters.")
        return len(self.errors) == 0

    def validate_postal_code(self, postal_code):
        self.errors = []
        postal_code = self.sanitize_string(postal_code).upper()
        if not postal_code:
            self.errors.append("Postal code is required.")
        elif not re.match(r"^[A-Z0-9\s\-]{3,10}$", postal_code):
            self.errors.append("Postal code format is invalid.")
        return len(self.errors) == 0

    def validate_tax_id(self, tax_id):
        self.errors = []
        tax_id = self.sanitize_string(tax_id).upper()
        if not tax_id:
            self.errors.append("Tax ID is required.")
        elif not re.match(r"^[A-Z0-9\-]{5,20}$", tax_id):
            self.errors.append("Tax ID format is invalid.")
        return len(self.errors) == 0

    def validate_all(self, data):
        self.errors = []
        all_valid = True

        if not self.validate_name(data.get("name")):
            all_valid = False
        if not self.validate_email(data.get("email")):
            all_valid = False
        if not self.validate_phone(data.get("phone")):
            all_valid = False
        if not self.validate_address(data.get("address")):
            all_valid = False
        if not self.validate_postal_code(data.get("postal_code")):
            all_valid = False
        if not self.validate_tax_id(data.get("tax_id")):
            all_valid = False

        return all_valid

    def get_errors(self):
        return self.errors
