class EntityRepository:
    """Simple in-memory repository."""

    def __init__(self):
        self._entities: Dict[str, Entity] = {}

    def add(self, entity: Entity) -> Entity:
        self._entities[entity.id] = entity
        return entity

    def get(self, entity_id: str) -> Optional[Entity]:
        return self._entities.get(entity_id)

    def all(self) -> List[Entity]:
        return list(self._entities.values())


def main() -> None:
    repo = EntityRepository()
    audit_logger = AuditLogger()
    notification_handler = NotificationHandler()
    workflow_engine = WorkflowEngine(notification_handler, audit_logger)

    e1 = Entity(name="Purchase Order #1001")
    repo.add(e1)

    workflow_engine.transition(e1, EntityStatus.PENDING_APPROVAL, actor="alice")
    workflow_engine.transition(e1, EntityStatus.APPROVED, actor="bob")
    workflow_engine.transition(e1, EntityStatus.ACTIVE, actor="bob")
    workflow_engine.transition(e1, EntityStatus.ON_HOLD, actor="carol")

    print("\n--- API Response ---")
    print(json.dumps(APIResponseBuilder.build(e1), indent=2))

    print("\n--- UI Badge ---")
    print(UIComponents.render_badge(e1))
    print("Available actions:", UIComponents.get_available_actions(e1))
    print("Dropdown options:", UIComponents.render_dropdown_options(e1))

    print("\n--- Report Summary ---")
    print(ReportFilter.summary(repo.all()))

    print("\n--- CSV Export ---")
    print(ExportHandler.to_csv(repo.all()))

    print("\n--- Audit Logs ---")
    for log in audit_logger.get_logs_for_entity(e1.id):
        print(log)


