class AuditLogger:
    """Logs all status transitions with severity classification."""

    SEVERITY_MAP: Dict[EntityStatus, str] = {
        EntityStatus.DRAFT: "INFO",
        EntityStatus.PENDING_APPROVAL: "INFO",
        EntityStatus.APPROVED: "INFO",
        EntityStatus.ACTIVE: "INFO",
        EntityStatus.ON_HOLD: "WARNING",
        EntityStatus.REJECTED: "WARNING",
        EntityStatus.CANCELLED: "CRITICAL",
        EntityStatus.ARCHIVED: "INFO",
    }

    def __init__(self):
        self.logs: List[Dict[str, Any]] = []

    def log_transition(
        self, entity: Entity, old_status: EntityStatus, new_status: EntityStatus, actor: str
    ) -> None:
        severity = self.SEVERITY_MAP.get(new_status, "INFO")
        entry = {
            "entity_id": entity.id,
            "entity_name": entity.name,
            "actor": actor,
            "from_status": old_status.value,
            "to_status": new_status.value,
            "severity": severity,
            "timestamp": datetime.utcnow().isoformat(),
        }
        self.logs.append(entry)
        print(f"[AUDIT:{severity}] {entry['entity_name']}: {old_status.value} -> {new_status.value} by {actor}")

    def get_logs_for_entity(self, entity_id: str) -> List[Dict[str, Any]]:
        return [log for log in self.logs if log["entity_id"] == entity_id]

    def get_logs_by_severity(self, severity: str) -> List[Dict[str, Any]]:
        return [log for log in self.logs if log["severity"] == severity]


