import json
import uuid
import hashlib
import copy
import statistics
import datetime
from collections import defaultdict


class ResearchPlatform:
    def __init__(self, name="ResearchPlatform"):
        self.name = name
        self.experiments = {}
        self.datasets = {}
        self.analyses = {}
        self.visualizations = {}
        self.collaborators = {}
        self.publications = {}
        self.archive = {}
        self.reproducibility_log = []
        self.audit_trail = []
        self.pipelines = {}

    # ---------- Utility ----------

    def _now(self):
        return datetime.datetime.utcnow().isoformat()

    def _new_id(self, prefix):
        return f"{prefix}_{uuid.uuid4().hex[:10]}"

    def _log_event(self, event_type, details):
        entry = {
            "id": self._new_id("evt"),
            "timestamp": self._now(),
            "type": event_type,
            "details": details,
        }
        self.audit_trail.append(entry)
        return entry

    def _hash_data(self, data):
        serialized = json.dumps(data, sort_keys=True, default=str).encode("utf-8")
        return hashlib.sha256(serialized).hexdigest()

    # ---------- Experiment Design ----------

    def design_experiment(self, title, hypothesis, variables, methodology,
                           sample_size=None, controls=None, owner=None):
        exp_id = self._new_id("exp")
        experiment = {
            "id": exp_id,
            "title": title,
            "hypothesis": hypothesis,
            "variables": variables,
            "methodology": methodology,
            "sample_size": sample_size,
            "controls": controls or [],
            "owner": owner,
            "status": "designed",
            "created_at": self._now(),
            "revisions": [],
            "datasets": [],
            "analyses": [],
        }
        self.experiments[exp_id] = experiment
        self._log_event("experiment_designed", {"experiment_id": exp_id, "title": title})
        return exp_id

    def revise_experiment(self, exp_id, **updates):
        experiment = self._require(self.experiments, exp_id, "Experiment")
        revision = {
            "timestamp": self._now(),
            "previous_state": copy.deepcopy(experiment),
        }
        for key, value in updates.items():
            if key in experiment and key not in ("id", "created_at"):
                experiment[key] = value
        experiment["revisions"].append(revision)
        self._log_event("experiment_revised", {"experiment_id": exp_id, "updates": updates})
        return experiment

    def approve_experiment(self, exp_id, approver):
        experiment = self._require(self.experiments, exp_id, "Experiment")
        experiment["status"] = "approved"
        experiment["approved_by"] = approver
        experiment["approved_at"] = self._now()
        self._log_event("experiment_approved", {"experiment_id": exp_id, "approver": approver})
        return experiment

    # ---------- Data Collection ----------

    def collect_data(self, exp_id, dataset_name, records, source=None, collector=None):
        experiment = self._require(self.experiments, exp_id, "Experiment")
        dataset_id = self._new_id("ds")
        checksum = self._hash_data(records)
        dataset = {
            "id": dataset_id,
            "experiment_id": exp_id,
            "name": dataset_name,
            "records": records,
            "source": source,
            "collector": collector,
            "collected_at": self._now(),
            "checksum": checksum,
            "version": 1,
            "history": [],
        }
        self.datasets[dataset_id] = dataset
        experiment["datasets"].append(dataset_id)
        self._log_event("data_collected", {
            "experiment_id": exp_id, "dataset_id": dataset_id, "n_records": len(records)
        })
        return dataset_id

    def append_data(self, dataset_id, new_records, collector=None):
        dataset = self._require(self.datasets, dataset_id, "Dataset")
        dataset["history"].append({
            "timestamp": self._now(),
            "action": "append",
            "n_records_added": len(new_records),
            "previous_checksum": dataset["checksum"],
        })
        dataset["records"].extend(new_records)
        dataset["checksum"] = self._hash_data(dataset["records"])
        dataset["version"] += 1
        self._log_event("data_appended", {
            "dataset_id": dataset_id, "n_new_records": len(new_records), "collector": collector
        })
        return dataset

    def validate_dataset(self, dataset_id, required_fields):
        dataset = self._require(self.datasets, dataset_id, "Dataset")
        errors = []
        for i, record in enumerate(dataset["records"]):
            missing = [f for f in required_fields if f not in record]
            if missing:
                errors.append({"index": i, "missing_fields": missing})
        result = {"valid": len(errors) == 0, "errors": errors}
        self._log_event("data_validated", {"dataset_id": dataset_id, "result": result})
        return result

    # ---------- Analysis Pipelines ----------

    def register_pipeline(self, pipeline_name, steps):
        """
        steps: list of callables, each taking and returning a data structure
        """
        pipeline_id = self._new_id("pipe")
        self.pipelines[pipeline_id] = {
            "id": pipeline_id,
            "name": pipeline_name,
            "steps": steps,
            "created_at": self._now(),
        }
        self._log_event("pipeline_registered", {"pipeline_id": pipeline_id, "name": pipeline_name})
        return pipeline_id

    def run_pipeline(self, pipeline_id, dataset_id, analyst=None):
        pipeline = self._require(self.pipelines, pipeline_id, "Pipeline")
        dataset = self._require(self.datasets, dataset_id, "Dataset")

        data = copy.deepcopy(dataset["records"])
        step_log = []
        for i, step in enumerate(pipeline["steps"]):
            try:
                data = step(data)
                step_log.append({"step_index": i, "step_name": getattr(step, "__name__", str(step)), "status": "success"})
            except Exception as e:
                step_log.append({"step_index": i, "step_name": getattr(step, "__name__", str(step)),
                                  "status": "failed", "error": str(e)})
                break

        analysis_id = self._new_id("ana")
        analysis = {
            "id": analysis_id,
            "pipeline_id": pipeline_id,
            "dataset_id": dataset_id,
            "analyst": analyst,
            "result": data,
            "step_log": step_log,
            "created_at": self._now(),
            "input_checksum": dataset["checksum"],
        }
        self.analyses[analysis_id] = analysis

        exp_id = dataset["experiment_id"]
        if exp_id in self.experiments:
            self.experiments[exp_id]["analyses"].append(analysis_id)

        self._log_event("pipeline_run", {
            "pipeline_id": pipeline_id, "dataset_id": dataset_id, "analysis_id": analysis_id
        })
        self._record_reproducibility(analysis_id)
        return analysis_id

    def summarize_analysis(self, analysis_id, numeric_field):
        analysis = self._require(self.analyses, analysis_id, "Analysis")
        values = [r[numeric_field] for r in analysis["result"] if isinstance(r, dict) and numeric_field in r]
        if not values:
            return {"count": 0}
        summary = {
            "count": len(values),
            "mean": statistics.mean(values),
            "median": statistics.median(values),
            "stdev": statistics.stdev(values) if len(values) > 1 else 0.0,
            "min": min(values),
            "max": max(values),
        }
        analysis.setdefault("summaries", {})[numeric_field] = summary
        return summary

    # ---------- Visualization ----------

    def create_visualization(self, analysis_id, viz_type, field, title=None):
        analysis = self._require(self.analyses, analysis_id, "Analysis")
        viz_id = self._new_id("viz")

        values = [r[field] for r in analysis["result"] if isinstance(r, dict) and field in r]

        viz_spec = {
            "id": viz_id,
            "analysis_id": analysis_id,
            "type": viz_type,
            "field": field,
            "title": title or f"{viz_type} of {field}",
            "data": values,
            "created_at": self._now(),
        }
        self.visualizations[viz_id] = viz_spec
        self._log_event("visualization_created", {"viz_id": viz_id, "analysis_id": analysis_id, "type": viz_type})
        return viz_id

    def render_visualization_spec(self, viz_id):
        viz = self._require(self.visualizations, viz_id, "Visualization")
        return {
            "title": viz["title"],
            "type": viz["type"],
            "field": viz["field"],
            "data_points": len(viz["data"]),
            "preview": viz["data"][:10],
        }

    # ---------- Collaboration ----------

    def add_collaborator(self, exp_id, name, role="contributor", permissions=None):
        experiment = self._require(self.experiments, exp_id, "Experiment")
        collab_id = self._new_id("collab")
        collaborator = {
            "id": collab_id,
            "experiment_id": exp_id,
            "name": name,
            "role": role,
            "permissions": permissions or ["read"],
            "added_at": self._now(),
        }
        self.collaborators[collab_id] = collaborator
        self._log_event("collaborator_added", {"experiment_id": exp_id, "name": name, "role": role})
        return collab_id

    def update_permissions(self, collab_id, permissions):
        collaborator = self._require(self.collaborators, collab_id, "Collaborator")
        collaborator["permissions"] = permissions
        self._log_event("permissions_updated", {"collab_id": collab_id, "permissions": permissions})
        return collaborator

    def leave_comment(self, exp_id, author, message):
        experiment = self._require(self.experiments, exp_id, "Experiment")
        comment = {
            "id": self._new_id("cmt"),
            "author": author,
            "message": message,
            "timestamp": self._now(),
        }
        experiment.setdefault("comments", []).append(comment)
        self._log_event("comment_added", {"experiment_id": exp_id, "author": author})
        return comment

    def list_collaborators(self, exp_id):
        return [c for c in self.collaborators.values() if c["experiment_id"] == exp_id]

    # ---------- Publication Workflow ----------

    def draft_publication(self, exp_id, title, authors, abstract, analysis_ids=None):
        experiment = self._require(self.experiments, exp_id, "Experiment")
        pub_id = self._new_id("pub")
        publication = {
            "id": pub_id,
            "experiment_id": exp_id,
            "title": title,
            "authors": authors,
            "abstract": abstract,
            "analysis_ids": analysis_ids or [],
            "status": "draft",
            "created_at": self._now(),
            "review_history": [],
        }
        self.publications[pub_id] = publication
        self._log_event("publication_drafted", {"pub_id": pub_id, "experiment_id": exp_id, "title": title})
        return pub_id

    def submit_for_review(self, pub_id):
        publication = self._require(self.publications, pub_id, "Publication")
        publication["status"] = "under_review"
        publication["review_history"].append({"timestamp": self._now(), "event": "submitted"})
        self._log_event("publication_submitted", {"pub_id": pub_id})
        return publication

    def review_publication(self, pub_id, reviewer, decision, comments=None):
        publication = self._require(self.publications, pub_id, "Publication")
        if decision not in ("approve", "reject", "revise"):
            raise ValueError("decision must be 'approve', 'reject', or 'revise'")

        review_entry = {
            "timestamp": self._now(),
            "reviewer": reviewer,
            "decision": decision,
            "comments": comments,
        }
        publication["review_history"].append(review_entry)

        status_map = {"approve": "accepted", "reject": "rejected", "revise": "revision_requested"}
        publication["status"] = status_map[decision]

