@dataclass
class DoseSchedule:
    """Represents a medication dosing schedule."""
    frequency: DoseFrequency
    start: datetime
    duration_days: Optional[float] = None
    max_doses: Optional[int] = None
    first_dose_immediate: bool = True

    def __post_init__(self):
        if self.duration_days is not None and self.duration_days <= 0:
            raise DosingError("duration_days must be positive")
        if self.max_doses is not None and self.max_doses <= 0:
            raise DosingError("max_doses must be positive")

    def _end_time(self) -> Optional[datetime]:
        if self.duration_days is not None:
            return self.start + timedelta(days=self.duration_days)
        return None

    def scheduled_times(self) -> List[datetime]:
        """Generate all scheduled dose times based on constraints."""
        interval = timedelta(hours=self.frequency.interval_hours)
        end_time = self._end_time()

        if end_time is None and self.max_doses is None:
            raise DosingError(
                "Must specify duration_days or max_doses to enumerate doses"
            )

        times = []
        current = self.start
        count = 0
        while True:
            if end_time is not None and current > end_time:
                break
            if self.max_doses is not None and count >= self.max_doses:
                break
            times.append(current)
            count += 1
            current = current + interval
        return times

    def next_dose_after(self, reference: Union[date, datetime]) -> Optional[datetime]:
        """Find the next scheduled dose strictly after the reference time."""
        ref_dt = _to_datetime(reference)
        interval = timedelta(hours=self.frequency.interval_hours)
        if ref_dt < self.start:
            return self.start
        elapsed = ref_dt - self.start
        intervals_passed = math.floor(elapsed / interval) + 1
        candidate = self.start + intervals_passed * interval

        end_time = self._end_time()
        if end_time is not None and candidate > end_time:
            return None
        if self.max_doses is not None:
            dose_index = intervals_passed
            if dose_index >= self.max_doses:
                return None
        return candidate

    def doses_remaining(self, reference: Optional[Union[date, datetime]] = None) -> int:
        """Count doses remaining after a reference time (default now)."""
        ref_dt = _to_datetime(reference) if reference else datetime.now()
        all_times = self.scheduled_times()
        return sum(1 for t in all_times if t > ref_dt)

    def is_dose_due(
        self,
        reference: Optional[Union[date, datetime]] = None,
        tolerance_minutes: int = 30,
    ) -> bool:
        """Check whether a dose is due within tolerance window of reference time."""
        ref_dt = _to_datetime(reference) if reference else datetime.now()
        tolerance = timedelta(minutes=tolerance_minutes)
        for t in self.scheduled_times():
            if abs((t - ref_dt).total_seconds()) <= tolerance.total_seconds():
                return True
        return False


def check_dosing_interval_safety(
    last_dose: Union[date, datetime],
    proposed_dose: Union[date, datetime],
    minimum_interval_hours: float,
) -> Tuple[bool, timedelta]:
    """
    Verify that the time between doses meets a minimum safe interval.
    Returns (is_safe, actual_interval).
    """
    last_dt = _to_datetime(last_dose)
    proposed_dt = _to_datetime(proposed_dose)
    if proposed_dt < last_dt:
        raise DosingError("Proposed dose time precedes last dose time")
    actual_interval = proposed_dt - last_dt
    is_safe = actual_interval >= timedelta(hours=minimum_interval_hours)
    return is_safe, actual_interval


