class ClinicalDateTime:
    """
    High-level facade combining gestational age, dosing, and window
    utilities for convenient access in clinical applications.
    """

    def __init__(self):
        self._windows: List[ClinicalTimeWindow] = []

    def add_window(self, window: ClinicalTimeWindow) -> None:
        self._windows.append(window)

    def active_windows(
        self, moment: Optional[Union[date, datetime]] = None
    ) -> List[ClinicalTimeWindow]:
        moment_dt = _to_datetime(moment) if moment else datetime.now()
        return [w for w in self._windows if w.is_within(moment_dt)]

    @staticmethod
    def gestational_calculator(**kwargs) -> GestationalCalculator:
        return GestationalCalculator(**kwargs)

