    """
    Configure and validate an ETL data pipeline definition.

    Returns a dict representing the fully assembled pipeline configuration,
    including defaults, validation results, and derived metadata.
    """

    errors = []
    warnings = []

    VALID_SOURCE_TYPES = {
        "database", "file", "api", "stream", "warehouse", "s3", "gcs",
        "azure_blob", "kafka", "sftp", "queue"
    }
    VALID_DESTINATION_TYPES = {
