    if not isinstance(destination_config, dict):
        add_error("destination_config must be a dictionary.")
        destination_config = {}

    if not isinstance(schema_mapping, dict):
        add_error("schema_mapping must be a dictionary mapping source fields to destination fields.")
        schema_mapping = {}

    if transformations is None:
        transformations = []
    if not isinstance(transformations, list):
        add_error("transformations must be a list of transformation definitions.")
        transformations = []

    if validations is None:
        validations = []
    if not isinstance(validations, list):
        add_error("validations must be a list of validation rules.")
