    # ---------- error handling ----------

    if isinstance(error_handling, str):
        error_handling = {"strategy": error_handling}
    if not isinstance(error_handling, dict):
        add_error("error_handling must be a dict or string strategy name.")
        error_handling = {}

    strategy = error_handling.get("strategy", "fail_fast")
    if strategy not in VALID_ERROR_STRATEGIES:
        add_error(f"error_handling.strategy '{strategy}' invalid. Valid: {sorted(VALID_ERROR_STRATEGIES)}")
        strategy = "fail_fast"

    error_handling_config = {
        "strategy": strategy,
        "max_error_rate": error_handling.get("max_error_rate", 0.0),
        "dead_letter_location": error_handling.get("dead_letter_location"),
        "log_errors": error_handling.get("log_errors", True),
