    # ---------- retry policy ----------

    if retry_policy is None:
        retry_policy = {}
    if not isinstance(retry_policy, dict):
        add_error("retry_policy must be a dictionary.")
        retry_policy = {}

    max_retries = retry_policy.get("max_retries", 3)
    backoff_strategy = retry_policy.get("backoff_strategy", "exponential")
    initial_delay_seconds = retry_policy.get("initial_delay_seconds", 5)
    max_delay_seconds = retry_policy.get("max_delay_seconds", 300)

