    email_pattern = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
    valid_recipients = []
    for r in alert_recipients:
        if isinstance(r, str) and (email_pattern.match(r) or r.startswith("http") or ":" in r):
            valid_recipients.append(r)
        else:
            add_warning(f"alert_recipient '{r}' does not look like a valid email/webhook/channel; keeping anyway.")
            valid_recipients.append(r)

    if monitoring_enabled and not valid_recipients:
        add_warning("monitoring_enabled is True but no alert_recipients were provided.")

    # ---------- logging ----------

    if not isinstance(logging_level, str) or logging_level.upper() not in VALID_LOG_LEVELS:
        add_warning(f"logging_level '{logging_level}' invalid; defaulting to 'INFO'.")
        logging_level = "INFO"
    else:
