    if not isinstance(partitioning, dict):
        add_error("partitioning must be a dict, string column name, or None.")
        partitioning = {"enabled": False}

    partitioning_config = {
        "enabled": partitioning.get("enabled", bool(partitioning.get("column"))),
        "column": partitioning.get("column"),
        "strategy": partitioning.get("strategy", "date"),
        "granularity": partitioning.get("granularity", "day"),
