    if partitioning_config["enabled"] and not is_non_empty_str(partitioning_config["column"]):
        add_error("partitioning.column is required when partitioning is enabled.")

    # ---------- deduplication ----------

    if deduplication is None:
        deduplication = {"enabled": False}
    if isinstance(deduplication, bool):
        deduplication = {"enabled": deduplication}
    if not isinstance(deduplication, dict):
        add_error("deduplication must be a dict or boolean.")
        deduplication = {"enabled": False}

    dedup_config = {
