        engagement_frequency = behaviors.get('engagement_frequency', 0.5)
        avg_session_duration = behaviors.get('avg_session_duration', 0)
        device_diversity = len(behaviors.get('devices', []))

        score = (purchase_intent * 0.4) + (engagement_frequency * 0.3)
        score += min(avg_session_duration / 300, 1.0) * 0.2
        score += min(device_diversity / 3, 1.0) * 0.1

        return max(0.0, min(1.0, score))

    def _score_conversions(self, conversions):
        if not conversions:
            return 0.5

        conversion_value = conversions.get('total_value', 0)
        conversion_count = conversions.get('count', 0)
        cost_per_conversion = conversions.get('cost_per_conversion', float('inf'))
        conversion_velocity = conversions.get('velocity_trend', 0.0)

        score = 0.0
        if conversion_count > 0:
            score += min(conversion_count / 100, 1.0) * 0.3

        if conversion_value > 0:
            score += min(conversion_value / 10000, 1.0) * 0.3

        if cost_per_conversion < float('inf') and cost_per_conversion > 0:
            efficiency = 1.0 / (1.0 + cost_per_conversion / 50)
            score += efficiency * 0.3

        score += max(-0.1, min(0.1, conversion_velocity))

        return max(0.0, min(1.0, score))

    def _score_market_trends(self, trends):
        if not trends:
            return 0.5

        growth_rate = trends.get('industry_growth_rate', 0.0)
        seasonality_factor = trends.get('seasonality_factor', 1.0)
        demand_index = trends.get('demand_index', 0.5)

        score = 0.0
        score += max(0.0, min(1.0, (growth_rate + 0.5))) * 0.4
        score += max(0.0, min(2.0, seasonality_factor)) / 2 * 0.3
        score += max(0.0, min(1.0, demand_index)) * 0.3

        return max(0.0, min(1.0, score))

    def _score_competitor_activity(self, competitor):
        if not competitor:
            return 0.5

        competitor_spend_trend = competitor.get('spend_trend', 0.0)
        market_share = competitor.get('our_market_share', 0.5)
        competitive_pressure = competitor.get('pressure_index', 0.5)

        score = 0.5
        score -= max(-0.2, min(0.2, competitor_spend_trend * 0.2))
        score += max(0.0, min(1.0, market_share)) * 0.3
        score -= max(0.0, min(0.3, competitive_pressure * 0.3))

        return max(0.0, min(1.0, score))

    def _apply_budget_constraints(self, recommended_budget, constraints):
        if not constraints:
            return recommended_budget

        min_budget = constraints.get('min_budget', self.min_budget)
        max_budget = constraints.get('max_budget', float('inf'))
        daily_cap = constraints.get('daily_cap', float('inf'))
        total_budget_remaining = constraints.get('total_remaining', float('inf'))

        adjusted = max(min_budget, recommended_budget)
        adjusted = min(adjusted, max_budget)
        adjusted = min(adjusted, daily_cap)
        adjusted = min(adjusted, total_budget_remaining)

        return max(self.min_budget, adjusted)

    def _determine_targeting_adjustments(self, scores):
        adjustments = {}

        if scores['performance'] < 0.4:
            adjustments['performance_action'] = 'reduce_scope'
        elif scores['performance'] > 0.7:
            adjustments['performance_action'] = 'expand_scope'
        else:
            adjustments['performance_action'] = 'maintain'

        if scores['demographics'] < 0.4:
            adjustments['demographic_action'] = 'broaden_segments'
        else:
            adjustments['demographic_action'] = 'refine_segments'

        if scores['behaviors'] > 0.6:
            adjustments['behavior_action'] = 'increase_bid_for_high_intent'
        else:
            adjustments['behavior_action'] = 'test_new_creatives'

        if scores['conversions'] < 0.4:
            adjustments['conversion_action'] = 'optimize_funnel'
        else:
            adjustments['conversion_action'] = 'scale_winning_segments'

        if scores['market_trends'] > 0.6:
            adjustments['market_action'] = 'increase_investment'
        else:
            adjustments['market_action'] = 'maintain_investment'

        if scores['competitor_activity'] < 0.4:
            adjustments['competitive_action'] = 'defensive_bidding'
        else:
            adjustments['competitive_action'] = 'aggressive_expansion'

        return adjustments

    def optimize_targeting(self, campaign_data, audience_data, market_data,
                            competitor_data, budget_data, current_budget=None):
        performance = self._get(campaign_data, 'performance', {}) or {}
        demographics = self._get(audience_data, 'demographics', {}) or {}
        behaviors = self._get(audience_data, 'behaviors', {}) or {}
        conversions = self._get(audience_data, 'conversions', {}) or {}
        trends = self._get(market_data, 'trends', {}) or {}
        competitor_activity = self._get(competitor_data, 'activity', {}) or {}
        constraints = self._get(budget_data, 'constraints', {}) or {}

        scores = {
            'performance': self._score_performance(performance),
            'demographics': self._score_demographics(demographics),
            'behaviors': self._score_behaviors(behaviors),
            'conversions': self._score_conversions(conversions),
            'market_trends': self._score_market_trends(trends),
            'competitor_activity': self._score_competitor_activity(competitor_activity),
        }

        weights = {
            'performance': 0.25,
            'demographics': 0.15,
            'behaviors': 0.15,
            'conversions': 0.25,
            'market_trends': 0.10,
            'competitor_activity': 0.10,
        }

        overall_score = sum(scores[k] * weights[k] for k in scores)

        if current_budget is None:
            current_budget = constraints.get('current_budget', 100.0)

        budget_multiplier = 0.5 + overall_score
        recommended_budget = current_budget * budget_multiplier
        final_budget = self._apply_budget_constraints(recommended_budget, constraints)

        adjustments = self._determine_targeting_adjustments(scores)

        if overall_score >= 0.7:
            priority = 'high'
        elif overall_score >= 0.4:
            priority = 'medium'
        else:
            priority = 'low'

        recommendations = []
        for key, action in adjustments.items():
            recommendations.append({
                'category': key,
                'action': action
            })

        return {
            'overall_score': round(overall_score, 4),
            'component_scores': {k: round(v, 4) for k, v in scores.items()},
            'recommended_budget': round(final_budget, 2),
            'budget_change_pct': round(
                ((final_budget - current_budget) / current_budget * 100)
                if current_budget > 0 else 0.0, 2
            ),
            'priority': priority,
            'adjustments': adjustments,
            'recommendations': recommendations,
        }
