    """
    Apply a dict of {field: value} equality filters to a dataset and
    return the filtered rows without mutating the cache.
    """
    rows = get_dataset(name)
    if not filters:
        return list(rows)

    def matches(row):
        for field, value in filters.items():
            if row.get(field) != value:
                return False
        return True

    return [row for row in rows if matches(row)]


