import hashlib
import json
import os
import pickle
import sqlite3
import threading
import time
from typing import Any, Optional, List


class CacheBackendError(Exception):
    """Raised when a cache backend operation fails."""
    pass


class BaseCacheBackend:
    """Abstract base class for all cache backends."""

    name = "base"

    def get(self, key: str) -> Any:
        raise NotImplementedError

    def set(self, key: str, value: Any, ttl: Optional[int] = None) -> None:
        raise NotImplementedError

    def delete(self, key: str) -> None:
        raise NotImplementedError

    def clear(self) -> None:
        raise NotImplementedError

    def exists(self, key: str) -> bool:
        raise NotImplementedError

    def ping(self) -> bool:
        raise NotImplementedError

    def close(self) -> None:
        pass


class DictCacheBackend(BaseCacheBackend):
    """Simple in-memory dictionary cache backend (thread-safe, TTL supported)."""

    name = "dict"

    def __init__(self):
        self._store = {}
        self._lock = threading.RLock()

    def _is_expired(self, entry) -> bool:
        expires_at = entry[1]
        return expires_at is not None and time.time() > expires_at

    def get(self, key: str) -> Any:
        with self._lock:
            entry = self._store.get(key)
            if entry is None:
                return None
            if self._is_expired(entry):
                del self._store[key]
                return None
            return entry[0]

    def set(self, key: str, value: Any, ttl: Optional[int] = None) -> None:
        with self._lock:
            expires_at = time.time() + ttl if ttl else None
            self._store[key] = (value, expires_at)

    def delete(self, key: str) -> None:
        with self._lock:
            self._store.pop(key, None)

    def clear(self) -> None:
        with self._lock:
            self._store.clear()

    def exists(self, key: str) -> bool:
        with self._lock:
            entry = self._store.get(key)
            if entry is None:
                return False
            if self._is_expired(entry):
                del self._store[key]
                return False
            return True

    def ping(self) -> bool:
        return True

    def close(self) -> None:
        with self._lock:
            self._store.clear()


class RedisCacheBackend(BaseCacheBackend):
    """Redis-backed cache. Requires the `redis` package."""

    name = "redis"

    def __init__(self, host="localhost", port=6379, db=0, password=None,
                 socket_timeout=2, **kwargs):
        try:
            import redis
        except ImportError as exc:
            raise CacheBackendError(
                "The 'redis' package is required for RedisCacheBackend."
            ) from exc

        self._redis_module = redis
        try:
            self._client = redis.Redis(
                host=host,
                port=port,
                db=db,
                password=password,
                socket_timeout=socket_timeout,
                socket_connect_timeout=socket_timeout,
                **kwargs,
            )
            self._client.ping()
        except Exception as exc:
            raise CacheBackendError(f"Could not connect to Redis: {exc}") from exc

    def get(self, key: str) -> Any:
        try:
            raw = self._client.get(key)
            if raw is None:
                return None
            return pickle.loads(raw)
        except Exception as exc:
            raise CacheBackendError(f"Redis get failed: {exc}") from exc

    def set(self, key: str, value: Any, ttl: Optional[int] = None) -> None:
        try:
            raw = pickle.dumps(value)
            if ttl:
                self._client.setex(key, ttl, raw)
            else:
                self._client.set(key, raw)
        except Exception as exc:
            raise CacheBackendError(f"Redis set failed: {exc}") from exc

    def delete(self, key: str) -> None:
        try:
            self._client.delete(key)
        except Exception as exc:
            raise CacheBackendError(f"Redis delete failed: {exc}") from exc

    def clear(self) -> None:
        try:
            self._client.flushdb()
        except Exception as exc:
            raise CacheBackendError(f"Redis clear failed: {exc}") from exc

    def exists(self, key: str) -> bool:
        try:
            return bool(self._client.exists(key))
        except Exception as exc:
            raise CacheBackendError(f"Redis exists failed: {exc}") from exc

    def ping(self) -> bool:
        try:
            return bool(self._client.ping())
        except Exception:
            return False

    def close(self) -> None:
        try:
            self._client.close()
