    def exists(self, key: str) -> bool:
        try:
            return self._client.get(key) is not None
        except Exception as exc:
            raise CacheBackendError(f"Memcached exists failed: {exc}") from exc

    def ping(self) -> bool:
        try:
            self._client.version()
