class InventoryManager:
    def __init__(self):
        self._stock_levels = {}
        self._reserved_items = defaultdict(int)
        self._reorder_triggers = {}
        self._supplier_queues = defaultdict(deque)
        self._lock = threading.RLock()
        self._id_counter = itertools.count(1)
        self._history = []

    def add_product(self, sku, initial_stock=0, reorder_threshold=10, supplier_id=None):
        with self._lock:
            self._stock_levels[sku] = initial_stock
            self._reserved_items[sku] = 0
            self._reorder_triggers[sku] = reorder_threshold
            if supplier_id is not None:
                self._supplier_queues[supplier_id].append(sku)
            self._history.append((datetime.utcnow(), sku, "add_product", initial_stock))

    def get_available_stock(self, sku):
        with self._lock:
            total = self._stock_levels.get(sku, 0)
            reserved = self._reserved_items.get(sku, 0)
            return max(total - reserved, 0)

    def get_total_stock(self, sku):
        with self._lock:
            return self._stock_levels.get(sku, 0)

    def get_reserved(self, sku):
        with self._lock:
            return self._reserved_items.get(sku, 0)

    def restock(self, sku, quantity):
        with self._lock:
            if sku not in self._stock_levels:
                raise KeyError(f"Unknown SKU: {sku}")
            self._stock_levels[sku] += quantity
            self._history.append((datetime.utcnow(), sku, "restock", quantity))

    def set_reorder_threshold(self, sku, threshold):
        with self._lock:
            self._reorder_triggers[sku] = threshold

    def queue_supplier_order(self, supplier_id, sku):
        with self._lock:
            self._supplier_queues[supplier_id].append(sku)

    def next_id(self):
