        if column is not None:
            if column not in self._obj.columns:
                raise KeyError(f"Column '{column}' not found in DataFrame")
            return self._obj[column]
        if isinstance(self._obj, pd.Series):
            return self._obj
        if self._obj.shape[1] == 1:
