    # Returns
    # ------------------------------------------------------------------
    def returns(self, column=None, periods=1, log=False):
        """Compute simple or log returns."""
        series = self._get_series(column)
        if log:
            result = np.log(series / series.shift(periods))
        else:
            result = series.pct_change(periods=periods)
        return result.rename("returns")

    def cumulative_returns(self, column=None, log=False):
        """Compute cumulative returns series."""
        rets = self.returns(column=column, log=log)
        if log:
            cum = rets.cumsum()
            cum = np.exp(cum) - 1
        else:
            cum = (1 + rets.fillna(0)).cumprod() - 1
        return cum.rename("cumulative_returns")

    def total_return(self, column=None):
        """Compute total return over the entire period."""
        series = self._get_series(column).dropna()
        if len(series) < 2:
            return np.nan
        return series.iloc[-1] / series.iloc[0] - 1

    def annualized_return(self, column=None, periods_per_year=252):
        """Compute CAGR-style annualized return."""
        series = self._get_series(column).dropna()
        n = len(series)
        if n < 2:
            return np.nan
        total_ret = series.iloc[-1] / series.iloc[0]
        years = n / periods_per_year
        if years <= 0:
            return np.nan
        return total_ret ** (1 / years) - 1

