    # Moving averages / smoothing
    # ------------------------------------------------------------------
    def sma(self, column=None, window=20):
        """Simple Moving Average."""
        series = self._get_series(column)
        return series.rolling(window=window, min_periods=window).mean().rename(
            f"sma_{window}"
