    def rolling_std(self, column=None, window=20):
        """Rolling standard deviation of price/level series."""
        series = self._get_series(column)
        return series.rolling(window=window).std().rename(f"rolling_std_{window}")

    # ------------------------------------------------------------------
    # Bollinger Bands
    # ------------------------------------------------------------------
    def bollinger_bands(self, column=None, window=20, num_std=2.0):
        """Compute Bollinger Bands. Returns DataFrame with middle/upper/lower bands."""
        series = self._get_series(column)
        mid = series.rolling(window=window).mean()
        std = series.rolling(window=window).std()
        upper = mid + num_std * std
        lower = mid - num_std * std
        return pd.DataFrame(
            {
                "bb_mid": mid,
                "bb_upper": upper,
                "bb_lower": lower,
            },
            index=series.index,
        )

    # ------------------------------------------------------------------
    # Momentum indicators
    # ------------------------------------------------------------------
    def rsi(self, column=None, window=14):
        """Relative Strength Index."""
        series = self._get_series(column)
        delta = series.diff()
        gain = delta.clip(lower=0)
        loss = -delta.clip(upper=0)

        avg_gain = gain.ewm(alpha=1 / window, min_periods=window, adjust=False).mean()
        avg_loss = loss.ewm(alpha=1 / window, min_periods=window, adjust=False).mean()

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        rsi = rsi.where(avg_loss != 0, 100)
        return rsi.rename(f"rsi_{window}")

    def macd(self, column=None, fast=12, slow=26, signal=9):
        """MACD indicator. Returns DataFrame with macd, signal, histogram."""
        series = self._get_series(column)
        ema_fast = series.ewm(span=fast, adjust=False).mean()
        ema_slow = series.ewm(span=slow, adjust=False).mean()
        macd_line = ema_fast - ema_slow
        signal_line = macd_line.ewm(span=signal, adjust=False).mean()
        histogram = macd_line - signal_line
        return pd.DataFrame(
            {
                "macd": macd_line,
                "macd_signal": signal_line,
                "macd_hist": histogram,
            },
            index=series.index,
