        if customer_id is not None:
            results = [t for t in results if t.customer_id == customer_id]
        if status is not None:
            results = [t for t in results if t.status == status]
        if priority is not None:
            results = [t for t in results if t.priority == priority]
        return results

    def _require_ticket(self, ticket_id):
        ticket = self.tickets.get(ticket_id)
        if not ticket:
            raise ValueError(f"Ticket {ticket_id} not found")
        return ticket

    # ---------- Escalation Workflow ----------
    def escalate_ticket(self, ticket_id, reason=None):
        ticket = self._require_ticket(ticket_id)
        ticket.escalation_level += 1
        ticket.status = TicketStatus.ESCALATED
        ticket.priority = TicketPriority(min(ticket.priority.value + 1, TicketPriority.CRITICAL.value))
        ticket.updated_at = datetime.datetime.now()
        note = f"Escalated to level {ticket.escalation_level}"
        if reason:
            note += f": {reason}"
        ticket.add_comment("system", note)

        rule = self.escalation_rules.get(ticket.escalation_level)
        required_skill = rule["next_level"] if rule else None
        new_agent = self._get_available_agent(required_skill=required_skill)
        if new_agent:
            if ticket.assigned_agent:
                self.agent_workload[ticket.assigned_agent] = max(
                    0, self.agent_workload[ticket.assigned_agent] - 1
                )
            ticket.assigned_agent = new_agent["agent_id"]
            self.agent_workload[new_agent["agent_id"]] += 1
        return ticket

    def check_and_auto_escalate(self):
        escalated = []
        now = datetime.datetime.now()
        for ticket in self.tickets.values():
            if ticket.status in (TicketStatus.RESOLVED, TicketStatus.CLOSED):
                continue
            rule = self.escalation_rules.get(ticket.escalation_level + 1)
            if not rule:
                continue
            hours_open = (now - ticket.updated_at).total_seconds() / 3600
            if hours_open >= rule["threshold_hours"]:
                self.escalate_ticket(ticket.ticket_id, reason="SLA threshold exceeded")
                escalated.append(ticket.ticket_id)
        return escalated

    # ---------- Chat Support ----------
    def start_chat(self, customer_id, required_skill=None):
        chat_id = str(uuid.uuid4())
        agent = self._get_available_agent(required_skill)
        agent_id = agent["agent_id"] if agent else None
        chat = ChatSession(chat_id, customer_id, agent_id)
        self.chats[chat_id] = chat
        if agent_id:
            self.agent_workload[agent_id] += 1
        return chat

    def send_chat_message(self, chat_id, sender, message):
        chat = self._require_chat(chat_id)
        if chat.status != ChatStatus.ACTIVE:
            raise ValueError("Chat is not active")
        chat.add_message(sender, message)
        return chat

    def transfer_chat(self, chat_id, new_agent_id):
        chat = self._require_chat(chat_id)
        if new_agent_id not in self.agents:
            raise ValueError("Agent not found")
        if chat.agent_id:
            self.agent_workload[chat.agent_id] = max(0, self.agent_workload[chat.agent_id] - 1)
        chat.agent_id = new_agent_id
        chat.status = ChatStatus.TRANSFERRED
        self.agent_workload[new_agent_id] += 1
        chat.status = ChatStatus.ACTIVE
        return chat

    def end_chat(self, chat_id):
        chat = self._require_chat(chat_id)
        chat.end_chat()
        if chat.agent_id:
            self.agent_workload[chat.agent_id] = max(0, self.agent_workload[chat.agent_id] - 1)
        return chat

    def _require_chat(self, chat_id):
        chat = self.chats.get(chat_id)
        if not chat:
            raise ValueError(f"Chat {chat_id} not found")
        return chat

    def convert_chat_to_ticket(self, chat_id, subject, priority=TicketPriority.MEDIUM):
        chat = self._require_chat(chat_id)
        description = "\n".join(
            f"[{m['timestamp']}] {m['sender']}: {m['message']}" for m in chat.messages
        )
        ticket = self.create_ticket(chat.customer_id, subject, description, priority)
        return ticket

    # ---------- Email Responses ----------
    def send_email_response(self, customer_id, subject, body, in_reply_to=None):
        email_id = str(uuid.uuid4())
        email = EmailResponse(email_id, customer_id, subject, body, in_reply_to)
        email.mark_sent()
        self.emails[email_id] = email
        return email

    def draft_email_from_ticket(self, ticket_id, body_override=None):
        ticket = self._require_ticket(ticket_id)
        subject = f"Re: {ticket.subject} (Ticket #{ticket.ticket_id})"
        body = body_override or ticket.resolution or "We are looking into your request."
        return self.send_email_response(ticket.customer_id, subject, body, in_reply_to=ticket_id)

    def get_customer_emails(self, customer_id):
        return [e for e in self.emails.values() if e.customer_id == customer_id]

    # ---------- Knowledge Base ----------
    def add_kb_article(self, title, content, tags=None, category="general"):
        article_id = str(uuid.uuid4())
        article = KnowledgeBaseArticle(article_id, title, content, tags, category)
        self.knowledge_base[article_id] = article
        return article

    def update_kb_article(self, article_id, **kwargs):
        article = self._require_article(article_id)
        article.update(**kwargs)
        return article

    def delete_kb_article(self, article_id):
        return self.knowledge_base.pop(article_id, None)

    def search_kb(self, query):
        query_lower = query.lower()
        results = []
        for article in self.knowledge_base.values():
            if (query_lower in article.title.lower()
                    or query_lower in article.content.lower()
                    or any(query_lower in tag.lower() for tag in article.tags)):
                results.append(article)
        for article in results:
            article.record_view()
        return results

    def vote_kb_article(self, article_id, helpful=True):
        article = self._require_article(article_id)
        article.vote(helpful)
        return article

    def get_kb_article(self, article_id):
        return self._require_article(article_id)

    def _require_article(self, article_id):
        article = self.knowledge_base.get(article_id)
        if not article:
            raise ValueError(f"Article {article_id} not found")
        return article

    def list_kb_by_category(self, category):
        return [a for a in self.knowledge_base.values() if a.category == category]

    # ---------- Satisfaction Surveys ----------
    def submit_survey(self, ticket_id, customer_id, rating, feedback=None):
        if not (1 <= rating <= 5):
            raise ValueError("Rating must be between 1 and 5")
        survey_id = str(uuid.uuid4())
        survey = SatisfactionSurvey(survey_id, ticket_id, customer_id, rating, feedback)
        self.surveys[survey_id] = survey
        return survey

    def get_average_satisfaction(self, agent_id=None):
        relevant_surveys = []
        for survey in self.surveys.values():
            if agent_id is not None:
                ticket = self.tickets.get(survey.ticket_id)
                if not ticket or ticket.assigned_agent != agent_id:
                    continue
            relevant_surveys.append(survey)
        if not relevant_surveys:
            return None
        return sum(s.rating for s in relevant_surveys) / len(relevant_surveys)

    def get_surveys_for_ticket(self, ticket_id):
        return [s for s in self.surveys.values() if s.ticket_id == ticket_id]

    # ---------- Reporting ----------
    def get_agent_performance(self, agent_id):
        agent_tickets = [t for t in self.tickets.values() if t.assigned_agent == agent_id]
        resolved = [t for t in agent_tickets if t.status in (TicketStatus.RESOLVED, TicketStatus.CLOSED)]
        avg_satisfaction = self.get_average_satisfaction(agent_id=agent_id)
        return {
            "agent_id": agent_id,
            "total_tickets": len(agent_tickets),
            "resolved_tickets": len(resolved),
            "current_workload": self.agent_workload.get(agent_id, 0),
            "average_satisfaction": avg_satisfaction,
        }

    def get_ticket_stats(self):
        stats = {status.value: 0 for status in TicketStatus}
        for ticket in self.tickets.values():
            stats[ticket.status.value] += 1
        stats["total"] = len(self.tickets)
        return stats
