import re
import uuid
import random
import datetime


class LoanProcessingError(Exception):
    """Base exception for loan processing errors."""
    pass


class ValidationError(LoanProcessingError):
    pass


class CreditReportError(LoanProcessingError):
    pass


def validate_applicant_info(applicant):
    """
    Validates applicant information dictionary.
    Expected keys: full_name, dob (YYYY-MM-DD), ssn, email, phone,
    address, annual_income, requested_amount, employment_status
    """
    required_fields = [
        "full_name", "dob", "ssn", "email", "phone",
        "address", "annual_income", "requested_amount", "employment_status"
    ]

    missing = [f for f in required_fields if f not in applicant or applicant[f] in (None, "")]
    if missing:
        raise ValidationError(f"Missing required fields: {', '.join(missing)}")

    if not re.match(r"^[A-Za-z\s\.\-']{2,100}$", applicant["full_name"]):
        raise ValidationError("Invalid full name format.")

    try:
        dob = datetime.datetime.strptime(applicant["dob"], "%Y-%m-%d").date()
    except ValueError:
        raise ValidationError("Invalid date of birth format. Expected YYYY-MM-DD.")

    today = datetime.date.today()
    age = today.year - dob.year - ((today.month, today.day) < (dob.month, dob.day))
    if age < 18:
        raise ValidationError("Applicant must be at least 18 years old.")
    if age > 100:
        raise ValidationError("Invalid date of birth; age exceeds reasonable limit.")

    if not re.match(r"^\d{3}-\d{2}-\d{4}$", applicant["ssn"]):
        raise ValidationError("Invalid SSN format. Expected XXX-XX-XXXX.")

    if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", applicant["email"]):
        raise ValidationError("Invalid email format.")

    phone_digits = re.sub(r"\D", "", applicant["phone"])
    if len(phone_digits) not in (10, 11):
        raise ValidationError("Invalid phone number format.")

    if not isinstance(applicant["address"], dict):
        raise ValidationError("Address must be a dictionary with street, city, state, zip.")
    for key in ("street", "city", "state", "zip"):
        if key not in applicant["address"] or not applicant["address"][key]:
            raise ValidationError(f"Address missing required field: {key}")

    try:
        income = float(applicant["annual_income"])
        if income <= 0:
            raise ValidationError("Annual income must be positive.")
    except (ValueError, TypeError):
        raise ValidationError("Annual income must be a valid number.")

    try:
        requested_amount = float(applicant["requested_amount"])
        if requested_amount <= 0:
            raise ValidationError("Requested loan amount must be positive.")
        if requested_amount > 1_000_000:
            raise ValidationError("Requested loan amount exceeds maximum limit of $1,000,000.")
    except (ValueError, TypeError):
        raise ValidationError("Requested amount must be a valid number.")

    valid_employment_statuses = {"employed", "self-employed", "unemployed", "retired", "student"}
    if applicant["employment_status"].lower() not in valid_employment_statuses:
        raise ValidationError(
            f"Invalid employment status. Must be one of: {', '.join(valid_employment_statuses)}"
        )

    return {
        "full_name": applicant["full_name"].strip(),
        "dob": dob,
        "ssn": applicant["ssn"],
        "email": applicant["email"].strip().lower(),
        "phone": phone_digits,
        "address": applicant["address"],
        "annual_income": income,
        "requested_amount": requested_amount,
        "employment_status": applicant["employment_status"].lower(),
    }


def pull_credit_report(applicant):
    """
    Simulates pulling a credit report for the applicant using their SSN.
    In production this would call an external credit bureau API
    (Experian, Equifax, TransUnion, etc.)
    """
    ssn = applicant.get("ssn")
    if not ssn:
        raise CreditReportError("SSN is required to pull credit report.")

    try:
        seed_value = int(re.sub(r"\D", "", ssn))
        rng = random.Random(seed_value)

        credit_score = rng.randint(300, 850)
        open_accounts = rng.randint(0, 15)
        delinquencies = rng.randint(0, 5)
        total_debt = round(rng.uniform(0, 100000), 2)
        credit_history_years = rng.randint(0, 30)
        bankruptcies = rng.randint(0, 2)

        return {
            "credit_score": credit_score,
            "open_accounts": open_accounts,
            "delinquencies": delinquencies,
            "total_debt": total_debt,
            "credit_history_years": credit_history_years,
            "bankruptcies": bankruptcies,
            "report_id": str(uuid.uuid4()),
            "pulled_at": datetime.datetime.utcnow().isoformat(),
        }
    except Exception as e:
        raise CreditReportError(f"Failed to pull credit report: {str(e)}")


def calculate_risk_score(applicant, credit_report):
    """
    Calculates a composite risk score (0-100, lower is better/less risky)
    based on credit report data and applicant financials.
    """
    score = 0

    credit_score = credit_report["credit_score"]
    if credit_score >= 750:
        score += 5
    elif credit_score >= 700:
        score += 15
    elif credit_score >= 650:
        score += 30
    elif credit_score >= 600:
        score += 45
    else:
        score += 60

    debt_to_income = credit_report["total_debt"] / applicant["annual_income"] if applicant["annual_income"] > 0 else 1
    if debt_to_income < 0.1:
        score += 2
    elif debt_to_income < 0.3:
        score += 10
    elif debt_to_income < 0.5:
        score += 20
    else:
        score += 35

    score += min(credit_report["delinquencies"] * 5, 25)
    score += credit_report["bankruptcies"] * 15

    if credit_report["credit_history_years"] < 2:
        score += 10
    elif credit_report["credit_history_years"] < 5:
        score += 5

    loan_to_income = applicant["requested_amount"] / applicant["annual_income"] if applicant["annual_income"] > 0 else 1
    if loan_to_income > 0.5:
        score += 15
    elif loan_to_income > 0.3:
        score += 8

    if applicant["employment_status"] == "unemployed":
        score += 20
    elif applicant["employment_status"] == "student":
        score += 10

    return min(max(round(score), 0), 100)


def determine_rate(risk_score, requested_amount):
    """
    Determines loan approval decision and interest rate based on risk score.
    Returns dict with approved (bool), interest_rate, term_months, max_amount.
    """
    base_rate = 5.0

    if risk_score <= 15:
        rate_adjustment = 0.0
        approved = True
        max_amount = requested_amount
    elif risk_score <= 30:
        rate_adjustment = 3.0
        approved = True
        max_amount = requested_amount
    elif risk_score <= 45:
        rate_adjustment = 7.0
        approved = True
        max_amount = min(requested_amount, 50000)
    elif risk_score <= 60:
        rate_adjustment = 12.0
        approved = True
        max_amount = min(requested_amount, 20000)
    elif risk_score <= 75:
        rate_adjustment = 18.0
        approved = True
        max_amount = min(requested_amount, 5000)
    else:
        rate_adjustment = 0.0
        approved = False
        max_amount = 0.0

    interest_rate = round(base_rate + rate_adjustment, 2)

    if requested_amount <= 10000:
        term_months = 36
    elif requested_amount <= 50000:
        term_months = 60
    else:
        term_months = 84

    return {
        "approved": approved,
        "interest_rate": interest_rate if approved else None,
        "term_months": term_months if approved else None,
        "approved_amount": round(max_amount, 2) if approved else 0.0,
    }


def generate_documents(applicant, loan_decision, risk_score, credit_report):
    """
    Generates loan-related documents (as structured data representing
    document contents; in production these would be PDFs).
    """
    documents = []
    application_id = str(uuid.uuid4())
    timestamp = datetime.datetime.utcnow().isoformat()

    documents.append({
        "type": "application_summary",
        "application_id": application_id,
        "generated_at": timestamp,
        "content": {
            "applicant_name": applicant["full_name"],
            "requested_amount": applicant["requested_amount"],
            "annual_income": applicant["annual_income"],
            "employment_status": applicant["employment_status"],
        }
    })

    documents.append({
        "type": "credit_disclosure",
        "application_id": application_id,
        "generated_at": timestamp,
        "content": {
            "credit_score": credit_report["credit_score"],
            "report_id": credit_report["report_id"],
        }
    })

    if loan_decision["approved"]:
        documents.append({
            "type": "loan_agreement",
            "application_id": application_id,
            "generated_at": timestamp,
            "content": {
                "applicant_name": applicant["full_name"],
                "approved_amount": loan_decision["approved_amount"],
                "interest_rate": loan_decision["interest_rate"],
                "term_months": loan_decision["term_months"],
                "risk_score": risk_score,
                "terms_and_conditions": "Standard loan terms and conditions apply.",
            }
        })
    else:
        documents.append({
            "type": "denial_letter",
            "application_id": application_id,
            "generated_at": timestamp,
            "content": {
                "applicant_name": applicant["full_name"],
                "reason": "Risk score exceeded acceptable threshold.",
                "risk_score": risk_score,
            }
        })

    return {
        "application_id": application_id,
        "documents": documents,
    }


def submit_for_approval(applicant, loan_decision, risk_score, document_package):
    """
    Simulates submitting the loan package to an internal/external
    approval workflow or underwriting system.
    """
    submission_id = str(uuid.uuid4())
    submitted_at = datetime.datetime.utcnow().isoformat()

    if loan_decision["approved"]:
        if risk_score <= 30:
            status = "auto_approved"
        else:
            status = "pending_manual_review"
    else:
        status = "auto_denied"

    return {
        "submission_id": submission_id,
        "application_id": document_package["application_id"],
        "status": status,
        "submitted_at": submitted_at,
        "risk_score": risk_score,
        "approved_amount": loan_decision["approved_amount"],
        "interest_rate": loan_decision["interest_rate"],
    }


def notify_applicant(applicant, submission_result, loan_decision):
    """
    Simulates sending a notification (email/SMS) to the applicant
    regarding their loan application status.
    """
    if loan_decision["approved"]:
        if submission_result["status"] == "auto_approved":
            subject = "Your Loan Application Has Been Approved!"
            message = (
                f"Dear {applicant['full_name']},\n\n"
                f"Congratulations! Your loan application has been approved.\n"
                f"Approved Amount: ${loan_decision['approved_amount']:,.2f}\n"
                f"Interest Rate: {loan_decision['interest_rate']}%\n"
                f"Term: {loan_decision['term_months']} months\n\n"
                f"Please review and sign your loan agreement.\n"
            )
        else:
            subject = "Your Loan Application Is Under Review"
            message = (
                f"Dear {applicant['full_name']},\n\n"
                f"Your loan application has passed initial screening and is now "
                f"pending manual review by our underwriting team. "
                f"We will notify you once a final decision has been made.\n"
            )
    else:
        subject = "Update on Your Loan Application"
        message = (
            f"Dear {applicant['full_name']},\n\n"
            f"We regret to inform you that your loan application was not approved "
            f"at this time based on our risk assessment criteria.\n"
        )

    notification_record = {
        "notification_id": str(uuid.uuid4()),
        "recipient_email": applicant["email"],
        "recipient_phone": applicant["phone"],
        "subject": subject,
        "message": message,
        "sent_at": datetime.datetime.utcnow().isoformat(),
        "status": "sent",
    }

    return notification_record


def process_loan_application(applicant_raw):
    """
    Main orchestration function that runs the full loan e-commerce
    processing pipeline end-to-end.

    Returns a dict containing the full results of processing, or raises
    a LoanProcessingError subclass if a step fails.
    """
    result = {
        "success": False,
        "steps_completed": [],
        "errors": [],
    }

    try:
        applicant = validate_applicant_info(applicant_raw)
