            "id": record_id,
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "diagnosis": diagnosis,
            "treatment": treatment,
            "notes": notes,
            "date": datetime.now(),
        }
        return record_id

    def get_patient_history(self, patient_id):
        self._get_patient(patient_id)
        return [r for r in self.medical_records.values() if r["patient_id"] == patient_id]

    def get_medical_record(self, record_id):
        if record_id not in self.medical_records:
            raise HospitalManagementError(f"Medical record {record_id} not found")
        return self.medical_records[record_id]

    # ---------------------- BILLING ----------------------
    def create_bill(self, patient_id, items=None):
        self._get_patient(patient_id)
        items = items or []
        total = sum(item.get("cost", 0) * item.get("quantity", 1) for item in items)

        bill_id = next(self._bill_id_counter)
        self.bills[bill_id] = {
            "id": bill_id,
            "patient_id": patient_id,
            "items": items,
            "total": total,
            "paid": False,
            "created_at": datetime.now(),
        }
