    def add_medicine(self, name, quantity, price, expiry_date=None):
        if name in self.pharmacy_inventory:
            self.pharmacy_inventory[name]["quantity"] += quantity
        else:
            self.pharmacy_inventory[name] = {
                "name": name,
                "quantity": quantity,
                "price": price,
                "expiry_date": expiry_date,
            }
        return self.pharmacy_inventory[name]

    def dispense_medicine(self, name, quantity):
        if name not in self.pharmacy_inventory:
            raise HospitalManagementError(f"Medicine {name} not found in inventory")
        med = self.pharmacy_inventory[name]
        if med["quantity"] < quantity:
            raise HospitalManagementError(f"Insufficient stock for {name}")
        med["quantity"] -= quantity
        return med

    def prescribe_medicine(self, patient_id, doctor_id, medicines):
        self._get_patient(patient_id)
        self._get_staff(doctor_id, role="doctor")

        prescription_id = next(self._prescription_id_counter)
        self.prescriptions[prescription_id] = {
            "id": prescription_id,
            "patient_id": patient_id,
            "doctor_id": doctor_id,
            "medicines": medicines,
            "date": datetime.now(),
            "fulfilled": False,
        }
        return prescription_id

    def fulfill_prescription(self, prescription_id):
        prescription = self._get_prescription(prescription_id)
        for med in prescription["medicines"]:
