        prescription["fulfilled"] = True
        return prescription

    def _get_prescription(self, prescription_id):
        if prescription_id not in self.prescriptions:
            raise HospitalManagementError(f"Prescription {prescription_id} not found")
        return self.prescriptions[prescription_id]

    def check_stock(self, name):
        if name not in self.pharmacy_inventory:
            raise HospitalManagementError(f"Medicine {name} not found")
        return self.pharmacy_inventory[name]["quantity"]

