"""
Trading system with order-type support.

The design intentionally centralizes order-type-specific behavior behind a
single `OrderTypeHandler` interface (Strategy pattern) that is registered in
an `OrderTypeRegistry`. Every subsystem (validation, routing, execution,
risk, position tracking, settlement, compliance, reporting, audit, and the
client API) queries the registry instead of embedding per-order-type
branching logic. Adding a new order type therefore requires exactly ONE new
handler class + one registration call, instead of touching 20+ files.

This file is organized into logical sections (as if they were separate
modules) to show how each subsystem plugs into the registry.
"""

from __future__ import annotations

import uuid
import time
import threading
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from decimal import Decimal
from enum import Enum
from typing import Dict, List, Optional, Any, Type


# =====================================================================
# module: core/enums.py
# =====================================================================

class OrderSide(Enum):
    BUY = "BUY"
    SELL = "SELL"


class OrderStatus(Enum):
    NEW = "NEW"
    VALIDATED = "VALIDATED"
    ROUTED = "ROUTED"
    PARTIALLY_FILLED = "PARTIALLY_FILLED"
    FILLED = "FILLED"
    CANCELLED = "CANCELLED"
    REJECTED = "REJECTED"
    SETTLED = "SETTLED"


# =====================================================================
# module: core/order.py
# =====================================================================

@dataclass
class Order:
    """
    Generic order model. Order-type-specific fields live in `params`,
    a free-form dict interpreted only by the corresponding
    OrderTypeHandler. This keeps the Order model stable as new order
    types are added.
    """
    symbol: str
    side: OrderSide
    quantity: Decimal
    order_type: str  # string key into OrderTypeRegistry
    order_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    status: OrderStatus = OrderStatus.NEW
    params: Dict[str, Any] = field(default_factory=dict)
    filled_quantity: Decimal = Decimal("0")
    avg_fill_price: Optional[Decimal] = None
    created_at: float = field(default_factory=time.time)

    def remaining_quantity(self) -> Decimal:
        return self.quantity - self.filled_quantity


# =====================================================================
# module: core/order_type_handler.py
#
# This is the extension point. Every subsystem below asks the handler
# "how do you want this done for your order type?" instead of hardcoding
# per-type logic.
# =====================================================================

class OrderTypeHandler(ABC):
    """Strategy interface encapsulating all order-type-specific behavior."""

    name: str = "BASE"

    # ---- Validation ----
    @abstractmethod
    def validate(self, order: Order) -> List[str]:
        """Return list of validation error strings (empty == valid)."""
        raise NotImplementedError

    # ---- Routing ----
    @abstractmethod
    def select_venue(self, order: Order, available_venues: List[str]) -> str:
        raise NotImplementedError

    # ---- Execution ----
    @abstractmethod
    def build_execution_instructions(self, order: Order) -> Dict[str, Any]:
        raise NotImplementedError

    # ---- Risk ----
    @abstractmethod
    def calculate_risk_exposure(self, order: Order, market_price: Decimal) -> Decimal:
        raise NotImplementedError

    # ---- Position impact ----
    @abstractmethod
    def position_delta(self, order: Order, fill_qty: Decimal) -> Decimal:
        raise NotImplementedError

    # ---- Settlement ----
    @abstractmethod
    def settlement_terms(self, order: Order) -> Dict[str, Any]:
        raise NotImplementedError

    # ---- Compliance ----
    @abstractmethod
    def compliance_flags(self, order: Order) -> List[str]:
        raise NotImplementedError

    # ---- Reporting ----
    @abstractmethod
    def report_fields(self, order: Order) -> Dict[str, Any]:
        raise NotImplementedError

    # ---- Audit ----
    def audit_summary(self, order: Order) -> str:
        return f"{self.name} order {order.order_id} qty={order.quantity} side={order.side.value}"


# =====================================================================
# module: core/registry.py
# =====================================================================

class OrderTypeRegistry:
    """Central registry mapping order_type string -> handler instance."""

    _handlers: Dict[str, OrderTypeHandler] = {}

    @classmethod
