# order types beyond passing through the `order_type` string and a
# free-form `params` dict.
# =====================================================================

class TradingClientAPI:
    def __init__(self):
        self.validator = OrderValidator()
        self.router = OrderRouter()
        self.execution_handler = ExecutionHandler()
        self.risk_calculator = RiskCalculator()
        self.position_tracker = PositionTracker()
        self.settlement_processor = SettlementProcessor()
        self.compliance_checker = ComplianceChecker()
        self.report_generator = ReportGenerator()
        self.audit_logger = AuditLogger()
        self.orders: Dict[str, Order] = {}

    def submit_order(
        self,
        symbol: str,
        side: str,
        quantity: Decimal,
        order_type: str,
        params: Optional[Dict[str, Any]] = None,
    ) -> Order:
        order = Order(
            symbol=symbol,
            side=OrderSide(side),
            quantity=Decimal(quantity),
            order_type=order_type,
            params=params or {},
        )
        self.orders[order.order_id] = order
        self.audit_logger.log(order, "SUBMITTED")

        errors = self.validator.validate(order)
        if errors:
            order.status = OrderStatus.REJECTED
            self.audit_logger.log(order, f"REJECTED: {errors}")
            return order
        order.status = OrderStatus.VALIDATED

        compliance_flags = self.compliance_checker.check(order)
        if compliance_flags:
            self.audit_logger.log(order, f"COMPLIANCE_FLAGS: {compliance_flags}")

        venue = self.router.route(order)
        self.audit_logger.log(order, f"ROUTED_TO: {venue}")

        return order

    def execute_order(self, order_id: str, market_price: Decimal) -> Fill:
        order = self.orders[order_id]
        fill = self.execution_handler.execute(order, market_price)
        self.position_tracker.apply_fill(order, fill)
        self.audit_logger.log(order, f"EXECUTED: qty={fill.quantity} price={fill.price}")
        return fill

    def settle_order(self, order_id: str, fill: Fill) -> SettlementInstruction:
        order = self.orders[order_id]
        instruction = self.settlement_processor.prepare_settlement(order, fill)
        self.audit_logger.log(order, "SETTLED")
        return instruction

    def get_risk_exposure(self, order_id: str, market_price: Decimal) -> Decimal:
        order = self.orders[order_id]
        return self.risk_calculator.calculate_exposure(order, market_price)

    def get_report(self, order_id: str) -> Dict[str, Any]:
        order = self.orders[order_id]
        return self.report_generator.generate(order)

    def list_supported_order_types(self) -> List[str]:
        return OrderTypeRegistry.available_types()


