# per-type logic.
# =====================================================================

class OrderTypeHandler(ABC):
    """Strategy interface encapsulating all order-type-specific behavior."""

    name: str = "BASE"

    # ---- Validation ----
    @abstractmethod
    def validate(self, order: Order) -> List[str]:
        """Return list of validation error strings (empty == valid)."""
        raise NotImplementedError

