        raise NotImplementedError

    # ---- Risk ----
    @abstractmethod
    def calculate_risk_exposure(self, order: Order, market_price: Decimal) -> Decimal:
        raise NotImplementedError

    # ---- Position impact ----
    @abstractmethod
    def position_delta(self, order: Order, fill_qty: Decimal) -> Decimal:
        raise NotImplementedError

    # ---- Settlement ----
    @abstractmethod
    def settlement_terms(self, order: Order) -> Dict[str, Any]:
        raise NotImplementedError

    # ---- Compliance ----
    @abstractmethod
    def compliance_flags(self, order: Order) -> List[str]:
        raise NotImplementedError

    # ---- Reporting ----
    @abstractmethod
    def report_fields(self, order: Order) -> Dict[str, Any]:
        raise NotImplementedError

    # ---- Audit ----
    def audit_summary(self, order: Order) -> str:
        return f"{self.name} order {order.order_id} qty={order.quantity} side={order.side.value}"


