class Validator:
    """Basic rule-based validator."""

    @staticmethod
    def validate(data, rules):
        errors = {}
        for field, rule_set in rules.items():
            value = data.get(field)
            required = rule_set.get("required", False)
            field_type = rule_set.get("type")
            min_len = rule_set.get("min_length")
            max_len = rule_set.get("max_length")
            min_val = rule_set.get("min")
            max_val = rule_set.get("max")
            custom = rule_set.get("validator")

            if required and (value is None or value == ""):
                errors.setdefault(field, []).append("This field is required")
                continue

            if value is None:
                continue

            if field_type is not None:
                if field_type == "int":
                    try:
                        value = int(value)
                    except (ValueError, TypeError):
                        errors.setdefault(field, []).append("Must be an integer")
                        continue
                elif field_type == "float":
                    try:
                        value = float(value)
                    except (ValueError, TypeError):
                        errors.setdefault(field, []).append("Must be a number")
                        continue
                elif field_type == "str":
                    if not isinstance(value, str):
                        errors.setdefault(field, []).append("Must be a string")
                        continue
                elif field_type == "bool":
                    if not isinstance(value, bool):
                        errors.setdefault(field, []).append("Must be a boolean")
                        continue
                elif field_type == "list":
                    if not isinstance(value, list):
                        errors.setdefault(field, []).append("Must be a list")
                        continue
                elif field_type == "dict":
                    if not isinstance(value, dict):
                        errors.setdefault(field, []).append("Must be an object")
                        continue

            if min_len is not None and hasattr(value, "__len__") and len(value) < min_len:
                errors.setdefault(field, []).append(f"Minimum length is {min_len}")

            if max_len is not None and hasattr(value, "__len__") and len(value) > max_len:
                errors.setdefault(field, []).append(f"Maximum length is {max_len}")

            if min_val is not None and isinstance(value, (int, float)) and value < min_val:
                errors.setdefault(field, []).append(f"Minimum value is {min_val}")

            if max_val is not None and isinstance(value, (int, float)) and value > max_val:
                errors.setdefault(field, []).append(f"Maximum value is {max_val}")

            if custom and callable(custom):
                try:
                    ok = custom(value)
                    if not ok:
                        errors.setdefault(field, []).append("Invalid value")
                except Exception as e:
                    errors.setdefault(field, []).append(str(e))

        return errors


class TemplateRenderer:
    """Simple string.Template-based renderer with template registry."""

    def __init__(self):
        self._templates = {}

    def register(self, name, template_str):
        self._templates[name] = Template(template_str)

    def render(self, name, context=None):
        context = context or {}
        template = self._templates.get(name)
        if template is None:
            raise NotFoundError(f"Template '{name}' not found")
        try:
            return template.safe_substitute(**context)
        except Exception as e:
            raise ApplicationError(f"Template rendering failed: {e}")


class ApplicationController:
    """
    Central controller managing DB connections, routing, validation,
    business logic execution, template rendering, caching, error handling,
    API responses, and logging.
    """

    def __init__(self, db_path=":memory:", cache_ttl=60, log_level=logging.INFO):
        self.db = DatabaseConnectionManager(db_path)
        self.cache = SimpleCache(default_ttl=cache_ttl)
        self.renderer = TemplateRenderer()
        self.routes = []
        self.middlewares = []
        self.error_handlers = {}

        self.logger = logging.getLogger("ApplicationController")
        self.logger.setLevel(log_level)
        if not self.logger.handlers:
            handler = logging.StreamHandler()
            formatter = logging.Formatter(
                "[%(asctime)s] %(levelname)s in %(name)s: %(message)s"
            )
            handler.setFormatter(formatter)
            self.logger.addHandler(handler)

        self._register_default_error_handlers()

    # ---------------- Routing ----------------

    def route(self, method, path, validators=None):
        def decorator(func):
            self.add_route(method, path, func, validators)
            return func
        return decorator

    def add_route(self, method, path, handler, validators=None):
        self.routes.append(Route(method, path, handler, validators))
        self.logger.debug(f"Registered route: {method.upper()} {path}")

    def use_middleware(self, middleware_func):
        self.middlewares.append(middleware_func)

    def register_error_handler(self, exception_type, handler_func):
        self.error_handlers[exception_type] = handler_func

    def _register_default_error_handlers(self):
        self.error_handlers[ValidationError] = lambda e, req: self.api_response(
            success=False, message=e.message, errors=e.payload.get("errors"),
            status_code=e.status_code
        )
        self.error_handlers[NotFoundError] = lambda e, req: self.api_response(
            success=False, message=e.message, status_code=e.status_code
        )
        self.error_handlers[UnauthorizedError] = lambda e, req: self.api_response(
            success=False, message=e.message, status_code=e.status_code
        )
        self.error_handlers[ApplicationError] = lambda e, req: self.api_response(
            success=False, message=e.message, status_code=e.status_code,
            **e.payload
        )

    def find_route(self, method, path):
        for route in self.routes:
            params = route.match(method, path)
            if params is not None:
                return route, params
        return None, None

    # ---------------- Request Dispatch ----------------

    def dispatch(self, request: Request):
        start_time = time.time()
        self.logger.info(f"Incoming request: {request.method} {request.path}")

        try:
            route, params = self.find_route(request.method, request.path)
            if route is None:
                raise NotFoundError(f"No route found for {request.method} {request.path}")

            request.path_params = params

            for mw in self.middlewares:
                result = mw(request)
                if result is not None:
                    return self._finalize(result, start_time, request)

            if route.validators:
                data = {**request.get_json(), **request.query_params, **params}
                errors = Validator.validate(data, route.validators)
                if errors:
                    raise ValidationError("Validation failed", errors=errors)

            response = self.execute_handler(route.handler, request)
            return self._finalize(response, start_time, request)

        except Exception as e:
            response = self.handle_error(e, request)
            return self._finalize(response, start_time, request, error=e)

    def execute_handler(self, handler, request):
        try:
            result = handler(request)
            if isinstance(result, Response):
                return result
            if isinstance(result, dict):
                return self.api_response(success=True, data=result)
            return self.api_response(success=True, data=result)
        except ApplicationError:
            raise
        except Exception as e:
            self.logger.error(f"Handler execution failed: {e}\n{traceback.format_exc()}")
            raise ApplicationError("Internal server error", status_code=500)

    def _finalize(self, response, start_time, request, error=None):
        duration = time.time() - start_time
        status = response.status_code if isinstance(response, Response) else 200
        if error:
            self.logger.warning(
                f"Request failed: {request.method} {request.path} "
                f"status={status} duration={duration:.4f}s error={error}"
            )
        else:
            self.logger.info(
                f"Request completed: {request.method} {request.path} "
                f"status={status} duration={duration:.4f}s"
            )
        return response

    # ---------------- Error Handling ----------------

    def handle_error(self, error, request):
        for exc_type, handler in self.error_handlers.items():
            if isinstance(error, exc_type):
                try:
                    return handler(error, request)
                except Exception as e:
                    self.logger.error(f"Error handler raised an exception: {e}")
                    break

        self.logger.error(f"Unhandled exception: {error}\n{traceback.format_exc()}")
        return self.api_response(
            success=False, message="Internal server error", status_code=500
        )

    # ---------------- API Response Building ----------------

    def api_response(self, success=True, data=None, message=None, errors=None,
                      status_code=200, **extra):
        body = {
            "success": success,
            "timestamp": datetime.utcnow().isoformat() + "Z",
        }
        if data is not None:
            body["data"] = data
        if message is not None:
            body["message"] = message
        if errors:
            body["errors"] = errors
        if extra:
            body.update(extra)
        return Response(status_code=status_code, body=body)

