    def register_template(self, name, template_str):
        self.renderer.register(name, template_str)

    def render_template(self, name, context=None):
        return self.renderer.render(name, context)

    def render_response(self, name, context=None, status_code=200):
        html = self.render_template(name, context)
        return Response(
            status_code=status_code,
            body=html,
            headers={"Content-Type": "text/html"},
        )

    # ---------------- Business Logic Helpers ----------------

    def run_in_transaction(self, func, *args, **kwargs):
        with self.db.transaction():
            return func(*args, **kwargs)

    def cached_query(self, query, params=None, ttl=None):
        cache_key = {"query": query, "params": params}
