            recent_views = sum(1 for log in data["view_log"] if log["timestamp"] >= cutoff)
            trend_score = recent_views + data["likes"] * 0.5 + data["shares"] * 0.8
            scores.append((article_id, trend_score))
        scores.sort(key=lambda x: x[1], reverse=True)
        return [self.articles[aid] for aid, _ in scores[:limit] if aid in self.articles]

