    # ---------------------- Workflow ----------------------

    def _create_workflow(self, article_id):
        self.workflows[article_id] = {
            "current_stage": "draft",
            "history": [{"stage": "draft", "timestamp": self._now(), "actor": None, "comment": ""}],
            "assignees": {}
        }

    def transition_workflow(self, article_id, new_stage, actor=None, comment=""):
        if new_stage not in self.workflow_stages:
            raise ValueError(f"Invalid workflow stage: {new_stage}")
        workflow = self.workflows.get(article_id)
        if not workflow:
            raise KeyError(f"No workflow found for article {article_id}")

        current_index = self.workflow_stages.index(workflow["current_stage"])
        new_index = self.workflow_stages.index(new_stage)
        if new_index < current_index and new_stage != "draft":
            pass  # allow reverting for corrections

        workflow["current_stage"] = new_stage
        workflow["history"].append({
            "stage": new_stage,
            "timestamp": self._now(),
            "actor": actor,
            "comment": comment
        })

        article = self._require_article(article_id)
        if new_stage == "published":
            self.publish_article(article_id)
        else:
            article["status"] = new_stage

        self._log_action("workflow_transition", "article", article_id, {"stage": new_stage, "actor": actor})
        return workflow

