    def check_scheduled_publications(self):
        now = self._now()
        published = []
        for article_id, article in self.articles.items():
            if article["status"] == "scheduled" and article.get("scheduled_time", "") <= now:
                article["status"] = "published"
                article["published_at"] = now
                published.append(article_id)
