    def analyze_seo(self, article_id):
        article = self._require_article(article_id)
        title = article["title"] or ""
        body = article["body"] or ""
        tokens = self._tokenize(body)
        word_count = len(tokens)
        keyword_freq = Counter(tokens)
        top_keywords = [w for w, _ in keyword_freq.most_common(10) if len(w) > 3]

        issues = []
