class Router:
    def __init__(self):
        self.routes = []

    def add_route(self, method, path, handler):
        pattern = self._compile_path(path)
        self.routes.append((method.upper(), pattern, handler, path))

    def _compile_path(self, path):
        pattern = re.sub(r"<(\w+)>", r"(?P<\1>[^/]+)", path)
        return re.compile(f"^{pattern}$")

    def route(self, method, path):
        def decorator(func):
            self.add_route(method, path, func)
            return func
        return decorator

    def match(self, method, path):
        for m, pattern, handler, original in self.routes:
            if m != method.upper():
                continue
            match = pattern.match(path)
            if match:
                return handler, match.groupdict()
        return None, None


