    def register_service(self, name: str, handler: ServiceHandler) -> None:
        self.registry.register(name, handler)

    def unregister_service(self, name: str) -> None:
        self.registry.unregister(name)

    def call(self, service_name: str, payload: Any = None, timeout: Optional[float] = 30.0) -> Any:
        """Simple synchronous request-response call."""
        handler = self.registry.get(service_name)
        result_holder: Dict[str, Any] = {}
        exc_holder: Dict[str, BaseException] = {}
        done_event = threading.Event()

        def run():
            try:
                result_holder["result"] = handler(payload)
            except BaseException as exc:  # noqa: BLE001
                exc_holder["error"] = exc
            finally:
                done_event.set()

        t = threading.Thread(target=run, daemon=True)
        t.start()
        finished = done_event.wait(timeout)
        if not finished:
            raise TimeoutErrorESB(f"Call to service '{service_name}' timed out after {timeout}s")
        if "error" in exc_holder:
            raise exc_holder["error"]
        return result_holder.get("result")

    def call_direct(self, service_name: str, payload: Any = None) -> Any:
        """Direct in-thread call without extra thread overhead, for the simple case."""
        handler = self.registry.get(service_name)
        return handler(payload)

    # ---------------- Async messaging ----------------

    def publish_event(self, channel: str, payload: Any, headers: Optional[Dict[str, Any]] = None) -> None:
        message = Message(type=MessageType.EVENT, channel=channel, payload=payload, headers=headers or {})
        self.broker.publish(message)

    def subscribe(self, channel: str, handler: Subscriber) -> Callable[[], None]:
        return self.broker.subscribe(channel, handler)

    def send_command(self, queue_name: str, payload: Any, headers: Optional[Dict[str, Any]] = None) -> None:
        message = Message(type=MessageType.COMMAND, channel=queue_name, payload=payload, headers=headers or {})
        self.broker.send_to_queue(queue_name, message)

    def receive_command(self, queue_name: str, timeout: Optional[float] = None) -> Optional[Message]:
        return self.broker.receive_from_queue(queue_name, timeout=timeout)

    def request_async(self, service_name: str, payload: Any, timeout: Optional[float] = 30.0) -> Future:
        """Async request-response using futures, backed by the sync registry."""
        future: Future = Future()

        def worker():
            try:
                result = self.call(service_name, payload, timeout=timeout)
                future.set_result(result)
            except BaseException as exc:  # noqa: BLE001
                future.set_exception(exc)

        threading.Thread(target=worker, daemon=True).start()
        return future

    # ---------------- Event sourcing ----------------

    def append_event(self, stream_id: str, event_type: str, data: Any,
                      expected_version: Optional[int] = None) -> Event:
        return self.event_store.append(stream_id, event_type, data, expected_version)

    def get_events(self, stream_id: str) -> List[Event]:
        return self.event_store.get_stream(stream_id)

    # ---------------- Saga ----------------

    def create_saga(self, name: str) -> Saga:
        return Saga(name, event_store=self.event_store)

    # ---------------- Distributed transactions ----------------

    def run_distributed_transaction(self, participants: List[TransactionParticipant], payload: Any) -> bool:
        return self.tx_coordinator.execute(participants, payload)

    def shutdown(self) -> None:
        self.broker.shutdown()


