# =====================================================================
# Common utilities
# =====================================================================

def new_id() -> str:
    return str(uuid.uuid4())


class ESBError(Exception):
    pass


class TimeoutErrorESB(ESBError):
    pass


class ServiceNotFoundError(ESBError):
