@dataclass
class Event:
    stream_id: str
    event_type: str
    data: Any
    version: int
    event_id: str = field(default_factory=new_id)
    timestamp: float = field(default_factory=time.time)
    metadata: Dict[str, Any] = field(default_factory=dict)


class EventStore:
    """Append-only event store with optimistic concurrency control."""

    def __init__(self):
        self._streams: Dict[str, List[Event]] = {}
        self._lock = threading.RLock()
        self._subscribers: List[Callable[[Event], None]] = []

    def append(self, stream_id: str, event_type: str, data: Any,
               expected_version: Optional[int] = None,
               metadata: Optional[Dict[str, Any]] = None) -> Event:
        with self._lock:
            stream = self._streams.setdefault(stream_id, [])
            current_version = len(stream)
            if expected_version is not None and expected_version != current_version:
                raise ESBError(
                    f"Concurrency conflict on stream {stream_id}: "
                    f"expected version {expected_version}, got {current_version}"
                )
            event = Event(
                stream_id=stream_id,
                event_type=event_type,
                data=data,
                version=current_version + 1,
                metadata=metadata or {},
            )
            stream.append(event)
        for sub in list(self._subscribers):
            try:
                sub(event)
            except Exception:
                pass
        return event

    def get_stream(self, stream_id: str, from_version: int = 0) -> List[Event]:
        with self._lock:
            stream = self._streams.get(stream_id, [])
            return [e for e in stream if e.version > from_version]

    def subscribe(self, handler: Callable[[Event], None]) -> None:
        self._subscribers.append(handler)

    def replay(self, stream_id: str, apply_fn: Callable[[Any, Event], Any], initial_state: Any = None) -> Any:
        state = initial_state
        for event in self.get_stream(stream_id):
            state = apply_fn(state, event)
        return state


class Aggregate(ABC):
    """Base class for event-sourced aggregates."""

    def __init__(self, aggregate_id: str, event_store: EventStore):
        self.aggregate_id = aggregate_id
        self._event_store = event_store
        self.version = 0
        self._load()

    @abstractmethod
    def apply(self, event: Event) -> None:
        """Mutate internal state based on an event."""
        raise NotImplementedError

    def _load(self) -> None:
        for event in self._event_store.get_stream(self.aggregate_id):
            self.apply(event)
            self.version = event.version

    def raise_event(self, event_type: str, data: Any, metadata: Optional[Dict[str, Any]] = None) -> Event:
        event = self._event_store.append(
            self.aggregate_id, event_type, data,
            expected_version=self.version,
            metadata=metadata,
        )
        self.apply(event)
        self.version = event.version
        return event


# =====================================================================
# Saga pattern (orchestration)
# =====================================================================

class SagaStepStatus(Enum):
    PENDING = "PENDING"
    COMPLETED = "COMPLETED"
    COMPENSATED = "COMPENSATED"
    FAILED = "FAILED"


@dataclass
class SagaStep:
    name: str
    action: Callable[[Dict[str, Any]], Any]
    compensation: Optional[Callable[[Dict[str, Any]], Any]] = None
    status: SagaStepStatus = SagaStepStatus.PENDING
    result: Any = None
    error: Optional[str] = None


class SagaStatus(Enum):
    IN_PROGRESS = "IN_PROGRESS"
    COMPLETED = "COMPLETED"
    COMPENSATING = "COMPENSATING"
    COMPENSATED = "COMPENSATED"
    FAILED = "FAILED"


class Saga:
    """Orchestration-based saga with automatic compensation on failure."""

    def __init__(self, name: str, event_store: Optional[EventStore] = None):
        self.saga_id = new_id()
        self.name = name
        self.steps: List[SagaStep] = []
        self.status = SagaStatus.IN_PROGRESS
        self.context: Dict[str, Any] = {}
        self._event_store = event_store

    def add_step(self, name: str, action: Callable[[Dict[str, Any]], Any],
                 compensation: Optional[Callable[[Dict[str, Any]], Any]] = None) -> "Saga":
        self.steps.append(SagaStep(name=name, action=action, compensation=compensation))
        return self

    def _record(self, event_type: str, data: Any) -> None:
        if self._event_store:
            self._event_store.append(f"saga:{self.saga_id}", event_type, data)

    def execute(self, initial_context: Optional[Dict[str, Any]] = None) -> bool:
        self.context = dict(initial_context or {})
        self._record("SagaStarted", {"name": self.name})

        executed_steps: List[SagaStep] = []
        for step in self.steps:
            try:
                step.result = step.action(self.context)
                step.status = SagaStepStatus.COMPLETED
                executed_steps.append(step)
                self._record("SagaStepCompleted", {"step": step.name, "result": step.result})
            except Exception as exc:
                step.status = SagaStepStatus.FAILED
                step.error = str(exc)
                self._record("SagaStepFailed", {"step": step.name, "error": str(exc)})
                self._compensate(executed_steps)
                self.status = SagaStatus.FAILED
                self._record("SagaFailed", {"name": self.name})
                return False

        self.status = SagaStatus.COMPLETED
        self._record("SagaCompleted", {"name": self.name})
        return True

    def _compensate(self, executed_steps: List[SagaStep]) -> None:
        self.status = SagaStatus.COMPENSATING
        self._record("SagaCompensating", {"name": self.name})
        for step in reversed(executed_steps):
            if step.compensation:
                try:
                    step.compensation(self.context)
                    step.status = SagaStepStatus.COMPENSATED
                    self._record("SagaStepCompensated", {"step": step.name})
                except Exception as exc:
                    step.error = f"compensation failed: {exc}"
                    self._record("SagaCompensationFailed", {"step": step.name, "error": str(exc)})
        self.status = SagaStatus.COMPENSATED


# =====================================================================
# Distributed transactions (Two-Phase Commit coordinator)
# =====================================================================

class TransactionParticipant(ABC):
    @abstractmethod
    def prepare(self, tx_id: str, payload: Any) -> bool:
        """Return True if participant votes to commit."""
        raise NotImplementedError

    @abstractmethod
    def commit(self, tx_id: str) -> None:
        raise NotImplementedError

    @abstractmethod
    def rollback(self, tx_id: str) -> None:
        raise NotImplementedError


class TransactionStatus(Enum):
    STARTED = "STARTED"
    PREPARED = "PREPARED"
    COMMITTED = "COMMITTED"
    ROLLED_BACK = "ROLLED_BACK"


@dataclass
class DistributedTransaction:
    tx_id: str
    participants: List[TransactionParticipant]
    status: TransactionStatus = TransactionStatus.STARTED


class TransactionCoordinator:
    """Implements a basic two-phase commit protocol."""

    def __init__(self):
        self._transactions: Dict[str, DistributedTransaction] = {}
        self._lock = threading.RLock()

    def begin(self, participants: List[TransactionParticipant]) -> str:
        tx_id = new_id()
        with self._lock:
            self._transactions[tx_id] = DistributedTransaction(tx_id=tx_id, participants=participants)
        return tx_id

    def execute(self, participants: List[TransactionParticipant], payload: Any) -> bool:
        """Convenience: begin + full 2PC run in one call."""
        tx_id = self.begin(participants)
        return self.run(tx_id, payload)

    def run(self, tx_id: str, payload: Any) -> bool:
        with self._lock:
            tx = self._transactions.get(tx_id)
        if tx is None:
            raise ESBError(f"Unknown transaction {tx_id}")

        # Phase 1: prepare
        votes = []
        for participant in tx.participants:
            try:
                votes.append(participant.prepare(tx_id, payload))
            except Exception:
                votes.append(False)

        if all(votes):
            tx.status = TransactionStatus.PREPARED
            # Phase 2: commit
            for participant in tx.participants:
                try:
                    participant.commit(tx_id)
                except Exception:
                    pass
            tx.status = TransactionStatus.COMMITTED
            return True
        else:
            for participant in tx.participants:
                try:
                    participant.rollback(tx_id)
                except Exception:
                    pass
            tx.status = TransactionStatus.ROLLED_BACK
            return False

    def get_status(self, tx_id: str) -> TransactionStatus:
        with self._lock:
            tx = self._transactions.get(tx_id)
        if tx is None:
            raise ESBError(f"Unknown transaction {tx_id}")
        return tx.status


class FunctionTransactionParticipant(TransactionParticipant):
    """Wraps plain callables into a TransactionParticipant for convenience."""

    def __init__(self, prepare_fn: Callable[[str, Any], bool],
                 commit_fn: Callable[[str], None],
                 rollback_fn: Callable[[str], None]):
        self._prepare_fn = prepare_fn
        self._commit_fn = commit_fn
        self._rollback_fn = rollback_fn

    def prepare(self, tx_id: str, payload: Any) -> bool:
        return self._prepare_fn(tx_id, payload)

    def commit(self, tx_id: str) -> None:
        self._commit_fn(tx_id)

    def rollback(self, tx_id: str) -> None:
        self._rollback_fn(tx_id)


# =====================================================================
# The Enterprise Service Bus facade
# =====================================================================

class EnterpriseServiceBus:
    """
    Unified facade tying together:
      - synchronous request/response service calls
      - async pub/sub and queue messaging
      - event sourcing
      - saga orchestration
      - distributed transactions (2PC)
    """

    def __init__(self, max_workers: int = 8):
        self.registry = ServiceRegistry()
        self.broker = MessageBroker(max_workers=max_workers)
        self.event_store = EventStore()
        self.tx_coordinator = TransactionCoordinator()
        self._pending_requests: Dict[str, Future] = {}
        self._lock = threading.RLock()

    # ---------------- Synchronous request-response ----------------

    def register_service(self, name: str, handler: ServiceHandler) -> None:
        self.registry.register(name, handler)

    def unregister_service(self, name: str) -> None:
        self.registry.unregister(name)

    def call(self, service_name: str, payload: Any = None, timeout: Optional[float] = 30.0) -> Any:
        """Simple synchronous request-response call."""
        handler = self.registry.get(service_name)
        result_holder: Dict[str, Any] = {}
        exc_holder: Dict[str, BaseException] = {}
        done_event = threading.Event()

        def run():
            try:
                result_holder["result"] = handler(payload)
            except BaseException as exc:  # noqa: BLE001
                exc_holder["error"] = exc
            finally:
                done_event.set()

        t = threading.Thread(target=run, daemon=True)
        t.start()
        finished = done_event.wait(timeout)
        if not finished:
            raise TimeoutErrorESB(f"Call to service '{service_name}' timed out after {timeout}s")
        if "error" in exc_holder:
            raise exc_holder["error"]
        return result_holder.get("result")

    def call_direct(self, service_name: str, payload: Any = None) -> Any:
        """Direct in-thread call without extra thread overhead, for the simple case."""
        handler = self.registry.get(service_name)
        return handler(payload)

    # ---------------- Async messaging ----------------

    def publish_event(self, channel: str, payload: Any, headers: Optional[Dict[str, Any]] = None) -> None:
        message = Message(type=MessageType.EVENT, channel=channel, payload=payload, headers=headers or {})
        self.broker.publish(message)

    def subscribe(self, channel: str, handler: Subscriber) -> Callable[[], None]:
        return self.broker.subscribe(channel, handler)

    def send_command(self, queue_name: str, payload: Any, headers: Optional[Dict[str, Any]] = None) -> None:
        message = Message(type=MessageType.COMMAND, channel=queue_name, payload=payload, headers=headers or {})
        self.broker.send_to_queue(queue_name, message)

    def receive_command(self, queue_name: str, timeout: Optional[float] = None) -> Optional[Message]:
        return self.broker.receive_from_queue(queue_name, timeout=timeout)

    def request_async(self, service_name: str, payload: Any, timeout: Optional[float] = 30.0) -> Future:
        """Async request-response using futures, backed by the sync registry."""
        future: Future = Future()

        def worker():
            try:
                result = self.call(service_name, payload, timeout=timeout)
                future.set_result(result)
            except BaseException as exc:  # noqa: BLE001
                future.set_exception(exc)

        threading.Thread(target=worker, daemon=True).start()
        return future

    # ---------------- Event sourcing ----------------

    def append_event(self, stream_id: str, event_type: str, data: Any,
                      expected_version: Optional[int] = None) -> Event:
        return self.event_store.append(stream_id, event_type, data, expected_version)

    def get_events(self, stream_id: str) -> List[Event]:
        return self.event_store.get_stream(stream_id)

    # ---------------- Saga ----------------

    def create_saga(self, name: str) -> Saga:
        return Saga(name, event_store=self.event_store)

    # ---------------- Distributed transactions ----------------

    def run_distributed_transaction(self, participants: List[TransactionParticipant], payload: Any) -> bool:
        return self.tx_coordinator.execute(participants, payload)

    def shutdown(self) -> None:
        self.broker.shutdown()


# =====================================================================
# Simple usage example (only runs when executed directly)
# =====================================================================

if __name__ == "__main__":
    esb = EnterpriseServiceBus()

    # --- Simple synchronous request-response (the common case) ---
    esb.register_service("add", lambda payload: payload["a"] + payload["b"])
    result = esb.call("add", {"a": 2, "b": 3})
    print("Sync call result:", result)

    # --- Async pub/sub ---
    def on_order_created(msg: Message):
        print("Received event:", msg.channel, msg.payload)

    esb.subscribe("orders.created", on_order_created)
    esb.publish_event("orders.created", {"order_id": "123"})
    time.sleep(0.5)

    # --- Event sourcing ---
    esb.append_event("order-123", "OrderCreated", {"amount": 100})
    esb.append_event("order-123", "OrderShipped", {"carrier": "DHL"})
    print("Order events:", esb.get_events("order-123"))

    # --- Saga ---
    saga = esb.create_saga("order-fulfillment")
    saga.add_step(
        "reserve_inventory",
        action=lambda ctx: ctx.update({"inventory_reserved": True}),
        compensation=lambda ctx: ctx.update({"inventory_reserved": False}),
    )
    saga.add_step(
        "charge_payment",
        action=lambda ctx: (_ for _ in ()).throw(RuntimeError("payment failed")),
        compensation=lambda ctx: None,
    )
    success = saga.execute()
    print("Saga success:", success, "status:", saga.status)

    # --- Distributed transaction ---
    def make_participant(name):
        def prepare(tx_id, payload):
            print(f"{name} preparing tx {tx_id}")
            return True

        def commit(tx_id):
            print(f"{name} committing tx {tx_id}")

        def rollback(tx_id):
            print(f"{name} rolling back tx {tx_id}")

        return FunctionTransactionParticipant(prepare, commit, rollback)

    p1 = make_participant("ServiceA")
    p2 = make_participant("ServiceB")
    tx_success = esb.run_distributed_transaction([p1, p2], {"amount": 50})
    print("Transaction success:", tx_success)

    esb.shutdown()
