    Validates an order through a series of checks and processes it if all pass.

    Args:
        order (dict): Order data, expected to have 'id' and 'items' (list of dicts with 'sku' and 'quantity').
        customer (dict): Customer data, expected to have 'active' (bool).
        payment (dict): Payment data, expected to have 'verified' (bool).
        inventory (dict): Mapping of sku -> available stock quantity.
        shipping_address (dict): Address data, expected to have 'street', 'city', 'state', 'zip_code', 'country'.
        fraud_flags (list): List of fraud flags associated with the order.

    Returns:
        dict: A result dictionary with 'success' (bool), 'message' (str), and optionally 'order' (dict).
    """

    # 1. Check if order exists
    if not order or not isinstance(order, dict) or not order.get('id'):
        return {
            "success": False,
            "message": "Order does not exist."
        }

    # 2. Check if customer is active
    if not customer or not isinstance(customer, dict):
        return {
            "success": False,
            "message": "Customer information is missing."
        }

    if not customer.get('active', False):
        return {
            "success": False,
            "message": "Customer account is not active."
        }

    # 3. Check if payment is verified
    if not payment or not isinstance(payment, dict):
        return {
            "success": False,
            "message": "Payment information is missing."
        }

    if not payment.get('verified', False):
        return {
            "success": False,
            "message": "Payment is not verified."
        }

    # 4. Check if items are in stock
    items = order.get('items', [])
    if not items:
        return {
            "success": False,
            "message": "Order has no items."
        }

    for item in items:
        sku = item.get('sku')
        quantity_requested = item.get('quantity', 0)

        if sku is None:
            return {
                "success": False,
                "message": "Order item is missing SKU."
            }

        available_quantity = inventory.get(sku, 0)

        if available_quantity < quantity_requested:
            return {
                "success": False,
                "message": f"Insufficient stock for item '{sku}'. "
                            f"Requested: {quantity_requested}, Available: {available_quantity}."
            }

    # 5. Check if shipping address is valid
    if not shipping_address or not isinstance(shipping_address, dict):
        return {
            "success": False,
            "message": "Shipping address is missing."
        }

    required_address_fields = ['street', 'city', 'state', 'zip_code', 'country']
    for field in required_address_fields:
        value = shipping_address.get(field)
        if not value or not isinstance(value, str) or not value.strip():
            return {
                "success": False,
                "message": f"Shipping address is invalid: missing or empty '{field}'."
            }

    # 6. Check if no fraud flags
    if fraud_flags:
        return {
            "success": False,
            "message": f"Order flagged for fraud: {', '.join(str(flag) for flag in fraud_flags)}."
        }

    # 7. Process the order
    try:
        processed_order = process_order(order, customer, payment, shipping_address)
        return {
            "success": True,
            "message": "Order processed successfully.",
            "order": processed_order
        }
    except Exception as e:
        return {
            "success": False,
            "message": f"Order processing failed: {str(e)}"
        }


def process_order(order, customer, payment, shipping_address):
    """
    Simulates processing of an order after all validations have passed.

    Args:
        order (dict): The validated order.
        customer (dict): The validated customer.
        payment (dict): The validated payment.
        shipping_address (dict): The validated shipping address.

    Returns:
        dict: The processed order with updated status.
    """
    processed_order = dict(order)
    processed_order['status'] = 'processed'
    processed_order['customer_id'] = customer.get('id')
    processed_order['payment_id'] = payment.get('id')
    processed_order['shipping_address'] = shipping_address

    return processed_order
