def authenticate_request(request, connection):
    token = request.get("auth_token")
    if not token:
        raise AuthenticationError("Missing authentication token")
    if token != "valid-token":
        raise AuthenticationError("Invalid authentication token")
    return {"user_id": 123, "username": "demo_user"}


def authorize_request(request, user):
    required_scope = request.get("required_scope", "read")
    user_scopes = request.get("user_scopes", ["read"])
    if required_scope not in user_scopes:
        raise AuthorizationError(
            f"User lacks required scope: {required_scope}"
        )
    return True


def validate_payload(request):
    payload = request.get("payload")
    if payload is None:
        raise ValidationError("Payload is required")
    if not isinstance(payload, dict):
        raise ValidationError("Payload must be a JSON object")
    required_fields = request.get("required_fields", [])
    missing = [f for f in required_fields if f not in payload]
    if missing:
        raise ValidationError(f"Missing required fields: {', '.join(missing)}")
    return payload


