class ProductCatalog:
    def __init__(self):
        self.products = {}  # id -> Product
        self.sku_index = {}  # sku -> id
        self.category_index = defaultdict(set)  # category -> set(id)
        self.tag_index = defaultdict(set)  # tag -> set(id)
        self.purchase_history = []  # list of dicts
        self.co_purchase_counter = defaultdict(Counter)  # product_id -> Counter(other_id -> count)

    # ---------- Product Creation ----------
    def add_product(self, name, category, price, quantity=0, description="", tags=None, sku=None):
        if price < 0:
            raise ValueError("Price cannot be negative")
        if quantity < 0:
            raise ValueError("Quantity cannot be negative")

        product = Product(name, category, price, quantity, description, tags, sku)

        if product.sku in self.sku_index:
            raise ValueError(f"SKU {product.sku} already exists")

        self.products[product.id] = product
        self.sku_index[product.sku] = product.id
        self.category_index[category.lower()].add(product.id)
        for tag in product.tags:
            self.tag_index[tag.lower()].add(product.id)

        return product

    def remove_product(self, product_id):
        product = self._get_product_or_raise(product_id)
        self.category_index[product.category.lower()].discard(product_id)
        for tag in product.tags:
            self.tag_index[tag.lower()].discard(product_id)
        del self.sku_index[product.sku]
        del self.products[product_id]
        return True

    def _get_product_or_raise(self, product_id):
        product = self.products.get(product_id)
        if not product:
            raise ProductNotFoundError(f"Product {product_id} not found")
        return product

    def get_product(self, product_id):
        return self._get_product_or_raise(product_id)

