        product = self._get_product_or_raise(product_id)
        product.price = float(new_price)
        product.updated_at = datetime.now()
        product.price_history.append((product.updated_at, product.price))
        return product

    def apply_discount(self, product_id, percentage):
        if not (0 <= percentage <= 100):
            raise ValueError("Percentage must be between 0 and 100")
        product = self._get_product_or_raise(product_id)
        new_price = round(product.price * (1 - percentage / 100), 2)
        return self.update_price(product_id, new_price)

    def apply_bulk_discount(self, category, percentage):
        products = self.get_products_by_category(category)
        updated = []
        for product in products:
            updated.append(self.apply_discount(product.id, percentage))
        return updated

