        product = self._get_product_or_raise(product_id)
        return list(product.price_history)

    def get_price_range(self, category=None):
        if category:
            products = self.get_products_by_category(category)
        else:
            products = list(self.products.values())
        if not products:
            return (0, 0)
        prices = [p.price for p in products]
        return (min(prices), max(prices))

