        )
        return _fail_result(ref_date, errors)

    # Step 6: credentials.certifications
    certifications = safe_get(credentials, "certifications")
    if certifications is None:
        errors.append(
            "Missing 'certifications' on "
            "study.sites.primary.investigators.principal.credentials."
        )
        return _fail_result(ref_date, errors)

