            "study.sites.primary.investigators.principal.credentials.certifications."
        )
        return _fail_result(ref_date, errors)

    # Step 8: board.specialty
    specialty = safe_get(board, "specialty")
    if specialty is None:
        errors.append(
            "Missing 'specialty' on "
            "study.sites.primary.investigators.principal.credentials"
            ".certifications.board."
        )
        return _fail_result(ref_date, errors)

    # Step 9: specialty.subspecialty
    subspecialty = safe_get(specialty, "subspecialty")
    if subspecialty is None:
        errors.append(
            "Missing 'subspecialty' on "
            "study.sites.primary.investigators.principal.credentials"
            ".certifications.board.specialty."
        )
        return _fail_result(ref_date, errors)

    # Step 10: subspecialty.effective_date
    effective_date_raw = safe_get(subspecialty, "effective_date")
    if effective_date_raw is None:
        errors.append(
            "Missing 'effective_date' on "
            "study.sites.primary.investigators.principal.credentials"
            ".certifications.board.specialty.subspecialty."
        )
        return _fail_result(ref_date, errors)

