        "effective_date": effective_date,
        "reference_date": ref_date,
        "path_valid": True,
        "errors": errors,
    }


def _parse_date(value: Any, errors: list) -> Optional[date]:
    """Attempt to normalize various date representations to a date object."""
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, str):
