        try:
            return datetime.fromisoformat(value).date()
        except ValueError:
            errors.append(f"Unable to parse effective_date string: '{value}'.")
            return None
    errors.append(f"Unsupported effective_date type: {type(value)}.")
    return None


def _fail_result(ref_date: date, errors: list) -> dict:
    return {
        "compliant": False,
        "effective_date": None,
        "reference_date": ref_date,
        "path_valid": False,
        "errors": errors,
