        sku = order["sku"]
        quantity = order["quantity"]

        inv._reserved_items[sku] = max(0, inv._reserved_items.get(sku, 0) - quantity)

        order["status"] = "cancelled"
        return True

    def force_restock(self, sku, quantity):
        inv = self.inventory_manager
        if sku not in inv._stock_levels:
            inv._stock_levels[sku] = 0
            inv._reserved_items[sku] = 0
            inv._reorder_triggers[sku] = 5
            inv._supplier_queues[sku] = []

        inv._stock_levels[sku] += quantity

        if inv._supplier_queues.get(sku):
            inv._supplier_queues[sku].pop(0)

    def get_order_status(self, order_id):
        if order_id not in self.orders:
            raise ValueError(f"Order {order_id} does not exist")
        return self.orders[order_id]["status"]
