    elif action == "diagnosis":
        patient_id = request.get("patient_id")
        condition = request.get("condition")
        notes = request.get("notes", "")

        if not patient_id or not condition:
            return _error("Diagnosis requires 'patient_id' and 'condition'.")

        patient = _get_patient(patient_id)
        if not patient:
            return _error(f"No patient found with ID {patient_id}.")
        if patient.get("discharged"):
            return _error("Cannot add diagnosis: patient already discharged.")

        condition_key = condition.lower().strip()
        icd_code = ICD_CODES.get(condition_key, "R69")  # R69 = illness unspecified

        diagnosis_entry = {
            "diagnosis_id": _gen_id("DX"),
            "condition": condition,
            "icd_code": icd_code,
            "notes": notes,
            "date": _now(),
        }
        db["diagnoses"][patient_id].append(diagnosis_entry)

        db["bills"][patient_id].append({
