            return _error("Treatment plan requires 'patient_id'.")

        patient = _get_patient(patient_id)
        if not patient:
            return _error(f"No patient found with ID {patient_id}.")

        diagnoses = db["diagnoses"].get(patient_id, [])
        if not icd_code:
            if not diagnoses:
                return _error("No diagnosis on record; cannot create treatment plan.")
            icd_code = diagnoses[-1]["icd_code"]

        recommended = TREATMENT_LIBRARY.get(icd_code, ["General supportive care", "Follow-up as needed"])
        custom_notes = request.get("custom_instructions", "")

        plan = {
            "plan_id": _gen_id("TX"),
            "icd_code": icd_code,
            "recommended_treatments": recommended,
            "custom_instructions": custom_notes,
            "date": _now(),
        }
        db["treatments"][patient_id].append(plan)

        db["bills"][patient_id].append({
            "item": "Consultation / Treatment Planning Fee",
            "amount": BASE_COSTS["consultation_fee"],
            "timestamp": _now(),
