        if not patient:
            return _error(f"No patient found with ID {patient_id}.")

        provider_key = provider.lower().strip()
        provider_info = INSURANCE_PROVIDERS.get(provider_key)

        if not provider_info:
            verification = {
                "provider": provider,
                "policy_number": policy_number,
                "verified": False,
                "coverage_rate": 0.0,
                "message": "Unknown insurance provider.",
                "date": _now(),
            }
            db["insurance"][patient_id] = verification
            return {
                "success": False,
                "message": f"Provider '{provider}' not recognized. Marked as unverified.",
                "insurance": verification,
            }

        verified = provider_info["valid"] and bool(policy_number)
        verification = {
            "provider": provider,
            "policy_number": policy_number,
            "verified": verified,
            "coverage_rate": provider_info["coverage_rate"] if verified else 0.0,
