        insurance_info = db["insurance"].get(patient_id, {})
        coverage_rate = insurance_info.get("coverage_rate", 0.0) if insurance_info.get("verified") else 0.0

        insurance_covered = round(subtotal * coverage_rate, 2)
        patient_owed = round(subtotal - insurance_covered, 2)

        invoice = {
            "invoice_id": _gen_id("INV"),
            "patient_id": patient_id,
            "line_items": bills,
            "subtotal": round(subtotal, 2),
            "insurance_coverage_rate": coverage_rate,
            "insurance_covered_amount": insurance_covered,
            "amount_due": patient_owed,
            "generated_on": _now(),
        }

        return {
            "success": True,
