        existing_drugs = [p["drug_name"].lower() for p in db["prescriptions"].get(patient_id, [])]
        new_drug = drug_name.lower().strip()

        warnings = []
        for existing in existing_drugs:
            pair1 = (existing, new_drug)
            pair2 = (new_drug, existing)
            if pair1 in DRUG_INTERACTIONS:
                warnings.append(f"Interaction warning: {existing} + {new_drug} -> {DRUG_INTERACTIONS[pair1]}")
            elif pair2 in DRUG_INTERACTIONS:
                warnings.append(f"Interaction warning: {new_drug} + {existing} -> {DRUG_INTERACTIONS[pair2]}")

