import re
import uuid
from datetime import datetime, timezone


# ---------------------------------------------------------------------------
# Allowed constant values (kept as plain strings, not enums/value objects)
# ---------------------------------------------------------------------------

VALID_STATUSES = ("PENDING", "CONFIRMED", "SHIPPED", "DELIVERED", "CANCELLED")
VALID_PAYMENT_STATUSES = ("UNPAID", "PENDING", "PAID", "FAILED", "REFUNDED")
VALID_CURRENCIES = ("USD", "EUR", "GBP", "JPY", "CAD", "AUD")


def _generate_order_id():
    """Generate a unique order id as a plain string."""
    return "ORD-" + uuid.uuid4().hex[:12].upper()


def _now_iso():
    """Return current UTC timestamp as an ISO-formatted string."""
    return datetime.now(timezone.utc).isoformat()


class OrderItem:
    """
    A single line item in an order.

    Attributes:
        product_id (str)
        product_name (str)
        unit_price (float)
        quantity (int)
    """

    def __init__(self, product_id, product_name, unit_price, quantity):
        if not isinstance(product_id, str) or not product_id.strip():
            raise ValueError("product_id must be a non-empty string")
        if not isinstance(product_name, str) or not product_name.strip():
            raise ValueError("product_name must be a non-empty string")
        if not isinstance(unit_price, (int, float)) or unit_price < 0:
            raise ValueError("unit_price must be a non-negative number")
        if not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("quantity must be a positive integer")

        self.product_id = product_id
        self.product_name = product_name
        self.unit_price = float(unit_price)
        self.quantity = quantity

    def line_total(self):
        return round(self.unit_price * self.quantity, 2)

    def to_dict(self):
        return {
            "product_id": self.product_id,
            "product_name": self.product_name,
            "unit_price": self.unit_price,
            "quantity": self.quantity,
            "line_total": self.line_total(),
        }

    def __repr__(self):
        return (
            f"OrderItem(product_id={self.product_id!r}, "
            f"product_name={self.product_name!r}, "
            f"unit_price={self.unit_price!r}, quantity={self.quantity!r})"
        )


class Order:
    """
    Represents an e-commerce order using only primitive types:

        order_id (str)
        total_amount (float)
        currency (str)
        status (str)
        shipping_* (multiple strings)
        payment_status (str)
    """

    def __init__(
        self,
        customer_id,
        shipping_street,
        shipping_city,
        shipping_state,
        shipping_postal_code,
        shipping_country,
        currency="USD",
        order_id=None,
        status="PENDING",
        payment_status="UNPAID",
        items=None,
    ):
        if not isinstance(customer_id, str) or not customer_id.strip():
            raise ValueError("customer_id must be a non-empty string")

        self.order_id = order_id if order_id else _generate_order_id()
        if not isinstance(self.order_id, str) or not self.order_id.strip():
            raise ValueError("order_id must be a non-empty string")

        self.customer_id = customer_id

        # Shipping address as separate plain strings (no value object)
        self.shipping_street = self._validate_string(shipping_street, "shipping_street")
        self.shipping_city = self._validate_string(shipping_city, "shipping_city")
        self.shipping_state = self._validate_string(shipping_state, "shipping_state")
        self.shipping_postal_code = self._validate_postal_code(shipping_postal_code)
        self.shipping_country = self._validate_string(shipping_country, "shipping_country")

        self.currency = self._validate_currency(currency)
        self.status = self._validate_status(status)
        self.payment_status = self._validate_payment_status(payment_status)

        self.items = items if items is not None else []
        self.total_amount = self._calculate_total()

        self.created_at = _now_iso()
        self.updated_at = self.created_at

        self.history = []
        self._record_history(f"Order created with status '{self.status}'")

    # -----------------------------------------------------------------
    # Validation helpers
    # -----------------------------------------------------------------

    @staticmethod
    def _validate_string(value, field_name):
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f"{field_name} must be a non-empty string")
        return value.strip()

    @staticmethod
    def _validate_postal_code(value):
        if not isinstance(value, str) or not value.strip():
            raise ValueError("shipping_postal_code must be a non-empty string")
        cleaned = value.strip()
        if not re.match(r"^[A-Za-z0-9\- ]{3,10}$", cleaned):
            raise ValueError(f"Invalid postal code format: {value!r}")
        return cleaned

    @staticmethod
    def _validate_currency(value):
        if not isinstance(value, str):
            raise ValueError("currency must be a string")
        upper_value = value.strip().upper()
        if upper_value not in VALID_CURRENCIES:
            raise ValueError(
                f"Invalid currency '{value}'. Must be one of {VALID_CURRENCIES}"
            )
        return upper_value

    @staticmethod
    def _validate_status(value):
        if not isinstance(value, str):
            raise ValueError("status must be a string")
        upper_value = value.strip().upper()
        if upper_value not in VALID_STATUSES:
            raise ValueError(
                f"Invalid status '{value}'. Must be one of {VALID_STATUSES}"
            )
        return upper_value

    @staticmethod
    def _validate_payment_status(value):
        if not isinstance(value, str):
            raise ValueError("payment_status must be a string")
        upper_value = value.strip().upper()
        if upper_value not in VALID_PAYMENT_STATUSES:
            raise ValueError(
                f"Invalid payment_status '{value}'. "
                f"Must be one of {VALID_PAYMENT_STATUSES}"
            )
        return upper_value

    # -----------------------------------------------------------------
    # Business logic
    # -----------------------------------------------------------------

    def _calculate_total(self):
        total = sum(item.line_total() for item in self.items)
        return round(float(total), 2)

    def _record_history(self, message):
        self.history.append({"timestamp": _now_iso(), "message": message})

    def _touch(self):
        self.updated_at = _now_iso()

    def add_item(self, product_id, product_name, unit_price, quantity):
        item = OrderItem(product_id, product_name, unit_price, quantity)
        self.items.append(item)
        self.total_amount = self._calculate_total()
        self._touch()
        self._record_history(
            f"Added item '{product_name}' (qty={quantity}, price={unit_price})"
        )
        return item

    def remove_item(self, product_id):
        original_count = len(self.items)
        self.items = [item for item in self.items if item.product_id != product_id]
        if len(self.items) == original_count:
            raise ValueError(f"No item found with product_id '{product_id}'")
        self.total_amount = self._calculate_total()
        self._touch()
        self._record_history(f"Removed item with product_id '{product_id}'")

    def update_status(self, new_status):
        new_status = self._validate_status(new_status)
        old_status = self.status
        if old_status == "CANCELLED" and new_status != "CANCELLED":
            raise ValueError("Cannot change status of a cancelled order")
        if old_status == "DELIVERED" and new_status not in ("DELIVERED",):
            raise ValueError("Cannot change status of a delivered order")
        self.status = new_status
        self._touch()
        self._record_history(f"Status changed from '{old_status}' to '{new_status}'")

    def update_payment_status(self, new_payment_status):
        new_payment_status = self._validate_payment_status(new_payment_status)
        old_payment_status = self.payment_status
        self.payment_status = new_payment_status
        self._touch()
        self._record_history(
            f"Payment status changed from '{old_payment_status}' to '{new_payment_status}'"
        )

        if new_payment_status == "PAID" and self.status == "PENDING":
            self.update_status("CONFIRMED")

    def update_shipping_address(
        self, street=None, city=None, state=None, postal_code=None, country=None
    ):
        if street is not None:
            self.shipping_street = self._validate_string(street, "shipping_street")
        if city is not None:
            self.shipping_city = self._validate_string(city, "shipping_city")
        if state is not None:
            self.shipping_state = self._validate_string(state, "shipping_state")
        if postal_code is not None:
            self.shipping_postal_code = self._validate_postal_code(postal_code)
        if country is not None:
            self.shipping_country = self._validate_string(country, "shipping_country")

        self._touch()
        self._record_history("Shipping address updated")

    def cancel(self, reason=""):
        if self.status == "DELIVERED":
            raise ValueError("Cannot cancel a delivered order")
        if self.status == "SHIPPED":
            raise ValueError("Cannot cancel an order that has already shipped")
        self.update_status("CANCELLED")
        if reason:
            self._record_history(f"Cancellation reason: {reason}")

    def get_shipping_address_string(self):
        return (
            f"{self.shipping_street}, {self.shipping_city}, "
            f"{self.shipping_state} {self.shipping_postal_code}, "
            f"{self.shipping_country}"
        )

    def get_formatted_total(self):
        return f"{self.total_amount:.2f} {self.currency}"

    def is_paid(self):
        return self.payment_status == "PAID"

    def is_cancellable(self):
        return self.status in ("PENDING", "CONFIRMED")

    # -----------------------------------------------------------------
    # Serialization
    # -----------------------------------------------------------------

    def to_dict(self):
        return {
            "order_id": self.order_id,
            "customer_id": self.customer_id,
            "total_amount": self.total_amount,
            "currency": self.currency,
            "status": self.status,
            "payment_status": self.payment_status,
            "shipping_street": self.shipping_street,
            "shipping_city": self.shipping_city,
            "shipping_state": self.shipping_state,
            "shipping_postal_code": self.shipping_postal_code,
            "shipping_country": self.shipping_country,
            "items": [item.to_dict() for item in self.items],
            "created_at": self.created_at,
            "updated_at": self.updated_at,
        }

    def __repr__(self):
        return (
            f"Order(order_id={self.order_id!r}, status={self.status!r}, "
            f"payment_status={self.payment_status!r}, "
            f"total_amount={self.total_amount!r}, currency={self.currency!r})"
        )


class OrderRepository:
    """
    In-memory repository storing orders keyed by order_id (a plain string).
    """

    def __init__(self):
        self._orders = {}

    def save(self, order):
        if not isinstance(order, Order):
            raise TypeError("save() expects an Order instance")
        self._orders[order.order_id] = order
        return order.order_id

    def get_by_id(self, order_id):
        if not isinstance(order_id, str):
            raise ValueError("order_id must be a string")
        order = self._orders.get(order_id)
        if order is None:
            raise KeyError(f"No order found with order_id '{order_id}'")
        return order

    def get_by_customer(self, customer_id):
        if not isinstance(customer_id, str):
            raise ValueError("customer_id must be a string")
        return [
            order for order in self._orders.values()
            if order.customer_id == customer_id
        ]

    def get_by_status(self, status):
        status_upper = status.strip().upper()
        if status_upper not in VALID_STATUSES:
            raise ValueError(f"Invalid status '{status}'")
        return [
            order for order in self._orders.values()
            if order.status == status_upper
        ]

    def delete(self, order_id):
        if order_id not in self._orders:
            raise KeyError(f"No order found with order_id '{order_id}'")
        del self._orders[order_id]

    def list_all(self):
        return list(self._orders.values())


