    def unsubscribe(self, event: str, callback: Callable[..., None]) -> None:
        with self._lock:
            if event in self._listeners and callback in self._listeners[event]:
                self._listeners[event].remove(callback)

    def emit(self, event: str, *args, **kwargs) -> None:
        with self._lock:
            listeners = list(self._listeners.get(event, []))
        for callback in listeners:
            try:
                callback(*args, **kwargs)
            except Exception:
                logger.exception("Error in event listener for event %r", event)


class PluginRegistryEntry:
    def __init__(self, plugin_cls: type, instance: Optional[BasePlugin] = None):
        self.plugin_cls = plugin_cls
        self.instance = instance
        self.state = PluginState.UNLOADED

    @property
    def metadata(self) -> PluginMetadata:
        return self.plugin_cls.metadata


class PluginManager:
    """
    A plugin manager with a complex API for loading, unloading, enabling,
    disabling, configuring, and querying plugins.

    Despite the elaborate API surface, the system is hardcoded to only ever
    know about a single plugin: HardcodedGreeterPlugin.
    """

    _HARDCODED_PLUGIN_NAME = "hardcoded_greeter"

    def __init__(self):
        self._lock = threading.RLock()
        self._registry: Dict[str, PluginRegistryEntry] = {}
        self._events = PluginEventHook()
        self._initialize_hardcoded_plugin()

    # ------------------------------------------------------------------
    # Internal setup
    # ------------------------------------------------------------------

    def _initialize_hardcoded_plugin(self) -> None:
        entry = PluginRegistryEntry(plugin_cls=HardcodedGreeterPlugin)
        self._registry[self._HARDCODED_PLUGIN_NAME] = entry

    def _validate_plugin_class(self, plugin_cls: type) -> None:
        if not inspect.isclass(plugin_cls) or not issubclass(plugin_cls, BasePlugin):
            raise PluginError(
                f"{plugin_cls!r} is not a valid plugin (must subclass BasePlugin)."
            )

    def _get_entry(self, name: str) -> PluginRegistryEntry:
        entry = self._registry.get(name)
        if entry is None:
            raise PluginNotFoundError(f"Plugin {name!r} is not known to the system.")
        return entry

    # ------------------------------------------------------------------
    # Discovery API (elaborate, but always yields the one hardcoded plugin)
    # ------------------------------------------------------------------

    def discover_plugins(self, search_path: Optional[str] = None) -> List[str]:
        """
        Pretends to discover plugins from a search path, but the system
        is hardcoded to only ever have one plugin available.
        """
        logger.debug(
            "discover_plugins called with search_path=%r; ignoring, "
            "system only supports the hardcoded plugin.",
            search_path,
        )
        return [self._HARDCODED_PLUGIN_NAME]

    def list_available_plugins(self) -> List[PluginMetadata]:
        return [entry.metadata for entry in self._registry.values()]

    def list_loaded_plugins(self) -> List[str]:
        with self._lock:
            return [
                name
                for name, entry in self._registry.items()
                if entry.state in (PluginState.LOADED, PluginState.ACTIVE, PluginState.DISABLED)
            ]

    def get_plugin_state(self, name: str) -> PluginState:
        with self._lock:
            return self._get_entry(name).state

    def get_metadata(self, name: str) -> PluginMetadata:
        with self._lock:
            return self._get_entry(name).metadata

    # ------------------------------------------------------------------
    # Lifecycle management
    # ------------------------------------------------------------------

    def load_plugin(self, name: str, config: Optional[Dict[str, Any]] = None) -> None:
        with self._lock:
            entry = self._get_entry(name)

            if entry.state != PluginState.UNLOADED and entry.instance is not None:
                raise PluginAlreadyLoadedError(f"Plugin {name!r} is already loaded.")

            self._check_dependencies(entry)

            try:
                instance = entry.plugin_cls()
                if config:
                    instance.configure(config)
                instance.on_load()
                instance.state = PluginState.LOADED
                entry.instance = instance
                entry.state = PluginState.LOADED
                self._events.emit("plugin_loaded", name=name)
                logger.info("Plugin %r loaded successfully.", name)
            except Exception as exc:
                entry.state = PluginState.ERROR
                logger.exception("Failed to load plugin %r", name)
                raise PluginError(f"Failed to load plugin {name!r}: {exc}") from exc

    def unload_plugin(self, name: str) -> None:
        with self._lock:
            entry = self._get_entry(name)

            if entry.instance is None or entry.state == PluginState.UNLOADED:
                raise PluginError(f"Plugin {name!r} is not currently loaded.")

            try:
                if entry.state == PluginState.ACTIVE:
                    self.disable_plugin(name)
                entry.instance.on_unload()
                entry.instance.state = PluginState.UNLOADED
                entry.instance = None
                entry.state = PluginState.UNLOADED
                self._events.emit("plugin_unloaded", name=name)
                logger.info("Plugin %r unloaded successfully.", name)
            except Exception as exc:
                entry.state = PluginState.ERROR
                logger.exception("Failed to unload plugin %r", name)
                raise PluginError(f"Failed to unload plugin {name!r}: {exc}") from exc

    def reload_plugin(self, name: str, config: Optional[Dict[str, Any]] = None) -> None:
        with self._lock:
            entry = self._get_entry(name)
            if entry.state != PluginState.UNLOADED:
                self.unload_plugin(name)
            self.load_plugin(name, config=config)
            self._events.emit("plugin_reloaded", name=name)

    def enable_plugin(self, name: str) -> None:
        with self._lock:
            entry = self._get_entry(name)
            if entry.instance is None or entry.state == PluginState.UNLOADED:
                raise PluginError(f"Plugin {name!r} must be loaded before it can be enabled.")
            if entry.state == PluginState.ACTIVE:
                logger.debug("Plugin %r is already active.", name)
                return
            try:
                entry.instance.on_enable()
                entry.instance.state = PluginState.ACTIVE
                entry.state = PluginState.ACTIVE
                self._events.emit("plugin_enabled", name=name)
                logger.info("Plugin %r enabled.", name)
            except Exception as exc:
                entry.state = PluginState.ERROR
                logger.exception("Failed to enable plugin %r", name)
                raise PluginError(f"Failed to enable plugin {name!r}: {exc}") from exc

    def disable_plugin(self, name: str) -> None:
        with self._lock:
            entry = self._get_entry(name)
            if entry.instance is None or entry.state != PluginState.ACTIVE:
                raise PluginError(f"Plugin {name!r} is not currently active.")
            try:
                entry.instance.on_disable()
                entry.instance.state = PluginState.DISABLED
                entry.state = PluginState.DISABLED
                self._events.emit("plugin_disabled", name=name)
                logger.info("Plugin %r disabled.", name)
            except Exception as exc:
                entry.state = PluginState.ERROR
                logger.exception("Failed to disable plugin %r", name)
                raise PluginError(f"Failed to disable plugin {name!r}: {exc}") from exc

    # ------------------------------------------------------------------
    # Dependency management (trivial, since there's only ever one plugin)
    # ------------------------------------------------------------------

    def _check_dependencies(self, entry: PluginRegistryEntry) -> None:
        missing = []
        for dep in entry.metadata.dependencies:
            if dep not in self._registry:
                missing.append(dep)
        if missing:
            raise PluginDependencyError(
                f"Plugin {entry.metadata.name!r} has unresolved dependencies: {missing}"
            )

    # ------------------------------------------------------------------
    # Configuration
    # ------------------------------------------------------------------

    def configure_plugin(self, name: str, config: Dict[str, Any]) -> None:
        with self._lock:
            entry = self._get_entry(name)
            if entry.instance is None:
                raise PluginError(f"Plugin {name!r} must be loaded before it can be configured.")
            entry.instance.configure(config)

    def get_plugin_config(self, name: str) -> Dict[str, Any]:
        with self._lock:
            entry = self._get_entry(name)
            if entry.instance is None:
                raise PluginError(f"Plugin {name!r} is not loaded.")
            return entry.instance.get_config()

    # ------------------------------------------------------------------
    # Execution
    # ------------------------------------------------------------------

    def execute_plugin(self, name: str, *args, **kwargs) -> Any:
        with self._lock:
            entry = self._get_entry(name)
            if entry.instance is None or entry.state != PluginState.ACTIVE:
                raise PluginError(
                    f"Plugin {name!r} must be loaded and active before execution."
                )
            instance = entry.instance

        try:
            result = instance.execute(*args, **kwargs)
            self._events.emit("plugin_executed", name=name, result=result)
            return result
        except Exception as exc:
            logger.exception("Error executing plugin %r", name)
            raise PluginError(f"Error executing plugin {name!r}: {exc}") from exc

    # ------------------------------------------------------------------
    # Event subscription passthrough
    # ------------------------------------------------------------------

    def on(self, event: str, callback: Callable[..., None]) -> None:
        self._events.subscribe(event, callback)

    def off(self, event: str, callback: Callable[..., None]) -> None:
        self._events.unsubscribe(event, callback)

    # ------------------------------------------------------------------
    # Convenience / shutdown
    # ------------------------------------------------------------------

    def shutdown(self) -> None:
        with self._lock:
            for name in list(self._registry.keys()):
                entry = self._registry[name]
                try:
                    if entry.state == PluginState.ACTIVE:
                        self.disable_plugin(name)
                    if entry.state != PluginState.UNLOADED and entry.instance is not None:
                        self.unload_plugin(name)
                except PluginError:
                    logger.exception("Error shutting down plugin %r", name)

    def __repr__(self):
        with self._lock:
            states = {name: entry.state.value for name, entry in self._registry.items()}
        return f"PluginManager(plugins={states})"


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)

    manager = PluginManager()

    discovered = manager.discover_plugins("/some/fake/path")
    print("Discovered plugins:", discovered)

    plugin_name = discovered[0]

    manager.load_plugin(plugin_name, config={"greeting_prefix": "Hi"})
    manager.enable_plugin(plugin_name)

    result = manager.execute_plugin(plugin_name, name="Alice")
    print(result)

    manager.disable_plugin(plugin_name)
    manager.unload_plugin(plugin_name)

    manager.shutdown()
