class SearchIndexer:
    """
    In-memory search index over Article content fields.
    """

    def __init__(self):
        self._index = {}  # article_id -> dict of indexed field data

    def _tokenize(self, text):
        return set(re.findall(r"[a-z0-9]+", (text or "").lower()))

    def index_article(self, article: Article):
        tokens = set()
        tokens |= self._tokenize(article.title)
        tokens |= self._tokenize(article.body)
        tokens |= self._tokenize(article.author)
        tokens |= self._tokenize(article.tags)

        self._index[article.id] = {
            "tokens": tokens,
            "title": article.title,
            "body": article.body,
            "author": article.author,
            "tags": article.tags,
        }

    def remove_article(self, article_id):
        self._index.pop(article_id, None)

    def rebuild(self):
        self._index.clear()
        for article in Article.all():
            self.index_article(article)

    def search(self, query):
        query_tokens = self._tokenize(query)
