import csv
import io
import re
from datetime import datetime
from html import escape


# ---------------------------------------------------------------------------
# Database setup
# ---------------------------------------------------------------------------

DB_PATH = "cms.db"


def get_connection():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_connection()
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS articles (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            body TEXT NOT NULL,
            author TEXT NOT NULL,
            tags TEXT,
            created_at TEXT NOT NULL
        )
        """
    )
    conn.commit()
    conn.close()


# ---------------------------------------------------------------------------
# MODEL
# ---------------------------------------------------------------------------

class Article:
    """
    Model representing a CMS content item.

    Fields:
        id: int
        title: str
        body: str
        author: str
        tags: str (comma separated)
        created_at: str (ISO datetime)
    """

    FIELDS = ("title", "body", "author", "tags", "created_at")

    def __init__(self, id=None, title="", body="", author="", tags="",
                 created_at=None):
        self.id = id
        self.title = title
        self.body = body
        self.author = author
        self.tags = tags
        self.created_at = created_at or datetime.utcnow().isoformat()

    @classmethod
    def from_row(cls, row):
        if row is None:
            return None
        return cls(
            id=row["id"],
            title=row["title"],
            body=row["body"],
            author=row["author"],
            tags=row["tags"],
            created_at=row["created_at"],
        )

    def to_dict(self):
        return {
            "id": self.id,
            "title": self.title,
            "body": self.body,
            "author": self.author,
            "tags": self.tags,
            "created_at": self.created_at,
        }

    def save(self):
        conn = get_connection()
        cur = conn.cursor()
        if self.id is None:
            cur.execute(
                """
                INSERT INTO articles (title, body, author, tags, created_at)
                VALUES (?, ?, ?, ?, ?)
                """,
                (self.title, self.body, self.author, self.tags,
                 self.created_at),
            )
            self.id = cur.lastrowid
        else:
            cur.execute(
                """
                UPDATE articles
                SET title = ?, body = ?, author = ?, tags = ?, created_at = ?
                WHERE id = ?
                """,
                (self.title, self.body, self.author, self.tags,
                 self.created_at, self.id),
            )
        conn.commit()
        conn.close()
        return self

    @classmethod
    def get(cls, article_id):
        conn = get_connection()
        cur = conn.cursor()
        cur.execute("SELECT * FROM articles WHERE id = ?", (article_id,))
        row = cur.fetchone()
        conn.close()
        return cls.from_row(row)

    @classmethod
    def all(cls):
        conn = get_connection()
        cur = conn.cursor()
        cur.execute("SELECT * FROM articles ORDER BY id DESC")
        rows = cur.fetchall()
        conn.close()
        return [cls.from_row(r) for r in rows]

    @classmethod
    def delete(cls, article_id):
        conn = get_connection()
        cur = conn.cursor()
        cur.execute("DELETE FROM articles WHERE id = ?", (article_id,))
        conn.commit()
        conn.close()


