class ApiResponse:
    def __init__(self, status_code, body):
        self.status_code = status_code
        self.body = body

    def to_json(self):
        return json.dumps(self.body)

    def __repr__(self):
        return f"<ApiResponse {self.status_code} {self.body}>"


class ArticleAPIViews:
    """
    Simulated API view layer (framework-agnostic).
    Each method takes plain Python data structures and returns ApiResponse.
    """

    @staticmethod
    def list(query_params=None):
        query_params = query_params or {}
        search_query = query_params.get("q")

        if search_query:
            ids = search_indexer.search(search_query)
            articles = [Article.get(i) for i in ids]
            articles = [a for a in articles if a is not None]
        else:
            articles = Article.all()

        data = ArticleSerializer.serialize_many(articles)
        return ApiResponse(200, {"results": data, "count": len(data)})

    @staticmethod
    def retrieve(article_id):
        article = Article.get(article_id)
        if article is None:
            return ApiResponse(404, {"error": "Article not found."})
        return ApiResponse(200, ArticleSerializer.serialize(article))

    @staticmethod
    def create(payload):
        form = ArticleForm(payload)
        if not form.is_valid():
            return ApiResponse(400, {"errors": form.errors})
        article = form.save()
        search_indexer.index_article(article)
        return ApiResponse(201, ArticleSerializer.serialize(article))

    @staticmethod
    def update(article_id, payload):
        article = Article.get(article_id)
        if article is None:
            return ApiResponse(404, {"error": "Article not found."})

        form = ArticleForm(payload)
        if not form.is_valid():
            return ApiResponse(400, {"errors": form.errors})

        article = form.save(instance=article)
        search_indexer.index_article(article)
        return ApiResponse(200, ArticleSerializer.serialize(article))

    @staticmethod
    def delete(article_id):
        article = Article.get(article_id)
        if article is None:
            return ApiResponse(404, {"error": "Article not found."})
        Article.delete(article_id)
        search_indexer.remove_article(article_id)
        return ApiResponse(204, {})

    @staticmethod
    def export(query_params=None):
        query_params = query_params or {}
        fmt = query_params.get("format", "json")
        articles = Article.all()
        try:
            content = ExportHandler.export(articles, fmt=fmt)
        except ValueError as e:
            return ApiResponse(400, {"error": str(e)})
        return ApiResponse(200, {"format": fmt, "content": content})

    @staticmethod
    def render_html_detail(article_id):
        article = Article.get(article_id)
        if article is None:
            return ApiResponse(404, {"error": "Article not found."})
        html = ArticleTemplate.render_detail(article)
        return ApiResponse(200, {"html": html})

    @staticmethod
    def render_html_list():
        articles = Article.all()
        html = ArticleTemplate.render_list(articles)
        return ApiResponse(200, {"html": html})


