                "transaction_id": transaction_id,
                "message": "Transaction flagged for manual compliance review",
                "compliance_notes": compliance_notes,
                "account_from": account_from,
                "account_to": account_to,
                "amount": amount,
                "currency": currency,
                "category": category,
            }

    # --- Calculate fee ---
    if fee_type == "flat":
        calculated_fee = fee_amount
    elif fee_type == "percentage":
        calculated_fee = round(amount * (fee_amount / 100), 2)
    else:
