class TTLCache:
    """A simple thread-safe in-memory TTL cache."""

    def __init__(self, default_ttl: float = 60.0, max_size: int = 1024):
        self.default_ttl = default_ttl
        self.max_size = max_size
        self._store: Dict[str, CacheEntry] = {}
        self._lock = threading.Lock()

    def get(self, key: str) -> Optional[Any]:
        with self._lock:
            entry = self._store.get(key)
            if entry is None:
                return None
            if entry.expires_at < time.monotonic():
                del self._store[key]
                return None
            return entry.value

    def set(self, key: str, value: Any, ttl: Optional[float] = None):
        ttl = self.default_ttl if ttl is None else ttl
        with self._lock:
            if len(self._store) >= self.max_size and key not in self._store:
                self._evict_oldest()
            self._store[key] = CacheEntry(
                value=value, expires_at=time.monotonic() + ttl
            )

    def invalidate(self, key: str):
        with self._lock:
            self._store.pop(key, None)

    def clear(self):
        with self._lock:
            self._store.clear()

    def _evict_oldest(self):
        """Evict the entry with the earliest expiration time."""
        if not self._store:
            return
        oldest_key = min(self._store, key=lambda k: self._store[k].expires_at)
        del self._store[oldest_key]


@dataclass
class CachedResponse:
    """A lightweight, picklable stand-in for requests.Response for cache storage."""
    status_code: int
    headers: Dict[str, str]
    content: bytes
    url: str
    encoding: Optional[str] = None
    reason: str = ""
    from_cache: bool = field(default=True)

    @property
    def text(self) -> str:
        encoding = self.encoding or "utf-8"
        try:
            return self.content.decode(encoding, errors="replace")
        except (LookupError, TypeError):
            return self.content.decode("utf-8", errors="replace")

    def json(self, **kwargs) -> Any:
        import json
        return json.loads(self.text, **kwargs)

    def raise_for_status(self):
        if 400 <= self.status_code < 600:
            raise requests.HTTPError(
                f"{self.status_code} Error for url: {self.url}", response=self
            )

    @classmethod
    def from_response(cls, response: Response) -> "CachedResponse":
        return cls(
            status_code=response.status_code,
            headers=dict(response.headers),
            content=response.content,
            url=response.url,
            encoding=response.encoding,
            reason=response.reason,
        )


# ---------------------------------------------------------------------------
# Retry logic
# ---------------------------------------------------------------------------

@dataclass
class RetryConfig:
    max_attempts: int = 3
    base_delay: float = 0.5
    max_delay: float = 30.0
    backoff_multiplier: float = 2.0
    jitter: float = 0.1  # fraction of delay to randomize (+/-)
    retry_on_status_codes: Tuple[int, ...] = (429, 500, 502, 503, 504)
    retry_on_exceptions: Tuple[type, ...] = (
        requests.ConnectionError,
        requests.Timeout,
    )

    def compute_delay(self, attempt: int) -> float:
        """attempt is 0-indexed (0 = first retry delay)."""
        delay = min(self.base_delay * (self.backoff_multiplier ** attempt), self.max_delay)
        jitter_amount = delay * self.jitter
        delay = delay + random.uniform(-jitter_amount, jitter_amount)
        return max(delay, 0.0)


# ---------------------------------------------------------------------------
# Main client
# ---------------------------------------------------------------------------

class ResilientClient:
    """
    Wraps `requests` to add retry logic, a circuit breaker, and response caching.
    """

    CACHEABLE_METHODS = ("GET", "HEAD", "OPTIONS")

    def __init__(
        self,
        session: Optional[requests.Session] = None,
        retry_config: Optional[RetryConfig] = None,
        circuit_breaker: Optional[CircuitBreaker] = None,
        cache: Optional[TTLCache] = None,
        default_timeout: float = 10.0,
        cache_enabled: bool = True,
        cache_ttl: float = 60.0,
    ):
        self.session = session or requests.Session()
        self.retry_config = retry_config or RetryConfig()
        self.circuit_breaker = circuit_breaker or CircuitBreaker()
        self.cache = cache or TTLCache(default_ttl=cache_ttl)
        self.default_timeout = default_timeout
        self.cache_enabled = cache_enabled
        self.cache_ttl = cache_ttl

    # -- Public HTTP verb helpers -----------------------------------------

    def get(self, url: str, **kwargs) -> Any:
        return self.request("GET", url, **kwargs)

    def post(self, url: str, **kwargs) -> Any:
        return self.request("POST", url, **kwargs)

    def put(self, url: str, **kwargs) -> Any:
        return self.request("PUT", url, **kwargs)

    def delete(self, url: str, **kwargs) -> Any:
        return self.request("DELETE", url, **kwargs)

    def patch(self, url: str, **kwargs) -> Any:
        return self.request("PATCH", url, **kwargs)

    def head(self, url: str, **kwargs) -> Any:
        return self.request("HEAD", url, **kwargs)

    def options(self, url: str, **kwargs) -> Any:
        return self.request("OPTIONS", url, **kwargs)

    # -- Core request logic -------------------------------------------------

    def request(
        self,
        method: str,
        url: str,
        use_cache: Optional[bool] = None,
        cache_ttl: Optional[float] = None,
        params: Optional[Dict[str, Any]] = None,
        **kwargs,
    ) -> Any:
        """
        Perform an HTTP request with retry, circuit breaker, and caching support.

        Args:
            method: HTTP method (GET, POST, etc.)
            url: target URL
            use_cache: override default cache_enabled behavior for this call
            cache_ttl: override default cache TTL for this call
            params: query params (used in cache key)
            **kwargs: passed through to requests.Session.request

        Returns:
            requests.Response or CachedResponse
        """
        method = method.upper()
        should_use_cache = (
            self.cache_enabled if use_cache is None else use_cache
        ) and method in self.CACHEABLE_METHODS

        cache_key = None
        if should_use_cache:
            cache_key = self._build_cache_key(method, url, params, kwargs)
            cached = self.cache.get(cache_key)
            if cached is not None:
                logger.debug("Cache hit for %s %s", method, url)
                return cached

        kwargs.setdefault("timeout", self.default_timeout)

        response = self._execute_with_retry_and_breaker(method, url, params=params, **kwargs)

        if should_use_cache and response is not None:
            if 200 <= getattr(response, "status_code", 0) < 400:
                cached_response = CachedResponse.from_response(response)
                self.cache.set(cache_key, cached_response, ttl=cache_ttl or self.cache_ttl)

        return response

    def _execute_with_retry_and_breaker(
        self, method: str, url: str, **kwargs
    ) -> Response:
        last_exception: Optional[Exception] = None
        attempts = self.retry_config.max_attempts

        for attempt in range(attempts):
            try:
                self.circuit_breaker.before_call()
            except CircuitBreakerOpenError:
                logger.warning("Blocked by open circuit breaker: %s %s", method, url)
                raise

            try:
                response = self.session.request(method, url, **kwargs)
            except self.retry_config.retry_on_exceptions as exc:
                last_exception = exc
                self.circuit_breaker.on_failure(exc)
                logger.warning(
                    "Request exception on attempt %d/%d for %s %s: %s",
                    attempt + 1, attempts, method, url, exc,
                )
                if attempt < attempts - 1:
                    delay = self.retry_config.compute_delay(attempt)
                    time.sleep(delay)
                    continue
                raise RetryExhaustedError(
                    f"Retries exhausted for {method} {url}", last_exception=exc
                ) from exc
            except RequestException as exc:
                # Non-retryable request exception; still counts as circuit failure.
                self.circuit_breaker.on_failure(exc)
                raise

            if response.status_code in self.retry_config.retry_on_status_codes:
                last_exception = None
                self.circuit_breaker.on_failure(
                    RequestException(f"Status code {response.status_code}")
                )
                logger.warning(
                    "Retryable status code %d on attempt %d/%d for %s %s",
                    response.status_code, attempt + 1, attempts, method, url,
                )
                if attempt < attempts - 1:
                    delay = self.retry_config.compute_delay(attempt)
                    time.sleep(delay)
                    continue
                # Exhausted retries but we still have a valid HTTP response.
                return response

            # Success (including non-retryable error status codes like 404)
            self.circuit_breaker.on_success()
            return response

        # Should not reach here, but guard just in case.
        if last_exception:
            raise RetryExhaustedError(
                f"Retries exhausted for {method} {url}", last_exception=last_exception
            )
        raise RuntimeError("Unexpected state in retry loop")

    # -- Cache helpers -------------------------------------------------------

    @staticmethod
    def _build_cache_key(
        method: str, url: str, params: Optional[Dict[str, Any]], kwargs: Dict[str, Any]
    ) -> str:
        headers = kwargs.get("headers") or {}
        auth = kwargs.get("auth")
        key_material = repr((method, url, sorted((params or {}).items()),
                              sorted(headers.items()), auth))
        return hashlib.sha256(key_material.encode("utf-8")).hexdigest()

    def invalidate_cache(
        self, method: str, url: str, params: Optional[Dict[str, Any]] = None, **kwargs
    ):
        key = self._build_cache_key(method.upper(), url, params, kwargs)
        self.cache.invalidate(key)

    def clear_cache(self):
        self.cache.clear()

    # -- Circuit breaker helpers ----------------------------------------

    def reset_circuit_breaker(self):
        self.circuit_breaker.reset()

    @property
    def circuit_state(self) -> CircuitState:
        return self.circuit_breaker.state
