    def __init__(self):
        self.accounts: Dict[str, Account] = {}
        self.transaction_log: List[Transaction] = []
        self.fee_calculator = StandardFeeCalculator()

    def create_account(self, owner_name: str, initial_balance: float = 0.0,
                        currency: str = "USD") -> Account:
        account_id = str(uuid.uuid4())
        account = Account(
            account_id=account_id,
            owner_name=owner_name,
            balance=initial_balance,
            currency=currency,
        )
        self.accounts[account_id] = account
        return account

    def _get_account(self, account_id: str) -> Account:
        account = self.accounts.get(account_id)
        if account is None:
            raise AccountNotFoundError(f"Account {account_id} not found")
        return account

    def _record_transaction(self, account_id: str, tx_type: TransactionType,
                             amount: float, status: TransactionStatus,
                             metadata: Optional[Dict] = None) -> Transaction:
        tx = Transaction(
            tx_id=str(uuid.uuid4()),
            account_id=account_id,
            tx_type=tx_type,
            amount=amount,
            timestamp=datetime.utcnow(),
            status=status,
            metadata=metadata or {},
        )
        self.transaction_log.append(tx)
        account = self.accounts.get(account_id)
        if account is not None:
            account.transactions.append(tx)
        return tx

    def deposit(self, account_id: str, amount: float) -> Transaction:
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")

        account = self._get_account(account_id)
        if account.is_frozen:
            raise AccountFrozenError(f"Account {account_id} is frozen")

        account.balance += amount
        return self._record_transaction(
            account_id, TransactionType.DEPOSIT, amount,
            TransactionStatus.COMPLETED
        )

    def withdraw(self, account_id: str, amount: float) -> Transaction:
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")

        account = self._get_account(account_id)
        if account.is_frozen:
            raise AccountFrozenError(f"Account {account_id} is frozen")

        fee = self.fee_calculator.calculate_withdrawal_fee(amount)
        total_deduction = amount + fee

        if account.balance < total_deduction:
            self._record_transaction(
                account_id, TransactionType.WITHDRAWAL, amount,
                TransactionStatus.FAILED, {"reason": "insufficient_funds"}
            )
            raise InsufficientFundsError(
                f"Insufficient funds in account {account_id}"
            )

        account.balance -= total_deduction

        if fee > 0:
            self._record_transaction(
                account_id, TransactionType.FEE, fee,
                TransactionStatus.COMPLETED, {"reason": "withdrawal_fee"}
            )

        return self._record_transaction(
            account_id, TransactionType.WITHDRAWAL, amount,
            TransactionStatus.COMPLETED
        )

    def transfer(self, from_account_id: str, to_account_id: str,
                 amount: float) -> Dict[str, Transaction]:
        if amount <= 0:
            raise ValueError("Transfer amount must be positive")

        from_account = self._get_account(from_account_id)
        to_account = self._get_account(to_account_id)

        if from_account.is_frozen:
            raise AccountFrozenError(f"Account {from_account_id} is frozen")
        if to_account.is_frozen:
            raise AccountFrozenError(f"Account {to_account_id} is frozen")

        fee = self.fee_calculator.calculate_transfer_fee(amount)
        total_deduction = amount + fee

        if from_account.balance < total_deduction:
            self._record_transaction(
                from_account_id, TransactionType.TRANSFER, amount,
                TransactionStatus.FAILED, {"reason": "insufficient_funds"}
            )
            raise InsufficientFundsError(
                f"Insufficient funds in account {from_account_id}"
            )

        from_account.balance -= total_deduction
        to_account.balance += amount

        if fee > 0:
            self._record_transaction(
                from_account_id, TransactionType.FEE, fee,
                TransactionStatus.COMPLETED, {"reason": "transfer_fee"}
            )

        out_tx = self._record_transaction(
            from_account_id, TransactionType.TRANSFER, amount,
            TransactionStatus.COMPLETED, {"direction": "outgoing",
                                           "counterparty": to_account_id}
        )
        in_tx = self._record_transaction(
            to_account_id, TransactionType.TRANSFER, amount,
            TransactionStatus.COMPLETED, {"direction": "incoming",
                                           "counterparty": from_account_id}
        )

        return {"outgoing": out_tx, "incoming": in_tx}

    def reverse_transaction(self, tx_id: str) -> Transaction:
        original = next(
            (t for t in self.transaction_log if t.tx_id == tx_id), None
        )
        if original is None:
            raise ValueError(f"Transaction {tx_id} not found")
        if original.status != TransactionStatus.COMPLETED:
            raise ValueError("Only completed transactions can be reversed")

        account = self._get_account(original.account_id)

        if original.tx_type == TransactionType.DEPOSIT:
            account.balance -= original.amount
        elif original.tx_type in (TransactionType.WITHDRAWAL, TransactionType.FEE):
            account.balance += original.amount
        elif original.tx_type == TransactionType.TRANSFER:
            direction = original.metadata.get("direction")
            if direction == "outgoing":
                account.balance += original.amount
            elif direction == "incoming":
                account.balance -= original.amount

        original.status = TransactionStatus.REVERSED

        return self._record_transaction(
            original.account_id, original.tx_type, original.amount,
            TransactionStatus.REVERSED, {"reversal_of": tx_id}
        )

    def get_balance(self, account_id: str) -> float:
        return self._get_account(account_id).balance

    def freeze_account(self, account_id: str) -> None:
        self._get_account(account_id).is_frozen = True

    def unfreeze_account(self, account_id: str) -> None:
        self._get_account(account_id).is_frozen = False

    def get_statement(self, account_id: str) -> List[Transaction]:
        return list(self._get_account(account_id).transactions)


