class StandardFeeCalculator:
    """Current, active fee structure used by TransactionProcessor."""

    WITHDRAWAL_FEE_RATE = 0.001   # 0.1%
    TRANSFER_FEE_RATE = 0.0005    # 0.05%
    MIN_FEE = 0.0
    MAX_FEE = 25.0

    def calculate_withdrawal_fee(self, amount: float) -> float:
        fee = amount * self.WITHDRAWAL_FEE_RATE
        return min(max(fee, self.MIN_FEE), self.MAX_FEE)

    def calculate_transfer_fee(self, amount: float) -> float:
        fee = amount * self.TRANSFER_FEE_RATE
        return min(max(fee, self.MIN_FEE), self.MAX_FEE)


