class ExperimentalMeanReversionStrategy:
    """
    EXPERIMENTAL - untested in live markets. Uses z-score of price
    relative to a rolling window to suggest reversion trades.
    """

    def __init__(self, window: int = 20, z_threshold: float = 2.0):
        self.window = window
        self.z_threshold = z_threshold

    def _zscore(self, series: List[float]) -> float:
        mean = statistics.mean(series)
        stdev = statistics.pstdev(series)
        if stdev == 0:
            return 0.0
        return (series[-1] - mean) / stdev

    def generate_signals(self, prices: List[float]) -> List[str]:
        signals = []
        for i in range(len(prices)):
            if i < self.window:
                signals.append("HOLD")
                continue
            window_slice = prices[i - self.window:i + 1]
            z = self._zscore(window_slice)
            if z > self.z_threshold:
                signals.append("SELL")
            elif z < -self.z_threshold:
                signals.append("BUY")
            else:
                signals.append("HOLD")
        return signals


class ExperimentalMomentumRiskModel:
    """
    EXPERIMENTAL risk-adjusted momentum scorer. Purely for
    research; not wired into any live risk management pipeline.
    """

    def __init__(self, lookback: int = 30):
        self.lookback = lookback

    def score(self, prices: List[float]) -> float:
        if len(prices) < self.lookback + 1:
            return 0.0
        window = prices[-(self.lookback + 1):]
        returns = [
            (window[i] - window[i - 1]) / window[i - 1]
            for i in range(1, len(window))
            if window[i - 1] != 0
        ]
        if not returns:
            return 0.0
        avg_return = statistics.mean(returns)
        volatility = statistics.pstdev(returns) or 1e-9
        sharpe_like = avg_return / volatility
        return sharpe_like * math.sqrt(len(returns))


