    PHASE_3 = "Phase 3"
    PHASE_4 = "Phase 4"


class SeverityLevel(Enum):
    MILD = "Mild"
    MODERATE = "Moderate"
    SEVERE = "Severe"
    LIFE_THREATENING = "Life-Threatening"
    FATAL = "Fatal"


# ---------------------------------------------------------------------------
