class SafetyMonitor(ABC):
    def __init__(self):
        self.adverse_events: List[Dict[str, Any]] = []
        self.study_halted: bool = False

    @abstractmethod
    def monitoring_frequency(self) -> str:
        ...

    @abstractmethod
    def stopping_rule_threshold(self) -> int:
        ...

    def report_adverse_event(self, subject_id: str, description: str,
                              severity: SeverityLevel) -> None:
        event = {
            "subject_id": subject_id,
            "description": description,
            "severity": severity,
            "timestamp": datetime.now(),
        }
        self.adverse_events.append(event)
        self._evaluate_stopping_rules()

    def _evaluate_stopping_rules(self) -> None:
        severe_count = sum(
            1 for e in self.adverse_events
            if e["severity"] in (SeverityLevel.SEVERE, SeverityLevel.LIFE_THREATENING,
                                  SeverityLevel.FATAL)
        )
        if severe_count >= self.stopping_rule_threshold():
            self.study_halted = True

    def get_adverse_event_summary(self) -> Dict[str, int]:
        summary: Dict[str, int] = {}
        for e in self.adverse_events:
            key = e["severity"].value
            summary[key] = summary.get(key, 0) + 1
        return summary


