    CANCELLED = "CANCELLED"
    IN_PROGRESS = "IN_PROGRESS"
    ACTIVE = "ACTIVE"
    INACTIVE = "INACTIVE"


class EnterpriseResourcePlanning:
    def __init__(self, company_name: str):
        self.company_name = company_name

        # Procurement
        self.suppliers = {}
        self.purchase_orders = {}

        # Inventory
        self.warehouses = {}
        self.items = {}

        # Manufacturing
        self.bom = {}
        self.work_orders = {}

        # Sales
        self.customers = {}
        self.sales_orders = {}

        # Finance
        self.gl_accounts = {}
        self.journal_entries = {}
        self.invoices = {}

        # HR
        self.employees = {}
        self.payroll_records = {}

        # Project management
        self.projects = {}
        self.tasks = {}

        # Business intelligence
        self.reports = {}
        self.kpis = {}

        # Compliance
        self.audit_logs = []
        self.compliance_records = {}

        # Integration
        self.external_systems = {}
        self.integration_logs = []

    # ---------------------------------------------------------------
    # Internal helpers
    # ---------------------------------------------------------------
    def _new_id(self, prefix: str) -> str:
        return f"{prefix}-{uuid.uuid4().hex[:8]}"

    def _timestamp(self) -> str:
        return datetime.datetime.utcnow().isoformat()

    def _log_audit(self, action: str, details: dict):
        entry = {
            "id": self._new_id("AUD"),
            "timestamp": self._timestamp(),
            "action": action,
            "details": details,
        }
        self.audit_logs.append(entry)
        return entry

    # ---------------------------------------------------------------
    # Procurement
    # ---------------------------------------------------------------
    def add_supplier(self, name: str, contact_info: str, rating: float = 0.0) -> str:
        supplier_id = self._new_id("SUP")
        self.suppliers[supplier_id] = {
            "id": supplier_id,
            "name": name,
            "contact_info": contact_info,
            "rating": rating,
            "status": Status.ACTIVE.value,
        }
        self._log_audit("ADD_SUPPLIER", {"supplier_id": supplier_id, "name": name})
        return supplier_id

    def create_purchase_order(self, supplier_id: str, items: dict, expected_date: str = None) -> str:
        if supplier_id not in self.suppliers:
            raise ValueError("Supplier not found")
        po_id = self._new_id("PO")
        total_amount = sum(qty * price for qty, price in items.values())
        self.purchase_orders[po_id] = {
            "id": po_id,
            "supplier_id": supplier_id,
            "items": items,
            "total_amount": total_amount,
            "status": Status.PENDING.value,
            "created_at": self._timestamp(),
            "expected_date": expected_date,
        }
        self._log_audit("CREATE_PO", {"po_id": po_id, "supplier_id": supplier_id})
        return po_id

    def approve_purchase_order(self, po_id: str) -> bool:
        po = self.purchase_orders.get(po_id)
        if not po:
            raise ValueError("Purchase order not found")
        po["status"] = Status.APPROVED.value
        self._log_audit("APPROVE_PO", {"po_id": po_id})
        return True

    def receive_purchase_order(self, po_id: str) -> bool:
        po = self.purchase_orders.get(po_id)
        if not po:
            raise ValueError("Purchase order not found")
        if po["status"] != Status.APPROVED.value:
            raise ValueError("Purchase order must be approved before receiving")
        for item_id, (qty, _price) in po["items"].items():
            self.receive_inventory(item_id, qty, warehouse_id=None)
        po["status"] = Status.COMPLETED.value
        self._log_audit("RECEIVE_PO", {"po_id": po_id})
        return True

    # ---------------------------------------------------------------
    # Inventory
    # ---------------------------------------------------------------
    def add_warehouse(self, name: str, location: str) -> str:
        warehouse_id = self._new_id("WH")
        self.warehouses[warehouse_id] = {
            "id": warehouse_id,
            "name": name,
            "location": location,
            "inventory": {},
        }
        return warehouse_id

    def add_item(self, name: str, sku: str, unit_price: float, reorder_level: int = 10) -> str:
        item_id = self._new_id("ITM")
        self.items[item_id] = {
            "id": item_id,
            "name": name,
            "sku": sku,
            "unit_price": unit_price,
            "reorder_level": reorder_level,
            "quantity_on_hand": 0,
        }
        return item_id

    def receive_inventory(self, item_id: str, quantity: int, warehouse_id: Optional[str] = None) -> bool:
        if item_id not in self.items:
            raise ValueError("Item not found")
        self.items[item_id]["quantity_on_hand"] += quantity
        if warehouse_id:
            if warehouse_id not in self.warehouses:
                raise ValueError("Warehouse not found")
            wh_inv = self.warehouses[warehouse_id]["inventory"]
            wh_inv[item_id] = wh_inv.get(item_id, 0) + quantity
        self._log_audit("RECEIVE_INVENTORY", {"item_id": item_id, "quantity": quantity})
        return True

    def issue_inventory(self, item_id: str, quantity: int, warehouse_id: Optional[str] = None) -> bool:
        item = self.items.get(item_id)
        if not item:
            raise ValueError("Item not found")
        if item["quantity_on_hand"] < quantity:
            raise ValueError("Insufficient inventory")
        item["quantity_on_hand"] -= quantity
        if warehouse_id:
            wh = self.warehouses.get(warehouse_id)
            if not wh:
                raise ValueError("Warehouse not found")
            if wh["inventory"].get(item_id, 0) < quantity:
                raise ValueError("Insufficient inventory in warehouse")
            wh["inventory"][item_id] -= quantity
        self._log_audit("ISSUE_INVENTORY", {"item_id": item_id, "quantity": quantity})
        return True

    def check_reorder_needs(self) -> list:
        return [item for item in self.items.values() if item["quantity_on_hand"] <= item["reorder_level"]]

    # ---------------------------------------------------------------
    # Manufacturing
    # ---------------------------------------------------------------
    def create_bom(self, product_item_id: str, components: dict) -> str:
        bom_id = self._new_id("BOM")
        self.bom[bom_id] = {
            "id": bom_id,
            "product_item_id": product_item_id,
            "components": components,
        }
        return bom_id

    def create_work_order(self, bom_id: str, quantity: int) -> str:
        if bom_id not in self.bom:
            raise ValueError("BOM not found")
        wo_id = self._new_id("WO")
        self.work_orders[wo_id] = {
            "id": wo_id,
            "bom_id": bom_id,
            "quantity": quantity,
            "status": Status.PENDING.value,
            "created_at": self._timestamp(),
        }
        return wo_id

    def start_work_order(self, wo_id: str) -> bool:
        wo = self.work_orders.get(wo_id)
        if not wo:
            raise ValueError("Work order not found")
        bom = self.bom[wo["bom_id"]]
        for comp_id, qty_per_unit in bom["components"].items():
            required_qty = qty_per_unit * wo["quantity"]
            self.issue_inventory(comp_id, required_qty)
        wo["status"] = Status.IN_PROGRESS.value
        return True

    def complete_work_order(self, wo_id: str) -> bool:
        wo = self.work_orders.get(wo_id)
        if not wo:
            raise ValueError("Work order not found")
        if wo["status"] != Status.IN_PROGRESS.value:
            raise ValueError("Work order must be in progress to complete")
        bom = self.bom[wo["bom_id"]]
        self.receive_inventory(bom["product_item_id"], wo["quantity"])
        wo["status"] = Status.COMPLETED.value
        return True

    # ---------------------------------------------------------------
    # Sales
    # ---------------------------------------------------------------
    def add_customer(self, name: str, contact_info: str, credit_limit: float = 0.0) -> str:
        customer_id = self._new_id("CUST")
        self.customers[customer_id] = {
            "id": customer_id,
            "name": name,
            "contact_info": contact_info,
            "credit_limit": credit_limit,
            "status": Status.ACTIVE.value,
        }
        return customer_id

    def create_sales_order(self, customer_id: str, items: dict) -> str:
        if customer_id not in self.customers:
            raise ValueError("Customer not found")
        so_id = self._new_id("SO")
        total_amount = sum(qty * price for qty, price in items.values())
        self.sales_orders[so_id] = {
            "id": so_id,
            "customer_id": customer_id,
            "items": items,
            "total_amount": total_amount,
            "status": Status.PENDING.value,
            "created_at": self._timestamp(),
        }
        return so_id

    def fulfill_sales_order(self, so_id: str) -> bool:
        so = self.sales_orders.get(so_id)
        if not so:
            raise ValueError("Sales order not found")
        for item_id, (qty, _price) in so["items"].items():
            self.issue_inventory(item_id, qty)
        so["status"] = Status.COMPLETED.value
        self.create_invoice(so["customer_id"], so["total_amount"], reference_id=so_id)
        return True

    def cancel_sales_order(self, so_id: str) -> bool:
        so = self.sales_orders.get(so_id)
        if not so:
            raise ValueError("Sales order not found")
        so["status"] = Status.CANCELLED.value
        return True

    # ---------------------------------------------------------------
    # Finance
    # ---------------------------------------------------------------
    def add_gl_account(self, name: str, account_type: str) -> str:
        account_id = self._new_id("GL")
        self.gl_accounts[account_id] = {
            "id": account_id,
            "name": name,
            "type": account_type,
            "balance": 0.0,
        }
        return account_id

    def post_journal_entry(self, debit_account_id: str, credit_account_id: str, amount: float, memo: str = "") -> str:
        if debit_account_id not in self.gl_accounts or credit_account_id not in self.gl_accounts:
            raise ValueError("Invalid GL account")
        entry_id = self._new_id("JE")
        self.gl_accounts[debit_account_id]["balance"] += amount
        self.gl_accounts[credit_account_id]["balance"] -= amount
        self.journal_entries[entry_id] = {
            "id": entry_id,
            "debit_account": debit_account_id,
            "credit_account": credit_account_id,
            "amount": amount,
            "memo": memo,
            "timestamp": self._timestamp(),
        }
        return entry_id

    def create_invoice(self, customer_id: str, amount: float, reference_id: str = None) -> str:
        invoice_id = self._new_id("INV")
        self.invoices[invoice_id] = {
            "id": invoice_id,
            "customer_id": customer_id,
            "amount": amount,
            "reference_id": reference_id,
            "status": Status.PENDING.value,
            "created_at": self._timestamp(),
        }
        return invoice_id

    def pay_invoice(self, invoice_id: str) -> bool:
        invoice = self.invoices.get(invoice_id)
        if not invoice:
            raise ValueError("Invoice not found")
        invoice["status"] = Status.COMPLETED.value
        return True

    def get_financial_summary(self) -> dict:
        total_assets = sum(a["balance"] for a in self.gl_accounts.values() if a["type"] == "asset")
        total_liabilities = sum(a["balance"] for a in self.gl_accounts.values() if a["type"] == "liability")
        total_revenue = sum(a["balance"] for a in self.gl_accounts.values() if a["type"] == "revenue")
        total_expense = sum(a["balance"] for a in self.gl_accounts.values() if a["type"] == "expense")
        return {
            "total_assets": total_assets,
            "total_liabilities": total_liabilities,
            "total_revenue": total_revenue,
            "total_expense": total_expense,
            "net_income": total_revenue - total_expense,
        }

    # ---------------------------------------------------------------
    # HR
    # ---------------------------------------------------------------
    def hire_employee(self, name: str, position: str, salary: float, department: str) -> str:
        employee_id = self._new_id("EMP")
        self.employees[employee_id] = {
            "id": employee_id,
            "name": name,
            "position": position,
            "salary": salary,
            "department": department,
            "status": Status.ACTIVE.value,
            "hired_at": self._timestamp(),
        }
        return employee_id

    def terminate_employee(self, employee_id: str) -> bool:
        emp = self.employees.get(employee_id)
        if not emp:
            raise ValueError("Employee not found")
        emp["status"] = Status.INACTIVE.value
        return True

    def run_payroll(self, employee_id: str) -> str:
        emp = self.employees.get(employee_id)
        if not emp:
            raise ValueError("Employee not found")
        payroll_id = self._new_id("PAY")
        self.payroll_records[payroll_id] = {
            "id": payroll_id,
            "employee_id": employee_id,
            "amount": emp["salary"],
            "date": self._timestamp(),
        }
        return payroll_id

    def run_payroll_batch(self) -> list:
        return [self.run_payroll(emp_id) for emp_id, emp in self.employees.items() if emp["status"] == Status.ACTIVE.value]

    # ---------------------------------------------------------------
    # Project Management
    # ---------------------------------------------------------------
    def create_project(self, name: str, budget: float, manager_id: Optional[str] = None) -> str:
        project_id = self._new_id("PRJ")
        self.projects[project_id] = {
            "id": project_id,
            "name": name,
            "budget": budget,
            "manager_id": manager_id,
            "status": Status.ACTIVE.value,
            "created_at": self._timestamp(),
        }
        return project_id

    def add_task(self, project_id: str, name: str, assignee_id: Optional[str] = None, due_date: str = None) -> str:
        if project_id not in self.projects:
            raise ValueError("Project not found")
        task_id = self._new_id("TSK")
        self.tasks[task_id] = {
            "id": task_id,
            "project_id": project_id,
            "name": name,
            "assignee_id": assignee_id,
            "due_date": due_date,
            "status": Status.PENDING.value,
        }
        return task_id

    def complete_task(self, task_id: str) -> bool:
        task = self.tasks.get(task_id)
        if not task:
            raise ValueError("Task not found")
        task["status"] = Status.COMPLETED.value
        return True

    def get_project_status(self, project_id: str) -> dict:
        if project_id not in self.projects:
            raise ValueError("Project not found")
        project_tasks = [t for t in self.tasks.values() if t["project_id"] == project_id]
        completed = len([t for t in project_tasks if t["status"] == Status.COMPLETED.value])
        total = len(project_tasks)
        return {
            "project_id": project_id,
            "total_tasks": total,
            "completed_tasks": completed,
            "completion_rate": (completed / total * 100) if total else 0.0,
        }

    # ---------------------------------------------------------------
    # Business Intelligence
    # ---------------------------------------------------------------
    def generate_report(self, report_type: str) -> str:
        report_id = self._new_id("RPT")
        data = {}
        if report_type == "financial":
            data = self.get_financial_summary()
        elif report_type == "inventory":
            data = {"low_stock_items": [i["id"] for i in self.check_reorder_needs()]}
        elif report_type == "sales":
            data = {
                "total_orders": len(self.sales_orders),
                "total_revenue": sum(so["total_amount"] for so in self.sales_orders.values()
                                      if so["status"] == Status.COMPLETED.value),
            }
        elif report_type == "hr":
            data = {"active_employees": len([e for e in self.employees.values() if e["status"] == Status.ACTIVE.value])}
        else:
            data = {"message": "Unknown report type"}

        self.reports[report_id] = {
            "id": report_id,
            "type": report_type,
            "data": data,
            "generated_at": self._timestamp(),
        }
        return report_id

    def set_kpi(self, name: str, target_value: float, current_value: float = 0.0) -> str:
        kpi_id = self._new_id("KPI")
        self.kpis[kpi_id] = {
            "id": kpi_id,
            "name": name,
            "target_value": target_value,
            "current_value": current_value,
        }
        return kpi_id

    def update_kpi(self, kpi_id: str, current_value: float) -> bool:
        kpi = self.kpis.get(kpi_id)
        if not kpi:
            raise ValueError("KPI not found")
        kpi["current_value"] = current_value
        return True

    def get_dashboard(self) -> dict:
        return {
            "financial_summary": self.get_financial_summary(),
            "low_stock_items": len(self.check_reorder_needs()),
            "active_projects": len([p for p in self.projects.values() if p["status"] == Status.ACTIVE.value]),
            "kpis": self.kpis,
        }

    # ---------------------------------------------------------------
    # Compliance
    # ---------------------------------------------------------------
    def add_compliance_record(self, regulation: str, description: str, status: str = "PENDING") -> str:
        record_id = self._new_id("CMP")
        self.compliance_records[record_id] = {
            "id": record_id,
            "regulation": regulation,
            "description": description,
            "status": status,
            "created_at": self._timestamp(),
        }
        return record_id

    def update_compliance_status(self, record_id: str, status: str) -> bool:
        record = self.compliance_records.get(record_id)
        if not record:
            raise ValueError("Compliance record not found")
        record["status"] = status
        return True

    def get_audit_trail(self, action_filter: Optional[str] = None) -> list:
        if action_filter:
            return [log for log in self.audit_logs if log["action"] == action_filter]
        return self.audit_logs

    def get_compliance_report(self) -> dict:
        total = len(self.compliance_records)
        compliant = len([r for r in self.compliance_records.values() if r["status"] == "COMPLIANT"])
        return {
            "total_records": total,
            "compliant_records": compliant,
            "compliance_rate": (compliant / total * 100) if total else 0.0,
        }

    # ---------------------------------------------------------------
    # Integration
    # ---------------------------------------------------------------
    def register_external_system(self, name: str, system_type: str, config: dict = None) -> str:
        system_id = self._new_id("EXT")
        self.external_systems[system_id] = {
            "id": system_id,
            "name": name,
            "type": system_type,
            "config": config or {},
            "status": Status.ACTIVE.value,
        }
        return system_id

    def sync_with_external_system(self, system_id: str, payload: dict) -> str:
        system = self.external_systems.get(system_id)
        if not system:
            raise ValueError("External system not found")
        log_id = self._new_id("INTLOG")
        log_entry = {
            "id": log_id,
            "system_id": system_id,
            "payload": payload,
            "timestamp": self._timestamp(),
            "status": "SUCCESS",
        }
        self.integration_logs.append(log_entry)
        return log_id

    def disconnect_external_system(self, system_id: str) -> bool:
        system = self.external_systems.get(system_id)
        if not system:
            raise ValueError("External system not found")
        system["status"] = Status.INACTIVE.value
        return True

    def get_integration_logs(self, system_id: Optional[str] = None) -> list:
        if system_id:
            return [log for log in self.integration_logs if log["system_id"] == system_id]
        return self.integration_logs
