    def render_list_item(user: User) -> str:
        return (
            f"<li data-user-id='{user.user_id}'>"
            f"{user.username} ({user.email}) - {user.full_name}"
            f"</li>"
        )

    @staticmethod
    def render_list(users: List[User]) -> str:
        items = "\n".join(UserTemplates.render_list_item(u) for u in users)
