        if claim_id not in self.insurance_claims:
            raise ValueError("Claim not found")
        claim = self.insurance_claims[claim_id]
        claim["status"] = status
        claim["paid_amount"] = paid_amount
        claim["adjudication_notes"] = notes
        claim["adjudicated_at"] = self._now()

        if status == ClaimStatus.PAID and paid_amount > 0:
            self.apply_payment(claim["invoice_id"], paid_amount, payment_source="insurance")

        self._log("adjudicate_claim", {"claim_id": claim_id, "status": status.value})
        return claim

    def get_claims_for_patient(self, patient_id):
        self._check_patient_exists(patient_id)
        return [c for c in self.insurance_claims.values() if c["patient_id"] == patient_id]

