    def record_quality_metric(self, metric_name, value, patient_id=None,
                               measurement_date=None):
        metric_id = self._new_id("QM-")
        self.quality_metrics[metric_id] = {
            "metric_id": metric_id,
            "metric_name": metric_name,
            "value": value,
            "patient_id": patient_id,
            "measurement_date": measurement_date or self._now(),
            "recorded_at": self._now()
        }
        self._log("record_quality_metric", {"metric_id": metric_id, "metric_name": metric_name})
        return metric_id

    def get_metric_average(self, metric_name):
        values = [m["value"] for m in self.quality_metrics.values()
                  if m["metric_name"] == metric_name]
        if not values:
            return None
        return sum(values) / len(values)

    def get_metrics_summary(self):
        summary = {}
        for m in self.quality_metrics.values():
            summary.setdefault(m["metric_name"], []).append(m["value"])
        return {name: {"count": len(vals), "average": sum(vals) / len(vals)}
                for name, vals in summary.items()}

    # ---------------------- Regulatory Reporting ----------------------
    def generate_regulatory_report(self, report_type, start_date, end_date):
        report_id = self._new_id("REP-")

        def in_range(timestamp_str):
            try:
                ts = datetime.datetime.fromisoformat(timestamp_str)
            except (ValueError, TypeError):
                return False
            return start_date <= ts <= end_date

        data = {}
        if report_type == "patient_census":
            data["total_patients"] = len(self.patients)
            data["active_patients"] = sum(1 for p in self.patients.values() if p["active"])
        elif report_type == "clinical_activity":
            data["total_notes"] = sum(1 for n in self.clinical_notes.values()
                                       if in_range(n["created_at"]))
            data["total_orders"] = sum(1 for o in self.orders.values()
                                        if in_range(o["created_at"]))
        elif report_type == "pharmacy_activity":
            data["total_prescriptions"] = sum(1 for rx in self.prescriptions.values()
                                               if in_range(rx["prescribed_at"]))
        elif report_type == "lab_activity":
            data["total_lab_orders"] = sum(1 for lo in self.lab_orders.values()
                                            if in_range(lo["created_at"]))
        elif report_type == "financial":
            data["total_invoiced"] = sum(i["total_amount"] for i in self.invoices.values()
                                          if in_range(i["created_at"]))
            data["total_collected"] = sum(i["amount_paid"] for i in self.invoices.values()
                                           if in_range(i["created_at"]))
        elif report_type == "quality":
            data["metrics"] = self.get_metrics_summary()
        else:
            raise ValueError(f"Unknown report type: {report_type}")

        report = {
            "report_id": report_id,
            "report_type": report_type,
            "start_date": start_date.isoformat(),
            "end_date": end_date.isoformat(),
            "data": data,
            "generated_at": self._now()
        }
        self.regulatory_reports[report_id] = report
        self._log("generate_regulatory_report", {"report_id": report_id, "report_type": report_type})
        return report

    def get_report(self, report_id):
        if report_id not in self.regulatory_reports:
            raise ValueError("Report not found")
        return self.regulatory_reports[report_id]

    def get_audit_log(self, limit=None):
        if limit:
            return self.audit_log[-limit:]
        return self.audit_log
