class OrderProcessor:
    def __init__(
        self,
        inventory: Optional[Dict[str, int]] = None,
        catalog: Optional[Dict[str, float]] = None,
        tax_rate: float = 0.08,
        base_shipping_cost: float = 5.0,
        free_shipping_threshold: float = 100.0,
        payment_gateway: Optional[Callable[[str, float], bool]] = None,
        shipping_provider: Optional[Callable[[Dict], str]] = None,
        notifier: Optional[Callable[[str, str, Dict], None]] = None,
    ):
        self.inventory = inventory if inventory is not None else {}
        self.catalog = catalog if catalog is not None else {}
        self.tax_rate = tax_rate
        self.base_shipping_cost = base_shipping_cost
        self.free_shipping_threshold = free_shipping_threshold
        self.payment_gateway = payment_gateway or self._default_payment_gateway
        self.shipping_provider = shipping_provider or self._default_shipping_provider
        self.notifier = notifier or self._default_notifier
        self.orders: Dict[str, Order] = {}
        self._reserved_inventory: Dict[str, Dict[str, int]] = {}

    # ---------------- Default integrations ----------------

    def _default_payment_gateway(self, customer_id: str, amount: float) -> bool:
        if amount <= 0:
            return False
        return True

    def _default_shipping_provider(self, shipping_address: Dict) -> str:
        return f"TRACK-{uuid.uuid4().hex[:12].upper()}"

    def _default_notifier(self, customer_id: str, event: str, payload: Dict) -> None:
        print(f"[NOTIFY] customer={customer_id} event={event} payload={payload}")

    # ---------------- Public API ----------------

    def create_order(self, customer_id: str, items: List[Dict], shipping_address: Dict) -> Order:
        if not customer_id:
            raise ValidationError("customer_id is required.")
        if not items:
            raise ValidationError("Order must contain at least one item.")
        if not shipping_address:
            raise ValidationError("shipping_address is required.")

        order_items = []
        for raw_item in items:
            sku = raw_item.get("sku")
            quantity = raw_item.get("quantity")
            if not sku or quantity is None:
                raise ValidationError("Each item requires 'sku' and 'quantity'.")
            order_items.append(OrderItem(sku=sku, quantity=quantity))

        order = Order(customer_id=customer_id, items=order_items, shipping_address=shipping_address)
        order.add_history("order_created")
        self.orders[order.order_id] = order
        return order

    def process_order(self, order_id: str) -> Order:
        order = self._get_order(order_id)
        try:
            self.validate_order(order)
            self.calculate_pricing(order)
            self.reserve_inventory(order)
            self.process_payment(order)
            self.coordinate_shipping(order)
            self.commit_inventory(order)
            order.set_status(OrderStatus.COMPLETED)
            self.send_notification(order, "order_completed")
        except OrderProcessingError as e:
            self.release_reserved_inventory(order)
            order.error_message = str(e)
            order.set_status(OrderStatus.FAILED)
            self.send_notification(order, "order_failed", {"error": str(e)})
            raise
        return order

    def cancel_order(self, order_id: str) -> Order:
        order = self._get_order(order_id)
        if order.status in (OrderStatus.COMPLETED, OrderStatus.SHIPPED):
            raise OrderProcessingError("Cannot cancel an order that has already shipped or completed.")
        self.release_reserved_inventory(order)
        order.set_status(OrderStatus.CANCELLED)
        self.send_notification(order, "order_cancelled")
        return order

    def get_order(self, order_id: str) -> Order:
        return self._get_order(order_id)

    # ---------------- Internal processing steps ----------------

    def _get_order(self, order_id: str) -> Order:
        order = self.orders.get(order_id)
        if not order:
            raise OrderProcessingError(f"Order {order_id} not found.")
        return order

    def validate_order(self, order: Order) -> None:
        if order.status != OrderStatus.PENDING:
            raise ValidationError(f"Order {order.order_id} is not in PENDING state.")

        if not order.items:
            raise ValidationError("Order has no items.")

        for item in order.items:
            if item.sku not in self.catalog:
                raise ValidationError(f"SKU {item.sku} not found in catalog.")
            available = self.inventory.get(item.sku, 0)
            if available < item.quantity:
                raise InventoryError(
                    f"Insufficient inventory for {item.sku}: requested {item.quantity}, available {available}."
                )

        required_fields = ["street", "city", "postal_code", "country"]
        for field in required_fields:
            if field not in order.shipping_address or not order.shipping_address[field]:
                raise ValidationError(f"Shipping address missing required field: {field}")

        order.set_status(OrderStatus.VALIDATED)

    def calculate_pricing(self, order: Order) -> None:
        if order.status != OrderStatus.VALIDATED:
            raise OrderProcessingError("Order must be validated before pricing.")

        subtotal = 0.0
        for item in order.items:
            unit_price = self.catalog[item.sku]
            item.unit_price = unit_price
            item.line_total = unit_price * item.quantity
            subtotal += item.line_total

        tax = round(subtotal * self.tax_rate, 2)
        shipping_cost = 0.0 if subtotal >= self.free_shipping_threshold else self.base_shipping_cost
        total = round(subtotal + tax + shipping_cost, 2)

        order.subtotal = round(subtotal, 2)
        order.tax = tax
        order.shipping_cost = shipping_cost
        order.total = total

        order.set_status(OrderStatus.PRICED)

    def reserve_inventory(self, order: Order) -> None:
        reserved = {}
        try:
            for item in order.items:
                available = self.inventory.get(item.sku, 0)
                if available < item.quantity:
                    raise InventoryError(
                        f"Insufficient inventory for {item.sku} during reservation."
                    )
                self.inventory[item.sku] = available - item.quantity
                reserved[item.sku] = item.quantity
            self._reserved_inventory[order.order_id] = reserved
            order.add_history("inventory_reserved", reserved)
        except InventoryError:
            for sku, qty in reserved.items():
                self.inventory[sku] = self.inventory.get(sku, 0) + qty
            raise

    def release_reserved_inventory(self, order: Order) -> None:
        reserved = self._reserved_inventory.pop(order.order_id, None)
        if reserved:
            for sku, qty in reserved.items():
                self.inventory[sku] = self.inventory.get(sku, 0) + qty
            order.add_history("inventory_released", reserved)

    def commit_inventory(self, order: Order) -> None:
        self._reserved_inventory.pop(order.order_id, None)
        order.add_history("inventory_committed")

    def process_payment(self, order: Order) -> None:
        if order.status != OrderStatus.PRICED:
            raise OrderProcessingError("Order must be priced before payment.")

        try:
            success = self.payment_gateway(order.customer_id, order.total)
        except Exception as e:
            raise PaymentError(f"Payment gateway error: {e}")

        if not success:
            raise PaymentError(f"Payment failed for order {order.order_id}.")

        order.payment_id = f"PMT-{uuid.uuid4().hex[:16].upper()}"
        order.set_status(OrderStatus.PAID)
        order.add_history("payment_processed", {"payment_id": order.payment_id, "amount": order.total})

    def coordinate_shipping(self, order: Order) -> None:
        if order.status != OrderStatus.PAID:
            raise OrderProcessingError("Order must be paid before shipping.")

        try:
            tracking_number = self.shipping_provider(order.shipping_address)
        except Exception as e:
            raise ShippingError(f"Shipping provider error: {e}")

        if not tracking_number:
            raise ShippingError(f"Failed to obtain tracking number for order {order.order_id}.")

        order.tracking_number = tracking_number
        order.set_status(OrderStatus.SHIPPED)
        order.add_history("shipping_coordinated", {"tracking_number": tracking_number})

    def send_notification(self, order: Order, event: str, extra: Optional[Dict] = None) -> None:
        payload = order.to_dict()
        if extra:
            payload.update(extra)
        try:
            self.notifier(order.customer_id, event, payload)
        except Exception:
            pass
        order.add_history(f"notification_sent:{event}")
