def has_diagnosis(record: Dict, diagnosis_code: str) -> bool:
    """Check whether the record contains a given diagnosis code."""
    return diagnosis_code in record["diagnosis_codes"]


def total_dosage_for_medication(record: Dict, medication_code: str) -> float:
    """Sum dosages for all entries matching a given medication code."""
    total = 0.0
    for code, dosage in zip(record["medication_codes"], record["dosages"]):
        if code == medication_code:
            total += dosage
    return total


def validate_record_consistency(record: Dict) -> List[str]:
    """
    Validate that a record's parallel lists are consistent and all entries
    are valid. Returns a list of error messages (empty list means valid).
    """
    errors = []

    if not validate_mrn(record.get("patient_mrn", "")):
        errors.append("Invalid or missing patient_mrn")

    diagnosis_codes = record.get("diagnosis_codes", [])
    medication_codes = record.get("medication_codes", [])
    dosages = record.get("dosages", [])
    units = record.get("units", [])

    if not (len(medication_codes) == len(dosages) == len(units)):
        errors.append(
            "medication_codes, dosages, and units lengths do not match"
        )
        return errors

    for code in diagnosis_codes:
        if not validate_diagnosis_code(code):
            errors.append(f"Invalid diagnosis code: {code!r}")

    for i, med_code in enumerate(medication_codes):
        if not validate_medication_code(med_code):
            errors.append(f"Invalid medication code at index {i}: {med_code!r}")
        if not validate_dosage(dosages[i]):
            errors.append(f"Invalid dosage at index {i}: {dosages[i]!r}")
        if not validate_unit(units[i]):
            errors.append(f"Invalid unit at index {i}: {units[i]!r}")

    return errors


def merge_patient_records(record_a: Dict, record_b: Dict) -> Dict:
    """
    Merge two patient records with the same MRN into one, deduplicating
    diagnosis codes and combining medication lists.
    """
    if record_a["patient_mrn"] != record_b["patient_mrn"]:
        raise PatientRecordError(
            "Cannot merge records with different patient_mrn values"
        )

    merged_diagnoses = list(record_a["diagnosis_codes"])
    for code in record_b["diagnosis_codes"]:
        if code not in merged_diagnoses:
            merged_diagnoses.append(code)

    merged_med_codes = list(record_a["medication_codes"]) + list(
        record_b["medication_codes"]
    )
    merged_dosages = list(record_a["dosages"]) + list(record_b["dosages"])
    merged_units = list(record_a["units"]) + list(record_b["units"])

    return {
        "patient_mrn": record_a["patient_mrn"],
        "diagnosis_codes": merged_diagnoses,
        "medication_codes": merged_med_codes,
        "dosages": merged_dosages,
        "units": merged_units,
    }


def find_records_by_diagnosis(
    records: List[Dict], diagnosis_code: str
) -> List[Dict]:
    """Return all records that contain the given diagnosis code."""
    return [r for r in records if has_diagnosis(r, diagnosis_code)]


def find_records_by_medication(
    records: List[Dict], medication_code: str
) -> List[Dict]:
    """Return all records that contain the given medication code."""
    return [
        r for r in records if medication_code in r.get("medication_codes", [])
    ]


def format_record_summary(record: Dict) -> str:
    """Generate a human-readable summary string for a patient record."""
    lines = [f"Patient MRN: {record['patient_mrn']}"]

    if record["diagnosis_codes"]:
        lines.append("Diagnoses: " + ", ".join(record["diagnosis_codes"]))
    else:
        lines.append("Diagnoses: None")

    if record["medication_codes"]:
        lines.append("Medications:")
        for code, dosage, unit in zip(
            record["medication_codes"], record["dosages"], record["units"]
        ):
            lines.append(f"  - {code}: {dosage} {unit}")
    else:
        lines.append("Medications: None")

    return "\n".join(lines)


def check_dosage_within_range(
    record: Dict,
    medication_code: str,
    min_dosage: float,
    max_dosage: float,
) -> Optional[bool]:
    """
    Check whether all dosages for the given medication code fall within
    [min_dosage, max_dosage]. Returns None if the medication is not present.
    """
    details = get_medication_details(record, medication_code)
    if not details:
        return None

    return all(min_dosage <= dosage <= max_dosage for _, dosage, _ in details)
