"""
Analytics system.

Adding a new metric requires touching:
  - DataCollector   (collect raw data for the metric)
  - MetricCalculator(compute the metric value)
  - Dashboard       (render the metric on the dashboard)
  - Report          (include the metric in generated reports)
  - Export          (export the metric to external formats)
  - Alert           (check the metric against thresholds)
  - APIResponse     (serialize the metric for API consumers)
"""

from __future__ import annotations

import json
import statistics
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Dict, List, Optional


# ---------------------------------------------------------------------------
# Raw data storage
# ---------------------------------------------------------------------------

@dataclass
class RawDataStore:
    page_views: List[Dict[str, Any]] = field(default_factory=list)
    session_durations: List[Dict[str, Any]] = field(default_factory=list)
    bounce_events: List[Dict[str, Any]] = field(default_factory=list)
    conversion_events: List[Dict[str, Any]] = field(default_factory=list)
    revenue_events: List[Dict[str, Any]] = field(default_factory=list)
    error_events: List[Dict[str, Any]] = field(default_factory=list)


# ---------------------------------------------------------------------------
# DataCollector: one explicit method per metric
# ---------------------------------------------------------------------------

class DataCollector:
    def __init__(self):
        self.store = RawDataStore()

    def collect_page_view(self, url: str, timestamp: Optional[datetime] = None) -> None:
        self.store.page_views.append({
            "url": url,
            "timestamp": timestamp or datetime.utcnow(),
        })

    def collect_session_duration(self, session_id: str, duration_seconds: float) -> None:
        self.store.session_durations.append({
            "session_id": session_id,
            "duration_seconds": duration_seconds,
        })

    def collect_bounce_event(self, session_id: str, bounced: bool) -> None:
        self.store.bounce_events.append({
            "session_id": session_id,
            "bounced": bounced,
        })

    def collect_conversion_event(self, user_id: str, converted: bool) -> None:
        self.store.conversion_events.append({
            "user_id": user_id,
            "converted": converted,
        })

    def collect_revenue_event(self, user_id: str, amount: float) -> None:
        self.store.revenue_events.append({
            "user_id": user_id,
            "amount": amount,
        })

    def collect_error_event(self, error_code: str) -> None:
        self.store.error_events.append({
            "error_code": error_code,
        })

    def get_store(self) -> RawDataStore:
        return self.store


# ---------------------------------------------------------------------------
# MetricCalculator: one explicit method per metric
# ---------------------------------------------------------------------------

class MetricCalculator:
    def __init__(self, store: RawDataStore):
        self.store = store

    def calculate_page_views(self) -> int:
        return len(self.store.page_views)

    def calculate_avg_session_duration(self) -> float:
        durations = [d["duration_seconds"] for d in self.store.session_durations]
        return statistics.mean(durations) if durations else 0.0

    def calculate_bounce_rate(self) -> float:
        events = self.store.bounce_events
        if not events:
            return 0.0
        bounced = sum(1 for e in events if e["bounced"])
        return bounced / len(events)

    def calculate_conversion_rate(self) -> float:
        events = self.store.conversion_events
        if not events:
            return 0.0
        converted = sum(1 for e in events if e["converted"])
        return converted / len(events)

    def calculate_total_revenue(self) -> float:
        return sum(e["amount"] for e in self.store.revenue_events)

    def calculate_error_rate(self) -> float:
        total_requests = len(self.store.page_views)
        if not total_requests:
            return 0.0
        return len(self.store.error_events) / total_requests

    def calculate_all(self) -> Dict[str, float]:
        return {
            "page_views": self.calculate_page_views(),
            "avg_session_duration": self.calculate_avg_session_duration(),
            "bounce_rate": self.calculate_bounce_rate(),
            "conversion_rate": self.calculate_conversion_rate(),
            "total_revenue": self.calculate_total_revenue(),
            "error_rate": self.calculate_error_rate(),
        }


# ---------------------------------------------------------------------------
# Dashboard: one explicit render method per metric widget
# ---------------------------------------------------------------------------

class Dashboard:
    def __init__(self, calculator: MetricCalculator):
        self.calculator = calculator

    def render_page_views_widget(self) -> str:
        value = self.calculator.calculate_page_views()
        return f"[Widget] Page Views: {value}"

    def render_avg_session_duration_widget(self) -> str:
        value = self.calculator.calculate_avg_session_duration()
        return f"[Widget] Avg Session Duration: {value:.2f}s"

    def render_bounce_rate_widget(self) -> str:
        value = self.calculator.calculate_bounce_rate()
        return f"[Widget] Bounce Rate: {value:.2%}"

    def render_conversion_rate_widget(self) -> str:
        value = self.calculator.calculate_conversion_rate()
        return f"[Widget] Conversion Rate: {value:.2%}"

    def render_total_revenue_widget(self) -> str:
        value = self.calculator.calculate_total_revenue()
        return f"[Widget] Total Revenue: ${value:,.2f}"

    def render_error_rate_widget(self) -> str:
        value = self.calculator.calculate_error_rate()
        return f"[Widget] Error Rate: {value:.2%}"

    def render_full_dashboard(self) -> str:
        widgets = [
            self.render_page_views_widget(),
            self.render_avg_session_duration_widget(),
            self.render_bounce_rate_widget(),
            self.render_conversion_rate_widget(),
            self.render_total_revenue_widget(),
            self.render_error_rate_widget(),
        ]
        return "\n".join(widgets)


# ---------------------------------------------------------------------------
# Report: one explicit section builder per metric
# ---------------------------------------------------------------------------

class Report:
    def __init__(self, calculator: MetricCalculator):
        self.calculator = calculator

    def build_page_views_section(self) -> str:
        value = self.calculator.calculate_page_views()
        return f"Page Views: {value}"

    def build_avg_session_duration_section(self) -> str:
        value = self.calculator.calculate_avg_session_duration()
        return f"Average Session Duration: {value:.2f} seconds"

    def build_bounce_rate_section(self) -> str:
        value = self.calculator.calculate_bounce_rate()
        return f"Bounce Rate: {value * 100:.2f}%"

    def build_conversion_rate_section(self) -> str:
        value = self.calculator.calculate_conversion_rate()
        return f"Conversion Rate: {value * 100:.2f}%"

    def build_total_revenue_section(self) -> str:
        value = self.calculator.calculate_total_revenue()
        return f"Total Revenue: ${value:,.2f}"

    def build_error_rate_section(self) -> str:
        value = self.calculator.calculate_error_rate()
        return f"Error Rate: {value * 100:.2f}%"

    def generate_full_report(self) -> str:
        sections = [
            "=== Analytics Report ===",
            self.build_page_views_section(),
            self.build_avg_session_duration_section(),
            self.build_bounce_rate_section(),
            self.build_conversion_rate_section(),
            self.build_total_revenue_section(),
            self.build_error_rate_section(),
        ]
        return "\n".join(sections)


# ---------------------------------------------------------------------------
# Export: one explicit field mapping per metric, per format
# ---------------------------------------------------------------------------

class Export:
    def __init__(self, calculator: MetricCalculator):
        self.calculator = calculator

    def _collect_export_fields(self) -> Dict[str, Any]:
        return {
            "page_views": self.calculator.calculate_page_views(),
            "avg_session_duration": self.calculator.calculate_avg_session_duration(),
            "bounce_rate": self.calculator.calculate_bounce_rate(),
            "conversion_rate": self.calculator.calculate_conversion_rate(),
            "total_revenue": self.calculator.calculate_total_revenue(),
            "error_rate": self.calculator.calculate_error_rate(),
        }

    def export_to_json(self) -> str:
        return json.dumps(self._collect_export_fields(), indent=2)

    def export_to_csv(self) -> str:
        fields = self._collect_export_fields()
        header = ",".join(fields.keys())
        row = ",".join(str(v) for v in fields.values())
        return f"{header}\n{row}"

    def export_to_dict(self) -> Dict[str, Any]:
        return self._collect_export_fields()


# ---------------------------------------------------------------------------
# Alert: one explicit threshold check per metric
# ---------------------------------------------------------------------------

@dataclass
class AlertThresholds:
    max_page_views: Optional[float] = None
    min_page_views: Optional[float] = None
    max_avg_session_duration: Optional[float] = None
    min_avg_session_duration: Optional[float] = None
    max_bounce_rate: Optional[float] = None
    min_conversion_rate: Optional[float] = None
    min_total_revenue: Optional[float] = None
    max_error_rate: Optional[float] = None


class Alert:
    def __init__(self, calculator: MetricCalculator, thresholds: AlertThresholds):
        self.calculator = calculator
        self.thresholds = thresholds

    def check_page_views(self) -> List[str]:
        alerts = []
        value = self.calculator.calculate_page_views()
        if self.thresholds.max_page_views is not None and value > self.thresholds.max_page_views:
            alerts.append(f"ALERT: Page views {value} exceeded max {self.thresholds.max_page_views}")
        if self.thresholds.min_page_views is not None and value < self.thresholds.min_page_views:
            alerts.append(f"ALERT: Page views {value} below min {self.thresholds.min_page_views}")
        return alerts

    def check_avg_session_duration(self) -> List[str]:
        alerts = []
        value = self.calculator.calculate_avg_session_duration()
        if self.thresholds.max_avg_session_duration is not None and value > self.thresholds.max_avg_session_duration:
            alerts.append(f"ALERT: Avg session duration {value:.2f}s exceeded max {self.thresholds.max_avg_session_duration}s")
        if self.thresholds.min_avg_session_duration is not None and value < self.thresholds.min_avg_session_duration:
            alerts.append(f"ALERT: Avg session duration {value:.2f}s below min {self.thresholds.min_avg_session_duration}s")
        return alerts

    def check_bounce_rate(self) -> List[str]:
        alerts = []
        value = self.calculator.calculate_bounce_rate()
        if self.thresholds.max_bounce_rate is not None and value > self.thresholds.max_bounce_rate:
