        if not isinstance(premium, (int, float)) or premium < 0:
            raise ValueError("premium must be a non-negative number")
        if status not in self.VALID_STATUSES:
            raise ValueError(f"status must be one of {self.VALID_STATUSES}")

        self.policy_number = policy_number
        self.effective_date = effective_date
        self.expiration_date = expiration_date
        self.premium = float(premium)
        self.coverage_limits = self._validate_float_dict(
            coverage_limits or {}, "coverage_limits"
        )
        self.deductibles = self._validate_float_dict(deductibles or {}, "deductibles")
