        stock: Stock = order.instrument  # type: ignore[assignment]
        if not isinstance(stock, Stock):
            self._reject(order, "Instrument is not a Stock")

    def route(self, order: Order) -> None:
        # route to equities exchange
        self._simulate_fill(order)


class OptionOrderHandler(OrderHandler):
    def _validate_instrument_specific(self, order: Order) -> None:
        option: Option = order.instrument  # type: ignore[assignment]
        if not isinstance(option, Option):
            self._reject(order, "Instrument is not an Option")
            return
        if option.is_expired(date.today()):
            self._reject(order, "Option has expired")

    def route(self, order: Order) -> None:
        # route to options exchange, factoring multiplier
        self._simulate_fill(order)


class FutureOrderHandler(OrderHandler):
    def _validate_instrument_specific(self, order: Order) -> None:
        future: Future = order.instrument  # type: ignore[assignment]
        if not isinstance(future, Future):
            self._reject(order, "Instrument is not a Future")
            return
        if future.expiry <= date.today():
            self._reject(order, "Future contract has expired")

    def route(self, order: Order) -> None:
        # route to futures exchange, snap to tick size
        future: Future = order.instrument  # type: ignore[assignment]
        if order.limit_price is not None:
            ticks = round(order.limit_price / future.tick_size)
            order.limit_price = ticks * future.tick_size
        self._simulate_fill(order)


class ForexOrderHandler(OrderHandler):
    def _validate_instrument_specific(self, order: Order) -> None:
        fx: Forex = order.instrument  # type: ignore[assignment]
        if not isinstance(fx, Forex):
            self._reject(order, "Instrument is not Forex")

    def route(self, order: Order) -> None:
        # route to OTC/ECN liquidity pool
        self._simulate_fill(order)


# ----------------------------------------------------------------------------
# RiskCalculator hierarchy
# ----------------------------------------------------------------------------

class RiskCalculator(ABC):
    @abstractmethod
    def calculate_var(self, order: Order, confidence: float = 0.99) -> float:
        """Value at Risk estimate for the position."""
        ...

    @abstractmethod
    def max_loss(self, order: Order) -> float:
        ...

    def notional(self, order: Order) -> float:
        return order.instrument.price * order.quantity * order.instrument.contract_size()


class StockRiskCalculator(RiskCalculator):
    DAILY_VOL = 0.02

    def calculate_var(self, order: Order, confidence: float = 0.99) -> float:
        z = 2.33 if confidence >= 0.99 else 1.65
        return self.notional(order) * self.DAILY_VOL * z

    def max_loss(self, order: Order) -> float:
        if order.side == OrderSide.BUY:
            return self.notional(order)  # can lose full value
        return float("inf")  # unlimited loss potential on short stock


class OptionRiskCalculator(RiskCalculator):
    def calculate_var(self, order: Order, confidence: float = 0.99) -> float:
        option: Option = order.instrument  # type: ignore[assignment]
        z = 2.33 if confidence >= 0.99 else 1.65
        vega_like_risk = option.implied_vol * option.price
        return vega_like_risk * order.quantity * option.multiplier * z

    def max_loss(self, order: Order) -> float:
        option: Option = order.instrument  # type: ignore[assignment]
        if order.side == OrderSide.BUY:
            return option.price * order.quantity * option.multiplier
        if option.option_type == OptionType.CALL:
            return float("inf")  # naked short call unlimited risk
        return option.strike * order.quantity * option.multiplier  # short put


class FutureRiskCalculator(RiskCalculator):
    DAILY_VOL = 0.015

    def calculate_var(self, order: Order, confidence: float = 0.99) -> float:
        z = 2.33 if confidence >= 0.99 else 1.65
        return self.notional(order) * self.DAILY_VOL * z

    def max_loss(self, order: Order) -> float:
        return float("inf")  # leveraged, theoretically unlimited


class ForexRiskCalculator(RiskCalculator):
    DAILY_VOL = 0.01

    def calculate_var(self, order: Order, confidence: float = 0.99) -> float:
        z = 2.33 if confidence >= 0.99 else 1.65
        return self.notional(order) * self.DAILY_VOL * z

    def max_loss(self, order: Order) -> float:
        return self.notional(order)


# ----------------------------------------------------------------------------
# MarginCalculator hierarchy
# ----------------------------------------------------------------------------

class MarginCalculator(ABC):
    @abstractmethod
    def initial_margin(self, order: Order) -> float:
        ...

    @abstractmethod
    def maintenance_margin(self, order: Order) -> float:
        ...

    def _notional(self, order: Order) -> float:
        return order.instrument.price * order.quantity * order.instrument.contract_size()


class StockMarginCalculator(MarginCalculator):
    REG_T_INITIAL = 0.50
    MAINTENANCE = 0.25

    def initial_margin(self, order: Order) -> float:
        return self._notional(order) * self.REG_T_INITIAL

    def maintenance_margin(self, order: Order) -> float:
        return self._notional(order) * self.MAINTENANCE


class OptionMarginCalculator(MarginCalculator):
    def initial_margin(self, order: Order) -> float:
        option: Option = order.instrument  # type: ignore[assignment]
        premium = option.price * order.quantity * option.multiplier
        if order.side == OrderSide.BUY:
            return premium  # pay full premium, no additional margin
        # simplified short-option margin: premium + % of underlying notional
        underlying_notional = option.strike * order.quantity * option.multiplier
        return premium + 0.20 * underlying_notional

    def maintenance_margin(self, order: Order) -> float:
        return self.initial_margin(order) * 0.75


class FutureMarginCalculator(MarginCalculator):
    SPAN_RATE = 0.10

    def initial_margin(self, order: Order) -> float:
        return self._notional(order) * self.SPAN_RATE

    def maintenance_margin(self, order: Order) -> float:
        return self.initial_margin(order) * 0.80


class ForexMarginCalculator(MarginCalculator):
    LEVERAGE = 50  # 2% margin

    def initial_margin(self, order: Order) -> float:
        return self._notional(order) / self.LEVERAGE

    def maintenance_margin(self, order: Order) -> float:
        return self.initial_margin(order) * 0.5


# ----------------------------------------------------------------------------
# SettlementProcessor hierarchy
# ----------------------------------------------------------------------------

class SettlementProcessor(ABC):
    def settle(self, order: Order) -> Order:
        if order.status != OrderStatus.FILLED:
            raise ValueError("Order must be FILLED before settlement")
        self._process_settlement(order)
        order.status = OrderStatus.SETTLED
        return order

    @abstractmethod
    def _process_settlement(self, order: Order) -> None:
        ...

    @abstractmethod
    def settlement_days(self) -> int:
        ...


class StockSettlementProcessor(SettlementProcessor):
    def settlement_days(self) -> int:
        return 2  # T+2

    def _process_settlement(self, order: Order) -> None:
        # transfer shares vs. cash, T+2
        order.settlement_note = f"Equity settled T+{self.settlement_days()}"  # type: ignore[attr-defined]


class OptionSettlementProcessor(SettlementProcessor):
    def settlement_days(self) -> int:
        return 1  # T+1

    def _process_settlement(self, order: Order) -> None:
        option: Option = order.instrument  # type: ignore[assignment]
        if option.is_expired(date.today()):
            order.settlement_note = "Option expired - exercised/assigned"  # type: ignore[attr-defined]
        else:
            order.settlement_note = f"Option settled T+{self.settlement_days()}"  # type: ignore[attr-defined]


class FutureSettlementProcessor(SettlementProcessor):
    def settlement_days(self) -> int:
        return 0  # daily mark-to-market, T+0 variation margin

    def _process_settlement(self, order: Order) -> None:
        future: Future = order.instrument  # type: ignore[assignment]
        variation = (order.fill_price - future.price) * order.quantity * future.multiplier
        order.settlement_note = f"Future daily variation margin: {variation:.2f}"  # type: ignore[attr-defined]


class ForexSettlementProcessor(SettlementProcessor):
    def settlement_days(self) -> int:
        return 2  # T+2 spot convention

    def _process_settlement(self, order: Order) -> None:
        order.settlement_note = f"FX spot settled T+{self.settlement_days()}"  # type: ignore[attr-defined]


# ----------------------------------------------------------------------------
# ReportGenerator hierarchy
# ----------------------------------------------------------------------------

class ReportGenerator(ABC):
    def generate(self, order: Order) -> str:
        header = self._header(order)
        body = self._body(order)
        return f"{header}\n{body}"

    def _header(self, order: Order) -> str:
        return (f"=== Trade Report: {order.instrument.describe()} ===\n"
                f"Order ID: {order.order_id} | Side: {order.side.value} | "
                f"Qty: {order.quantity} | Status: {order.status.value}")

    @abstractmethod
    def _body(self, order: Order) -> str:
        ...


class StockReportGenerator(ReportGenerator):
    def _body(self, order: Order) -> str:
        stock: Stock = order.instrument  # type: ignore[assignment]
        return (f"Sector: {stock.sector}\n"
                f"Fill Price: {order.fill_price}\n"
                f"Dividend Yield: {stock.dividend_yield:.2%}")


class OptionReportGenerator(ReportGenerator):
    def _body(self, order: Order) -> str:
        option: Option = order.instrument  # type: ignore[assignment]
        return (f"Underlying: {option.underlying} | Strike: {option.strike} | "
                f"Type: {option.option_type.value} | Expiry: {option.expiry}\n"
                f"Fill Price: {order.fill_price} | Multiplier: {option.multiplier}")


class FutureReportGenerator(ReportGenerator):
    def _body(self, order: Order) -> str:
        future: Future = order.instrument  # type: ignore[assignment]
        return (f"Underlying: {future.underlying} | Expiry: {future.expiry}\n"
                f"Fill Price: {order.fill_price} | Multiplier: {future.multiplier}")


class ForexReportGenerator(ReportGenerator):
    def _body(self, order: Order) -> str:
        fx: Forex = order.instrument  # type: ignore[assignment]
        return (f"Pair: {fx.base_ccy}/{fx.quote_ccy}\n"
                f"Fill Price: {order.fill_price} | Pip Size: {fx.pip_size}")


# ----------------------------------------------------------------------------
# Factory tying all hierarchies together per instrument type
# ----------------------------------------------------------------------------

@dataclass
class InstrumentServices:
    order_handler: OrderHandler
    risk_calculator: RiskCalculator
    margin_calculator: MarginCalculator
    settlement_processor: SettlementProcessor
    report_generator: ReportGenerator


class ServiceFactory:
    _registry: dict[type, InstrumentServices] = {
        Stock: InstrumentServices(
            order_handler=StockOrderHandler(),
            risk_calculator=StockRiskCalculator(),
            margin_calculator=StockMarginCalculator(),
            settlement_processor=StockSettlementProcessor(),
            report_generator=StockReportGenerator(),
        ),
        Option: InstrumentServices(
            order_handler=OptionOrderHandler(),
            risk_calculator=OptionRiskCalculator(),
            margin_calculator=OptionMarginCalculator(),
            settlement_processor=OptionSettlementProcessor(),
            report_generator=OptionReportGenerator(),
        ),
        Future: InstrumentServices(
            order_handler=FutureOrderHandler(),
            risk_calculator=FutureRiskCalculator(),
            margin_calculator=FutureMarginCalculator(),
            settlement_processor=FutureSettlementProcessor(),
            report_generator=FutureReportGenerator(),
        ),
        Forex: InstrumentServices(
            order_handler=ForexOrderHandler(),
            risk_calculator=ForexRiskCalculator(),
            margin_calculator=ForexMarginCalculator(),
            settlement_processor=ForexSettlementProcessor(),
            report_generator=ForexReportGenerator(),
        ),
    }

    @classmethod
    def get_services(cls, instrument: Instrument) -> InstrumentServices:
        services = cls._registry.get(type(instrument))
        if services is None:
            raise ValueError(f"No services registered for {type(instrument)}")
        return services


# ----------------------------------------------------------------------------
# Example orchestration (trading workflow)
# ----------------------------------------------------------------------------

class TradingWorkflow:
    """High level orchestrator that uses the parallel hierarchies together."""

    def execute_order(self, order: Order) -> str:
        services = ServiceFactory.get_services(order.instrument)

        services.order_handler.submit(order)
        if order.status == OrderStatus.REJECTED:
            reason = getattr(order, "reject_reason", "Unknown")
            return f"Order {order.order_id} REJECTED: {reason}"

        var_estimate = services.risk_calculator.calculate_var(order)
        max_loss = services.risk_calculator.max_loss(order)
        initial_margin = services.margin_calculator.initial_margin(order)
        maintenance_margin = services.margin_calculator.maintenance_margin(order)

        services.settlement_processor.settle(order)

        report = services.report_generator.generate(order)
        risk_summary = (
            f"\n--- Risk & Margin ---\n"
            f"VaR (99%): {var_estimate:.2f}\n"
            f"Max Loss: {max_loss}\n"
            f"Initial Margin: {initial_margin:.2f}\n"
            f"Maintenance Margin: {maintenance_margin:.2f}\n"
            f"Settlement: {getattr(order, 'settlement_note', 'N/A')}\n"
        )
        return report + risk_summary
