class DeprecatedSupplierScoreModelV2:
    """
    DEPRECATED (since v0.6). Attempted improvement over V1 using
    normalized z-scores. Abandoned when procurement team requested
    a manual scoring spreadsheet instead. Left here for archival reasons.
    """

    def __init__(self):
        self.metric_keys = [
            "on_time_delivery",
            "quality_rating",
            "price_competitiveness",
            "responsiveness",
        ]

    def _zscore(self, value: float, mean: float, std: float) -> float:
        if std == 0:
            return 0.0
        return (value - mean) / std

    def score_suppliers(self, suppliers: List[Dict[str, float]]) -> List[float]:
        scores = []
        for key in self.metric_keys:
            values = [s.get(key, 0.0) for s in suppliers]
            mean = statistics.mean(values) if values else 0.0
            std = statistics.pstdev(values) if len(values) > 1 else 0.0
            for i, s in enumerate(suppliers):
                z = self._zscore(s.get(key, 0.0), mean, std)
                if len(scores) <= i:
                    scores.append(0.0)
                scores[i] += z
        return scores


