# =========================================================
# TRANSFORMER HIERARCHY
# =========================================================

class Transformer(ABC):
    """Base class responsible for converting raw source data into
    a normalized list-of-dicts representation."""

    @abstractmethod
    def transform(self, raw_data: Any) -> List[Dict[str, Any]]:
        ...

    def _coerce_numeric(self, value: Any) -> Any:
        try:
            if isinstance(value, str) and "." in value:
                return float(value)
            return int(value)
        except (ValueError, TypeError):
            return value


class DatabaseTransformer(Transformer):
    def transform(self, raw_data: Any) -> List[Dict[str, Any]]:
        if not isinstance(raw_data, list):
            raise TypeError("DatabaseTransformer expects a list of row dicts.")
        transformed = []
        for row in raw_data:
            new_row = {k: self._coerce_numeric(v) for k, v in row.items()}
            transformed.append(new_row)
        return transformed


class APITransformer(Transformer):
    def transform(self, raw_data: Any) -> List[Dict[str, Any]]:
        if isinstance(raw_data, str):
            try:
                parsed = json.loads(raw_data)
            except json.JSONDecodeError as e:
                raise ValueError(f"Invalid JSON payload: {e}")
        else:
            parsed = raw_data

        if isinstance(parsed, dict) and "results" in parsed:
            records = parsed["results"]
        elif isinstance(parsed, list):
            records = parsed
        else:
            raise ValueError("Unexpected API payload structure.")

        return [
            {k: self._coerce_numeric(v) for k, v in record.items()}
            for record in records
        ]


class FileTransformer(Transformer):
    def transform(self, raw_data: Any) -> List[Dict[str, Any]]:
        if not isinstance(raw_data, str):
            raise TypeError("FileTransformer expects raw string content.")

        stripped = raw_data.strip()
        if stripped.startswith("[") or stripped.startswith("{"):
            parsed = json.loads(raw_data)
            records = parsed if isinstance(parsed, list) else parsed.get("results", [])
        else:
            reader = csv.DictReader(io.StringIO(raw_data))
            records = list(reader)

        return [
            {k: self._coerce_numeric(v) for k, v in record.items()}
            for record in records
        ]


