# VALIDATOR HIERARCHY
# =========================================================

class ValidationError(Exception):
    def __init__(self, errors: List[str]):
        super().__init__("; ".join(errors))
        self.errors = errors


class Validator(ABC):
    """Base class for validating normalized data before it is used downstream."""

    def __init__(self, required_fields: Optional[List[str]] = None):
        self.required_fields = required_fields or ["id"]

    @abstractmethod
    def validate(self, data: List[Dict[str, Any]]) -> bool:
        ...

    def _check_required_fields(self, data: List[Dict[str, Any]]) -> List[str]:
        errors = []
        for i, record in enumerate(data):
            missing = [f for f in self.required_fields if f not in record]
            if missing:
                errors.append(f"Record {i} missing required fields: {missing}")
        return errors


class DatabaseValidator(Validator):
    def __init__(self, required_fields: Optional[List[str]] = None):
        super().__init__(required_fields or ["id", "value", "category"])

    def validate(self, data: List[Dict[str, Any]]) -> bool:
        errors = self._check_required_fields(data)
        for i, record in enumerate(data):
            if "id" in record and not isinstance(record["id"], int):
                errors.append(f"Record {i}: 'id' must be an integer.")
        if errors:
            raise ValidationError(errors)
        return True


class APIValidator(Validator):
    def __init__(self, required_fields: Optional[List[str]] = None):
        super().__init__(required_fields or ["id", "value"])

    def validate(self, data: List[Dict[str, Any]]) -> bool:
        errors = self._check_required_fields(data)
        if not data:
            errors.append("API response contains no records.")
        if errors:
            raise ValidationError(errors)
        return True


class FileValidator(Validator):
    def __init__(self, required_fields: Optional[List[str]] = None):
        super().__init__(required_fields or ["id", "value"])

    def validate(self, data: List[Dict[str, Any]]) -> bool:
        errors = self._check_required_fields(data)
        for i, record in enumerate(data):
            if "value" in record and not isinstance(record["value"], (int, float)):
                errors.append(f"Record {i}: 'value' must be numeric.")
        if errors:
            raise ValidationError(errors)
        return True


# =========================================================
# DATASOURCE HIERARCHY (composes Connector, Transformer, Validator)
# =========================================================

class DataSource(ABC):
    """Base class binding together a Connector, Transformer, and Validator
    to provide a unified data-loading pipeline."""

    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.connector: Connector = self._create_connector(config)
        self.transformer: Transformer = self._create_transformer()
        self.validator: Validator = self._create_validator()

    @abstractmethod
    def _create_connector(self, config: Dict[str, Any]) -> Connector:
        ...

    @abstractmethod
    def _create_transformer(self) -> Transformer:
        ...

    @abstractmethod
    def _create_validator(self) -> Validator:
        ...

    def load(self) -> List[Dict[str, Any]]:
        self.connector.connect()
        try:
            raw = self.connector.fetch_raw()
            data = self.transformer.transform(raw)
            self.validator.validate(data)
            return data
        finally:
            self.connector.disconnect()


class Database(DataSource):
    def _create_connector(self, config: Dict[str, Any]) -> Connector:
        return DatabaseConnector(config)

    def _create_transformer(self) -> Transformer:
        return DatabaseTransformer()

    def _create_validator(self) -> Validator:
        return DatabaseValidator()


class API(DataSource):
    def _create_connector(self, config: Dict[str, Any]) -> Connector:
        return APIConnector(config)

    def _create_transformer(self) -> Transformer:
        return APITransformer()

    def _create_validator(self) -> Validator:
        return APIValidator()


class File(DataSource):
    def _create_connector(self, config: Dict[str, Any]) -> Connector:
        return FileConnector(config)

    def _create_transformer(self) -> Transformer:
        return FileTransformer()

    def _create_validator(self) -> Validator:
        return FileValidator()


