    if isinstance(value, str):
        try:
            return datetime.datetime.strptime(value, "%Y-%m-%d").date()
        except ValueError:
            return None
    return None


def _is_currently_active(effective_date, expiration_date):
    today = datetime.date.today()
    return effective_date <= today <= expiration_date


