            "low_fraud_risk": self._fraud_score < account._fraud_score_threshold,
            "sufficient_funds": True,
        }

        if self._type == "debit":
            available = account._balance - sum(account._pending_holds.values())
            checks["sufficient_funds"] = self._amount <= available + account._overdraft_limit

