class PharmacyModule:

    KNOWN_INTERACTIONS = {
        frozenset(["warfarin", "aspirin"]): "Increased bleeding risk",
        frozenset(["lisinopril", "spironolactone"]): "Hyperkalemia risk",
        frozenset(["simvastatin", "clarithromycin"]): "Risk of rhabdomyolysis",
    }

    @staticmethod
    def _check_allergy(patient_id, medication_name):
        allergens = {a["allergen"] for a in allergy_alerts.get(patient_id, [])}
        return medication_name.lower() in allergens

    @staticmethod
    def _check_interactions(patient_id, new_medication):
        active_meds = [
            m["medication_name"].lower()
            for m in medication_orders.get(patient_id, [])
            if m["status"] == "active"
        ]
        interactions_found = []
        for existing in active_meds:
            pair = frozenset([existing, new_medication.lower()])
            if pair in PharmacyModule.KNOWN_INTERACTIONS:
                interactions_found.append({
                    "pair": list(pair),
                    "risk": PharmacyModule.KNOWN_INTERACTIONS[pair]
                })
        return interactions_found

    @staticmethod
    def order_medication(patient_id, encounter_id, medication_name, dose, route,
                          frequency, drug_class="unknown", actor="physician",
                          override_alerts=False):
