            raise ValueError("Patient not found")

        allergy_conflict = PharmacyModule._check_allergy(patient_id, medication_name)
        interactions = PharmacyModule._check_interactions(patient_id, medication_name)

        if (allergy_conflict or interactions) and not override_alerts:
            _log_audit("pharmacy", "order_blocked", actor, {
                "patient_id": patient_id,
                "medication_name": medication_name,
                "allergy_conflict": allergy_conflict,
                "interactions": interactions
            })
            return {
                "success": False,
                "reason": "safety_alert",
                "allergy_conflict": allergy_conflict,
                "interactions": interactions
            }

        order_id = str(uuid.uuid4())
        order = {
            "order_id": order_id,
            "encounter_id": encounter_id,
            "medication_name": medication_name,
            "dose": dose,
            "route": route,
            "frequency": frequency,
            "drug_class": drug_class,
            "status": "active",
            "ordered_by": actor,
            "ordered_at": datetime.datetime.now().isoformat(),
            "overridden": override_alerts and (allergy_conflict or bool(interactions))
        }

        medication_orders.setdefault(patient_id, []).append(order)

        billing_context.setdefault(patient_id, {}).setdefault("pharmacy_charges", []).append({
            "order_id": order_id,
            "medication_name": medication_name,
            "charge_code": f"RX-{medication_name[:3].upper()}",
            "amount": 0.0,
            "status": "pending"
        })

        _log_audit("pharmacy", "order_medication", actor, {
            "patient_id": patient_id,
            "order_id": order_id,
            "medication_name": medication_name,
            "overridden": order["overridden"]
        })

        return {"success": True, "order_id": order_id}

    @staticmethod
    def dispense_medication(patient_id, order_id, actor="pharmacist"):
        orders = medication_orders.get(patient_id, [])
        order = next((o for o in orders if o["order_id"] == order_id), None)
        if not order:
            raise ValueError("Order not found")
        if order["status"] != "active":
            raise ValueError("Order is not active")

        order["status"] = "dispensed"
        order["dispensed_at"] = datetime.datetime.now().isoformat()

        for charge in billing_context.get(patient_id, {}).get("pharmacy_charges", []):
            if charge["order_id"] == order_id:
