"""
E-commerce currency module.

Wraps decimal.Decimal with currency-aware arithmetic, rounding rules,
and locale-independent formatting suitable for e-commerce applications.
"""

from __future__ import annotations

import re
from decimal import Decimal, ROUND_HALF_UP, ROUND_HALF_EVEN, ROUND_DOWN, ROUND_UP, InvalidOperation
from typing import Union, Dict, Optional

Number = Union[int, float, str, Decimal]


class CurrencyError(Exception):
    """Base exception for currency-related errors."""


class CurrencyMismatchError(CurrencyError):
    """Raised when operating on Money instances with different currencies."""

    def __init__(self, cur1: str, cur2: str):
        self.cur1 = cur1
        self.cur2 = cur2
        super().__init__(f"Currency mismatch: cannot operate on '{cur1}' and '{cur2}'")


class UnknownCurrencyError(CurrencyError):
    """Raised when an unknown currency code is used."""

    def __init__(self, code: str):
        self.code = code
        super().__init__(f"Unknown currency code: '{code}'")


class InvalidAmountError(CurrencyError):
    """Raised when an amount cannot be parsed into a Decimal."""

    def __init__(self, value):
        self.value = value
        super().__init__(f"Invalid amount: {value!r}")


class CurrencyInfo:
    """Metadata describing a currency: symbol, decimal precision, rounding rule."""

    __slots__ = ("code", "symbol", "exponent", "rounding", "symbol_first", "name")

    def __init__(
        self,
        code: str,
        symbol: str,
        exponent: int,
        rounding: str = ROUND_HALF_UP,
        symbol_first: bool = True,
        name: Optional[str] = None,
    ):
        self.code = code.upper()
        self.symbol = symbol
        self.exponent = exponent
        self.rounding = rounding
        self.symbol_first = symbol_first
        self.name = name or code

    @property
    def quantum(self) -> Decimal:
        """The smallest representable unit for this currency, e.g. Decimal('0.01')."""
        if self.exponent == 0:
            return Decimal("1")
        return Decimal("1").scaleb(-self.exponent)

    def __repr__(self):
        return f"CurrencyInfo({self.code!r}, symbol={self.symbol!r}, exponent={self.exponent})"


class CurrencyRegistry:
    """Registry of known currencies. Supports lookup and registration of custom currencies."""

    def __init__(self):
        self._currencies: Dict[str, CurrencyInfo] = {}
        self._load_defaults()

    def _load_defaults(self):
        defaults = [
