        results = [Money(Decimal(units) * quant, self._currency) for units in floor_shares]
        return results

    # ------------------------------------------------------------------ #
    # Tax / discount helpers
    # ------------------------------------------------------------------ #

    def with_tax(self, rate: Number, rounding: Optional[str] = None) -> "Money":
        """Return a new Money increased by `rate` (e.g. Decimal('0.2') for 20%)."""
        rate_dec = _parse_decimal(rate)
        result = self._amount * (Decimal("1") + rate_dec)
        return Money(result, self._currency).rounded(rounding)

    def tax_amount(self, rate: Number, rounding: Optional[str] = None) -> "Money":
        """Return just the tax portion for a given rate, assuming self is pre-tax."""
        rate_dec = _parse_decimal(rate)
        result = self._amount * rate_dec
        return Money(result, self._currency).rounded(rounding)

    def extract_tax(self, rate: Number, rounding: Optional[str] = None) -> "Money":
        """Given self is tax-inclusive, return the tax component."""
        rate_dec = _parse_decimal(rate)
        pre_tax = self._amount / (Decimal("1") + rate_dec)
        tax = self._amount - pre_tax
        return Money(tax, self._currency).rounded(rounding)

    def discounted(self, percent_off: Number, rounding: Optional[str] = None) -> "Money":
        """Apply a percentage discount, e.g. percent_off=Decimal('10') for 10% off."""
        pct = _parse_decimal(percent_off)
        factor = Decimal("1") - (pct / Decimal("100"))
        if factor < 0:
            raise ValueError("percent_off cannot exceed 100")
        result = self._amount * factor
        return Money(result, self._currency).rounded(rounding)

    # ------------------------------------------------------------------ #
    # Conversion
    # ------------------------------------------------------------------ #

    def convert(self, target_currency: str, rate: Number, rounding: Optional[str] = None) -> "Money":
        """Convert to another currency given an exchange rate (target per 1 source unit)."""
        target = registry.get(target_currency)  # validate
        rate_dec = _parse_decimal(rate)
        converted = self._amount * rate_dec
        return Money(converted, target.code).rounded(rounding)

    # ------------------------------------------------------------------ #
    # Formatting
    # ------------------------------------------------------------------ #

    def format(
        self,
        show_symbol: bool = True,
        show_code: bool = False,
        thousands_sep: str = ",",
        decimal_sep: str = ".",
        rounded: bool = True,
    ) -> str:
        """Locale-independent, configurable string formatting."""
        info = self.info
        amount = self.rounded()._amount if rounded else self._amount

        negative = amount < 0
        amount = abs(amount)

        exponent = info.exponent
        quant_str = format(amount, "f")

        if "." in quant_str:
            int_part, frac_part = quant_str.split(".")
        else:
            int_part, frac_part = quant_str, ""

        frac_part = (frac_part + "0" * exponent)[:exponent] if exponent > 0 else ""

        # Insert thousands separators into integer part.
        int_part = int_part.lstrip("-")
        groups = []
        while len(int_part) > 3:
            groups.append(int_part[-3:])
            int_part = int_part[:-3]
        groups.append(int_part)
        int_with_seps = thousands_sep.join(reversed(groups))

        number_str = int_with_seps
        if exponent > 0:
            number_str += decimal_sep + frac_part

        sign = "-" if negative else ""

        pieces = []
        if show_symbol and info.symbol_first:
            pieces.append(f"{sign}{info.symbol}{number_str}")
        elif show_symbol:
            pieces.append(f"{sign}{number_str}{info.symbol}")
        else:
            pieces.append(f"{sign}{number_str}")

        result = pieces[0]
        if show_code:
            result = f"{result} {info.code}"
        return result

    def __str__(self) -> str:
        return self.format()

    def __repr__(self) -> str:
        return f"Money('{self._amount}', '{self._currency}')"

    # ------------------------------------------------------------------ #
    # Serialization
    # ------------------------------------------------------------------ #

    def to_dict(self) -> dict:
        return {"amount": str(self._amount), "currency": self._currency}

    @classmethod
    def from_dict(cls, data: dict) -> "Money":
        return cls(data["amount"], data["currency"])

    @classmethod
    def from_minor_units(cls, units: int, currency: str) -> "Money":
        """Construct Money from an integer count of minor units (e.g. cents)."""
        info = registry.get(currency)
        amount = Decimal(units) * info.quantum
        return cls(amount, currency)

    def to_minor_units(self) -> int:
        """Return the integer number of minor units (e.g. cents), rounding first."""
        info = self.info
        rounded_amount = self.rounded()._amount
        units = (rounded_amount / info.quantum).to_integral_value(rounding=ROUND_HALF_UP)
        return int(units)

    def zero(self) -> "Money":
        return Money(0, self._currency)

    def is_zero(self) -> bool:
        return self._amount == 0

    def is_positive(self) -> bool:
        return self._amount > 0

    def is_negative(self) -> bool:
        return self._amount < 0


def sum_money(items: list) -> Money:
    """Sum a non-empty iterable of Money objects, all same currency."""
    items = list(items)
    if not items:
        raise ValueError("cannot sum an empty sequence of Money")
    total = items[0]
    for m in items[1:]:
        total = total + m
    return total


def max_money(*items: Money) -> Money:
    if not items:
        raise ValueError("max_money requires at least one Money argument")
    result = items[0]
    for m in items[1:]:
        if m > result:
            result = m
    return result


def min_money(*items: Money) -> Money:
    if not items:
        raise ValueError("min_money requires at least one Money argument")
    result = items[0]
    for m in items[1:]:
        if m < result:
            result = m
    return result
