            e for e in self.audit_trail
            if e["details"].get("account_id") == account_id
            or e["details"].get("from_account") == account_id
            or e["details"].get("to_account") == account_id
        ]

    # ---------------- Accounts ----------------

    def create_account(self, owner_name, account_type="checking", currency=None, initial_balance=0):
        account_id = str(uuid.uuid4())
        currency = currency or self.base_currency
        balance = self._to_decimal(initial_balance)

        if currency not in self.exchange_rates:
            raise ValueError(f"Unsupported currency: {currency}")

        account = {
            "id": account_id,
            "owner": owner_name,
            "type": account_type,
            "currency": currency,
            "balance": balance,
            "created_at": datetime.datetime.utcnow().isoformat(),
            "status": "active",
            "history": [],
        }
        self.accounts[account_id] = account
        self._log_audit("account_created", {
            "account_id": account_id,
            "owner": owner_name,
            "initial_balance": str(balance),
            "currency": currency,
        })
        return account_id

    def get_account(self, account_id):
        account = self.accounts.get(account_id)
        if not account:
            raise ValueError(f"Account not found: {account_id}")
        return account

    def close_account(self, account_id):
        account = self.get_account(account_id)
        if account["balance"] != 0:
            raise ValueError("Cannot close account with non-zero balance")
        account["status"] = "closed"
        self._log_audit("account_closed", {"account_id": account_id})
        return True

    def freeze_account(self, account_id):
        account = self.get_account(account_id)
        account["status"] = "frozen"
        self._log_audit("account_frozen", {"account_id": account_id})
        return True

    def unfreeze_account(self, account_id):
        account = self.get_account(account_id)
        account["status"] = "active"
        self._log_audit("account_unfrozen", {"account_id": account_id})
        return True

    # ---------------- Currency ----------------

    def set_exchange_rate(self, currency, rate_to_base):
        rate = self._to_decimal(rate_to_base)
        if rate <= 0:
            raise ValueError("Exchange rate must be positive")
        self.exchange_rates[currency] = rate
        self._log_audit("exchange_rate_set", {"currency": currency, "rate": str(rate)})

    def convert_currency(self, amount, from_currency, to_currency):
        amount = self._to_decimal(amount)
        if from_currency not in self.exchange_rates:
            raise ValueError(f"Unknown currency: {from_currency}")
        if to_currency not in self.exchange_rates:
            raise ValueError(f"Unknown currency: {to_currency}")

        amount_in_base = amount * self.exchange_rates[from_currency]
        converted = amount_in_base / self.exchange_rates[to_currency]
        return converted.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    # ---------------- Compliance ----------------

    def run_compliance_check(self, account_id, amount):
        account = self.get_account(account_id)
        amount = self._to_decimal(amount)
        violations = []

        if account["status"] != "active":
            violations.append(f"Account is not active (status={account['status']})")

        if account_id in self.compliance_rules["restricted_accounts"]:
            violations.append("Account is restricted")

        if amount > self.compliance_rules["max_transaction_amount"]:
            violations.append("Transaction exceeds max allowed amount")

        if amount < self.compliance_rules["min_transaction_amount"]:
            violations.append("Transaction below minimum allowed amount")

        today = datetime.datetime.utcnow().date()
        daily_total = sum(
            self._to_decimal(t["amount"])
            for t in self.transactions.values()
            if (t.get("from_account") == account_id or t.get("to_account") == account_id)
            and datetime.datetime.fromisoformat(t["timestamp"]).date() == today
        )
        if daily_total + amount > self.compliance_rules["daily_transaction_limit"]:
            violations.append("Daily transaction limit exceeded")

        result = {"passed": len(violations) == 0, "violations": violations}
        self._log_audit("compliance_check", {
            "account_id": account_id,
            "amount": str(amount),
            "result": result,
        })
        return result

    def add_restricted_account(self, account_id):
        self.compliance_rules["restricted_accounts"].add(account_id)
        self._log_audit("account_restricted", {"account_id": account_id})

    def remove_restricted_account(self, account_id):
        self.compliance_rules["restricted_accounts"].discard(account_id)
        self._log_audit("account_unrestricted", {"account_id": account_id})

    # ---------------- Transactions ----------------

    def _record_transaction(self, tx_type, from_account, to_account, amount, currency, status, meta=None):
        tx_id = str(uuid.uuid4())
        tx = {
            "id": tx_id,
            "type": tx_type,
            "from_account": from_account,
            "to_account": to_account,
            "amount": str(amount),
            "currency": currency,
            "status": status,
            "timestamp": datetime.datetime.utcnow().isoformat(),
            "meta": meta or {},
        }
        self.transactions[tx_id] = tx
        if from_account and from_account in self.accounts:
            self.accounts[from_account]["history"].append(tx_id)
        if to_account and to_account in self.accounts:
            self.accounts[to_account]["history"].append(tx_id)
        return tx_id

    def deposit(self, account_id, amount, currency=None):
        account = self.get_account(account_id)
        amount = self._to_decimal(amount)
        currency = currency or account["currency"]

        check = self.run_compliance_check(account_id, amount)
        if not check["passed"]:
            tx_id = self._record_transaction("deposit", None, account_id, amount, currency, "rejected",
                                              {"reason": check["violations"]})
            raise ValueError(f"Deposit failed compliance: {check['violations']}")

        converted_amount = amount
        if currency != account["currency"]:
            converted_amount = self.convert_currency(amount, currency, account["currency"])

        account["balance"] += converted_amount
        tx_id = self._record_transaction("deposit", None, account_id, amount, currency, "completed")
        self._log_audit("deposit", {"account_id": account_id, "amount": str(amount), "tx_id": tx_id})
        return tx_id

    def withdraw(self, account_id, amount, currency=None):
        account = self.get_account(account_id)
        amount = self._to_decimal(amount)
        currency = currency or account["currency"]

        converted_amount = amount
        if currency != account["currency"]:
            converted_amount = self.convert_currency(amount, currency, account["currency"])

        check = self.run_compliance_check(account_id, amount)
        if not check["passed"]:
            self._record_transaction("withdrawal", account_id, None, amount, currency, "rejected",
                                      {"reason": check["violations"]})
            raise ValueError(f"Withdrawal failed compliance: {check['violations']}")

        if account["balance"] < converted_amount:
            self._record_transaction("withdrawal", account_id, None, amount, currency, "rejected",
                                      {"reason": "Insufficient funds"})
            raise ValueError("Insufficient funds")

        account["balance"] -= converted_amount
        tx_id = self._record_transaction("withdrawal", account_id, None, amount, currency, "completed")
        self._log_audit("withdrawal", {"account_id": account_id, "amount": str(amount), "tx_id": tx_id})
        return tx_id

    def transfer(self, from_account_id, to_account_id, amount, currency=None):
        from_account = self.get_account(from_account_id)
        to_account = self.get_account(to_account_id)
        amount = self._to_decimal(amount)
        currency = currency or from_account["currency"]

        from_check = self.run_compliance_check(from_account_id, amount)
        to_check = self.run_compliance_check(to_account_id, amount)
        if not from_check["passed"] or not to_check["passed"]:
            violations = from_check["violations"] + to_check["violations"]
            self._record_transaction("transfer", from_account_id, to_account_id, amount, currency, "rejected",
                                      {"reason": violations})
            raise ValueError(f"Transfer failed compliance: {violations}")

        from_amount = amount
        if currency != from_account["currency"]:
            from_amount = self.convert_currency(amount, currency, from_account["currency"])

        if from_account["balance"] < from_amount:
            self._record_transaction("transfer", from_account_id, to_account_id, amount, currency, "rejected",
                                      {"reason": "Insufficient funds"})
            raise ValueError("Insufficient funds")

        to_amount = self.convert_currency(from_amount, from_account["currency"], to_account["currency"])

        from_account["balance"] -= from_amount
        to_account["balance"] += to_amount

        tx_id = self._record_transaction("transfer", from_account_id, to_account_id, amount, currency, "completed")
        self._log_audit("transfer", {
            "from_account": from_account_id,
            "to_account": to_account_id,
            "amount": str(amount),
            "tx_id": tx_id,
        })
        return tx_id

    def get_transaction(self, tx_id):
        tx = self.transactions.get(tx_id)
        if not tx:
            raise ValueError(f"Transaction not found: {tx_id}")
        return tx

    def reverse_transaction(self, tx_id):
        tx = self.get_transaction(tx_id)
        if tx["status"] != "completed":
            raise ValueError("Only completed transactions can be reversed")

        amount = self._to_decimal(tx["amount"])
        currency = tx["currency"]

        if tx["type"] == "deposit":
            self.withdraw(tx["to_account"], amount, currency)
        elif tx["type"] == "withdrawal":
            self.deposit(tx["from_account"], amount, currency)
        elif tx["type"] == "transfer":
            self.transfer(tx["to_account"], tx["from_account"], amount, currency)
        else:
            raise ValueError(f"Cannot reverse transaction type: {tx['type']}")

        tx["status"] = "reversed"
        self._log_audit("transaction_reversed", {"tx_id": tx_id})
        return True

    # ---------------- Reconciliation ----------------

    def reconcile_account(self, account_id, expected_balance):
        account = self.get_account(account_id)
        expected_balance = self._to_decimal(expected_balance)
        actual_balance = account["balance"]
        discrepancy = actual_balance - expected_balance

        result = {
            "account_id": account_id,
            "expected_balance": str(expected_balance),
            "actual_balance": str(actual_balance),
            "discrepancy": str(discrepancy),
            "reconciled": discrepancy == 0,
            "timestamp": datetime.datetime.utcnow().isoformat(),
        }
        self.reconciliation_log.append(result)
        self._log_audit("reconciliation", result)
        return result

    def reconcile_all(self, expected_balances):
        results = []
        for account_id, expected_balance in expected_balances.items():
            results.append(self.reconcile_account(account_id, expected_balance))
        return results

    def get_reconciliation_history(self, account_id=None):
        if account_id is None:
            return list(self.reconciliation_log)
        return [r for r in self.reconciliation_log if r["account_id"] == account_id]

    # ---------------- Tax ----------------

    def set_tax_rate(self, category, rate):
        rate = self._to_decimal(rate)
        if rate < 0 or rate > 1:
            raise ValueError("Tax rate must be between 0 and 1")
        self.tax_rates[category] = rate
        self._log_audit("tax_rate_set", {"category": category, "rate": str(rate)})

    def calculate_tax(self, amount, category="default"):
        amount = self._to_decimal(amount)
        rate = self.tax_rates.get(category, self.tax_rates.get("default", Decimal("0")))
        tax_amount = (amount * rate).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return {
            "gross_amount": str(amount),
            "tax_rate": str(rate),
            "tax_amount": str(tax_amount),
            "net_amount": str(amount - tax_amount),
        }

    def calculate_account_tax_liability(self, account_id, category="default", period_start=None, period_end=None):
        account = self.get_account(account_id)
        rate = self.tax_rates.get(category, self.tax_rates.get("default", Decimal("0")))

        total_income = Decimal("0")
        for tx_id in account["history"]:
            tx = self.transactions[tx_id]
            if tx["status"] != "completed":
                continue
            ts = datetime.datetime.fromisoformat(tx["timestamp"])
            if period_start and ts < period_start:
                continue
            if period_end and ts > period_end:
                continue
            if tx["to_account"] == account_id and tx["type"] in ("deposit", "transfer"):
                total_income += self._to_decimal(tx["amount"])

        tax_liability = (total_income * rate).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return {
            "account_id": account_id,
            "total_income": str(total_income),
            "tax_rate": str(rate),
            "tax_liability": str(tax_liability),
        }

    # ---------------- Reporting / Statements ----------------

    def generate_statement(self, account_id, start_date=None, end_date=None):
        account = self.get_account(account_id)
        transactions = []

        for tx_id in account["history"]:
            tx = self.transactions[tx_id]
            ts = datetime.datetime.fromisoformat(tx["timestamp"])
            if start_date and ts < start_date:
                continue
            if end_date and ts > end_date:
                continue
            transactions.append(tx)

        transactions.sort(key=lambda t: t["timestamp"])

        statement = {
            "account_id": account_id,
            "owner": account["owner"],
            "currency": account["currency"],
            "current_balance": str(account["balance"]),
            "period_start": start_date.isoformat() if start_date else None,
            "period_end": end_date.isoformat() if end_date else None,
            "transaction_count": len(transactions),
            "transactions": transactions,
            "generated_at": datetime.datetime.utcnow().isoformat(),
        }
        self._log_audit("statement_generated", {"account_id": account_id})
        return statement

    def generate_summary_report(self):
        total_balance_by_currency = {}
        for account in self.accounts.values():
            currency = account["currency"]
            total_balance_by_currency[currency] = total_balance_by_currency.get(currency, Decimal("0")) + account["balance"]

        report = {
            "total_accounts": len(self.accounts),
            "active_accounts": sum(1 for a in self.accounts.values() if a["status"] == "active"),
            "frozen_accounts": sum(1 for a in self.accounts.values() if a["status"] == "frozen"),
            "closed_accounts": sum(1 for a in self.accounts.values() if a["status"] == "closed"),
            "total_transactions": len(self.transactions),
            "completed_transactions": sum(1 for t in self.transactions.values() if t["status"] == "completed"),
            "rejected_transactions": sum(1 for t in self.transactions.values() if t["status"] == "rejected"),
            "reversed_transactions": sum(1 for t in self.transactions.values() if t["status"] == "reversed"),
            "balances_by_currency": {k: str(v) for k, v in total_balance_by_currency.items()},
            "generated_at": datetime.datetime.utcnow().isoformat(),
        }
        return report

    def generate_account_activity_report(self, account_id, start_date=None, end_date=None):
        account = self.get_account(account_id)
        deposits = Decimal("0")
        withdrawals = Decimal("0")
        transfers_in = Decimal("0")
        transfers_out = Decimal("0")

        for tx_id in account["history"]:
            tx = self.transactions[tx_id]
            if tx["status"] != "completed":
                continue
            ts = datetime.datetime.fromisoformat(tx["timestamp"])
            if start_date and ts < start_date:
                continue
            if end_date and ts > end_date:
                continue

            amount = self._to_decimal(tx["amount"])
            if tx["type"] == "deposit":
                deposits += amount
            elif tx["type"] == "withdrawal":
                withdrawals += amount
            elif tx["type"] == "transfer":
                if tx["to_account"] == account_id:
                    transfers_in += amount
                if tx["from_account"] == account_id:
                    transfers_out += amount

        return {
            "account_id": account_id,
            "deposits": str(deposits),
            "withdrawals": str(withdrawals),
            "transfers_in": str(transfers_in),
            "transfers_out": str(transfers_out),
            "net_change": str(deposits - withdrawals + transfers_in - transfers_out),
            "current_balance": str(account["balance"]),
        }

    def list_accounts(self, owner_name=None, status=None):
        results = list(self.accounts.values())
        if owner_name:
            results = [a for a in results if a["owner"] == owner_name]
        if status:
            results = [a for a in results if a["status"] == status]
        return results

    def list_transactions(self, account_id=None, tx_type=None, status=None):
        results = list(self.transactions.values())
        if account_id:
            results = [t for t in results if t.get("from_account") == account_id or t.get("to_account") == account_id]
        if tx_type:
            results = [t for t in results if t["type"] == tx_type]
        if status:
            results = [t for t in results if t["status"] == status]
        return results
