    def _attribute_performance(self, portfolio_value: float):
        self.performance_attribution = {}
        for candidate in self.trade_candidates:
            symbol = candidate["symbol"]
            dollar_amount = candidate["dollar_amount"]
            contribution = dollar_amount / portfolio_value if portfolio_value else 0.0
            self.performance_attribution[symbol] = contribution

