        self.order_generation_state = {
            "orders": [],
            "skipped_due_to_wash_sale": [],
        }

        for candidate in self.trade_candidates:
            symbol = candidate["symbol"]

            if candidate["action"] == "buy" and self.wash_sale_checks.get(symbol, False):
                self.order_generation_state["skipped_due_to_wash_sale"].append(symbol)
                continue

            order = {
                "symbol": symbol,
                "action": candidate["action"],
                "quantity": candidate["quantity"],
                "price": candidate["price"],
                "tax_lots_used": [
                    lot.lot_id for lot in self.tax_lot_selections.get(symbol, [])
                ] if candidate["action"] == "sell" else [],
            }
            self.order_generation_state["orders"].append(order)

    def _execute_orders(self, prices: Dict[str, float]):
        self.execution_status = {}
        orders = self.order_generation_state.get("orders", [])

        for order in orders:
            symbol = order["symbol"]
            price = prices.get(symbol)
            if price is None or price <= 0:
                self.execution_status[symbol] = "failed_no_price"
                continue
            if order["quantity"] <= 0:
                self.execution_status[symbol] = "skipped_zero_quantity"
                continue

            self.execution_status[symbol] = "executed"

