        allergies = getattr(patient, "allergies", []) or []
        preferences = getattr(patient, "preferences", []) or []

        protocols = getattr(treatment, "protocols", {}) or {}
        contraindications = getattr(treatment, "contraindications", {}) or {}

        specialties = getattr(provider, "specialties", []) or []
        coverage = getattr(insurance, "coverage", {}) or {}

