                    exclusion_reasons.append(
                        f"History conflict: {contraindication}"
                    )

            if protocol in preferences and "avoid" in str(preferences.get(protocol, "")).lower():
                exclusion_reasons.append("Patient preference exclusion")
            elif isinstance(preferences, list) and f"avoid_{protocol}" in preferences:
                exclusion_reasons.append("Patient preference exclusion")

            if exclusion_reasons:
                plan["excluded_protocols"].append({
                    "protocol": protocol,
                    "reasons": exclusion_reasons
                })
            else:
                plan["recommended_protocols"].append(protocol)

        matched_specialties = []
        for protocol in plan["recommended_protocols"]:
            for specialty in specialties:
                if specialty.lower() in protocol.lower() or protocol.lower() in specialty.lower():
                    matched_specialties.append(specialty)

        plan["matched_specialties"] = list(set(matched_specialties))
        plan["provider_match"] = len(plan["matched_specialties"]) > 0

        if not plan["provider_match"] and plan["recommended_protocols"]:
            plan["warnings"].append(
                "No matching provider specialty found for recommended protocols."
            )

        for protocol in plan["recommended_protocols"]:
            coverage_info = coverage.get(protocol, None)
            if coverage_info is None:
                plan["insurance_status"][protocol] = "Unknown / Not Covered"
                plan["warnings"].append(
                    f"Insurance coverage unknown for protocol: {protocol}"
                )
            else:
                plan["insurance_status"][protocol] = coverage_info
                if isinstance(coverage_info, dict):
                    if not coverage_info.get("covered", False):
                        plan["warnings"].append(
                            f"Protocol '{protocol}' is not covered by insurance."
                        )
                elif isinstance(coverage_info, bool):
                    if not coverage_info:
                        plan["warnings"].append(
                            f"Protocol '{protocol}' is not covered by insurance."
                        )

        final_plan = []
        for protocol in plan["recommended_protocols"]:
            coverage_status = plan["insurance_status"].get(protocol, "Unknown")
            is_covered = False
            if isinstance(coverage_status, dict):
                is_covered = coverage_status.get("covered", False)
            elif isinstance(coverage_status, bool):
                is_covered = coverage_status

            final_plan.append({
                "protocol": protocol,
                "covered": is_covered,
                "provider_specialty_match": any(
                    specialty.lower() in protocol.lower() or protocol.lower() in specialty.lower()
                    for specialty in specialties
                )
            })

        plan["final_plan"] = final_plan

        if not plan["recommended_protocols"]:
            plan["warnings"].append(
                "No suitable treatment protocols could be recommended given current constraints."
            )

