    """
    Writes documents composed of sections into various formats.
    """

    def __init__(self):
        self.supported_formats = ["text", "markdown", "html", "json"]

    def write_document(self, sections, format="text"):
        """
        Writes a document from a list of sections into the specified format.

        :param sections: list of dicts, each with 'title' and 'content' keys,
                          or list of strings
        :param format: str, one of 'text', 'markdown', 'html', 'json'
        :return: str representing the written document (or dict for json)
        """
        if sections is None:
            raise ValueError("Sections cannot be None")

        if not isinstance(sections, list):
            raise TypeError("sections must be a list")

        if not isinstance(format, str):
            raise TypeError("format must be a string")

        format_lower = format.lower()
        if format_lower not in self.supported_formats:
            raise ValueError(
                f"Unsupported format '{format}'. Supported formats: {self.supported_formats}"
            )

        normalized_sections = self._normalize_sections(sections)

        if format_lower == "text":
            return self._write_text(normalized_sections)
        elif format_lower == "markdown":
            return self._write_markdown(normalized_sections)
        elif format_lower == "html":
            return self._write_html(normalized_sections)
        elif format_lower == "json":
            return self._write_json(normalized_sections)

    def _normalize_sections(self, sections):
        normalized = []
        for idx, section in enumerate(sections):
            if isinstance(section, dict):
                title = section.get("title", f"Section {idx + 1}")
                content = section.get("content", "")
                level = section.get("level", 1)
                normalized.append({"title": title, "content": content, "level": level})
            elif isinstance(section, str):
                normalized.append(
                    {"title": f"Section {idx + 1}", "content": section, "level": 1}
                )
            else:
                normalized.append(
                    {"title": f"Section {idx + 1}", "content": str(section), "level": 1}
                )
        return normalized

    def _write_text(self, sections):
        lines = []
        for section in sections:
            title = section["title"]
            content = section["content"]
            lines.append(title)
            lines.append("-" * len(title))
            lines.append(str(content))
            lines.append("")
        return "\n".join(lines).strip() + "\n"

    def _write_markdown(self, sections):
        lines = []
        for section in sections:
            level = max(1, min(6, section.get("level", 1)))
            heading_prefix = "#" * level
            title = section["title"]
            content = section["content"]
            lines.append(f"{heading_prefix} {title}")
            lines.append("")
            lines.append(str(content))
            lines.append("")
        return "\n".join(lines).strip() + "\n"

    def _write_html(self, sections):
        html_parts = [
            "<!DOCTYPE html>",
            "<html>",
            "<head>",
            "<meta charset='utf-8'>",
            "<title>Document</title>",
            "</head>",
            "<body>",
        ]

        for section in sections:
            level = max(1, min(6, section.get("level", 1)))
            title = html.escape(str(section["title"]))
            content = html.escape(str(section["content"]))
            content_html = content.replace("\n", "<br>")
            html_parts.append(f"<h{level}>{title}</h{level}>")
            html_parts.append(f"<p>{content_html}</p>")

        html_parts.append("</body>")
        html_parts.append("</html>")

        return "\n".join(html_parts)

    def _write_json(self, sections):
        document = {
            "generated_at": datetime.now().isoformat(),
            "sections": sections,
        }
        return json.dumps(document, indent=2, ensure_ascii=False)
