            if missing_keys:
                result["errors"].append(f"Schedule missing required keys: {missing_keys}")
            else:
                valid_frequencies = {"daily", "weekly", "biweekly", "monthly", "yearly"}
                if schedule.get("frequency") not in valid_frequencies:
                    result["errors"].append(f"Invalid schedule frequency: {schedule.get('frequency')}")

    if notify_sender is None:
        notify_sender = False
    if notify_recipient is None:
        notify_recipient = False

    if compliance_check is None:
