        return result

    # --- Currency conversion ---
    try:
        converted_amount = amount * exchange_rate
        converted_amount = round(converted_amount, 2)
        result["converted_amount"] = converted_amount
    except Exception as e:
        result["errors"].append(f"Currency conversion error: {str(e)}")
        result["status"] = "failed"
        return result

    # --- Fee calculation ---
    try:
        if fee_type == "flat":
            calculated_fee = fee_amount
        elif fee_type == "percentage":
            calculated_fee = round(converted_amount * (fee_amount / 100.0), 2)
        else:
            calculated_fee = 0.0

        result["fee_charged"] = calculated_fee
    except Exception as e:
        result["errors"].append(f"Fee calculation error: {str(e)}")
        result["status"] = "failed"
        return result

    final_amount = round(converted_amount - calculated_fee, 2)
    if final_amount < 0:
        result["errors"].append("Final amount after fees is negative.")
        result["status"] = "failed"
        return result

    result["final_amount"] = final_amount

    # --- Compliance check ---
    if compliance_check:
        compliance_flags = []

        # Simulated AML threshold check
        aml_threshold = 10000
        if converted_amount >= aml_threshold:
            compliance_flags.append("Transaction exceeds AML reporting threshold.")

        # Simulated blacklist check
        blacklisted_accounts = {"BLOCKED_ACC_001", "BLOCKED_ACC_002"}
        if account_from in blacklisted_accounts or account_to in blacklisted_accounts:
            compliance_flags.append("One or more accounts are blacklisted.")

        # Simulated suspicious category check
        if category in {"loan", "investment"} and converted_amount > 50000:
            compliance_flags.append("High-value loan/investment transaction flagged for review.")

        if compliance_flags:
