    # --- Recurring schedule setup ---
    if recurring:
        result["recurring_schedule"] = {
            "frequency": schedule.get("frequency"),
            "start_date": schedule.get("start_date"),
            "end_date": schedule.get("end_date", None),
            "next_execution": schedule.get("start_date"),
        }

    # --- Notifications ---
    if notify_sender:
        message = (
            f"Transaction {transaction_id}: Sent {amount} {currency} "
            f"(converted: {converted_amount}, fee: {calculated_fee}, "
            f"final: {final_amount}) from {account_from} to {account_to}."
