        if key in cache:
            computation_cache["hits"] += 1
            cache.move_to_end(key)
            return cache[key]["value"]
        computation_cache["misses"] += 1
        return None

    @staticmethod
    def set(key, value):
        cache = computation_cache["cache"]
        cache[key] = {"value": value, "timestamp": _now()}
        cache.move_to_end(key)
        while len(cache) > computation_cache["max_size"]:
            cache.popitem(last=False)

    @staticmethod
    def clear():
        computation_cache["cache"].clear()
        computation_cache["hits"] = 0
        computation_cache["misses"] = 0

    @staticmethod
    def stats():
        total = computation_cache["hits"] + computation_cache["misses"]
        hit_rate = computation_cache["hits"] / total if total else 0.0
        return {
            "hits": computation_cache["hits"],
            "misses": computation_cache["misses"],
            "hit_rate": hit_rate,
            "size": len(computation_cache["cache"]),
