    def set(self, key, value):
        with self._lock:
            if len(self._store) >= self.max_entries:
                oldest_key = min(self._store, key=lambda k: self._store[k][0])
                del self._store[oldest_key]
            self._store[key] = (time.time(), value)

    def invalidate_prefix(self, prefix):
        with self._lock:
            keys = [k for k in self._store if k.startswith(prefix)]
            for k in keys:
                del self._store[k]

    def clear(self):
        with self._lock:
            self._store.clear()


class QueryOptimizer:
    """
    Lightweight, heuristic query optimizer:
      - caches SELECT results (invalidated on writes to same table)
      - tracks column usage to suggest indexes
      - rewrites SELECT * into explicit column lists when schema known
      - batches repeated single-row lookups (poor-man's IN batching hint)
    """

    def __init__(self, cache_ttl=30):
        self.cache = QueryCache(ttl=cache_ttl)
        self._column_usage: Dict[str, Dict[str, int]] = {}
        self._lock = threading.Lock()

    def track_column_usage(self, table: str, column: str):
        with self._lock:
            table_stats = self._column_usage.setdefault(table, {})
            table_stats[column] = table_stats.get(column, 0) + 1

    def suggest_indexes(self, table: str, threshold: int = 5) -> List[str]:
        with self._lock:
            stats = self._column_usage.get(table, {})
            return [col for col, count in stats.items() if count >= threshold]

    def optimize_select(self, table: str, columns: List[str],
                         schema_columns: Optional[List[str]] = None) -> List[str]:
        if columns == ["*"] and schema_columns:
            return schema_columns
        return columns

    def cache_key(self, sql: str, params: tuple) -> str:
        return f"{sql}|{params}"


