class SQLiteAdapter(BaseAdapter):
    dialect = "sqlite"
    supports_pooling = False

    def __init__(self, database=":memory:"):
        self.database = database
        self._local = threading.local()
        self.optimizer = QueryOptimizer()
        self._lock = threading.Lock()

    def _get_conn(self):
        if not hasattr(self._local, "conn") or self._local.conn is None:
            conn = sqlite3.connect(self.database, check_same_thread=False)
            conn.row_factory = sqlite3.Row
            self._local.conn = conn
        return self._local.conn

    def get_placeholder(self, index):
        return "?"

    def quote_identifier(self, name):
        return f'"{name}"'

    def execute(self, sql, params=None, fetch=True, commit=True, use_cache=False):
        params = params or ()
        sql = re.sub(r"%s", "?", sql)
        is_select = sql.strip().upper().startswith("SELECT")
        with self._lock:
            conn = self._get_conn()
            cur = conn.cursor()
            try:
                cur.execute(sql, params)
                if is_select and fetch:
                    rows = cur.fetchall()
                    result = [dict(row) for row in rows]
                else:
                    result = cur.rowcount
                if commit:
                    conn.commit()
            except Exception:
                conn.rollback()
                raise
            finally:
                cur.close()
        return result

    def executemany(self, sql, param_list):
        sql = re.sub(r"%s", "?", sql)
        with self._lock:
            conn = self._get_conn()
            cur = conn.cursor()
            try:
                cur.executemany(sql, param_list)
                conn.commit()
                return cur.rowcount
            except Exception:
                conn.rollback()
                raise
            finally:
                cur.close()

    def close(self):
        if hasattr(self._local, "conn") and self._local.conn:
            self._local.conn.close()
            self._local.conn = None


class MongoDBAdapter(BaseAdapter):
    dialect = "mongodb"
    supports_pooling = True  # pymongo manages its own internal pool

    def __init__(self, uri="mongodb://localhost:27017", database="test",
                 max_pool_size=10):
        try:
            import pymongo
        except ImportError as e:
            raise ORMError(
                "pymongo is required for MongoDBAdapter. Install with `pip install pymongo`."
            ) from e

        self._client = pymongo.MongoClient(uri, maxPoolSize=max_pool_size)
        self._db = self._client[database]
        self.optimizer = QueryOptimizer()

    def get_collection(self, name):
        return self._db[name]

    def execute(self, *args, **kwargs):
        raise QueryError("MongoDBAdapter does not use SQL execute(); use collection ops")

    def close(self):
        self._client.close()


class CassandraAdapter(BaseAdapter):
    dialect = "cassandra"
    supports_pooling = True  # driver manages its own connection pool

    def __init__(self, contact_points=("127.0.0.1",), keyspace=None, port=9042):
        try:
            from cassandra.cluster import Cluster
        except ImportError as e:
            raise ORMError(
                "cassandra-driver is required for CassandraAdapter. "
                "Install with `pip install cassandra-driver`."
            ) from e

        self._cluster = Cluster(list(contact_points), port=port)
        self._session = self._cluster.connect()
        if keyspace:
            self._session.set_keyspace(keyspace)
        self.optimizer = QueryOptimizer()

    def get_placeholder(self, index):
        return "%s"

    def quote_identifier(self, name):
        return name

    def execute(self, sql, params=None, fetch=True, commit=True, use_cache=False):
        params = params or ()
        rows = self._session.execute(sql, params)
        if fetch and sql.strip().upper().startswith("SELECT"):
            return [dict(row._asdict()) for row in rows]
        return None

    def executemany(self, sql, param_list):
        from cassandra.query import BatchStatement
        batch = BatchStatement()
        prepared = self._session.prepare(sql)
        for params in param_list:
            batch.add(prepared, params)
        self._session.execute(batch)

    def close(self):
        self._cluster.shutdown()


# ---------------------------------------------------------------------------
# QuerySet - unified query builder
# ---------------------------------------------------------------------------

class QuerySet:
    def __init__(self, model_cls):
        self.model_cls = model_cls
        self._filters: List[Tuple[str, str, Any]] = []
        self._limit = None
        self._offset = None
        self._order_by = None
        self._select_columns = ["*"]
        self._use_cache = False

    def filter(self, **kwargs):
        clone = self._clone()
        for key, value in kwargs.items():
            op = "="
            field_name = key
            if "__" in key:
                field_name, suffix = key.rsplit("__", 1)
                op_map = {
                    "gt": ">", "gte": ">=", "lt": "<", "lte": "<=",
                    "ne": "!=", "in": "IN", "like": "LIKE",
                }
                if suffix in op_map:
                    op = op_map[suffix]
                    field_name = field_name
            clone._filters.append((field_name, op, value))
        return clone

    def order_by(self, field, desc=False):
        clone = self._clone()
        clone._order_by = (field, desc)
        return clone

    def limit(self, n):
        clone = self._clone()
        clone._limit = n
        return clone

    def offset(self, n):
        clone = self._clone()
        clone._offset = n
        return clone

    def cache(self, enabled=True):
        clone = self._clone()
        clone._use_cache = enabled
        return clone

    def only(self, *columns):
        clone = self._clone()
        clone._select_columns = list(columns)
        return clone

    def _clone(self):
        clone = QuerySet(self.model_cls)
        clone._filters = list(self._filters)
        clone._limit = self._limit
        clone._offset = self._offset
        clone._order_by = self._order_by
        clone._select_columns = list(self._select_columns)
        clone._use_cache = self._use_cache
        return clone

    def _build_sql(self):
        adapter = self.model_cls._adapter
        table = self.model_cls._table_name
        cols = self.model_cls._get_schema_columns()
        select_cols = adapter.optimizer.optimize_select(
            table, self._select_columns, cols
        ) if hasattr(adapter, "optimizer") else self._select_columns

        col_sql = ", ".join(select_cols) if select_cols != ["*"] else "*"
        sql = f"SELECT {col_sql} FROM {adapter.quote_identifier(table)}"
        params = []

        if self._filters:
            clauses = []
            for field, op, value in self._filters:
                if hasattr(adapter, "optimizer"):
                    adapter.optimizer.track_column_usage(table, field)
                if op == "IN":
                    placeholders = ", ".join(
                        adapter.get_placeholder(i) for i in range(len(value))
                    )
                    clauses.append(f"{adapter.quote_identifier(field)} IN ({placeholders})")
                    params.extend(value)
                else:
                    idx = len(params)
                    clauses.append(
                        f"{adapter.quote_identifier(field)} {op} {adapter.get_placeholder(idx)}"
                    )
                    params.append(value)
            sql += " WHERE " + " AND ".join(clauses)

        if self._order_by:
            field, desc = self._order_by
            sql += f" ORDER BY {adapter.quote_identifier(field)}"
            if desc:
                sql += " DESC"

        if self._limit is not None:
            sql += f" LIMIT {int(self._limit)}"
        if self._offset is not None:
            sql += f" OFFSET {int(self._offset)}"

        return sql, tuple(params)

    def all(self):
        sql, params = self._build_sql()
        adapter = self.model_cls._adapter
        rows = adapter.execute(sql, params, use_cache=self._use_cache)
        return [self.model_cls._from_row(row) for row in rows]

    def first(self):
        results = self.limit(1).all()
        return results[0] if results else None

    def count(self):
        adapter = self.model_cls._adapter
        table = self.model_cls._table_name
        sql = f"SELECT COUNT(*) as cnt FROM {adapter.quote_identifier(table)}"
        params = []
        if self._filters:
            clauses = []
            for field, op, value in self._filters:
                idx = len(params)
                clauses.append(
                    f"{adapter.quote_identifier(field)} {op} {adapter.get_placeholder(idx)}"
                )
                params.append(value)
            sql += " WHERE " + " AND ".join(clauses)
        result = adapter.execute(sql, tuple(params))
        return result[0]["cnt"] if result else 0

    def delete(self):
        adapter = self.model_cls._adapter
        table = self.model_cls._table_name
        sql = f"DELETE FROM {adapter.quote_identifier(table)}"
        params = []
        if self._filters:
            clauses = []
            for field, op, value in self._filters:
                idx = len(params)
                clauses.append(
                    f"{adapter.quote_identifier(field)} {op} {adapter.get_placeholder(idx)}"
                )
                params.append(value)
            sql += " WHERE " + " AND ".join(clauses)
        return adapter.execute(sql, tuple(params), fetch=False)

    def update(self, **kwargs):
        adapter = self.model_cls._adapter
        table = self.model_cls._table_name
        set_clauses = []
        params = []
        for field, value in kwargs.items():
            idx = len(params)
            set_clauses.append(
                f"{adapter.quote_identifier(field)} = {adapter.get_placeholder(idx)}"
            )
            params.append(value)
        sql = f"UPDATE {adapter.quote_identifier(table)} SET " + ", ".join(set_clauses)
        if self._filters:
            clauses = []
            for field, op, value in self._filters:
                idx = len(params)
                clauses.append(
                    f"{adapter.quote_identifier(field)} {op} {adapter.get_placeholder(idx)}"
                )
                params.append(value)
            sql += " WHERE " + " AND ".join(clauses)
        return adapter.execute(sql, tuple(params), fetch=False)

    def __iter__(self):
        return iter(self.all())


# ---------------------------------------------------------------------------
# Model metaclass + base class
# ---------------------------------------------------------------------------

class ModelMeta(type):
    def __new__(mcs, name, bases, namespace):
        cls = super().__new__(mcs, name, bases, namespace)
        if name == "Model":
            return cls

        fields = {}
        for base in bases:
            if hasattr(base, "_fields"):
                fields.update(base._fields)

        for key, value in namespace.items():
            if isinstance(value, Field):
                value.name = key
                fields[key] = value

        cls._fields = fields
        cls._table_name = getattr(cls, "_table_name", None) or name.lower()
        cls._pk_field = None
        for fname, f in fields.items():
            if f.primary_key:
                cls._pk_field = fname
                break
        return cls


class Model(metaclass=ModelMeta):
    _adapter: Optional[BaseAdapter] = None

    def __init__(self, **kwargs):
        self._data = {}
        for fname, field in self._fields.items():
            value = kwargs.get(fname, field.default)
            self._data[fname] = value

    def __getattr__(self, name):
        if name.startswith("_"):
            raise AttributeError(name)
        try:
            return self._data[name]
        except KeyError:
            raise AttributeError(name)

    def __setattr__(self, name, value):
        if name.startswith("_"):
            super().__setattr__(name, value)
        elif name in self._fields:
            self._data[name] = value
        else:
            super().__setattr__(name, value)

    def validate(self):
        for fname, field in self._fields.items():
            field.validate(self._data.get(fname))

    @classmethod
    def _get_schema_columns(cls):
        return [f.name for f in cls._fields.values()]

    @classmethod
    def _from_row(cls, row: Dict[str, Any]):
        instance = cls()
        for fname, field in cls._fields.items():
            if fname in row:
                instance._data[fname] = field.from_db(row[fname])
        return instance

    @classmethod
    def create_table(cls):
        adapter = cls._adapter
        table = cls._table_name
        col_defs = []
        for fname, field in cls._fields.items():
            col_def = f"{adapter.quote_identifier(fname)} {field.field_type}"
            if field.field_type == "VARCHAR" and field.max_length:
                col_def = f"{adapter.quote_identifier(fname)} VARCHAR({field.max_length})"
            if field.primary_key:
                col_def += " PRIMARY KEY"
            if not field.nullable and not field.primary_key:
                col_def += " NOT NULL"
            if field.unique and not field.primary_key:
                col_def += " UNIQUE"
            col_defs.append(col_def)
        sql = f"CREATE TABLE IF NOT EXISTS {adapter.quote_identifier(table)} ({', '.join(col_defs)})"
        adapter.execute(sql, fetch=False)

        if hasattr(adapter, "optimizer"):
            for fname, field in cls._fields.items():
                if field.index and not field.primary_key:
                    idx_name = f"idx_{table}_{fname}"
                    idx_sql = (
                        f"CREATE INDEX IF NOT EXISTS {idx_name} "
                        f"ON {adapter.quote_identifier(table)} ({adapter.quote_identifier(fname)})"
                    )
                    try:
                        adapter.execute(idx_sql, fetch=False)
                    except Exception as e:
                        logger.warning(f"Failed to create index {idx_name}: {e}")

    @classmethod
    def objects(cls) -> QuerySet:
        return QuerySet(cls)

    @classmethod
    def get(cls, **kwargs):
        return cls.objects().filter(**kwargs).first()

    def save(self):
        self.validate()
        adapter = self._adapter
        table = self._table_name
        pk = self._pk_field

        columns = []
        values = []
        for fname, field in self._fields.items():
            if fname == pk and self._data.get(pk) is None:
                continue
            columns.append(fname)
            values.append(field.to_db(self._data.get(fname)))

        if pk and self._data.get(pk) is not None:
            existing = self.__class__.get(**{pk: self._data[pk]})
        else:
            existing = None

        if existing:
            set_clauses = []
            params = []
            for i, col in enumerate(columns):
                idx = len(params)
                set_clauses.append(
                    f"{adapter.quote_identifier(col)} = {adapter.get_placeholder(idx)}"
                )
                params.append(values[i])
            idx = len(params)
            sql = (
                f"UPDATE {adapter.quote_identifier(table)} SET "
                + ", ".join(set_clauses)
                + f" WHERE {adapter.quote_identifier(pk)} = {adapter.get_placeholder(idx)}"
            )
            params.append(self._data[pk])
            adapter.execute(sql, tuple(params), fetch=False)
        else:
            col_sql = ", ".join(adapter.quote_identifier(c) for c in columns)
            placeholders = ", ".join(
                adapter.get_placeholder(i) for i in range(len(columns))
            )
            returning = ""
            if pk and adapter.dialect == "postgresql":
                returning = f" RETURNING {adapter.quote_identifier(pk)}"
            sql = (
                f"INSERT INTO {adapter.quote_identifier(table)} ({col_sql}) "
                f"VALUES ({placeholders}){returning}"
            )
            result = adapter.execute(sql, tuple(values), fetch=bool(returning))
