"""
Multi-database ORM supporting PostgreSQL, MySQL, SQLite, MongoDB, and Cassandra.

NOTE: This implementation focuses primarily on PostgreSQL, which includes
full query optimization and connection pooling. Other backends (MySQL,
SQLite, MongoDB, Cassandra) are implemented with functional adapters that
share the same unified query interface, so switching backends only
requires changing the connection configuration.
"""

import re
import time
import threading
import queue
import sqlite3
import json
import logging
from contextlib import contextmanager
from typing import Any, Dict, List, Optional, Tuple, Type, Union

logger = logging.getLogger("multi_orm")
logger.setLevel(logging.INFO)


# ---------------------------------------------------------------------------
# Exceptions
# ---------------------------------------------------------------------------

class ORMError(Exception):
    pass


class ConnectionPoolExhausted(ORMError):
    pass


class ValidationError(ORMError):
    pass


class QueryError(ORMError):
    pass


# ---------------------------------------------------------------------------
# Connection Pool (generic, thread-safe)
# ---------------------------------------------------------------------------

class ConnectionPool:
    """
    Generic thread-safe connection pool used primarily for PostgreSQL,
    but reusable by MySQL/SQLite adapters as well.
    """

    def __init__(self, create_conn_fn, min_size=2, max_size=10, timeout=30,
                 max_idle_time=300, validate_fn=None):
        self._create_conn_fn = create_conn_fn
        self._validate_fn = validate_fn or (lambda c: True)
        self.min_size = min_size
        self.max_size = max_size
        self.timeout = timeout
        self.max_idle_time = max_idle_time

        self._pool = queue.Queue(maxsize=max_size)
        self._lock = threading.Lock()
        self._current_size = 0
        self._closed = False

        for _ in range(min_size):
            self._pool.put(self._new_conn_wrapper())

    def _new_conn_wrapper(self):
        conn = self._create_conn_fn()
        with self._lock:
            self._current_size += 1
        return {"conn": conn, "last_used": time.time()}

    @contextmanager
    def acquire(self):
        if self._closed:
            raise ORMError("Connection pool is closed")

        entry = None
        try:
            try:
                entry = self._pool.get(timeout=0.001)
            except queue.Empty:
                with self._lock:
                    if self._current_size < self.max_size:
                        entry = self._new_conn_wrapper()

            if entry is None:
                try:
                    entry = self._pool.get(timeout=self.timeout)
                except queue.Empty:
                    raise ConnectionPoolExhausted(
                        "Timed out waiting for a free connection"
                    )

            if time.time() - entry["last_used"] > self.max_idle_time:
                entry = self._refresh(entry)

            if not self._validate_fn(entry["conn"]):
                entry = self._refresh(entry)

            yield entry["conn"]
        finally:
            if entry is not None:
                entry["last_used"] = time.time()
                try:
                    self._pool.put_nowait(entry)
                except queue.Full:
                    self._destroy(entry)

    def _refresh(self, entry):
        self._destroy(entry)
        return self._new_conn_wrapper()

    def _destroy(self, entry):
        try:
            entry["conn"].close()
        except Exception:
            pass
        with self._lock:
            self._current_size -= 1

    def close_all(self):
        self._closed = True
        while not self._pool.empty():
            try:
                entry = self._pool.get_nowait()
                self._destroy(entry)
            except queue.Empty:
                break

    def stats(self):
        return {
            "current_size": self._current_size,
            "available": self._pool.qsize(),
            "max_size": self.max_size,
        }


# ---------------------------------------------------------------------------
# Query Cache / Optimizer (mainly targeted at PostgreSQL)
# ---------------------------------------------------------------------------

class QueryCache:
    def __init__(self, max_entries=256, ttl=60):
        self._store: Dict[str, Tuple[float, Any]] = {}
        self._lock = threading.Lock()
        self.max_entries = max_entries
        self.ttl = ttl

    def get(self, key):
        with self._lock:
            item = self._store.get(key)
            if not item:
                return None
            ts, value = item
            if time.time() - ts > self.ttl:
                del self._store[key]
                return None
            return value

    def set(self, key, value):
        with self._lock:
            if len(self._store) >= self.max_entries:
                oldest_key = min(self._store, key=lambda k: self._store[k][0])
                del self._store[oldest_key]
            self._store[key] = (time.time(), value)

    def invalidate_prefix(self, prefix):
        with self._lock:
            keys = [k for k in self._store if k.startswith(prefix)]
            for k in keys:
                del self._store[k]

    def clear(self):
        with self._lock:
            self._store.clear()


class QueryOptimizer:
    """
    Lightweight, heuristic query optimizer:
      - caches SELECT results (invalidated on writes to same table)
      - tracks column usage to suggest indexes
      - rewrites SELECT * into explicit column lists when schema known
      - batches repeated single-row lookups (poor-man's IN batching hint)
    """

    def __init__(self, cache_ttl=30):
        self.cache = QueryCache(ttl=cache_ttl)
        self._column_usage: Dict[str, Dict[str, int]] = {}
        self._lock = threading.Lock()

    def track_column_usage(self, table: str, column: str):
        with self._lock:
            table_stats = self._column_usage.setdefault(table, {})
            table_stats[column] = table_stats.get(column, 0) + 1

    def suggest_indexes(self, table: str, threshold: int = 5) -> List[str]:
        with self._lock:
            stats = self._column_usage.get(table, {})
            return [col for col, count in stats.items() if count >= threshold]

    def optimize_select(self, table: str, columns: List[str],
                         schema_columns: Optional[List[str]] = None) -> List[str]:
        if columns == ["*"] and schema_columns:
            return schema_columns
        return columns

    def cache_key(self, sql: str, params: tuple) -> str:
        return f"{sql}|{params}"


