class Field:
    def __init__(self, field_type="TEXT", primary_key=False, nullable=True,
                 default=None, unique=False, index=False, max_length=None):
        self.field_type = field_type
        self.primary_key = primary_key
        self.nullable = nullable
        self.default = default
        self.unique = unique
        self.index = index
        self.max_length = max_length
        self.name = None

    def validate(self, value):
        if value is None:
            if not self.nullable and self.default is None:
                raise ValidationError(f"Field '{self.name}' cannot be null")
            return
        if self.field_type == "VARCHAR" and self.max_length:
            if isinstance(value, str) and len(value) > self.max_length:
                raise ValidationError(
                    f"Field '{self.name}' exceeds max length {self.max_length}"
                )

    def to_db(self, value):
        return value

    def from_db(self, value):
        return value


class IntegerField(Field):
    def __init__(self, **kwargs):
        super().__init__(field_type="INTEGER", **kwargs)

    def validate(self, value):
        super().validate(value)
        if value is not None and not isinstance(value, int):
            raise ValidationError(f"Field '{self.name}' must be an integer")


class StringField(Field):
    def __init__(self, max_length=255, **kwargs):
        super().__init__(field_type="VARCHAR", max_length=max_length, **kwargs)

    def validate(self, value):
        super().validate(value)
        if value is not None and not isinstance(value, str):
            raise ValidationError(f"Field '{self.name}' must be a string")


class FloatField(Field):
    def __init__(self, **kwargs):
        super().__init__(field_type="FLOAT", **kwargs)


class BooleanField(Field):
    def __init__(self, **kwargs):
        super().__init__(field_type="BOOLEAN", **kwargs)


class JSONField(Field):
    def __init__(self, **kwargs):
        super().__init__(field_type="JSONB", **kwargs)

    def to_db(self, value):
        if value is None:
            return None
        return json.dumps(value)

    def from_db(self, value):
        if value is None:
            return None
        if isinstance(value, (dict, list)):
            return value
        return json.loads(value)


class DateTimeField(Field):
    def __init__(self, **kwargs):
        super().__init__(field_type="TIMESTAMP", **kwargs)


