class BaseAdapter:
    dialect = "generic"
    supports_pooling = False

    def connect(self):
        raise NotImplementedError

    def execute(self, sql, params=None):
        raise NotImplementedError

    def executemany(self, sql, param_list):
        raise NotImplementedError

    def get_placeholder(self, index):
