class PostgreSQLAdapter(BaseAdapter):
    """
    Full-featured adapter with connection pooling and query optimization.
    """
    dialect = "postgresql"
    supports_pooling = True

    def __init__(self, dsn=None, host="localhost", port=5432, user="postgres",
                 password="", database="postgres", min_pool=2, max_pool=10,
                 pool_timeout=30):
        try:
            import psycopg2
            import psycopg2.extras
        except ImportError as e:
            raise ORMError(
                "psycopg2 is required for PostgreSQLAdapter. "
                "Install with `pip install psycopg2-binary`."
            ) from e

        self._psycopg2 = psycopg2
        self._extras = psycopg2.extras
        self.dsn = dsn
        self.conn_params = dict(
            host=host, port=port, user=user, password=password, database=database
        )

        def _create_conn():
            if self.dsn:
                conn = self._psycopg2.connect(self.dsn)
            else:
                conn = self._psycopg2.connect(**self.conn_params)
            conn.autocommit = False
            return conn

        def _validate(conn):
            try:
                if conn.closed:
                    return False
                cur = conn.cursor()
                cur.execute("SELECT 1")
                cur.fetchone()
                cur.close()
                return True
            except Exception:
                return False

        self.pool = ConnectionPool(
            create_conn_fn=_create_conn,
            min_size=min_pool,
            max_size=max_pool,
            timeout=pool_timeout,
            validate_fn=_validate,
        )
        self.optimizer = QueryOptimizer()

    def get_placeholder(self, index):
        return "%s"

    def quote_identifier(self, name):
        return f'"{name}"'

    @contextmanager
    def connection(self):
        with self.pool.acquire() as conn:
            yield conn

    def execute(self, sql, params=None, fetch=True, commit=True, use_cache=False):
        params = params or ()
        cache_key = None
        is_select = sql.strip().upper().startswith("SELECT")

        if use_cache and is_select:
            cache_key = self.optimizer.cache_key(sql, tuple(params))
            cached = self.optimizer.cache.get(cache_key)
            if cached is not None:
                return cached

        with self.connection() as conn:
            cur = conn.cursor(cursor_factory=self._extras.RealDictCursor)
            try:
                cur.execute(sql, params)
                if is_select and fetch:
                    result = [dict(row) for row in cur.fetchall()]
                else:
                    result = cur.rowcount
                if commit:
                    conn.commit()
            except Exception:
                conn.rollback()
                raise
            finally:
                cur.close()

        if not is_select:
            table_match = re.search(
                r"(?:UPDATE|INTO|FROM)\s+\"?(\w+)\"?", sql, re.IGNORECASE
            )
            if table_match:
                self.optimizer.cache.invalidate_prefix("")
        elif use_cache and cache_key:
            self.optimizer.cache.set(cache_key, result)

        return result

    def executemany(self, sql, param_list):
        with self.connection() as conn:
            cur = conn.cursor()
            try:
                cur.executemany(sql, param_list)
                conn.commit()
                return cur.rowcount
            except Exception:
                conn.rollback()
                raise
            finally:
                cur.close()

    def close(self):
        self.pool.close_all()


