            amount_requested=amount_requested,
            details=details,
        )
        definition = self.registry.get(coverage_code)
        return definition.process_claim(claim, detail)


# ---------------------------------------------------------------------------
# 6. BILLING SYSTEM
# ---------------------------------------------------------------------------

class BillingSystem:
    def __init__(self, registry: CoverageRegistry, premium_calculator: PremiumCalculator):
        self.registry = registry
        self.premium_calculator = premium_calculator

    def generate_invoice(self, policy: Policy, risk_scores: Dict[CoverageCode, float]) -> List[BillingLineItem]:
        line_items = []
        for detail in policy.coverages:
            definition = self.registry.get(detail.code)
            risk = risk_scores.get(detail.code, 1.0)
            premium_ctx = PremiumContext(detail, {}, risk)
            premium = self.premium_calculator.calculate(premium_ctx)
            line_items.append(definition.build_billing_line(detail, premium))
        return line_items

    def total_due(self, line_items: List[BillingLineItem]) -> float:
        return round(sum(item.amount for item in line_items), 2)


# ---------------------------------------------------------------------------
# 7. RENEWAL HANDLER
# ---------------------------------------------------------------------------

class RenewalHandler:
    def __init__(self, registry: CoverageRegistry):
        self.registry = registry

    def renew_policy(self, policy: Policy, years_active: int) -> Policy:
        new_coverages = []
        for detail in policy.coverages:
            definition = self.registry.get(detail.code)
            ctx = RenewalContext(policy=policy, coverage_detail=detail, years_active=years_active)
            new_coverages.append(definition.renew(ctx))
        renewed = Policy(
            policy_id=policy.policy_id,
            holder_name=policy.holder_name,
            coverages=new_coverages,
            start_date=policy.end_date or datetime.date.today(),
            end_date=None,
            status="ACTIVE",
        )
        return renewed


# ---------------------------------------------------------------------------
# 8. COMPLIANCE REPORTER
# ---------------------------------------------------------------------------

class ComplianceReporter:
    def __init__(self, registry: CoverageRegistry):
        self.registry = registry

    def build_report(self, policy: Policy) -> List[ComplianceRecord]:
        records = []
        for detail in policy.coverages:
            definition = self.registry.get(detail.code)
            records.append(definition.compliance_record(detail))
        return records


# ---------------------------------------------------------------------------
# 9. AGENT PORTAL
# ---------------------------------------------------------------------------

class AgentPortal:
    def __init__(self, registry: CoverageRegistry):
        self.registry = registry

    def render_policy_summary(self, policy: Policy) -> str:
        lines = [f"Policy {policy.policy_id} for {policy.holder_name}:"]
        for detail in policy.coverages:
            definition = self.registry.get(detail.code)
            lines.append("  - " + definition.agent_portal_summary(detail))
        return "\n".join(lines)


