"""
Insurance System
================
Adding a new coverage type requires changes in exactly ten places:
  1. Policy model
  2. Quote engine
  3. Underwriting rules
  4. Premium calculator
  5. Claim processor
  6. Billing system
  7. Renewal handler
  8. Compliance reporter
  9. Agent portal
  10. Customer portal

Each coverage type is registered in a central registry and every subsystem
consults that registry to discover what coverage-specific logic to run.
To add a new coverage type, you implement a `CoverageDefinition` (or a
subclass) and register it -- but you must still supply the ten pieces of
logic (one per subsystem) that the definition requires.
"""

from __future__ import annotations

import datetime
import uuid
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Callable, Dict, List, Optional


# ---------------------------------------------------------------------------
# Core enums / value objects
# ---------------------------------------------------------------------------

class CoverageCode(str, Enum):
    AUTO_LIABILITY = "AUTO_LIABILITY"
    AUTO_COLLISION = "AUTO_COLLISION"
    HOME_DWELLING = "HOME_DWELLING"
    HOME_FLOOD = "HOME_FLOOD"
    LIFE_TERM = "LIFE_TERM"
    HEALTH_BASIC = "HEALTH_BASIC"
    TRAVEL_MEDICAL = "TRAVEL_MEDICAL"
    PET_ACCIDENT = "PET_ACCIDENT"


class ClaimStatus(str, Enum):
    OPEN = "OPEN"
    APPROVED = "APPROVED"
    DENIED = "DENIED"
    PAID = "PAID"


# ---------------------------------------------------------------------------
# 1. POLICY MODEL
# ---------------------------------------------------------------------------

@dataclass
class CoverageDetail:
    """Represents one coverage attached to a policy."""
    code: CoverageCode
    limit: float
    deductible: float
    attributes: Dict[str, Any] = field(default_factory=dict)


@dataclass
class Policy:
    """The Policy model. New coverage types must define how they serialize
    into a CoverageDetail and how they validate their own attributes."""
    policy_id: str
    holder_name: str
    coverages: List[CoverageDetail] = field(default_factory=list)
    start_date: datetime.date = field(default_factory=datetime.date.today)
    end_date: Optional[datetime.date] = None
    status: str = "ACTIVE"

    def add_coverage(self, detail: CoverageDetail) -> None:
        definition = COVERAGE_REGISTRY.get(detail.code)
        definition.policy_model_validate(detail)
        self.coverages.append(detail)

    def get_coverage(self, code: CoverageCode) -> Optional[CoverageDetail]:
        for c in self.coverages:
            if c.code == code:
                return c
        return None


# ---------------------------------------------------------------------------
# Abstract per-subsystem hook interfaces
# ---------------------------------------------------------------------------

@dataclass
class QuoteRequest:
    coverage_code: CoverageCode
    attributes: Dict[str, Any]
    applicant_profile: Dict[str, Any]


@dataclass
class QuoteResult:
    coverage_code: CoverageCode
    base_premium: float
    notes: List[str] = field(default_factory=list)


@dataclass
class UnderwritingContext:
    applicant_profile: Dict[str, Any]
    coverage_detail: CoverageDetail


@dataclass
class UnderwritingDecision:
    approved: bool
    reasons: List[str] = field(default_factory=list)
    risk_score: float = 0.0


@dataclass
class PremiumContext:
    coverage_detail: CoverageDetail
    applicant_profile: Dict[str, Any]
    risk_score: float


@dataclass
class Claim:
    claim_id: str
    policy_id: str
    coverage_code: CoverageCode
    amount_requested: float
    details: Dict[str, Any] = field(default_factory=dict)
    status: ClaimStatus = ClaimStatus.OPEN
    amount_approved: float = 0.0


@dataclass
class BillingLineItem:
    coverage_code: CoverageCode
    amount: float
    description: str


@dataclass
class RenewalContext:
    policy: Policy
    coverage_detail: CoverageDetail
    years_active: int


@dataclass
class ComplianceRecord:
    coverage_code: CoverageCode
    fields: Dict[str, Any]


class CoverageDefinition(ABC):
    """Base class that forces implementers to supply logic for every
    subsystem in the insurance system when introducing a new coverage."""

    code: CoverageCode
    display_name: str

    # ---- 1. Policy model ----
    @abstractmethod
    def policy_model_validate(self, detail: CoverageDetail) -> None:
        """Validate the coverage detail's attributes for the policy model."""

    # ---- 2. Quote engine ----
    @abstractmethod
    def generate_quote(self, request: QuoteRequest) -> QuoteResult:
        """Produce a base quote for this coverage."""

    # ---- 3. Underwriting rules ----
    @abstractmethod
    def underwrite(self, context: UnderwritingContext) -> UnderwritingDecision:
        """Decide whether to approve the coverage and compute risk score."""

    # ---- 4. Premium calculator ----
    @abstractmethod
    def calculate_premium(self, context: PremiumContext) -> float:
        """Compute the final premium for this coverage."""

    # ---- 5. Claim processor ----
    @abstractmethod
    def process_claim(self, claim: Claim, detail: CoverageDetail) -> Claim:
        """Adjudicate a claim for this coverage type."""

    # ---- 6. Billing system ----
    @abstractmethod
    def build_billing_line(self, detail: CoverageDetail, premium: float) -> BillingLineItem:
        """Create the billing line item representation."""

    # ---- 7. Renewal handler ----
    @abstractmethod
    def renew(self, context: RenewalContext) -> CoverageDetail:
        """Produce the renewed CoverageDetail (e.g. adjusted limits)."""

    # ---- 8. Compliance reporter ----
    @abstractmethod
    def compliance_record(self, detail: CoverageDetail) -> ComplianceRecord:
        """Produce the record required for regulatory reporting."""

    # ---- 9. Agent portal ----
    @abstractmethod
    def agent_portal_summary(self, detail: CoverageDetail) -> str:
        """Human readable summary for agents selling this coverage."""

    # ---- 10. Customer portal ----
    @abstractmethod
    def customer_portal_summary(self, detail: CoverageDetail) -> str:
        """Human readable summary for customers viewing this coverage."""


# ---------------------------------------------------------------------------
# Registry
# ---------------------------------------------------------------------------

class CoverageRegistry:
    def __init__(self) -> None:
        self._defs: Dict[CoverageCode, CoverageDefinition] = {}

    def register(self, definition: CoverageDefinition) -> None:
        self._defs[definition.code] = definition

    def get(self, code: CoverageCode) -> CoverageDefinition:
        if code not in self._defs:
            raise KeyError(f"No coverage definition registered for {code}")
        return self._defs[code]

    def all(self) -> List[CoverageDefinition]:
        return list(self._defs.values())


COVERAGE_REGISTRY = CoverageRegistry()


