# Concrete coverage implementations
# ---------------------------------------------------------------------------

class AutoLiabilityCoverage(CoverageDefinition):
    code = CoverageCode.AUTO_LIABILITY
    display_name = "Auto Liability"

    def policy_model_validate(self, detail: CoverageDetail) -> None:
        if detail.limit < 15000:
            raise ValueError("Auto liability limit must be at least 15,000")
        if "vehicle_value" not in detail.attributes:
            raise ValueError("Auto liability requires 'vehicle_value' attribute")

    def generate_quote(self, request: QuoteRequest) -> QuoteResult:
        base = 300 + request.attributes.get("vehicle_value", 0) * 0.01
        return QuoteResult(self.code, base_premium=round(base, 2),
                            notes=["Base quote for auto liability"])

    def underwrite(self, context: UnderwritingContext) -> UnderwritingDecision:
        age = context.applicant_profile.get("driver_age", 30)
        violations = context.applicant_profile.get("violations", 0)
        risk = 1.0 + violations * 0.2 + (0.3 if age < 25 else 0)
        approved = violations < 5
        reasons = [] if approved else ["Too many violations"]
        return UnderwritingDecision(approved=approved, reasons=reasons, risk_score=risk)

    def calculate_premium(self, context: PremiumContext) -> float:
        base = 300 + context.coverage_detail.attributes.get("vehicle_value", 0) * 0.01
        return round(base * context.risk_score, 2)

    def process_claim(self, claim: Claim, detail: CoverageDetail) -> Claim:
        payout = min(claim.amount_requested, detail.limit)
        claim.amount_approved = payout
        claim.status = ClaimStatus.APPROVED
        return claim

    def build_billing_line(self, detail: CoverageDetail, premium: float) -> BillingLineItem:
        return BillingLineItem(self.code, premium, "Auto Liability Premium")

    def renew(self, context: RenewalContext) -> CoverageDetail:
        new_limit = context.coverage_detail.limit
        return CoverageDetail(self.code, new_limit, context.coverage_detail.deductible,
                               dict(context.coverage_detail.attributes))

    def compliance_record(self, detail: CoverageDetail) -> ComplianceRecord:
        return ComplianceRecord(self.code, {"limit": detail.limit, "type": "liability"})

    def agent_portal_summary(self, detail: CoverageDetail) -> str:
        return f"Auto Liability - Limit: {detail.limit}, Vehicle Value: {detail.attributes.get('vehicle_value')}"

    def customer_portal_summary(self, detail: CoverageDetail) -> str:
        return f"Your auto liability coverage protects up to {detail.limit}."


class HomeFloodCoverage(CoverageDefinition):
    code = CoverageCode.HOME_FLOOD
    display_name = "Home Flood"

    def policy_model_validate(self, detail: CoverageDetail) -> None:
        if "flood_zone" not in detail.attributes:
            raise ValueError("Home flood requires 'flood_zone' attribute")

    def generate_quote(self, request: QuoteRequest) -> QuoteResult:
        zone = request.attributes.get("flood_zone", "X")
        multiplier = {"A": 3.0, "B": 1.8, "X": 1.0}.get(zone, 1.5)
        base = 500 * multiplier
        return QuoteResult(self.code, base_premium=round(base, 2),
                            notes=[f"Flood zone {zone} applied"])

    def underwrite(self, context: UnderwritingContext) -> UnderwritingDecision:
        zone = context.coverage_detail.attributes.get("flood_zone", "X")
        risk = {"A": 2.5, "B": 1.5, "X": 1.0}.get(zone, 1.5)
        approved = zone != "A" or context.applicant_profile.get("mitigation", False)
        reasons = [] if approved else ["High-risk flood zone without mitigation"]
        return UnderwritingDecision(approved=approved, reasons=reasons, risk_score=risk)

    def calculate_premium(self, context: PremiumContext) -> float:
        zone = context.coverage_detail.attributes.get("flood_zone", "X")
        multiplier = {"A": 3.0, "B": 1.8, "X": 1.0}.get(zone, 1.5)
        return round(500 * multiplier * context.risk_score, 2)

    def process_claim(self, claim: Claim, detail: CoverageDetail) -> Claim:
        deductible = detail.deductible
        payout = max(0.0, min(claim.amount_requested, detail.limit) - deductible)
        claim.amount_approved = round(payout, 2)
        claim.status = ClaimStatus.APPROVED if payout > 0 else ClaimStatus.DENIED
        return claim

    def build_billing_line(self, detail: CoverageDetail, premium: float) -> BillingLineItem:
        return BillingLineItem(self.code, premium, "Home Flood Premium")

    def renew(self, context: RenewalContext) -> CoverageDetail:
        bump = 1.0 + 0.02 * context.years_active
        new_limit = round(context.coverage_detail.limit * bump, 2)
        return CoverageDetail(self.code, new_limit, context.coverage_detail.deductible,
                               dict(context.coverage_detail.attributes))

    def compliance_record(self, detail: CoverageDetail) -> ComplianceRecord:
        return ComplianceRecord(self.code, {"flood_zone": detail.attributes.get("flood_zone")})

    def agent_portal_summary(self, detail: CoverageDetail) -> str:
        return f"Home Flood - Zone: {detail.attributes.get('flood_zone')}, Limit: {detail.limit}"

    def customer_portal_summary(self, detail: CoverageDetail) -> str:
        return f"Flood coverage active in zone {detail.attributes.get('flood_zone')}."


