# Market Data Alignment
# ---------------------------------------------------------------------------
class MarketDataAligner:
    """
    Utilities for aligning, resampling, and merging market data across
    multiple symbols and frequencies, respecting a trading calendar.
    """

    def __init__(self, calendar: Optional[TradingCalendar] = None):
        self.calendar = calendar or make_nyse_calendar()

    # -- Reindexing to sessions --------------------------------------------
    def reindex_to_sessions(
        self, df: pd.DataFrame, start: DateLike, end: DateLike, method: Optional[str] = None
    ) -> pd.DataFrame:
        sessions = self.calendar.sessions(start, end)
        naive_index = df.index.tz_localize(None) if df.index.tz is not None else df.index
        tmp = df.copy()
        tmp.index = naive_index.normalize()
        tmp = tmp.reindex(sessions, method=method)
        return tmp

    def fill_missing_sessions(self, df: pd.DataFrame, start: DateLike, end: DateLike) -> pd.DataFrame:
        """Forward-fill OHLCV data over missing trading sessions (e.g., halted symbols)."""
        reindexed = self.reindex_to_sessions(df, start, end)
        filled = reindexed.copy()
        if "close" in filled.columns:
            filled["close"] = filled["close"].ffill()
            for col in ["open", "high", "low"]:
                if col in filled.columns:
                    filled[col] = filled[col].fillna(filled["close"])
        if "volume" in filled.columns:
            filled["volume"] = filled["volume"].fillna(0)
        return filled

    # -- Multi-symbol alignment ---------------------------------------------
    def align_symbols(
        self, data: Dict[str, pd.DataFrame], field_name: str = "close", how: str = "outer"
    ) -> pd.DataFrame:
        """Align a single field (e.g. close price) across multiple symbols into one wide DataFrame."""
        series_map = {}
        for sym, df in data.items():
            if field_name not in df.columns:
                raise KeyError(f"{field_name} not in columns for {sym}")
            s = df[field_name].copy()
            s.name = sym
            series_map[sym] = s
        aligned = pd.concat(series_map.values(), axis=1, join=how)
        aligned = aligned.sort_index()
        return aligned

    def align_multi_field(
        self, data: Dict[str, pd.DataFrame], fields: Sequence[str] = ("open", "high", "low", "close", "volume")
    ) -> pd.DataFrame:
        """Build a MultiIndex-columns DataFrame: level0=symbol, level1=field."""
        frames = {}
        for sym, df in data.items():
            cols = [f for f in fields if f in df.columns]
            frames[sym] = df[cols]
        combined = pd.concat(frames, axis=1, join="outer")
        combined = combined.sort_index()
        return combined

    # -- Resampling -----------------------------------------------------------
    @staticmethod
    def resample_ohlcv(df: pd.DataFrame, rule: str) -> pd.DataFrame:
        """Resample intraday/daily OHLCV bars to a coarser frequency."""
        agg = {}
        if "open" in df.columns:
            agg["open"] = "first"
        if "high" in df.columns:
            agg["high"] = "max"
        if "low" in df.columns:
            agg["low"] = "min"
        if "close" in df.columns:
            agg["close"] = "last"
        if "volume" in df.columns:
            agg["volume"] = "sum"
        if "adj_close" in df.columns:
            agg["adj_close"] = "last"
        resampled = df.resample(rule).agg(agg)
        resampled = resampled.dropna(how="all")
        return resampled

    def resample_to_sessions(self, df: pd.DataFrame) -> pd.DataFrame:
        """Resample intraday data to daily bars using calendar session boundaries."""
        if df.index.tz is None:
            raise ValueError("Intraday data must be timezone-aware for session resampling")

        results = []
        dates = sorted(set(df.index.tz_convert(self.calendar.tz).normalize()))
        for d in dates:
            o = self.calendar.market_open(d)
            c = self.calendar.market_close(d)
            mask = (df.index >= o) & (df.index <= c)
            day_df = df.loc[mask]
            if day_df.empty:
                continue
            row = {}
            if "open" in day_df.columns:
                row["open"] = day_df["open"].iloc[0]
            if "high" in day_df.columns:
                row["high"] = day_df["high"].max()
            if "low" in day_df.columns:
                row["low"] = day_df["low"].min()
            if "close" in day_df.columns:
                row["close"] = day_df["close"].iloc[-1]
            if "volume" in day_df.columns:
                row["volume"] = day_df["volume"].sum()
            results.append((d, row))

        if not results:
            return pd.DataFrame()

        idx = pd.DatetimeIndex([r[0] for r in results])
        data_rows = [r[1] for r in results]
        return pd.DataFrame(data_rows, index=idx)

    # -- Gap / staleness detection --------------------------------------------
    def detect_stale_data(self, df: pd.DataFrame, max_gap: pd.Timedelta) -> pd.Series:
        """Return boolean Series flagging rows preceded by a gap larger than max_gap."""
        diffs = df.index.to_series().diff()
        stale = diffs > max_gap
        stale.iloc[0] = False
        return stale

    def compute_returns(
        self, prices: pd.DataFrame, method: str = "simple", periods: int = 1
    ) -> pd.DataFrame:
        if method == "simple":
            return prices.pct_change(periods=periods)
        elif method == "log":
            return np.log(prices / prices.shift(periods))
        else:
            raise ValueError("method must be 'simple' or 'log'")

    def synchronize_frequencies(
        self, data: Dict[str, pd.DataFrame], target_rule: str
    ) -> Dict[str, pd.DataFrame]:
        """Resample all symbol frames to a common frequency (OHLCV-aware)."""
        return {sym: self.resample_ohlcv(df, target_rule) for sym, df in data.items()}


# ---------------------------------------------------------------------------
# Convenience: high-level Market Data Wrapper combining all pieces
# ---------------------------------------------------------------------------
class MarketDataFrame:
    """
    A convenience wrapper around a pandas DataFrame of OHLCV data, bundling a
    TradingCalendar, TimezoneHandler, and CorporateActionsManager for a single
    symbol's price history.
    """

    def __init__(
        self,
        df: pd.DataFrame,
        symbol: str,
        calendar: Optional[TradingCalendar] = None,
        tz: str = "America/New_York",
        corporate_actions: Optional[CorporateActionsManager] = None,
    ):
        self.symbol = symbol
        self.calendar = calendar or make_nyse_calendar()
        self.tz = tz
        self.corporate_actions = corporate_actions or CorporateActionsManager()
        self.data = df.copy()
        self.data.columns = [c.lower() for c in self.data.columns]

    def localize(self) -> "MarketDataFrame":
        self.data.index = TimezoneHandler.localize(self.data.index, self.tz)
        return self

    def to_utc(self) -> pd.DataFrame:
        idx = TimezoneHandler.to_utc(self.data.index, source_tz=self.tz if self.data.index.tz is None else None)
        out = self.data.copy()
        out.index = idx
        return out

    def adjusted(self, method: str = "split_and_dividend") -> pd.DataFrame:
        return self.corporate_actions.adjust_ohlcv(self.data, method=method)

    def fill_sessions(self, start: DateLike, end: DateLike) -> pd.DataFrame:
        aligner = MarketDataAligner(self.calendar)
        return aligner.fill_missing_sessions(self.data, start, end)

    def resample(self, rule: str) -> pd.DataFrame:
        return MarketDataAligner.resample_ohlcv(self.data, rule)

    def returns(self, method: str = "simple", periods: int = 1) -> pd.Series:
        if "close" not in self.data.columns:
            raise KeyError("close column required for returns computation")
        close = self.data["close"]
        if method == "simple":
            return close.pct_change(periods=periods)
        elif method == "log":
            return np.log(close / close.shift(periods))
        raise ValueError("method must be 'simple' or 'log'")

    def summary(self) -> Dict[str, Number]:
        close = self.data.get("close")
        if close is None or close.empty:
            return {}
        rets = close.pct_change().dropna()
        return {
            "start": str(self.data.index.min()),
            "end": str(self.data.index.max()),
            "n_obs": int(len(self.data)),
            "mean_return": float(rets.mean()) if not rets.empty else float("nan"),
            "vol": float(rets.std()) if not rets.empty else float("nan"),
            "min_close": float(close.min()),
            "max_close": float(close.max()),
        }


# ---------------------------------------------------------------------------
# Module-level convenience functions
# ---------------------------------------------------------------------------
def generate_synthetic_ohlcv(
    start: DateLike,
    end: DateLike,
    calendar: Optional[TradingCalendar] = None,
    seed: int = 42,
    start_price: float = 100.0,
) -> pd.DataFrame:
    """Generate a synthetic daily OHLCV series over a calendar's sessions, for testing."""
    cal = calendar or make_nyse_calendar()
    sessions = cal.sessions(start, end)
    rng = np.random.default_rng(seed)
    n = len(sessions)
    rets = rng.normal(loc=0.0003, scale=0.01, size=n)
    close = start_price * np.cumprod(1 + rets)
    open_ = np.roll(close, 1)
    open_[0] = start_price
    high = np.maximum(open_, close) * (1 + np.abs(rng.normal(0, 0.002, size=n)))
    low = np.minimum(open_, close) * (1 - np.abs(rng.normal(0, 0.002, size=n)))
    volume = rng.integers(1_000_000, 5_000_000, size=n)

    df = pd.DataFrame(
        {"open": open_, "high": high, "low": low, "close": close, "volume": volume},
        index=sessions,
    )
    return df


def business_days_between(start: DateLike, end: DateLike, calendar: Optional[TradingCalendar] = None) -> int:
    cal = calendar or make_nyse_calendar()
    return cal.sessions_count(start, end)


def is_market_open_now(calendar: Optional[TradingCalendar] = None) -> bool:
    cal = calendar or make_nyse_calendar()
    return cal.is_session_now()

