            sorted(pd.Timestamp(h).normalize() for h in (holidays or []))
        )
        self.half_days: Dict[pd.Timestamp, dt.time] = {
            pd.Timestamp(k).normalize(): v for k, v in (half_days or {}).items()
        }

        self._busday_cal = np.busdaycalendar(
            weekmask=self.weekmask,
            holidays=self.holidays.to_numpy(dtype="datetime64[D]")
            if len(self.holidays) > 0
            else np.array([], dtype="datetime64[D]"),
        )

    # -- Basic calendar queries -------------------------------------------------
    def is_business_day(self, date: DateLike) -> bool:
        d = pd.Timestamp(date).normalize()
        arr = np.array([d.to_datetime64()], dtype="datetime64[D]")
        return bool(np.is_busday(arr, busdaycal=self._busday_cal)[0])

    def is_holiday(self, date: DateLike) -> bool:
        d = pd.Timestamp(date).normalize()
        return d in self.holidays

    def is_half_day(self, date: DateLike) -> bool:
        d = pd.Timestamp(date).normalize()
        return d in self.half_days

    def sessions(self, start: DateLike, end: DateLike) -> pd.DatetimeIndex:
        """Return normalized (midnight, tz-naive) trading session dates."""
        start_ts = pd.Timestamp(start).normalize()
        end_ts = pd.Timestamp(end).normalize()
        all_days = pd.date_range(start_ts, end_ts, freq="D")
        arr = all_days.to_numpy(dtype="datetime64[D]")
        mask = np.is_busday(arr, busdaycal=self._busday_cal)
        return pd.DatetimeIndex(all_days[mask])

    def session_close(self, date: DateLike) -> dt.time:
        d = pd.Timestamp(date).normalize()
        return self.half_days.get(d, self.close_time)

    def market_open(self, date: DateLike) -> pd.Timestamp:
        d = pd.Timestamp(date).normalize()
        naive = dt.datetime.combine(d.date(), self.open_time)
        return pd.Timestamp(naive, tz=self.tz)

    def market_close(self, date: DateLike) -> pd.Timestamp:
        d = pd.Timestamp(date).normalize()
        close_t = self.session_close(d)
        naive = dt.datetime.combine(d.date(), close_t)
        return pd.Timestamp(naive, tz=self.tz)

    def schedule(self, start: DateLike, end: DateLike) -> pd.DataFrame:
        """DataFrame indexed by session date, with market_open/market_close columns (tz-aware)."""
        sess = self.sessions(start, end)
        opens = [self.market_open(d) for d in sess]
        closes = [self.market_close(d) for d in sess]
        return pd.DataFrame({"market_open": opens, "market_close": closes}, index=sess)

    def next_session(self, date: DateLike) -> pd.Timestamp:
        d = pd.Timestamp(date).normalize()
        cursor = d + pd.Timedelta(days=1)
        while not self.is_business_day(cursor):
            cursor += pd.Timedelta(days=1)
        return cursor

    def previous_session(self, date: DateLike) -> pd.Timestamp:
        d = pd.Timestamp(date).normalize()
        cursor = d - pd.Timedelta(days=1)
        while not self.is_business_day(cursor):
            cursor -= pd.Timedelta(days=1)
        return cursor

    def sessions_count(self, start: DateLike, end: DateLike) -> int:
        return len(self.sessions(start, end))

    def is_session_now(self, moment: Optional[pd.Timestamp] = None) -> bool:
        """Check if a given tz-aware timestamp (default: now) falls within a trading session."""
        moment = moment or pd.Timestamp.now(tz=self.tz)
        if moment.tzinfo is None:
            moment = moment.tz_localize(self.tz)
        else:
            moment = moment.tz_convert(self.tz)
        d = moment.normalize()
        if not self.is_business_day(d):
            return False
        o = self.market_open(d)
        c = self.market_close(d)
        return o <= moment <= c

    def add_holiday(self, date: DateLike):
        d = pd.Timestamp(date).normalize()
        self.holidays = pd.DatetimeIndex(sorted(set(self.holidays) | {d}))
        self._rebuild_calendar()

    def add_half_day(self, date: DateLike, close_time: dt.time):
        d = pd.Timestamp(date).normalize()
        self.half_days[d] = close_time

    def _rebuild_calendar(self):
        self._busday_cal = np.busdaycalendar(
            weekmask=self.weekmask,
            holidays=self.holidays.to_numpy(dtype="datetime64[D]")
            if len(self.holidays) > 0
            else np.array([], dtype="datetime64[D]"),
        )


# Predefined common US calendar with a small illustrative holiday set.
def make_nyse_calendar(years: Sequence[int] = (2020, 2021, 2022, 2023, 2024, 2025)) -> TradingCalendar:
    holidays = []
    half_days = {}
    for y in years:
        holidays += [
            f"{y}-01-01",
            f"{y}-07-04",
            f"{y}-12-25",
        ]
        half_days[pd.Timestamp(f"{y}-07-03")] = dt.time(13, 0)
    return TradingCalendar(name="NYSE", tz="America/New_York", holidays=holidays, half_days=half_days)


# ---------------------------------------------------------------------------
# Timezone Handling
# ---------------------------------------------------------------------------
class TimezoneHandler:
    """Helper for converting market data timestamps between timezones."""

    def __init__(self, default_tz: str = "UTC"):
        self.default_tz = default_tz

    @staticmethod
    def localize(index: pd.DatetimeIndex, tz: str) -> pd.DatetimeIndex:
        if index.tz is None:
            return index.tz_localize(tz)
        return index.tz_convert(tz)

    @staticmethod
    def to_utc(index: pd.DatetimeIndex, source_tz: Optional[str] = None) -> pd.DatetimeIndex:
        if index.tz is None:
            if source_tz is None:
                raise ValueError("source_tz required for naive index")
            index = index.tz_localize(source_tz)
        return index.tz_convert("UTC")

    @staticmethod
    def convert(index: pd.DatetimeIndex, target_tz: str, source_tz: Optional[str] = None) -> pd.DatetimeIndex:
        if index.tz is None:
            if source_tz is None:
                raise ValueError("source_tz required for naive index")
            index = index.tz_localize(source_tz)
        return index.tz_convert(target_tz)

    @staticmethod
    def convert_frame(
        df: pd.DataFrame, target_tz: str, source_tz: Optional[str] = None
    ) -> pd.DataFrame:
        out = df.copy()
        out.index = TimezoneHandler.convert(out.index, target_tz, source_tz)
        return out

    @staticmethod
    def align_timestamp(ts: DateLike, tz: str) -> pd.Timestamp:
        t = pd.Timestamp(ts)
        if t.tzinfo is None:
            return t.tz_localize(tz)
        return t.tz_convert(tz)

    @staticmethod
    def session_bounds_utc(calendar: TradingCalendar, date: DateLike) -> Tuple[pd.Timestamp, pd.Timestamp]:
        o = calendar.market_open(date).tz_convert("UTC")
        c = calendar.market_close(date).tz_convert("UTC")
        return o, c


