@dataclass
class Split:
    ex_date: pd.Timestamp
    ratio: float  # e.g., 2.0 means 2-for-1 split

    def __post_init__(self):
        self.ex_date = pd.Timestamp(self.ex_date).normalize()


@dataclass
class Dividend:
    ex_date: pd.Timestamp
    amount: float  # cash amount per share

    def __post_init__(self):
