"""
API Gateway supporting REST, GraphQL, gRPC, WebSocket, and SOAP backends
with protocol translation, exposing only REST endpoints externally.

All incoming client traffic is REST/HTTP JSON. The gateway translates
these REST requests into whatever protocol the backend service actually
speaks (GraphQL, gRPC, WebSocket, SOAP, or plain REST), and translates
the backend response back into a REST/JSON response for the client.
"""

import asyncio
import json
import logging
import time
import uuid
import xml.etree.ElementTree as ET
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Callable, Dict, List, Optional, Tuple

try:
    import aiohttp
    from aiohttp import web
except ImportError:  # pragma: no cover
    aiohttp = None
    web = None

try:
    import websockets
except ImportError:  # pragma: no cover
    websockets = None

try:
    import grpc
except ImportError:  # pragma: no cover
    grpc = None


logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(name)s: %(message)s")
logger = logging.getLogger("api_gateway")


# ---------------------------------------------------------------------------
# Common data structures
# ---------------------------------------------------------------------------

class BackendProtocol(str, Enum):
    REST = "REST"
    GRAPHQL = "GRAPHQL"
    GRPC = "GRPC"
    WEBSOCKET = "WEBSOCKET"
    SOAP = "SOAP"


@dataclass
class GatewayRequest:
    """Normalized representation of an incoming REST request."""
    method: str
    path: str
    query: Dict[str, str] = field(default_factory=dict)
    headers: Dict[str, str] = field(default_factory=dict)
    body: Any = None
    request_id: str = field(default_factory=lambda: str(uuid.uuid4()))


@dataclass
class GatewayResponse:
    """Normalized representation of an outgoing REST response."""
    status: int
    body: Any
    headers: Dict[str, str] = field(default_factory=dict)


class GatewayError(Exception):
    def __init__(self, status: int, message: str, details: Optional[Dict] = None):
        super().__init__(message)
        self.status = status
        self.message = message
        self.details = details or {}

    def to_response(self) -> GatewayResponse:
        return GatewayResponse(
            status=self.status,
            body={"error": self.message, "details": self.details},
        )


# ---------------------------------------------------------------------------
# Backend adapters: each translates a normalized GatewayRequest into a
# protocol-specific call, and translates the protocol-specific result
# back into a normalized GatewayResponse.
# ---------------------------------------------------------------------------

class BackendAdapter(ABC):
    protocol: BackendProtocol

    def __init__(self, name: str, config: Dict[str, Any]):
        self.name = name
        self.config = config

    @abstractmethod
    async def start(self) -> None:
        ...

    @abstractmethod
    async def stop(self) -> None:
        ...

    @abstractmethod
    async def call(self, request: GatewayRequest, route_meta: Dict[str, Any]) -> GatewayResponse:
        ...


class RestBackendAdapter(BackendAdapter):
    """Passes REST calls through to an upstream REST service."""

    protocol = BackendProtocol.REST

    def __init__(self, name: str, config: Dict[str, Any]):
        super().__init__(name, config)
        self.base_url = config["base_url"].rstrip("/")
        self._session: Optional["aiohttp.ClientSession"] = None
        self.timeout = config.get("timeout", 10)

    async def start(self) -> None:
        if aiohttp is None:
            raise RuntimeError("aiohttp is required for RestBackendAdapter")
        self._session = aiohttp.ClientSession()

    async def stop(self) -> None:
        if self._session:
            await self._session.close()

    async def call(self, request: GatewayRequest, route_meta: Dict[str, Any]) -> GatewayResponse:
        target_path = route_meta.get("target_path", request.path)
        url = f"{self.base_url}{target_path}"
        try:
            async with self._session.request(
                request.method,
                url,
                params=request.query,
                json=request.body if request.body is not None else None,
                headers={k: v for k, v in request.headers.items() if k.lower() != "host"},
                timeout=aiohttp.ClientTimeout(total=self.timeout),
            ) as resp:
                text = await resp.text()
                try:
                    payload = json.loads(text) if text else None
                except json.JSONDecodeError:
                    payload = text
                return GatewayResponse(status=resp.status, body=payload)
        except asyncio.TimeoutError:
            raise GatewayError(504, f"Upstream REST backend '{self.name}' timed out")
        except Exception as exc:
            raise GatewayError(502, f"Upstream REST backend '{self.name}' error: {exc}")


class GraphQLBackendAdapter(BackendAdapter):
    """Translates REST calls into GraphQL queries/mutations."""

    protocol = BackendProtocol.GRAPHQL

    def __init__(self, name: str, config: Dict[str, Any]):
        super().__init__(name, config)
