class GrpcBackendAdapter(BackendAdapter):
    """Translates REST calls into gRPC unary calls using dynamically
    provided stub/method references, mapping JSON <-> protobuf messages."""

    protocol = BackendProtocol.GRPC

    def __init__(self, name: str, config: Dict[str, Any]):
        super().__init__(name, config)
        self.target = config["target"]
        self.channel = None

    async def start(self) -> None:
        if grpc is None:
            raise RuntimeError("grpcio is required for GrpcBackendAdapter")
        self.channel = grpc.aio.insecure_channel(self.target)

    async def stop(self) -> None:
        if self.channel:
            await self.channel.close()

    async def call(self, request: GatewayRequest, route_meta: Dict[str, Any]) -> GatewayResponse:
        """
        route_meta must supply:
          - stub_class: the generated gRPC stub class
          - method_name: str, method on the stub to invoke
          - request_class: the generated protobuf message class for the request
          - to_message(dict) -> protobuf message  (optional custom mapper)
          - to_dict(message) -> dict               (optional custom mapper)
        """
        try:
            stub_class = route_meta["stub_class"]
            method_name = route_meta["method_name"]
            request_class = route_meta["request_class"]
            to_message = route_meta.get("to_message")
            to_dict = route_meta.get("to_dict")

            stub = stub_class(self.channel)
            method = getattr(stub, method_name)

            payload = {}
            payload.update(request.query)
            if isinstance(request.body, dict):
                payload.update(request.body)
            payload.update(route_meta.get("path_params", {}))

            if to_message:
                grpc_request = to_message(payload)
            else:
                grpc_request = request_class(**payload)

            timeout = self.config.get("timeout", 10)
            response_msg = await method(grpc_request, timeout=timeout)

            if to_dict:
                body = to_dict(response_msg)
            else:
                body = self._message_to_dict(response_msg)

            return GatewayResponse(status=200, body=body)

        except KeyError as exc:
            raise GatewayError(500, f"gRPC route misconfigured, missing {exc}")
        except grpc.aio.AioRpcError as exc:
            status_map = {
                grpc.StatusCode.NOT_FOUND: 404,
                grpc.StatusCode.INVALID_ARGUMENT: 400,
                grpc.StatusCode.UNAUTHENTICATED: 401,
                grpc.StatusCode.PERMISSION_DENIED: 403,
                grpc.StatusCode.DEADLINE_EXCEEDED: 504,
            }
            status = status_map.get(exc.code(), 502)
            raise GatewayError(status, f"gRPC backend '{self.name}' error: {exc.details()}")
        except Exception as exc:
            raise GatewayError(502, f"gRPC backend '{self.name}' error: {exc}")

    @staticmethod
    def _message_to_dict(message) -> Dict[str, Any]:
        try:
            from google.protobuf.json_format import MessageToDict
            return MessageToDict(message, preserving_proto_field_name=True)
        except ImportError:
            result = {}
            for field_desc in message.DESCRIPTOR.fields:
                result[field_desc.name] = getattr(message, field_desc.name)
            return result


class WebSocketBackendAdapter(BackendAdapter):
    """Translates a REST request/response cycle into a single
    send-then-receive exchange over a persistent WebSocket connection."""

    protocol = BackendProtocol.WEBSOCKET

    def __init__(self, name: str, config: Dict[str, Any]):
        super().__init__(name, config)
        self.uri = config["uri"]
        self._ws = None
        self._lock = asyncio.Lock()
        self.timeout = config.get("timeout", 10)

    async def start(self) -> None:
        if websockets is None:
            raise RuntimeError("websockets library is required for WebSocketBackendAdapter")
        self._ws = await websockets.connect(self.uri)

    async def stop(self) -> None:
        if self._ws:
            await self._ws.close()

    async def _ensure_connected(self):
        if self._ws is None or self._ws.closed:
            self._ws = await websockets.connect(self.uri)

    async def call(self, request: GatewayRequest, route_meta: Dict[str, Any]) -> GatewayResponse:
        action = route_meta.get("action", request.path)
        payload = {
            "action": action,
            "params": {**request.query, **(request.body if isinstance(request.body, dict) else {})},
            "request_id": request.request_id,
        }

        async with self._lock:
            try:
                await self._ensure_connected()
                await self._ws.send(json.dumps(payload))
                raw = await asyncio.wait_for(self._ws.recv(), timeout=self.timeout)
            except asyncio.TimeoutError:
                raise GatewayError(504, f"WebSocket backend '{self.name}' timed out")
            except Exception as exc:
                raise GatewayError(502, f"WebSocket backend '{self.name}' error: {exc}")

        try:
            data = json.loads(raw)
        except json.JSONDecodeError:
            data = {"raw": raw}

        if isinstance(data, dict) and data.get("error"):
            return GatewayResponse(status=400, body={"error": data["error"]})

        return GatewayResponse(status=200, body=data)


class SoapBackendAdapter(BackendAdapter):
    """Translates REST calls into SOAP XML envelopes and parses the
    XML SOAP response back into JSON."""

    protocol = BackendProtocol.SOAP

    def __init__(self, name: str, config: Dict[str, Any]):
        super().__init__(name, config)
        self.endpoint = config["endpoint"]
        self._session: Optional["aiohttp.ClientSession"] = None
        self.timeout = config.get("timeout", 10)
        self.namespaces = config.get("namespaces", {"soap": "http://schemas.xmlsoap.org/soap/envelope/"})

    async def start(self) -> None:
        if aiohttp is None:
            raise RuntimeError("aiohttp is required for SoapBackendAdapter")
        self._session = aiohttp.ClientSession()

    async def stop(self) -> None:
        if self._session:
            await self._session.close()

    def _build_envelope(self, request: GatewayRequest, route_meta: Dict[str, Any]) -> str:
        soap_action = route_meta["soap_action"]
        body_template: str = route_meta["body_template"]

        params = {}
        params.update(request.query)
        if isinstance(request.body, dict):
            params.update(request.body)
        params.update(route_meta.get("path_params", {}))

        body_xml = body_template.format(**params)

        return (
            '<?xml version="1.0" encoding="utf-8"?>'
            '<soap:Envelope xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/">'
            f"<soap:Body>{body_xml}</soap:Body>"
            "</soap:Envelope>"
        ), soap_action

    def _xml_to_dict(self, elem: ET.Element) -> Any:
        children = list(elem)
        if not children:
            return elem.text.strip() if elem.text and elem.text.strip() else None

        result: Dict[str, Any] = {}
        for child in children:
            tag = child.tag.split("}")[-1]
            value = self._xml_to_dict(child)
            if tag in result:
                if not isinstance(result[tag], list):
                    result[tag] = [result[tag]]
                result[tag].append(value)
            else:
                result[tag] = value
        return result

    async def call(self, request: GatewayRequest, route_meta: Dict[str, Any]) -> GatewayResponse:
        envelope, soap_action = self._build_envelope(request, route_meta)
        headers = {
            "Content-Type": "text/xml; charset=utf-8",
            "SOAPAction": soap_action,
        }
        try:
            async with self._session.post(
                self.endpoint,
                data=envelope,
                headers=headers,
                timeout=aiohttp.ClientTimeout(total=self.timeout),
            ) as resp:
                text = await resp.text()
                status = resp.status
        except asyncio.TimeoutError:
            raise GatewayError(504, f"SOAP backend '{self.name}' timed out")
        except Exception as exc:
            raise GatewayError(502, f"SOAP backend '{self.name}' error: {exc}")

        try:
            root = ET.fromstring(text)
        except ET.ParseError:
            raise GatewayError(502, f"SOAP backend '{self.name}' returned invalid XML")

        body_elem = None
        for elem in root.iter():
            if elem.tag.split("}")[-1] == "Body":
                body_elem = elem
                break

        if body_elem is None or len(body_elem) == 0:
            return GatewayResponse(status=status, body=None)

        fault = None
        for child in body_elem:
            if child.tag.split("}")[-1] == "Fault":
                fault = child
                break

        if fault is not None:
            fault_dict = self._xml_to_dict(fault)
            return GatewayResponse(status=400, body={"fault": fault_dict})

        result_elem = list(body_elem)[0]
        result_dict = self._xml_to_dict(result_elem)
        return GatewayResponse(status=200 if status == 200 else status, body=result_dict)


# ---------------------------------------------------------------------------
# Routing
# ---------------------------------------------------------------------------

@dataclass
class Route:
    method: str
    path_pattern: str
    backend_name: str
    route_meta: Dict[str, Any] = field(default_factory=dict)

    def match(self, method: str, path: str) -> Optional[Dict[str, str]]:
        if method.upper() != self.method.upper():
            return None
        pattern_parts = self.path_pattern.strip("/").split("/")
        path_parts = path.strip("/").split("/")
        if len(pattern_parts) != len(path_parts):
            return None
        params = {}
        for p_part, a_part in zip(pattern_parts, path_parts):
            if p_part.startswith("{") and p_part.endswith("}"):
                params[p_part[1:-1]] = a_part
            elif p_part != a_part:
                return None
        return params


class Router:
    def __init__(self):
        self.routes: List[Route] = []

    def add_route(self, route: Route) -> None:
        self.routes.append(route)

    def resolve(self, method: str, path: str) -> Optional[Tuple[Route, Dict[str, str]]]:
        for route in self.routes:
            params = route.match(method, path)
            if params is not None:
                return route, params
        return None


# ---------------------------------------------------------------------------
# Middleware
# ---------------------------------------------------------------------------

Middleware = Callable[[GatewayRequest, Callable], "asyncio.Future"]


class MiddlewareChain:
    def __init__(self):
        self._middlewares: List[Middleware] = []

    def use(self, middleware: Middleware) -> None:
        self._middlewares.append(middleware)

    async def run(self, request: GatewayRequest, handler: Callable) -> GatewayResponse:
        async def build_chain(index: int) -> GatewayResponse:
            if index >= len(self._middlewares):
                return await handler(request)
            middleware = self._middlewares[index]

            async def next_fn(req: GatewayRequest) -> GatewayResponse:
                return await build_chain(index + 1)

            return await middleware(request, next_fn)

        return await build_chain(0)


async def logging_middleware(request: GatewayRequest, next_fn: Callable) -> GatewayResponse:
    start = time.monotonic()
    logger.info("[%s] %s %s - started", request.request_id, request.method, request.path)
    try:
        response = await next_fn(request)
        return response
    finally:
        duration_ms = (time.monotonic() - start) * 1000
        logger.info("[%s] %s %s - finished in %.2fms", request.request_id, request.method, request.path, duration_ms)


def make_auth_middleware(required_header: str = "Authorization", allow_missing: bool = False):
    async def auth_middleware(request: GatewayRequest, next_fn: Callable) -> GatewayResponse:
        if not allow_missing and required_header not in request.headers:
            raise GatewayError(401, "Missing authentication header")
        return await next_fn(request)
    return auth_middleware


def make_rate_limit_middleware(max_requests: int, window_seconds: float):
    buckets: Dict[str, List[float]] = {}

    async def rate_limit_middleware(request: GatewayRequest, next_fn: Callable) -> GatewayResponse:
        client_key = request.headers.get("X-Client-Id", "anonymous")
        now = time.monotonic()
        history = buckets.setdefault(client_key, [])
        history[:] = [t for t in history if now - t < window_seconds]
        if len(history) >= max_requests:
            raise GatewayError(429, "Rate limit exceeded")
        history.append(now)
        return await next_fn(request)

    return rate_limit_middleware


