# Gateway core
# ---------------------------------------------------------------------------

class ApiGateway:
    """
    Exposes only REST/HTTP endpoints to external clients. Internally
    dispatches to backends over REST, GraphQL, gRPC, WebSocket, or SOAP,
    translating protocol formats transparently.
    """

    def __init__(self, host: str = "0.0.0.0", port: int = 8080):
        if web is None:
            raise RuntimeError("aiohttp is required to run the gateway server")
        self.host = host
        self.port = port
        self.router = Router()
        self.backends: Dict[str, BackendAdapter] = {}
        self.middleware_chain = MiddlewareChain()
        self._app = web.Application()
        self._runner: Optional["web.AppRunner"] = None
        self._site: Optional["web.TCPSite"] = None

        self.middleware_chain.use(logging_middleware)

        self._app.router.add_route("*", "/{tail:.*}", self._handle_request)

    def register_backend(self, adapter: BackendAdapter) -> None:
        self.backends[adapter.name] = adapter

    def add_route(
        self,
        method: str,
        path_pattern: str,
        backend_name: str,
        route_meta: Optional[Dict[str, Any]] = None,
    ) -> None:
        if backend_name not in self.backends:
            raise ValueError(f"Unknown backend '{backend_name}'")
        self.router.add_route(Route(method, path_pattern, backend_name, route_meta or {}))

    def use_middleware(self, middleware: Middleware) -> None:
        self.middleware_chain.use(middleware)

    async def start(self) -> None:
        for backend in self.backends.values():
            logger.info("Starting backend '%s' (%s)", backend.name, backend.protocol.value)
            await backend.start()

        self._runner = web.AppRunner(self._app)
        await self._runner.setup()
        self._site = web.TCPSite(self._runner, self.host, self.port)
        await self._site.start()
        logger.info("API Gateway listening on http://%s:%s (REST only)", self.host, self.port)

    async def stop(self) -> None:
        if self._site:
            await self._site.stop()
        if self._runner:
            await self._runner.cleanup()
        for backend in self.backends.values():
            logger.info("Stopping backend '%s'", backend.name)
            await backend.stop()

    async def run_forever(self) -> None:
        await self.start()
        try:
            while True:
                await asyncio.sleep(3600)
        except asyncio.CancelledError:
            pass
        finally:
            await self.stop()

    async def _dispatch(self, request: GatewayRequest) -> GatewayResponse:
        resolved = self.router.resolve(request.method, request.path)
        if resolved is None:
            raise GatewayError(404, f"No route found for {request.method} {request.path}")

        route, path_params = resolved
        backend = self.backends[route.backend_name]

        route_meta = dict(route.route_meta)
        route_meta["path_params"] = path_params

        return await backend.call(request, route_meta)

    async def _handle_request(self, request: "web.Request") -> "web.Response":
        try:
            raw_body = await request.read()
            body: Any = None
            if raw_body:
                content_type = request.headers.get("Content-Type", "")
                if "application/json" in content_type:
                    try:
                        body = json.loads(raw_body)
                    except json.JSONDecodeError:
                        body = raw_body.decode("utf-8", errors="replace")
                else:
                    body = raw_body.decode("utf-8", errors="replace")

            gw_request = GatewayRequest(
                method=request.method,
                path=request.path,
                query=dict(request.query),
                headers=dict(request.headers),
                body=body,
            )

            async def handler(req: GatewayRequest) -> GatewayResponse:
                return await self._dispatch(req)

            gw_response = await self.middleware_chain.run(gw_request, handler)

        except GatewayError as err:
            gw_response = err.to_response()
        except Exception as exc:
            logger.exception("Unhandled error processing request")
            gw_response = GatewayResponse(status=500, body={"error": "Internal gateway error", "details": str(exc)})

        return web.json_response(
            data=gw_response.body,
            status=gw_response.status,
            headers=gw_response.headers,
        )


