            raise ValueError("Unknown station")
        entry = {"pollutant": pollutant, "value": value, "unit": unit, "time": _now()}
        self.readings[sid].append(entry)
        if self._is_hazardous(pollutant, value):
            alert = {"station": sid, "pollutant": pollutant, "value": value, "time": _now()}
            self.alerts.append(alert)
        return entry

    def _is_hazardous(self, pollutant, value):
        thresholds = {
            "PM2.5": 35,
            "PM10": 150,
            "CO": 9,
            "NO2": 100,
            "O3": 70,
        }
        limit = thresholds.get(pollutant)
        return limit is not None and value > limit

    def get_station_history(self, sid):
        return self.readings.get(sid, [])

    def get_active_alerts(self):
        return list(self.alerts)

    def average_reading(self, pollutant):
        values = [
            e["value"] for entries in self.readings.values()
            for e in entries if e["pollutant"] == pollutant
        ]
        return sum(values) / len(values) if values else None


