        adjustments = {}
        for iid, data in self.intersections.items():
            recent = [s for s in self.sensors.values() if s["intersection"] == iid and s["reading"]]
            if not recent:
                continue
            avg = sum(r["reading"].get("vehicle_count", 0) for r in recent) / len(recent)
            if avg > 70:
                data["cycle_time"] = min(120, data["cycle_time"] + 10)
                adjustments[iid] = data["cycle_time"]
            elif avg < 20:
                data["cycle_time"] = max(30, data["cycle_time"] - 10)
