    def add_bin(self, location, capacity_liters):
        bid = str(uuid.uuid4())
        self.bins[bid] = {
            "location": location,
            "capacity_liters": capacity_liters,
            "fill_liters": 0.0,
            "status": Status.OK,
        }
        return bid

    def update_fill_level(self, bid, fill_liters):
        if bid not in self.bins:
            raise ValueError("Unknown bin")
        b = self.bins[bid]
        b["fill_liters"] = fill_liters
        ratio = fill_liters / b["capacity_liters"] if b["capacity_liters"] else 0
        if ratio >= 0.9:
            b["status"] = Status.CRITICAL
        elif ratio >= 0.7:
            b["status"] = Status.WARNING
        else:
            b["status"] = Status.OK

    def create_route(self, name, bin_ids):
        rid = str(uuid.uuid4())
        self.routes[rid] = {"name": name, "bins": list(bin_ids), "active": True}
        return rid

    def collect_route(self, rid):
        if rid not in self.routes:
            raise ValueError("Unknown route")
        collected = []
        for bid in self.routes[rid]["bins"]:
            if bid in self.bins:
                self.bins[bid]["fill_liters"] = 0.0
                self.bins[bid]["status"] = Status.OK
                collected.append(bid)
        self.collections_log.append({"route": rid, "time": _now(), "bins": collected})
        return collected

    def get_bins_needing_collection(self, threshold=0.7):
        result = []
        for bid, data in self.bins.items():
            ratio = data["fill_liters"] / data["capacity_liters"] if data["capacity_liters"] else 0
            if ratio >= threshold:
                result.append(bid)
        return result

    def optimize_routes(self):
        needing = self.get_bins_needing_collection()
        suggested = {}
        for rid, route in self.routes.items():
            overlap = [b for b in route["bins"] if b in needing]
            if overlap:
                suggested[rid] = overlap
        return suggested


class EmergencyServices:
    def __init__(self):
        self.units = {}
        self.calls = {}

    def register_unit(self, unit_type, location):
        uid = str(uuid.uuid4())
        self.units[uid] = {
            "type": unit_type,
            "location": location,
            "status": "available",
            "assigned_call": None,
        }
        return uid

    def dispatch_call(self, description, location, priority=Priority.HIGH, unit_type=None):
        call_id = str(uuid.uuid4())
        candidates = [
            uid for uid, u in self.units.items()
            if u["status"] == "available" and (unit_type is None or u["type"] == unit_type)
        ]
        assigned = candidates[0] if candidates else None
        self.calls[call_id] = {
            "description": description,
            "location": location,
            "priority": priority,
            "time": _now(),
            "assigned_unit": assigned,
            "resolved": False,
        }
        if assigned:
            self.units[assigned]["status"] = "dispatched"
            self.units[assigned]["assigned_call"] = call_id
        return call_id, assigned

    def resolve_call(self, call_id):
        if call_id not in self.calls:
            raise ValueError("Unknown call")
        self.calls[call_id]["resolved"] = True
        unit_id = self.calls[call_id]["assigned_unit"]
        if unit_id and unit_id in self.units:
            self.units[unit_id]["status"] = "available"
            self.units[unit_id]["assigned_call"] = None

    def get_active_calls(self):
        return {cid: c for cid, c in self.calls.items() if not c["resolved"]}

    def available_units(self, unit_type=None):
        return [
            uid for uid, u in self.units.items()
            if u["status"] == "available" and (unit_type is None or u["type"] == unit_type)
        ]

    def average_response_metrics(self):
        resolved = [c for c in self.calls.values() if c["resolved"]]
        return {"resolved_count": len(resolved), "total_calls": len(self.calls)}


class PublicTransit:
    def __init__(self):
        self.routes = {}
        self.vehicles = {}
        self.stops = {}
        self.ridership_log = []

    def add_stop(self, name, location):
        sid = str(uuid.uuid4())
        self.stops[sid] = {"name": name, "location": location}
        return sid

    def add_route(self, name, stop_ids, mode="bus"):
        rid = str(uuid.uuid4())
        self.routes[rid] = {"name": name, "stops": list(stop_ids), "mode": mode, "active": True}
        return rid

    def add_vehicle(self, route_id, capacity):
        if route_id not in self.routes:
            raise ValueError("Unknown route")
        vid = str(uuid.uuid4())
        self.vehicles[vid] = {
            "route": route_id,
            "capacity": capacity,
            "occupancy": 0,
            "location": None,
            "status": Status.OK,
            "delay_minutes": 0,
        }
        return vid

    def update_vehicle_position(self, vid, location, delay_minutes=0):
        if vid not in self.vehicles:
            raise ValueError("Unknown vehicle")
        self.vehicles[vid]["location"] = location
        self.vehicles[vid]["delay_minutes"] = delay_minutes
        self.vehicles[vid]["status"] = Status.WARNING if delay_minutes > 10 else Status.OK

    def board_passengers(self, vid, count):
        if vid not in self.vehicles:
            raise ValueError("Unknown vehicle")
        v = self.vehicles[vid]
        v["occupancy"] = min(v["capacity"], v["occupancy"] + count)
        self.ridership_log.append({"vehicle": vid, "time": _now(), "boarded": count})

    def alight_passengers(self, vid, count):
        if vid not in self.vehicles:
            raise ValueError("Unknown vehicle")
        v = self.vehicles[vid]
        v["occupancy"] = max(0, v["occupancy"] - count)

    def get_delayed_vehicles(self, threshold=10):
        return [vid for vid, v in self.vehicles.items() if v["delay_minutes"] > threshold]

    def route_utilization(self, route_id):
        vehicles = [v for v in self.vehicles.values() if v["route"] == route_id]
        if not vehicles:
            return 0.0
        total_cap = sum(v["capacity"] for v in vehicles)
        total_occ = sum(v["occupancy"] for v in vehicles)
        return total_occ / total_cap if total_cap else 0.0


