    def generate_city_health_report(self):
        p = self.platform
        report = {
            "time": _now(),
            "traffic": {
                "active_incidents": len([i for i in p.traffic.incidents.values() if not i["resolved"]]),
                "congestion_events": len(p.traffic.congestion_log),
            },
            "energy": {
                "utilization": p.energy.grid_utilization(),
                "active_outages": len([o for o in p.energy.outages.values() if not o["resolved"]]),
            },
            "water": {
                "total_reserve_liters": p.water.total_reserve(),
                "active_leaks": len([l for l in p.water.leak_reports.values() if not l["resolved"]]),
            },
            "waste": {
                "bins_needing_collection": len(p.waste.get_bins_needing_collection()),
            },
