                "open_requests": len(p.citizen.get_open_requests()),
            },
            "environment": {
                "active_alerts": len(p.environment.get_active_alerts()),
            },
        }
        self.reports.append(report)
        return report

    def compute_sustainability_index(self):
        p = self.platform
        renewable = p.energy.renewable_mix()
        renewable_score = sum(v for k, v in renewable.items() if k in ("solar", "wind", "hydro"))
        env_alerts = len(p.environment.get_active_alerts())
        env_score = max(0.0, 1.0 - env_alerts * 0.05)
        water_ratio = 0.0
        if p.water.reservoirs:
            ratios = [
                r["level_liters"] / r["capacity_liters"]
                for r in p.water.reservoirs.values() if r["capacity_liters"]
            ]
            water_ratio = sum(ratios) / len(ratios) if ratios else 0.0
        index = (renewable_score * 0.4) + (env_score * 0.4) + (water_ratio * 0.2)
        return round(index, 4)

    def infrastructure_stress_report(self):
        p = self.platform
        stressed_substations = [
            sid for sid, s in p.energy.substations.items()
            if s["status"] in (Status.WARNING, Status.CRITICAL)
        ]
        stressed_reservoirs = [
            rid for rid, r in p.water.reservoirs.items()
            if r["status"] in (Status.WARNING, Status.CRITICAL)
        ]
        stressed_intersections = [
            iid for iid, i in p.traffic.intersections.items()
            if i["status"] in (Status.WARNING, Status.CRITICAL)
        ]
        return {
            "substations": stressed_substations,
            "reservoirs": stressed_reservoirs,
            "intersections": stressed_intersections,
        }

