def _now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _hash_obj(obj: Any) -> str:
    """Produce a stable hash for arbitrary (mostly array-like/dict) objects."""
    hasher = hashlib.sha256()

    def _update(o: Any):
        if isinstance(o, np.ndarray):
            hasher.update(o.tobytes())
            hasher.update(str(o.shape).encode())
            hasher.update(str(o.dtype).encode())
        elif isinstance(o, (pd.DataFrame, pd.Series)):
            hasher.update(pd.util.hash_pandas_object(o).values.tobytes())
        elif isinstance(o, dict):
            for k in sorted(o.keys(), key=str):
                hasher.update(str(k).encode())
                _update(o[k])
        elif isinstance(o, (list, tuple)):
            for item in o:
                _update(item)
        elif isinstance(o, (int, float, bool, str)) or o is None:
            hasher.update(str(o).encode())
        else:
            try:
                hasher.update(json.dumps(o, sort_keys=True, default=str).encode())
            except TypeError:
                hasher.update(repr(o).encode())

    _update(obj)
    return hasher.hexdigest()


def _get_environment_info() -> Dict[str, Any]:
    return {
        "python_version": sys.version,
        "platform": platform.platform(),
        "hostname": socket.gethostname(),
        "user": getpass.getuser(),
        "numpy_version": np.__version__,
        "pandas_version": pd.__version__,
        "scipy_version": scipy.__version__,
        "statsmodels_version": statsmodels.__version__,
        "timestamp": _now_iso(),
    }


