class SeedManager:
    """
    Centralized, reproducible seed control for numpy, python random,
    and scipy-based random number generation.
    """

    def __init__(self, seed: Optional[int] = None):
        self.seed = seed if seed is not None else int.from_bytes(os.urandom(4), "little")
        self._np_random_state = None
        self._py_random_state = None
        self.rng = np.random.default_rng(self.seed)

    def apply(self) -> "SeedManager":
        random.seed(self.seed)
        np.random.seed(self.seed)
        self.rng = np.random.default_rng(self.seed)
        return self

    def get_generator(self) -> np.random.Generator:
        return self.rng

    def spawn_child(self, n: int = 1) -> List["SeedManager"]:
        """Spawn deterministic child seed managers for parallel sub-experiments."""
        children_seeds = self.rng.integers(0, 2**32 - 1, size=n)
        return [SeedManager(int(s)) for s in children_seeds]

    @contextlib.contextmanager
    def scoped(self):
        """Temporarily apply this seed, restoring prior global RNG state after."""
        np_state = np.random.get_state()
        py_state = random.getstate()
        try:
            self.apply()
            yield self
        finally:
            np.random.set_state(np_state)
            random.setstate(py_state)

    def to_dict(self) -> Dict[str, Any]:
        return {"seed": self.seed}


