@pd.api.extensions.register_dataframe_accessor("sci")
class ScientificAccessor:
    """
    Attach scientific metadata (units, provenance, citations) to a DataFrame.

    Usage:
        df.sci.set_provenance(origin="lab_experiment_1")
        df.sci.set_variable_meta("temperature", unit="K", description="Core temp")
        df.sci.provenance
        df.sci.variable_meta("temperature")
    """

    def __init__(self, pandas_obj: pd.DataFrame):
        self._validate(pandas_obj)
        self._obj = pandas_obj
        if not hasattr(pandas_obj, "_sci_provenance"):
            pandas_obj._sci_provenance = DatasetProvenance()
        if not hasattr(pandas_obj, "_sci_variable_meta"):
            pandas_obj._sci_variable_meta = {}

    @staticmethod
    def _validate(obj):
        if not isinstance(obj, pd.DataFrame):
            raise TypeError("sci accessor only supports DataFrame objects")

    @property
    def provenance(self) -> DatasetProvenance:
        return self._obj._sci_provenance

    def set_provenance(self, origin: str = None, notes: str = None):
        prov = self._obj._sci_provenance
        if origin is not None:
            prov.origin = origin
        if notes is not None:
            prov.notes = notes
        checksum = hashlib.sha256(
            pd.util.hash_pandas_object(self._obj).values.tobytes()
        ).hexdigest()
        prov.checksum = checksum
        return prov

    def log_transform(self, description: str):
        self._obj._sci_provenance.log_transform(description)

    def set_variable_meta(self, column: str, **kwargs):
        if column not in self._obj.columns:
            warnings.warn(f"Column '{column}' not found in DataFrame.")
        meta = VariableMetadata(name=column, **kwargs)
        self._obj._sci_variable_meta[column] = meta
        return meta

    def variable_meta(self, column: str) -> Optional[VariableMetadata]:
        return self._obj._sci_variable_meta.get(column)

    def all_variable_meta(self) -> Dict[str, VariableMetadata]:
        return dict(self._obj._sci_variable_meta)

    def to_metadata_dict(self) -> Dict[str, Any]:
        return {
            "provenance": asdict(self._obj._sci_provenance),
            "variables": {
                k: asdict(v) for k, v in self._obj._sci_variable_meta.items()
            },
        }

    def validate_ranges(self) -> Dict[str, List[int]]:
        """Return indices where values fall outside declared valid_range."""
        violations = {}
        for col, meta in self._obj._sci_variable_meta.items():
            if meta.valid_range is None or col not in self._obj.columns:
                continue
            lo, hi = meta.valid_range
            mask = (self._obj[col] < lo) | (self._obj[col] > hi)
            bad_idx = list(self._obj.index[mask])
            if bad_idx:
                violations[col] = bad_idx
        return violations


