class Run:
    """Represents a single tracked experiment run."""

    def __init__(self, name: str, tracker: "ExperimentTracker", seed: Optional[int] = None):
        self.run_id = str(uuid.uuid4())
        self.name = name
        self.tracker = tracker
        self.seed_manager = SeedManager(seed)
        self.params: Dict[str, Any] = {}
        self.metrics: Dict[str, Any] = {}
        self.artifacts: Dict[str, Any] = {}
        self.tags: List[str] = []
        self.start_time = None
        self.end_time = None
        self.status = "created"
        self.environment = _get_environment_info()
        self.log_events: List[Dict[str, Any]] = []
        self.data_hashes: Dict[str, str] = {}

    def log_param(self, key: str, value: Any):
        self.params[key] = value
        return self

    def log_params(self, params: Dict[str, Any]):
        self.params.update(params)
        return self

    def log_metric(self, key: str, value: Any, step: Optional[int] = None):
        entry = {"value": value, "timestamp": _now_iso()}
        if step is not None:
            entry["step"] = step
        self.metrics.setdefault(key, []).append(entry)
        return self

    def log_artifact(self, key: str, value: Any):
        self.artifacts[key] = value
        return self

    def log_data(self, key: str, data: Any):
        self.data_hashes[key] = _hash_obj(data)
        return self

    def add_tag(self, tag: str):
        self.tags.append(tag)
        return self

    def log_event(self, message: str, level: str = "INFO"):
        self.log_events.append(
            {"timestamp": _now_iso(), "level": level, "message": message}
        )
        return self

    def __enter__(self):
        self.start_time = _now_iso()
        self.status = "running"
        self.seed_manager.apply()
        self.log_event(f"Run '{self.name}' started with seed={self.seed_manager.seed}")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.end_time = _now_iso()
        if exc_type is not None:
            self.status = "failed"
            self.log_event(f"Run failed: {exc_val}", level="ERROR")
        else:
            self.status = "completed"
            self.log_event("Run completed successfully")
        self.tracker._register(self)
        return False  # don't suppress exceptions

    def to_dict(self) -> Dict[str, Any]:
        flat_metrics = {}
        for k, entries in self.metrics.items():
            flat_metrics[k] = [e["value"] for e in entries]
        return {
            "run_id": self.run_id,
            "name": self.name,
            "status": self.status,
            "start_time": self.start_time,
            "end_time": self.end_time,
            "seed": self.seed_manager.to_dict(),
            "params": self.params,
            "metrics": self.metrics,
            "metrics_summary": flat_metrics,
            "artifacts": {k: repr(v) for k, v in self.artifacts.items()},
            "data_hashes": self.data_hashes,
            "tags": self.tags,
            "environment": self.environment,
            "log_events": self.log_events,
        }

    def to_markdown(self) -> str:
        lines = [
            f"# Run: {self.name} ({self.run_id})",
            f"- Status: {self.status}",
            f"- Start: {self.start_time}",
            f"- End: {self.end_time}",
            f"- Seed: {self.seed_manager.seed}",
            "",
            "## Parameters",
        ]
        for k, v in self.params.items():
            lines.append(f"- **{k}**: {v}")
        lines.append("\n## Metrics")
        for k, entries in self.metrics.items():
            vals = [str(e["value"]) for e in entries]
            lines.append(f"- **{k}**: {', '.join(vals)}")
        lines.append("\n## Tags")
        lines.append(", ".join(self.tags) if self.tags else "none")
        lines.append("\n## Environment")
        for k, v in self.environment.items():
            lines.append(f"- {k}: {v}")
        lines.append("\n## Log")
        for ev in self.log_events:
            lines.append(f"- [{ev['timestamp']}] {ev['level']}: {ev['message']}")
        return "\n".join(lines)


class ExperimentTracker:
    """
    Lightweight local experiment tracker. Stores runs in-memory and can
    persist them to disk as JSON / Markdown reports.
    """

    def __init__(self, project: str = "default", storage_dir: Union[str, Path] = "./runs"):
        self.project = project
        self.storage_dir = Path(storage_dir)
        self.storage_dir.mkdir(parents=True, exist_ok=True)
        self.runs: Dict[str, Run] = {}

    def start_run(self, name: str, seed: Optional[int] = None) -> Run:
        run = Run(name=name, tracker=self, seed=seed)
        return run

    def _register(self, run: Run):
        self.runs[run.run_id] = run
        self._persist(run)

    def _persist(self, run: Run):
        run_dir = self.storage_dir / self.project
        run_dir.mkdir(parents=True, exist_ok=True)
        json_path = run_dir / f"{run.run_id}.json"
        md_path = run_dir / f"{run.run_id}.md"
        with open(json_path, "w") as f:
            json.dump(run.to_dict(), f, indent=2, default=str)
        with open(md_path, "w") as f:
            f.write(run.to_markdown())

    def get_run(self, run_id: str) -> Optional[Run]:
        return self.runs.get(run_id)

    def list_runs(self) -> pd.DataFrame:
        records = []
        for run in self.runs.values():
            rec = {
                "run_id": run.run_id,
                "name": run.name,
                "status": run.status,
                "start_time": run.start_time,
                "end_time": run.end_time,
                "seed": run.seed_manager.seed,
            }
            rec.update({f"param.{k}": v for k, v in run.params.items()})
            self._flatten_metrics(run, rec)
            records.append(rec)
        return pd.DataFrame.from_records(records)

    @staticmethod
    def _flatten_metrics(run: Run, rec: Dict[str, Any]):
        for k, entries in run.metrics.items():
            if entries:
                rec[f"metric.{k}"] = entries[-1]["value"]

    def compare_runs(self, run_ids: List[str], metrics: Optional[List[str]] = None) -> pd.DataFrame:
        df = self.list_runs()
        df = df[df["run_id"].isin(run_ids)]
        if metrics:
            cols = ["run_id", "name"] + [f"metric.{m}" for m in metrics if f"metric.{m}" in df.columns]
            df = df[cols]
        return df.reset_index(drop=True)


# ---------------------------------------------------------------------------
# Reproducible caching decorator
# ---------------------------------------------------------------------------

class ReproCache:
    """Content-hash based cache for expensive deterministic computations."""

    def __init__(self, cache_dir: Union[str, Path] = "./.repro_cache"):
        self.cache_dir = Path(cache_dir)
        self.cache_dir.mkdir(parents=True, exist_ok=True)

    def _key(self, func: Callable, args, kwargs) -> str:
        sig_repr = {
            "func": func.__module__ + "." + func.__qualname__,
            "args": [self._safe_repr(a) for a in args],
            "kwargs": {k: self._safe_repr(v) for k, v in kwargs.items()},
        }
        return _hash_obj(sig_repr)

    @staticmethod
    def _safe_repr(obj):
        if isinstance(obj, (np.ndarray, pd.DataFrame, pd.Series)):
            return _hash_obj(obj)
        return obj

    def cached(self, func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = self._key(func, args, kwargs)
            path = self.cache_dir / f"{key}.json"
            if path.exists():
                with open(path, "r") as f:
                    payload = json.load(f)
                    return payload["result"]
            result = func(*args, **kwargs)
            try:
                with open(path, "w") as f:
                    json.dump({"result": result, "timestamp": _now_iso()}, f, default=str)
            except TypeError:
                warnings.warn(f"Result of {func.__name__} not JSON-serializable; caching skipped.")
            return result

        return wrapper


