# Reproducible statistical wrappers
# ---------------------------------------------------------------------------

@dataclass
class StatTestResult:
    test_name: str
    statistic: float
    p_value: float
    parameters: Dict[str, Any]
    inputs_hash: str
    timestamp: str = field(default_factory=_now_iso)
    environment: Dict[str, Any] = field(default_factory=_get_environment_info)
    interpretation: Optional[str] = None

    def to_dict(self):
        return asdict(self)


class ReproducibleStats:
    """
    Wraps scipy.stats hypothesis tests with automatic logging of
    inputs, environment, and provenance for reproducibility.
    """

    def __init__(self, tracker: Optional[ExperimentTracker] = None):
        self.tracker = tracker
        self.history: List[StatTestResult] = []

    def _record(self, test_name, statistic, p_value, params, inputs, run: Optional[Run] = None):
        result = StatTestResult(
            test_name=test_name,
            statistic=float(statistic),
            p_value=float(p_value),
            parameters=params,
            inputs_hash=_hash_obj(inputs),
        )
        if p_value < 0.001:
            result.interpretation = "highly significant"
        elif p_value < 0.05:
            result.interpretation = "significant"
        else:
            result.interpretation = "not significant"
        self.history.append(result)
        if run is not None:
            run.log_metric(f"{test_name}_statistic", result.statistic)
            run.log_metric(f"{test_name}_pvalue", result.p_value)
            run.log_data(f"{test_name}_inputs", inputs)
        return result

    def ttest_ind(self, a, b, run: Optional[Run] = None, **kwargs) -> StatTestResult:
        stat, p = stats.ttest_ind(a, b, **kwargs)
        return self._record("ttest_ind", stat, p, kwargs, {"a": a, "b": b}, run)

    def ttest_rel(self, a, b, run: Optional[Run] = None, **kwargs) -> StatTestResult:
        stat, p = stats.ttest_rel(a, b, **kwargs)
        return self._record("ttest_rel", stat, p, kwargs, {"a": a, "b": b}, run)

    def mannwhitneyu(self, a, b, run: Optional[Run] = None, **kwargs) -> StatTestResult:
        stat, p = stats.mannwhitneyu(a, b, **kwargs)
        return self._record("mannwhitneyu", stat, p, kwargs, {"a": a, "b": b}, run)

    def pearsonr(self, a, b, run: Optional[Run] = None) -> StatTestResult:
        stat, p = stats.pearsonr(a, b)
        return self._record("pearsonr", stat, p, {}, {"a": a, "b": b}, run)

    def shapiro(self, a, run: Optional[Run] = None) -> StatTestResult:
        stat, p = stats.shapiro(a)
        return self._record("shapiro", stat, p, {}, {"a": a}, run)

    def anova_oneway(self, *samples, run: Optional[Run] = None) -> StatTestResult:
        stat, p = stats.f_oneway(*samples)
        return self._record(
            "f_oneway", stat, p, {}, {"samples": list(samples)}, run
        )

    def get_history_df(self) -> pd.DataFrame:
        return pd.DataFrame([r.to_dict() for r in self.history])


class ReproducibleModel:
    """
    Wraps statsmodels model fitting with automatic metadata capture:
    formula, data hash, fit params, and summary snapshotting.
    """

    def __init__(self, model_class: Callable, tracker: Optional[ExperimentTracker] = None):
        self.model_class = model_class
        self.tracker = tracker
        self.fitted_models: List[Dict[str, Any]] = []

    def fit(
        self,
        formula: Optional[str] = None,
        data: Optional[pd.DataFrame] = None,
        run: Optional[Run] = None,
        fit_kwargs: Optional[Dict[str, Any]] = None,
        model_kwargs: Optional[Dict[str, Any]] = None,
        endog=None,
        exog=None,
    ):
        fit_kwargs = fit_kwargs or {}
        model_kwargs = model_kwargs or {}

        if formula is not None:
            if data is None:
                raise ValueError("`data` must be provided when using `formula`.")
            model = self.model_class.from_formula(formula, data=data, **model_kwargs)
            data_hash = _hash_obj(data)
        else:
            if endog is None or exog is None:
                raise ValueError("Either `formula`+`data` or `endog`+`exog` required.")
            model = self.model_class(endog, exog, **model_kwargs)
            data_hash = _hash_obj({"endog": endog, "exog": exog})

        fitted = model.fit(**fit_kwargs)

        record = {
            "model_class": self.model_class.__name__,
            "formula": formula,
            "data_hash": data_hash,
            "fit_kwargs": fit_kwargs,
            "model_kwargs": model_kwargs,
            "params": fitted.params.to_dict() if hasattr(fitted.params, "to_dict") else list(fitted.params),
            "aic": getattr(fitted, "aic", None),
            "bic": getattr(fitted, "bic", None),
            "rsquared": getattr(fitted, "rsquared", None),
            "timestamp": _now_iso(),
            "environment": _get_environment_info(),
        }
        self.fitted_models.append(record)

        if run is not None:
            run.log_param("model_class", record["model_class"])
            if formula:
                run.log_param("formula", formula)
            for k, v in record["params"].items() if isinstance(record["params"], dict) else enumerate(record["params"]):
                run.log_metric(f"coef_{k}", v)
            if record["aic"] is not None:
                run.log_metric("aic", record["aic"])
            if record["bic"] is not None:
                run.log_metric("bic", record["bic"])
            if record["rsquared"] is not None:
                run.log_metric("rsquared", record["rsquared"])
            run.log_data("model_fit_data", data if data is not None else {"endog": endog, "exog": exog})
            run.log_artifact("model_summary", fitted.summary().as_text())

        return fitted, record

    def get_history_df(self) -> pd.DataFrame:
        return pd.DataFrame(self.fitted_models)


