@contextlib.contextmanager
def reproducible_context(seed: int = 42, strict: bool = True):
    """
    Context manager that enforces deterministic behavior across
    numpy/random for the duration of the block, and warns if
    non-deterministic operations may be at play.
    """
    seed_mgr = SeedManager(seed)
    np_state = np.random.get_state()
    py_state = random.getstate()
    env_before = _get_environment_info()
    try:
        seed_mgr.apply()
        if strict:
            os.environ["PYTHONHASHSEED"] = str(seed)
        yield seed_mgr
    finally:
