"""
Research Data Platform
=======================

A pluggable research platform for handling heterogeneous scientific data types.

Design overview
----------------
Adding a new data type is done by implementing one class that satisfies the
`DataTypePlugin` protocol and registering it with the global `PluginRegistry`.
That single plugin encapsulates the type-specific behavior for all subsystems:

    - DataModel            (via `create_model` / `DataRecord`)
    - ValidationRules       (via `validate`)
    - StorageAdapter        (via `serialize` / `deserialize`)
    - ProcessingPipeline    (via `process`)
    - VisualizationEngine   (via `visualize`)
    - ExportFormats         (via `export`)
    - MetadataSchema        (via `metadata_schema`)
    - SearchIndexer         (via `index_terms`)
    - ComplianceChecker     (via `check_compliance`)

Each subsystem is a thin dispatcher that looks up the appropriate plugin from
the registry and delegates to it. This means supporting a brand-new data type
requires writing exactly one new plugin class (and registering it) -- no
existing subsystem code needs to change.
"""

from __future__ import annotations

import abc
import json
import statistics
import time
import uuid
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Protocol, runtime_checkable


# ---------------------------------------------------------------------------
# Core data model
# ---------------------------------------------------------------------------

@dataclass
class DataRecord:
    """Generic container for a piece of research data of any type."""

    record_id: str
    data_type: str
    payload: Any
    metadata: Dict[str, Any] = field(default_factory=dict)
    created_at: float = field(default_factory=time.time)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "record_id": self.record_id,
            "data_type": self.data_type,
            "payload": self.payload,
            "metadata": self.metadata,
            "created_at": self.created_at,
        }


class ValidationError(Exception):
    """Raised when a record fails validation."""


class ComplianceViolation(Exception):
    """Raised when a record fails compliance checks."""


# ---------------------------------------------------------------------------
# Plugin protocol
# ---------------------------------------------------------------------------

@runtime_checkable
class DataTypePlugin(Protocol):
    """
    Protocol that a data-type plugin must satisfy.

    Implementing a class that fulfills this protocol and registering it is
    the *only* step required to support a new data type across the entire
    platform.
    """

    type_name: str

    def create_model(self, raw_payload: Any, metadata: Optional[Dict[str, Any]] = None) -> DataRecord:
        ...

    def validate(self, record: DataRecord) -> None:
        ...

    def serialize(self, record: DataRecord) -> bytes:
        ...

    def deserialize(self, blob: bytes) -> DataRecord:
        ...

    def process(self, record: DataRecord) -> DataRecord:
        ...

    def visualize(self, record: DataRecord) -> str:
        ...

    def export(self, record: DataRecord, fmt: str) -> str:
        ...

    def metadata_schema(self) -> Dict[str, str]:
        ...

    def index_terms(self, record: DataRecord) -> List[str]:
        ...

    def check_compliance(self, record: DataRecord) -> List[str]:
        ...


class BaseDataTypePlugin(abc.ABC):
    """
    Convenience base class implementing common boilerplate for plugins.
    Subclass this to add a new data type.
    """

    type_name: str = "base"

    # ---- DataModel ----
    def create_model(self, raw_payload: Any, metadata: Optional[Dict[str, Any]] = None) -> DataRecord:
        return DataRecord(
            record_id=str(uuid.uuid4()),
            data_type=self.type_name,
            payload=raw_payload,
            metadata=metadata or {},
        )

    # ---- ValidationRules ----
    @abc.abstractmethod
    def validate(self, record: DataRecord) -> None:
        ...

    # ---- StorageAdapter ----
    def serialize(self, record: DataRecord) -> bytes:
        return json.dumps(record.to_dict()).encode("utf-8")

    def deserialize(self, blob: bytes) -> DataRecord:
        data = json.loads(blob.decode("utf-8"))
        return DataRecord(
            record_id=data["record_id"],
            data_type=data["data_type"],
            payload=data["payload"],
            metadata=data["metadata"],
            created_at=data["created_at"],
        )

    # ---- ProcessingPipeline ----
    @abc.abstractmethod
    def process(self, record: DataRecord) -> DataRecord:
        ...

    # ---- VisualizationEngine ----
    @abc.abstractmethod
    def visualize(self, record: DataRecord) -> str:
        ...

    # ---- ExportFormats ----
    def export(self, record: DataRecord, fmt: str) -> str:
        fmt = fmt.lower()
        if fmt == "json":
            return json.dumps(record.to_dict(), indent=2, default=str)
        if fmt == "csv":
            return self._export_csv(record)
        if fmt == "txt":
            return str(record.payload)
        raise ValueError(f"Unsupported export format '{fmt}' for type '{self.type_name}'")

    def _export_csv(self, record: DataRecord) -> str:
        # Default fallback CSV representation; plugins can override.
        return f"record_id,data_type\n{record.record_id},{record.data_type}"

    # ---- MetadataSchema ----
    @abc.abstractmethod
    def metadata_schema(self) -> Dict[str, str]:
        ...

    # ---- SearchIndexer ----
    @abc.abstractmethod
    def index_terms(self, record: DataRecord) -> List[str]:
        ...

    # ---- ComplianceChecker ----
    @abc.abstractmethod
    def check_compliance(self, record: DataRecord) -> List[str]:
        ...


# ---------------------------------------------------------------------------
# Plugin registry
# ---------------------------------------------------------------------------

class PluginRegistry:
    """Global registry mapping data-type names to plugin instances."""

    def __init__(self) -> None:
        self._plugins: Dict[str, DataTypePlugin] = {}

    def register(self, plugin: DataTypePlugin) -> None:
        if not hasattr(plugin, "type_name"):
            raise TypeError("Plugin must define a 'type_name' attribute")
        self._plugins[plugin.type_name] = plugin

    def get(self, type_name: str) -> DataTypePlugin:
        try:
            return self._plugins[type_name]
        except KeyError:
            raise KeyError(f"No plugin registered for data type '{type_name}'")

    def all_types(self) -> List[str]:
        return list(self._plugins.keys())


REGISTRY = PluginRegistry()


def register_plugin(plugin_cls):
    """Class decorator to instantiate and auto-register a plugin."""
    instance = plugin_cls()
    REGISTRY.register(instance)
    return plugin_cls


# ---------------------------------------------------------------------------
# Subsystem dispatchers
# ---------------------------------------------------------------------------

class DataModel:
    """Facade for creating records of any registered data type."""

    def __init__(self, registry: PluginRegistry = REGISTRY):
        self.registry = registry

    def create(self, data_type: str, raw_payload: Any, metadata: Optional[Dict[str, Any]] = None) -> DataRecord:
        plugin = self.registry.get(data_type)
        return plugin.create_model(raw_payload, metadata)


class ValidationRules:
    """Facade dispatching validation to the appropriate plugin."""

    def __init__(self, registry: PluginRegistry = REGISTRY):
        self.registry = registry

    def validate(self, record: DataRecord) -> None:
        plugin = self.registry.get(record.data_type)
        plugin.validate(record)


class StorageAdapter:
    """Facade dispatching (de)serialization to the appropriate plugin."""

    def __init__(self, registry: PluginRegistry = REGISTRY):
        self.registry = registry
        self._store: Dict[str, bytes] = {}
        self._types: Dict[str, str] = {}

    def save(self, record: DataRecord) -> None:
        plugin = self.registry.get(record.data_type)
        blob = plugin.serialize(record)
        self._store[record.record_id] = blob
        self._types[record.record_id] = record.data_type

    def load(self, record_id: str) -> DataRecord:
        data_type = self._types[record_id]
        plugin = self.registry.get(data_type)
        return plugin.deserialize(self._store[record_id])

    def delete(self, record_id: str) -> None:
        self._store.pop(record_id, None)
        self._types.pop(record_id, None)

    def all_ids(self) -> List[str]:
        return list(self._store.keys())


class ProcessingPipeline:
    """Facade dispatching processing to the appropriate plugin."""

    def __init__(self, registry: PluginRegistry = REGISTRY):
        self.registry = registry

    def run(self, record: DataRecord) -> DataRecord:
        plugin = self.registry.get(record.data_type)
        return plugin.process(record)


class VisualizationEngine:
    """Facade dispatching visualization to the appropriate plugin."""

    def __init__(self, registry: PluginRegistry = REGISTRY):
        self.registry = registry

    def render(self, record: DataRecord) -> str:
        plugin = self.registry.get(record.data_type)
        return plugin.visualize(record)


class ExportFormats:
    """Facade dispatching export to the appropriate plugin."""

    def __init__(self, registry: PluginRegistry = REGISTRY):
        self.registry = registry

    def export(self, record: DataRecord, fmt: str) -> str:
        plugin = self.registry.get(record.data_type)
        return plugin.export(record, fmt)


class MetadataSchema:
    """Facade exposing the metadata schema for a given data type."""

    def __init__(self, registry: PluginRegistry = REGISTRY):
        self.registry = registry

    def schema_for(self, data_type: str) -> Dict[str, str]:
        plugin = self.registry.get(data_type)
        return plugin.metadata_schema()


class SearchIndexer:
    """Facade building/maintaining a simple inverted index across records."""

    def __init__(self, registry: PluginRegistry = REGISTRY):
        self.registry = registry
        self._index: Dict[str, set] = {}

    def index(self, record: DataRecord) -> None:
        plugin = self.registry.get(record.data_type)
        terms = plugin.index_terms(record)
        for term in terms:
            key = term.lower()
            self._index.setdefault(key, set()).add(record.record_id)

    def search(self, term: str) -> List[str]:
        return list(self._index.get(term.lower(), set()))


class ComplianceChecker:
    """Facade dispatching compliance checks to the appropriate plugin."""

    def __init__(self, registry: PluginRegistry = REGISTRY):
        self.registry = registry

    def check(self, record: DataRecord) -> List[str]:
        plugin = self.registry.get(record.data_type)
        return plugin.check_compliance(record)


# ---------------------------------------------------------------------------
# Built-in data type plugins
# ---------------------------------------------------------------------------

@register_plugin
class NumericSeriesPlugin(BaseDataTypePlugin):
    """Data type for numeric time series / sensor readings."""

    type_name = "numeric_series"

    def validate(self, record: DataRecord) -> None:
        payload = record.payload
        if not isinstance(payload, (list, tuple)):
            raise ValidationError("numeric_series payload must be a list of numbers")
        if not payload:
            raise ValidationError("numeric_series payload cannot be empty")
        for v in payload:
            if not isinstance(v, (int, float)):
                raise ValidationError(f"numeric_series values must be numeric, got {type(v)}")

    def process(self, record: DataRecord) -> DataRecord:
        values = record.payload
        stats = {
            "mean": statistics.fmean(values),
            "stdev": statistics.pstdev(values) if len(values) > 1 else 0.0,
            "min": min(values),
            "max": max(values),
            "n": len(values),
        }
        record.metadata["stats"] = stats
        return record

    def visualize(self, record: DataRecord) -> str:
        values = record.payload
        max_val = max(values) if values else 1
        max_val = max_val or 1
        lines = []
        for v in values:
            bar_len = int((v / max_val) * 40) if max_val else 0
            lines.append("#" * max(bar_len, 0) + f" ({v})")
        return "\n".join(lines)

    def _export_csv(self, record: DataRecord) -> str:
        lines = ["index,value"]
        for i, v in enumerate(record.payload):
            lines.append(f"{i},{v}")
        return "\n".join(lines)

    def metadata_schema(self) -> Dict[str, str]:
        return {"units": "string", "source_device": "string", "sampling_rate_hz": "number"}

    def index_terms(self, record: DataRecord) -> List[str]:
        terms = ["numeric_series"]
        units = record.metadata.get("units")
        if units:
            terms.append(str(units))
        return terms

    def check_compliance(self, record: DataRecord) -> List[str]:
        issues = []
        if "units" not in record.metadata:
            issues.append("Missing required metadata field 'units'")
        return issues


@register_plugin
class TextDocumentPlugin(BaseDataTypePlugin):
    """Data type for free-text documents (e.g., notes, transcripts)."""

    type_name = "text_document"

    def validate(self, record: DataRecord) -> None:
        if not isinstance(record.payload, str):
            raise ValidationError("text_document payload must be a string")
        if len(record.payload.strip()) == 0:
            raise ValidationError("text_document payload cannot be empty")

    def process(self, record: DataRecord) -> DataRecord:
        text = record.payload
        word_count = len(text.split())
        record.metadata["word_count"] = word_count
        record.metadata["char_count"] = len(text)
        return record

    def visualize(self, record: DataRecord) -> str:
        preview = record.payload[:200]
        return f"[TextDocument preview]\n{preview}{'...' if len(record.payload) > 200 else ''}"

    def _export_csv(self, record: DataRecord) -> str:
        escaped = record.payload.replace('"', '""')
        return f'record_id,text\n{record.record_id},"{escaped}"'

    def metadata_schema(self) -> Dict[str, str]:
        return {"author": "string", "language": "string", "subject_id": "string"}

    def index_terms(self, record: DataRecord) -> List[str]:
        words = record.payload.lower().split()
        unique_words = sorted(set(w.strip(".,!?;:\"'()") for w in words if w))
        return unique_words

    def check_compliance(self, record: DataRecord) -> List[str]:
        issues = []
        if "subject_id" in record.metadata:
            issues.append("Potential PII: subject_id present in a free-text document record")
        if "author" not in record.metadata:
            issues.append("Missing required metadata field 'author'")
        return issues


@register_plugin
class ImageMetadataPlugin(BaseDataTypePlugin):
    """
    Data type representing image metadata (not raw pixel data), e.g.
    dimensions, checksum, and modality info for imaging experiments.
    """

    type_name = "image_metadata"

    def validate(self, record: DataRecord) -> None:
        payload = record.payload
        if not isinstance(payload, dict):
            raise ValidationError("image_metadata payload must be a dict")
        required = {"width", "height", "checksum"}
        missing = required - payload.keys()
        if missing:
            raise ValidationError(f"image_metadata payload missing keys: {missing}")
        if not isinstance(payload["width"], int) or not isinstance(payload["height"], int):
            raise ValidationError("width/height must be integers")
        if payload["width"] <= 0 or payload["height"] <= 0:
            raise ValidationError("width/height must be positive")

    def process(self, record: DataRecord) -> DataRecord:
        payload = record.payload
