class CreditCardProcessor(PaymentProcessor):
    """Fully functional credit card payment processor (simulated gateway)."""

    method_type = PaymentMethodType.CREDIT_CARD

    def __init__(self, merchant_id: str, decline_rate: float = 0.0):
        self.merchant_id = merchant_id
        self.decline_rate = decline_rate
        self._transactions: Dict[str, _CreditCardTransaction] = {}

    def _generate_transaction_id(self) -> str:
        return f"cc_{uuid.uuid4().hex[:16]}"

    def _simulate_gateway_call(self) -> bool:
        return random.random() >= self.decline_rate

    def authorize(self, amount: Money, details: PaymentDetails) -> PaymentResult:
        if not isinstance(details, CreditCardDetails):
            raise PaymentValidationError("CreditCardProcessor requires CreditCardDetails")

        details.validate()

