                amount=amount,
                method_type=self.method_type,
                message="Card issuer declined the transaction",
                metadata=details.masked(),
            )

        tx_id = self._generate_transaction_id()
        self._transactions[tx_id] = _CreditCardTransaction(
            transaction_id=tx_id,
            amount=amount,
            status=PaymentStatus.AUTHORIZED,
            authorized_amount=amount,
        )

        return PaymentResult(
            success=True,
            transaction_id=tx_id,
            status=PaymentStatus.AUTHORIZED,
            amount=amount,
            method_type=self.method_type,
            message="Payment authorized successfully",
            metadata=details.masked(),
        )

    def capture(self, transaction_id: str, amount: Money) -> PaymentResult:
        tx = self._transactions.get(transaction_id)
        if tx is None:
            raise PaymentProcessingError(f"Unknown transaction: {transaction_id}")
        if tx.status != PaymentStatus.AUTHORIZED:
            raise PaymentProcessingError(
                f"Transaction {transaction_id} cannot be captured from state {tx.status}"
            )
        if amount.amount > tx.authorized_amount.amount:
            raise PaymentProcessingError("Capture amount exceeds authorized amount")

        tx.status = PaymentStatus.CAPTURED
        tx.captured_amount = amount

        return PaymentResult(
            success=True,
            transaction_id=transaction_id,
            status=PaymentStatus.CAPTURED,
            amount=amount,
            method_type=self.method_type,
            message="Payment captured successfully",
        )

    def refund(self, transaction_id: str, amount: Money) -> PaymentResult:
        tx = self._transactions.get(transaction_id)
        if tx is None:
            raise PaymentProcessingError(f"Unknown transaction: {transaction_id}")
        if tx.status != PaymentStatus.CAPTURED:
            raise PaymentProcessingError("Only captured payments can be refunded")

        max_refundable = tx.captured_amount.amount - tx.refunded_amount
        if amount.amount > max_refundable:
            raise PaymentProcessingError("Refund amount exceeds refundable balance")

        tx.refunded_amount += amount.amount
        if tx.refunded_amount >= tx.captured_amount.amount:
            tx.status = PaymentStatus.REFUNDED

        return PaymentResult(
            success=True,
            transaction_id=transaction_id,
            status=tx.status,
            amount=amount,
            method_type=self.method_type,
            message="Refund processed successfully",
        )

    def cancel(self, transaction_id: str) -> PaymentResult:
        tx = self._transactions.get(transaction_id)
        if tx is None:
            raise PaymentProcessingError(f"Unknown transaction: {transaction_id}")
        if tx.status not in (PaymentStatus.PENDING, PaymentStatus.AUTHORIZED):
            raise PaymentProcessingError(
                f"Transaction {transaction_id} cannot be cancelled from state {tx.status}"
            )

        tx.status = PaymentStatus.CANCELLED

        return PaymentResult(
            success=True,
            transaction_id=transaction_id,
            status=PaymentStatus.CANCELLED,
            amount=tx.amount,
            method_type=self.method_type,
            message="Authorization cancelled successfully",
        )


