        PaymentMethodType.CREDIT_CARD: CreditCardProcessorFactory,
        PaymentMethodType.PAYPAL: PayPalProcessorFactory,
        PaymentMethodType.CRYPTOCURRENCY: CryptoProcessorFactory,
        PaymentMethodType.BANK_TRANSFER: BankTransferProcessorFactory,
        PaymentMethodType.BUY_NOW_PAY_LATER: BNPLProcessorFactory,
    }

