abstract interface, but the factory is configured to only register and
serve the credit card processor.
"""

from __future__ import annotations

import abc
import re
import uuid
import random
import string
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from enum import Enum
from typing import Dict, List, Optional, Type


# ---------------------------------------------------------------------------
# Enums and Value Objects
# ---------------------------------------------------------------------------

class PaymentMethodType(Enum):
    CREDIT_CARD = "credit_card"
    PAYPAL = "paypal"
    CRYPTOCURRENCY = "cryptocurrency"
    BANK_TRANSFER = "bank_transfer"
    BUY_NOW_PAY_LATER = "buy_now_pay_later"


class PaymentStatus(Enum):
    PENDING = "pending"
    AUTHORIZED = "authorized"
    CAPTURED = "captured"
    FAILED = "failed"
    REFUNDED = "refunded"
    CANCELLED = "cancelled"


class CardNetwork(Enum):
    VISA = "visa"
    MASTERCARD = "mastercard"
    AMEX = "amex"
    DISCOVER = "discover"
    UNKNOWN = "unknown"


@dataclass
class Money:
    amount: float
    currency: str = "USD"

    def __post_init__(self):
        if self.amount < 0:
            raise ValueError("Amount cannot be negative")
        self.amount = round(self.amount, 2)

    def __str__(self):
        return f"{self.amount:.2f} {self.currency}"


@dataclass
class PaymentResult:
    success: bool
    transaction_id: str
    status: PaymentStatus
    amount: Money
    method_type: PaymentMethodType
    timestamp: datetime = field(default_factory=datetime.utcnow)
    message: str = ""
    metadata: Dict[str, str] = field(default_factory=dict)


class PaymentError(Exception):
    """Base exception for payment processing errors."""


class PaymentValidationError(PaymentError):
    """Raised when payment details fail validation."""


class PaymentProcessingError(PaymentError):
    """Raised when a payment fails during processing/gateway communication."""


class UnsupportedPaymentMethodError(PaymentError):
    """Raised when a requested payment method is not registered/available."""


# ---------------------------------------------------------------------------
# Abstract Interfaces
# ---------------------------------------------------------------------------

class PaymentDetails(abc.ABC):
    """Abstract base for payment method specific details/credentials."""

    @abc.abstractmethod
    def validate(self) -> None:
        """Raise PaymentValidationError if details are invalid."""
        raise NotImplementedError

    @abc.abstractmethod
    def masked(self) -> Dict[str, str]:
        """Return a dict safe for logging (no sensitive raw data)."""
        raise NotImplementedError


class PaymentProcessor(abc.ABC):
    """Abstract interface all payment method processors must implement."""

    method_type: PaymentMethodType

    @abc.abstractmethod
    def authorize(self, amount: Money, details: PaymentDetails) -> PaymentResult:
        raise NotImplementedError

    @abc.abstractmethod
    def capture(self, transaction_id: str, amount: Money) -> PaymentResult:
        raise NotImplementedError

    @abc.abstractmethod
    def refund(self, transaction_id: str, amount: Money) -> PaymentResult:
        raise NotImplementedError

    @abc.abstractmethod
    def cancel(self, transaction_id: str) -> PaymentResult:
        raise NotImplementedError

    def process_payment(self, amount: Money, details: PaymentDetails) -> PaymentResult:
        """Convenience method: authorize + capture in one step."""
        details.validate()
        auth_result = self.authorize(amount, details)
        if not auth_result.success:
            return auth_result
        return self.capture(auth_result.transaction_id, amount)


