@dataclass
class CreditCardDetails(PaymentDetails):
    card_number: str
    cardholder_name: str
    expiry_month: int
    expiry_year: int
    cvv: str
    billing_zip: str = ""

    def validate(self) -> None:
        digits = re.sub(r"\D", "", self.card_number)
        if not (13 <= len(digits) <= 19):
            raise PaymentValidationError("Invalid card number length")
        if not self._luhn_check(digits):
            raise PaymentValidationError("Card number failed Luhn check")
        if not self.cardholder_name or len(self.cardholder_name.strip()) < 2:
            raise PaymentValidationError("Invalid cardholder name")
        if not (1 <= self.expiry_month <= 12):
            raise PaymentValidationError("Invalid expiry month")

        now = datetime.utcnow()
        expiry_date = datetime(self.expiry_year, self.expiry_month, 1) + timedelta(days=31)
        if expiry_date < now:
            raise PaymentValidationError("Card has expired")

        if not re.fullmatch(r"\d{3,4}", self.cvv):
            raise PaymentValidationError("Invalid CVV")

    @staticmethod
    def _luhn_check(card_number: str) -> bool:
        digits = [int(d) for d in card_number]
        odd_digits = digits[-1::-2]
        even_digits = digits[-2::-2]
        checksum = sum(odd_digits)
        for d in even_digits:
            checksum += sum(divmod(d * 2, 10))
        return checksum % 10 == 0

    def network(self) -> CardNetwork:
        digits = re.sub(r"\D", "", self.card_number)
        if digits.startswith("4"):
            return CardNetwork.VISA
        if digits[:2] in {"51", "52", "53", "54", "55"} or (
            len(digits) >= 4 and 2221 <= int(digits[:4]) <= 2720
        ):
            return CardNetwork.MASTERCARD
        if digits[:2] in {"34", "37"}:
            return CardNetwork.AMEX
        if digits.startswith("6011") or digits[:2] == "65":
            return CardNetwork.DISCOVER
        return CardNetwork.UNKNOWN

    def masked(self) -> Dict[str, str]:
        digits = re.sub(r"\D", "", self.card_number)
        masked_number = "*" * (len(digits) - 4) + digits[-4:] if len(digits) >= 4 else "****"
        return {
            "card_number": masked_number,
            "cardholder_name": self.cardholder_name,
            "expiry": f"{self.expiry_month:02d}/{self.expiry_year}",
            "network": self.network().value,
        }


@dataclass
class _CreditCardTransaction:
    transaction_id: str
    amount: Money
    status: PaymentStatus
    authorized_amount: Optional[Money] = None
    captured_amount: Optional[Money] = None
    refunded_amount: float = 0.0


class CreditCardProcessor(PaymentProcessor):
    """Fully functional credit card payment processor (simulated gateway)."""

    method_type = PaymentMethodType.CREDIT_CARD

    def __init__(self, merchant_id: str, decline_rate: float = 0.0):
        self.merchant_id = merchant_id
        self.decline_rate = decline_rate
        self._transactions: Dict[str, _CreditCardTransaction] = {}

    def _generate_transaction_id(self) -> str:
        return f"cc_{uuid.uuid4().hex[:16]}"

    def _simulate_gateway_call(self) -> bool:
        return random.random() >= self.decline_rate

    def authorize(self, amount: Money, details: PaymentDetails) -> PaymentResult:
        if not isinstance(details, CreditCardDetails):
            raise PaymentValidationError("CreditCardProcessor requires CreditCardDetails")

        details.validate()

        if not self._simulate_gateway_call():
            return PaymentResult(
                success=False,
                transaction_id="",
                status=PaymentStatus.FAILED,
                amount=amount,
                method_type=self.method_type,
                message="Card issuer declined the transaction",
                metadata=details.masked(),
            )

        tx_id = self._generate_transaction_id()
        self._transactions[tx_id] = _CreditCardTransaction(
            transaction_id=tx_id,
            amount=amount,
            status=PaymentStatus.AUTHORIZED,
            authorized_amount=amount,
        )

        return PaymentResult(
            success=True,
            transaction_id=tx_id,
            status=PaymentStatus.AUTHORIZED,
            amount=amount,
            method_type=self.method_type,
            message="Payment authorized successfully",
            metadata=details.masked(),
        )

    def capture(self, transaction_id: str, amount: Money) -> PaymentResult:
        tx = self._transactions.get(transaction_id)
        if tx is None:
            raise PaymentProcessingError(f"Unknown transaction: {transaction_id}")
        if tx.status != PaymentStatus.AUTHORIZED:
            raise PaymentProcessingError(
                f"Transaction {transaction_id} cannot be captured from state {tx.status}"
            )
        if amount.amount > tx.authorized_amount.amount:
            raise PaymentProcessingError("Capture amount exceeds authorized amount")

        tx.status = PaymentStatus.CAPTURED
        tx.captured_amount = amount

        return PaymentResult(
            success=True,
            transaction_id=transaction_id,
            status=PaymentStatus.CAPTURED,
            amount=amount,
            method_type=self.method_type,
            message="Payment captured successfully",
        )

    def refund(self, transaction_id: str, amount: Money) -> PaymentResult:
        tx = self._transactions.get(transaction_id)
        if tx is None:
            raise PaymentProcessingError(f"Unknown transaction: {transaction_id}")
        if tx.status != PaymentStatus.CAPTURED:
            raise PaymentProcessingError("Only captured payments can be refunded")

        max_refundable = tx.captured_amount.amount - tx.refunded_amount
        if amount.amount > max_refundable:
            raise PaymentProcessingError("Refund amount exceeds refundable balance")

        tx.refunded_amount += amount.amount
        if tx.refunded_amount >= tx.captured_amount.amount:
            tx.status = PaymentStatus.REFUNDED

        return PaymentResult(
            success=True,
            transaction_id=transaction_id,
            status=tx.status,
            amount=amount,
            method_type=self.method_type,
            message="Refund processed successfully",
        )

    def cancel(self, transaction_id: str) -> PaymentResult:
        tx = self._transactions.get(transaction_id)
        if tx is None:
            raise PaymentProcessingError(f"Unknown transaction: {transaction_id}")
        if tx.status not in (PaymentStatus.PENDING, PaymentStatus.AUTHORIZED):
            raise PaymentProcessingError(
                f"Transaction {transaction_id} cannot be cancelled from state {tx.status}"
            )

        tx.status = PaymentStatus.CANCELLED

        return PaymentResult(
            success=True,
            transaction_id=transaction_id,
            status=PaymentStatus.CANCELLED,
            amount=tx.amount,
            method_type=self.method_type,
            message="Authorization cancelled successfully",
        )


