# ---------------------------------------------------------------------------
# Factory Infrastructure
# ---------------------------------------------------------------------------

class PaymentProcessorFactory(abc.ABC):
    """Abstract factory for creating PaymentProcessor instances."""

    @abc.abstractmethod
    def create_processor(self, config: Dict[str, str]) -> PaymentProcessor:
        raise NotImplementedError

    @property
    @abc.abstractmethod
    def method_type(self) -> PaymentMethodType:
        raise NotImplementedError


class CreditCardProcessorFactory(PaymentProcessorFactory):
    method_type = PaymentMethodType.CREDIT_CARD

    def create_processor(self, config: Dict[str, str]) -> PaymentProcessor:
        merchant_id = config.get("merchant_id")
        if not merchant_id:
            raise PaymentValidationError("merchant_id is required to create CreditCardProcessor")
        decline_rate = float(config.get("decline_rate", 0.0))
        return CreditCardProcessor(merchant_id=merchant_id, decline_rate=decline_rate)


class PayPalProcessorFactory(PaymentProcessorFactory):
    method_type = PaymentMethodType.PAYPAL

    def create_processor(self, config: Dict[str, str]) -> PaymentProcessor:
