        return BNPLProcessor(
            provider_name=config.get("provider_name", ""),
            api_key=config.get("api_key", ""),
        )


class PaymentProcessorRegistry:
    """
    Central registry mapping PaymentMethodType -> PaymentProcessorFactory.

    Only CREDIT_CARD is registered as enabled/available in this deployment.
    Other factories exist and could be registered, but are intentionally
    left out so that only credit card payments are actually processable.
    """

    _all_factories: Dict[PaymentMethodType, Type[PaymentProcessorFactory]] = {
        PaymentMethodType.CREDIT_CARD: CreditCardProcessorFactory,
        PaymentMethodType.PAYPAL: PayPalProcessorFactory,
        PaymentMethodType.CRYPTOCURRENCY: CryptoProcessorFactory,
        PaymentMethodType.BANK_TRANSFER: BankTransferProcessorFactory,
        PaymentMethodType.BUY_NOW_PAY_LATER: BNPLProcessorFactory,
    }

    # Only credit card is enabled for actual use.
    _enabled_methods = {PaymentMethodType.CREDIT_CARD}

    def __init__(self):
        self._factories: Dict[PaymentMethodType, PaymentProcessorFactory] = {}
        for method in self._enabled_methods:
            factory_cls = self._all_factories[method]
            self._factories[method] = factory_cls()

    def is_supported(self, method_type: PaymentMethodType) -> bool:
        return method_type in self._factories

    def get_factory(self, method_type: PaymentMethodType) -> PaymentProcessorFactory:
        factory = self._factories.get(method_type)
        if factory is None:
            raise UnsupportedPaymentMethodError(
                f"Payment method '{method_type.value}' is not currently supported. "
                f"Supported methods: {[m.value for m in self._factories]}"
            )
        return factory

    def create_processor(
        self, method_type: PaymentMethodType, config: Dict[str, str]
    ) -> PaymentProcessor:
        factory = self.get_factory(method_type)
        return factory.create_processor(config)


# ---------------------------------------------------------------------------
# Payment Gateway / Facade
# ---------------------------------------------------------------------------

class PaymentGateway:
    """
    High-level facade for the e-commerce checkout flow.

    Internally uses the PaymentProcessorRegistry (factory pattern), but since
    only credit card processing is registered/enabled, this gateway will only
    successfully process PaymentMethodType.CREDIT_CARD requests.
    """

    def __init__(self, registry: Optional[PaymentProcessorRegistry] = None):
        self.registry = registry or PaymentProcessorRegistry()
        self._processor_cache: Dict[str, PaymentProcessor] = {}

    def _get_or_create_processor(
        self, method_type: PaymentMethodType, config: Dict[str, str]
    ) -> PaymentProcessor:
        cache_key = f"{method_type.value}:{config.get('merchant_id', 'default')}"
        if cache_key not in self._processor_cache:
            self._processor_cache[cache_key] = self.registry.create_processor(method_type, config)
        return self._processor_cache[cache_key]

    def checkout(
        self,
        method_type: PaymentMethodType,
        amount: Money,
        details: PaymentDetails,
        config: Dict[str, str],
    ) -> PaymentResult:
        if not self.registry.is_supported(method_type):
            raise UnsupportedPaymentMethodError(
                f"Cannot check out with '{method_type.value}': only credit card "
                f"payments are currently supported by this system."
            )

        processor = self._get_or_create_processor(method_type, config)
        return processor.process_payment(amount, details)

    def refund_payment(
        self,
        method_type: PaymentMethodType,
        transaction_id: str,
        amount: Money,
        config: Dict[str, str],
    ) -> PaymentResult:
        processor = self._get_or_create_processor(method_type, config)
        return processor.refund(transaction_id, amount)

    def cancel_payment(
        self,
        method_type: PaymentMethodType,
        transaction_id: str,
        config: Dict[str, str],
    ) -> PaymentResult:
        processor = self._get_or_create_processor(method_type, config)
        return processor.cancel(transaction_id)


# ---------------------------------------------------------------------------
# Demo / Example Usage
# ---------------------------------------------------------------------------

def _generate_test_card_number() -> str:
    """Generates a Luhn-valid test Visa card number."""
    prefix = "4"
    body = prefix + "".join(random.choice(string.digits) for _ in range(14))
    digits = [int(d) for d in body]
    odd_digits = digits[-1::-2]
    even_digits = digits[-2::-2]
    checksum = sum(odd_digits)
    for d in even_digits:
        checksum += sum(divmod(d * 2, 10))
    check_digit = (10 - (checksum % 10)) % 10
    return body + str(check_digit)


def main():
    gateway = PaymentGateway()

    card_details = CreditCardDetails(
        card_number=_generate_test_card_number(),
        cardholder_name="Jane Doe",
        expiry_month=12,
        expiry_year=datetime.utcnow().year + 2,
        cvv="123",
        billing_zip="90210",
    )

    amount = Money(149.99, "USD")
    config = {"merchant_id": "merchant_12345", "decline_rate": "0.0"}

    result = gateway.checkout(
        method_type=PaymentMethodType.CREDIT_CARD,
        amount=amount,
        details=card_details,
        config=config,
    )

    print("Payment Result:")
    print(f"  Success: {result.success}")
    print(f"  Transaction ID: {result.transaction_id}")
    print(f"  Status: {result.status.value}")
    print(f"  Amount: {result.amount}")
    print(f"  Message: {result.message}")
    print(f"  Metadata: {result.metadata}")

    if result.success:
        refund_result = gateway.refund_payment(
            method_type=PaymentMethodType.CREDIT_CARD,
            transaction_id=result.transaction_id,
            amount=Money(50.00, "USD"),
            config=config,
        )
        print("\nRefund Result:")
        print(f"  Success: {refund_result.success}")
        print(f"  Status: {refund_result.status.value}")
        print(f"  Amount refunded: {refund_result.amount}")

    try:
        gateway.checkout(
            method_type=PaymentMethodType.PAYPAL,
            amount=amount,
            details=PayPalDetails(email="test@example.com"),
            config={},
        )
    except UnsupportedPaymentMethodError as exc:
        print(f"\nExpected error for unsupported method: {exc}")


if __name__ == "__main__":
    main()
