class ValidationResult:
    def __init__(self):
        self.is_valid = True
        self.errors = []
        self.warnings = []
        self.order_id = None

    def add_error(self, message):
        self.is_valid = False
        self.errors.append(message)

    def add_warning(self, message):
        self.warnings.append(message)

    def to_dict(self):
        return {
            "is_valid": self.is_valid,
            "errors": self.errors,
            "warnings": self.warnings,
            "order_id": self.order_id,
        }


