def stock_order_validation(order):
    """
    Validates a stock order dictionary with keys:
    account_id, symbol, side ('BUY'/'SELL'), quantity, order_type
    ('MARKET'/'LIMIT'/'STOP'), limit_price (optional), stop_price (optional),
    time_in_force ('DAY'/'GTC'/'IOC').
    """
    result = ValidationResult()

    # --- Basic field presence checks ---
    required_fields = ["account_id", "symbol", "side", "quantity", "order_type"]
    for field in required_fields:
        if field not in order or order[field] is None:
            result.add_error(f"Missing required field: {field}")

    if not result.is_valid:
        return result.to_dict()

    account_id = order["account_id"]
    symbol = order["symbol"].upper()
    side = order["side"].upper()
    quantity = order["quantity"]
    order_type = order["order_type"].upper()
    limit_price = order.get("limit_price")
    stop_price = order.get("stop_price")
    time_in_force = order.get("time_in_force", "DAY").upper()

    # --- Account verification ---
    account = ACCOUNTS.get(account_id)
    if account is None:
        result.add_error(f"Account {account_id} not found")
        return result.to_dict()

    if account["status"] != "ACTIVE":
        result.add_error(f"Account {account_id} is not active (status: {account['status']})")

    if not account["kyc_verified"]:
        result.add_error("Account has not completed KYC verification")

    # --- Order field validation ---
    if side not in ("BUY", "SELL"):
        result.add_error(f"Invalid side: {side}. Must be BUY or SELL")

    if not isinstance(quantity, (int, float)) or quantity <= 0:
        result.add_error("Quantity must be a positive number")

    if quantity != int(quantity):
        result.add_error("Stock quantity must be a whole number")

    if order_type not in ("MARKET", "LIMIT", "STOP", "STOP_LIMIT"):
        result.add_error(f"Invalid order type: {order_type}")

    if order_type in ("LIMIT", "STOP_LIMIT"):
        if limit_price is None or limit_price <= 0:
            result.add_error("Limit price must be provided and positive for LIMIT orders")

    if order_type in ("STOP", "STOP_LIMIT"):
        if stop_price is None or stop_price <= 0:
            result.add_error("Stop price must be provided and positive for STOP orders")

    if time_in_force not in ("DAY", "GTC", "IOC", "FOK"):
        result.add_error(f"Invalid time in force: {time_in_force}")

    # --- Market data / instrument validation ---
    market_info = MARKET_DATA.get(symbol)
    if market_info is None:
        result.add_error(f"Symbol {symbol} not found in market data")
        return result.to_dict()

    if not market_info["tradable"]:
        result.add_error(f"Symbol {symbol} is not currently tradable")

    if market_info["halted"]:
        result.add_error(f"Symbol {symbol} is currently halted for trading")

    # --- Compliance checks ---
    if symbol in account["restricted_instruments"]:
        result.add_error(f"Symbol {symbol} is restricted for account {account_id}")

    if not result.is_valid:
        return result.to_dict()

    last_price = market_info["last_price"]
    estimated_cost = last_price * quantity

    # Pattern day trader rule
    if account["is_pattern_day_trader"] and account["day_trades_count"] >= 3:
        if account["account_type"] == "MARGIN" and account["margin_balance"] < 25000:
            result.add_error(
                "Pattern day trader rule violation: minimum equity of $25,000 required"
            )

    # --- Margin / buying power checks ---
    if side == "BUY":
        if account["account_type"] == "CASH":
            if estimated_cost > account["cash_balance"]:
                result.add_error(
                    f"Insufficient cash balance. Required: {estimated_cost:.2f}, "
                    f"Available: {account['cash_balance']:.2f}"
                )
        else:  # MARGIN account
            margin_required = estimated_cost * 0.5  # 50% Reg-T margin requirement
            if margin_required > account["buying_power"]:
                result.add_error(
                    f"Insufficient buying power. Required margin: {margin_required:.2f}, "
                    f"Available buying power: {account['buying_power']:.2f}"
                )

    elif side == "SELL":
        current_position = account["current_positions"].get(symbol, 0)
        if current_position < quantity:
            shares_to_short = quantity - max(current_position, 0)
            if shares_to_short > 0 and account["account_type"] != "MARGIN":
                result.add_error("Short selling requires a margin account")
            elif shares_to_short > 0:
                short_margin_required = last_price * shares_to_short * 1.5  # 150% req.
                if short_margin_required > account["buying_power"]:
                    result.add_error(
                        f"Insufficient buying power for short sale. "
                        f"Required: {short_margin_required:.2f}, "
                        f"Available: {account['buying_power']:.2f}"
                    )

    # --- Risk assessment ---
    new_position_value = estimated_cost
    if new_position_value > account["max_position_value"]:
        result.add_error(
            f"Order exceeds maximum position value limit of "
            f"{account['max_position_value']:.2f}"
        )

    if account["risk_score"] > 80:
        result.add_warning("Account has a high risk score; order flagged for manual review")

    volatility = market_info["volatility"]
    if volatility > 0.5:
        result.add_warning(f"Symbol {symbol} has high volatility ({volatility})")

    if estimated_cost > account["cash_balance"] * 2:
        result.add_warning("Order size is significantly larger than cash balance")

    # --- Limit / stop price sanity checks relative to market ---
    if order_type in ("LIMIT", "STOP_LIMIT") and limit_price:
        deviation = abs(limit_price - last_price) / last_price
        if deviation > 0.2:
            result.add_warning(
                f"Limit price deviates more than 20% from last price ({last_price})"
            )

    if order_type in ("STOP", "STOP_LIMIT") and stop_price:
        deviation = abs(stop_price - last_price) / last_price
        if deviation > 0.2:
            result.add_warning(
                f"Stop price deviates more than 20% from last price ({last_price})"
            )

    if result.is_valid:
        result.order_id = f"STK-{uuid.uuid4().hex[:10].upper()}"

    return result.to_dict()


