def options_order_validation(order):
    """
    Validates an options order dictionary with keys:
    account_id, symbol (underlying), option_type ('CALL'/'PUT'),
    strike, expiration, side ('BUY_TO_OPEN','SELL_TO_OPEN',
    'BUY_TO_CLOSE','SELL_TO_CLOSE'), quantity (contracts), order_type,
    limit_price (optional), time_in_force.
    """
    result = ValidationResult()

    required_fields = [
        "account_id", "symbol", "option_type", "strike",
        "expiration", "side", "quantity", "order_type",
    ]
    for field in required_fields:
        if field not in order or order[field] is None:
            result.add_error(f"Missing required field: {field}")

    if not result.is_valid:
        return result.to_dict()

    account_id = order["account_id"]
    symbol = order["symbol"].upper()
    option_type = order["option_type"].upper()
    strike = order["strike"]
    expiration = order["expiration"]
    side = order["side"].upper()
    quantity = order["quantity"]
    order_type = order["order_type"].upper()
    limit_price = order.get("limit_price")
    time_in_force = order.get("time_in_force", "DAY").upper()

    # --- Account verification ---
    account = ACCOUNTS.get(account_id)
    if account is None:
        result.add_error(f"Account {account_id} not found")
        return result.to_dict()

    if account["status"] != "ACTIVE":
        result.add_error(f"Account {account_id} is not active (status: {account['status']})")

    if not account["kyc_verified"]:
        result.add_error("Account has not completed KYC verification")

    # --- Options approval level check ---
    required_level = 1
    is_opening_order = side in ("BUY_TO_OPEN", "SELL_TO_OPEN")
    is_selling_naked = side == "SELL_TO_OPEN"

    if is_selling_naked:
        required_level = 3  # naked option selling requires higher approval
    elif is_opening_order:
        required_level = 2  # buying options requires level 2+

    if account["options_approved_level"] < required_level:
        result.add_error(
            f"Account options approval level ({account['options_approved_level']}) "
            f"is insufficient for this order type (requires level {required_level})"
        )

    # --- Order field validation ---
    if option_type not in ("CALL", "PUT"):
        result.add_error(f"Invalid option type: {option_type}. Must be CALL or PUT")

    if side not in ("BUY_TO_OPEN", "SELL_TO_OPEN", "BUY_TO_CLOSE", "SELL_TO_CLOSE"):
        result.add_error(f"Invalid side: {side}")

    if not isinstance(quantity, (int, float)) or quantity <= 0:
        result.add_error("Quantity must be a positive number")

    if quantity != int(quantity):
        result.add_error("Options quantity (contracts) must be a whole number")

    if order_type not in ("MARKET", "LIMIT", "STOP", "STOP_LIMIT"):
        result.add_error(f"Invalid order type: {order_type}")

    if order_type in ("LIMIT", "STOP_LIMIT") and (limit_price is None or limit_price <= 0):
        result.add_error("Limit price must be provided and positive for LIMIT orders")

    if time_in_force not in ("DAY", "GTC", "IOC", "FOK"):
        result.add_error(f"Invalid time in force: {time_in_force}")

    # --- Options chain validation ---
    chain = OPTIONS_CHAIN.get(symbol)
    if chain is None:
        result.add_error(f"No options chain available for underlying symbol {symbol}")
        return result.to_dict()

    if expiration not in chain["expirations"]:
        result.add_error(f"Expiration {expiration} is not available for {symbol}")

    if strike not in chain["strikes"]:
        result.add_error(f"Strike {strike} is not available for {symbol}")

    try:
        exp_date = datetime.datetime.strptime(expiration, "%Y-%m-%d").date()
        if exp_date < datetime.date.today():
            result.add_error(f"Expiration date {expiration} is in the past")
    except ValueError:
        result.add_error(f"Invalid expiration date format: {expiration}")

    # --- Underlying market data check ---
    underlying_info = MARKET_DATA.get(symbol)
    if underlying_info is None:
        result.add_error(f"Underlying symbol {symbol} not found in market data")
        return result.to_dict()

    if not underlying_info["tradable"]:
        result.add_error(f"Underlying symbol {symbol} is not currently tradable")

    if underlying_info["halted"]:
        result.add_error(f"Underlying symbol {symbol} is currently halted")

    # --- Compliance checks ---
    if symbol in account["restricted_instruments"]:
        result.add_error(f"Underlying symbol {symbol} is restricted for account {account_id}")

    if not result.is_valid:
        return result.to_dict()

    multiplier = chain["contract_multiplier"]
    underlying_price = underlying_info["last_price"]

    # --- Estimate option premium (simplified intrinsic + volatility-based extrinsic) ---
    if option_type == "CALL":
        intrinsic = max(underlying_price - strike, 0)
    else:
        intrinsic = max(strike - underlying_price, 0)

    volatility = underlying_info["volatility"]
    extrinsic = underlying_price * volatility * 0.05
    estimated_premium = max(intrinsic + extrinsic, 0.05)

    estimated_cost = estimated_premium * multiplier * quantity

    # --- Margin / buying power checks ---
    if side == "BUY_TO_OPEN":
        if estimated_cost > account["buying_power"]:
            result.add_error(
                f"Insufficient buying power for options purchase. "
                f"Required: {estimated_cost:.2f}, Available: {account['buying_power']:.2f}"
            )

    elif side == "SELL_TO_OPEN":
        # Naked option selling requires substantial margin
        if account["account_type"] != "MARGIN":
            result.add_error("Selling to open requires a margin account")
        else:
            margin_required = max(
                underlying_price * multiplier * quantity * 0.2,
                estimated_premium * multiplier * quantity,
            )
            if margin_required > account["margin_balance"]:
                result.add_error(
                    f"Insufficient margin balance for naked option sale. "
                    f"Required: {margin_required:.2f}, "
                    f"Available: {account['margin_balance']:.2f}"
                )

    elif side in ("BUY_TO_CLOSE", "SELL_TO_CLOSE"):
        # Closing orders require an existing position - simplified check
        position_key = f"{symbol}_{option_type}_{strike}_{expiration}"
        existing_qty = account["current_positions"].get(position_key, 0)
        if existing_qty == 0:
            result.add_warning(
                "No existing position found for this contract; "
                "closing order may be rejected by exchange"
            )

    # --- Risk assessment ---
    days_to_expiration = None
    try:
        exp_date = datetime.datetime.strptime(expiration, "%Y-%m-%d").date()
        days_to_expiration = (exp_date - datetime.date.today()).days
    except ValueError:
        pass

    if days_to_expiration is not None and days_to_expiration <= 2:
        result.add_warning("Option is close to expiration; elevated gamma/theta risk")

    if volatility > 0.5:
        result.add_warning(f"Underlying {symbol} has high volatility ({volatility})")

    if account["risk_score"] > 80:
        result.add_warning("Account has a high risk score; order flagged for manual review")

    notional_exposure = underlying_price * multiplier * quantity
    if notional_exposure > account["max_position_value"]:
        result.add_error(
            f"Order notional exposure ({notional_exposure:.2f}) exceeds "
            f"maximum position value limit of {account['max_position_value']:.2f}"
        )

    if side == "SELL_TO_OPEN" and option_type == "CALL":
        underlying_position = account["current_positions"].get(symbol, 0)
        shares_needed = quantity * multiplier
        if underlying_position < shares_needed:
            result.add_warning(
                "Selling calls without sufficient covering shares (naked call risk)"
            )

    if result.is_valid:
        result.order_id = f"OPT-{uuid.uuid4().hex[:10].upper()}"

    return result.to_dict()


