def futures_order_validation(order):
    """
    Validates a futures order dictionary with keys:
    account_id, symbol (contract code), expiration, side ('BUY'/'SELL'),
    quantity (contracts), order_type, limit_price (optional),
    stop_price (optional), time_in_force.
    """
