    symbol = order["symbol"].upper()
    expiration = order["expiration"]
    side = order["side"].upper()
    quantity = order["quantity"]
    order_type = order["order_type"].upper()
    limit_price = order.get("limit_price")
    stop_price = order.get("stop_price")
    time_in_force = order.get("time_in_force", "DAY").upper()

    # --- Account verification ---
    account = ACCOUNTS.get(account_id)
    if account is None:
        result.add_error(f"Account {account_id} not found")
        return result.to_dict()

    if account["status"] != "ACTIVE":
        result.add_error(f"Account {account_id} is not active (status: {account['status']})")

    if not account["kyc_verified"]:
        result.add_error("Account has not completed KYC verification")

    if not account["futures_approved"]:
        result.add_error(f"Account {account_id} is not approved for futures trading")

    # --- Order field validation ---
    if side not in ("BUY", "SELL"):
        result.add_error(f"Invalid side: {side}. Must be BUY or SELL")

    if not isinstance(quantity, (int, float)) or quantity <= 0:
        result.add_error("Quantity must be a positive number")

    if quantity != int(quantity):
        result.add_error("Futures quantity (contracts) must be a whole number")

    if order_type not in ("MARKET", "LIMIT", "STOP", "STOP_LIMIT"):
        result.add_error(f"Invalid order type: {order_type}")

    if order_type in ("LIMIT", "STOP_LIMIT") and (limit_price is None or limit_price <= 0):
        result.add_error("Limit price must be provided and positive for LIMIT orders")

    if order_type in ("STOP", "STOP_LIMIT") and (stop_price is None or stop_price <= 0):
        result.add_error("Stop price must be provided and positive for STOP orders")

    if time_in_force not in ("DAY", "GTC", "IOC", "FOK"):
        result.add_error(f"Invalid time in force: {time_in_force}")

    # --- Contract validation ---
    contract = FUTURES_CONTRACTS.get(symbol)
    if contract is None:
        result.add_error(f"Futures contract {symbol} not found")
        return result.to_dict()

    if expiration not in contract["expirations"]:
        result.add_error(f"Expiration {expiration} is not available for contract {symbol}")

    try:
        exp_date = datetime.datetime.strptime(expiration, "%Y-%m-%d").date()
        if exp_date < datetime.date.today():
            result.add_error(f"Expiration date {expiration} is in the past")
    except ValueError:
        result.add_error(f"Invalid expiration date format: {expiration}")

    if not contract["tradable"]:
        result.add_error(f"Contract {symbol} is not currently tradable")

    if contract["halted"]:
        result.add_error(f"Contract {symbol} is currently halted")

    # --- Compliance checks ---
    if symbol in account["restricted_instruments"]:
        result.add_error(f"Contract {symbol} is restricted for account {account_id}")

    # --- Tick size validation for limit/stop prices ---
    tick_size = contract["tick_size"]

    def _is_valid_tick(price):
        if price is None:
            return True
        remainder = round(price / tick_size) * tick_size
        return abs(price - remainder) < 1e-6

    if order_type in ("LIMIT", "STOP_LIMIT") and limit_price is not None:
        if not _is_valid_tick(limit_price):
            result.add_error(
                f"Limit price {limit_price} does not conform to tick size {tick_size}"
            )

    if order_type in ("STOP", "STOP_LIMIT") and stop_price is not None:
        if not _is_valid_tick(stop_price):
            result.add_error(
                f"Stop price {stop_price} does not conform to tick size {tick_size}"
            )

    if not result.is_valid:
        return result.to_dict()

    # --- Margin checks ---
    initial_margin_required = contract["margin_requirement"] * quantity
    maintenance_margin_required = contract["maintenance_margin"] * quantity

    if initial_margin_required > account["margin_balance"]:
        result.add_error(
            f"Insufficient margin balance for futures order. "
            f"Required initial margin: {initial_margin_required:.2f}, "
            f"Available margin balance: {account['margin_balance']:.2f}"
        )

    if account["account_type"] != "MARGIN":
        result.add_error("Futures trading requires a margin account")

    # --- Position and notional exposure checks ---
    last_price = contract["last_price"]
    contract_size = contract["contract_size"]
    notional_value = last_price * contract_size * quantity

    if notional_value > account["max_position_value"]:
        result.add_error(
            f"Order notional value ({notional_value:.2f}) exceeds maximum "
            f"position value limit of {account['max_position_value']:.2f}"
        )

    current_position = account["current_positions"].get(symbol, 0)
    projected_position = (
        current_position + quantity if side == "BUY" else current_position - quantity
    )
    projected_notional = abs(projected_position) * last_price * contract_size
    if projected_notional > account["max_position_value"] * 1.5:
        result.add_warning(
            "Projected position size after this order significantly exceeds "
            "typical position value limits"
        )

    # --- Risk assessment ---
    days_to_expiration = None
    try:
        exp_date = datetime.datetime.strptime(expiration, "%Y-%m-%d").date()
        days_to_expiration = (exp_date - datetime.date.today()).days
    except ValueError:
        pass

    if days_to_expiration is not None and days_to_expiration <= 5:
        result.add_warning(
            "Contract is close to expiration; consider rollover risk and delivery obligations"
        )

    if account["risk_score"] > 80:
        result.add_warning("Account has a high risk score; order flagged for manual review")

    leverage_ratio = notional_value / max(account["margin_balance"], 1)
    if leverage_ratio > 10:
        result.add_warning(
            f"High leverage detected (ratio: {leverage_ratio:.2f}); "
            "order carries significant risk"
        )

    if account["is_pattern_day_trader"] and account["day_trades_count"] >= 3:
        result.add_warning(
            "Account flagged as pattern day trader with elevated day trade count"
        )

    remaining_margin_after_order = account["margin_balance"] - initial_margin_required
    if 0 <= remaining_margin_after_order < maintenance_margin_required * 0.5:
        result.add_warning(
            "Remaining margin after this order is close to maintenance margin threshold"
        )

    if result.is_valid:
        result.order_id = f"FUT-{uuid.uuid4().hex[:10].upper()}"

    return result.to_dict()
