                "gross": 0.0,
                "net": 0.0,
                "limit": limit if limit is not None else 100000.0
            }


def update_risk_exposure(symbol, qty_delta, price):
    with _global_lock:
        init_risk_exposure(symbol)
        exposure = qty_delta * price
        risk_exposure[symbol]["net"] += exposure
        risk_exposure[symbol]["gross"] += abs(exposure)
        log_audit("RISK_EXPOSURE_UPDATE", {
            "symbol": symbol,
            "qty_delta": qty_delta,
            "price": price,
            "net": risk_exposure[symbol]["net"],
            "gross": risk_exposure[symbol]["gross"]
        })


def check_risk_limits(symbol, side, qty, price, strategy_name="default"):
    with _global_lock:
        params = get_strategy_parameters(strategy_name)
        max_order_size = params.get("max_order_size", 1000)
        risk_limit = params.get("risk_limit", 100000)

        if qty > max_order_size:
            log_audit("RISK_CHECK_FAILED", {
                "reason": "max_order_size_exceeded",
                "symbol": symbol, "qty": qty
            })
            return False, "Order size exceeds max_order_size"

        init_risk_exposure(symbol, limit=risk_limit)
        signed_qty = qty if side == OrderSide.BUY else -qty
        projected_exposure = risk_exposure[symbol]["gross"] + abs(signed_qty * price)

        if projected_exposure > risk_limit:
            log_audit("RISK_CHECK_FAILED", {
                "reason": "risk_limit_exceeded",
                "symbol": symbol,
                "projected_exposure": projected_exposure,
                "limit": risk_limit
            })
            return False, "Projected exposure exceeds risk limit"

        if symbol in market_status["halted_symbols"]:
            log_audit("RISK_CHECK_FAILED", {
                "reason": "symbol_halted", "symbol": symbol
            })
            return False, "Symbol is halted"

        if not market_status["is_open"]:
            log_audit("RISK_CHECK_FAILED", {"reason": "market_closed"})
            return False, "Market is closed"

        return True, "OK"


