                "avg_fill_price": 0.0,
                "reject_reason": reason,
                "strategy": strategy_name,
                "created_at": time.time()
            }
            log_audit("ORDER_REJECTED", {"order_id": order_id, "reason": reason})
            return order_id

        execution_state[order_id] = {
            "symbol": symbol,
            "side": side.value,
            "qty": qty,
            "price": price,
            "status": OrderStatus.NEW.value,
            "filled_qty": 0.0,
            "avg_fill_price": 0.0,
            "strategy": strategy_name,
            "created_at": time.time()
        }

