def execute_fill(order_id, fill_qty, fill_price):
    with _global_lock:
        order = execution_state.get(order_id)
        if not order:
            return False, "Order not found"

        if order["status"] in (OrderStatus.CANCELLED.value, OrderStatus.REJECTED.value,
                                OrderStatus.FILLED.value):
            return False, f"Cannot fill order in status {order['status']}"

        remaining = order["qty"] - order["filled_qty"]
        if fill_qty > remaining:
            fill_qty = remaining

        if fill_qty <= 0:
            return False, "No remaining quantity to fill"

        prev_filled = order["filled_qty"]
        prev_avg = order["avg_fill_price"]

        new_filled = prev_filled + fill_qty
        new_avg = ((prev_avg * prev_filled) + (fill_price * fill_qty)) / new_filled

        order["filled_qty"] = new_filled
        order["avg_fill_price"] = new_avg

        if new_filled >= order["qty"]:
            order["status"] = OrderStatus.FILLED.value
        else:
            order["status"] = OrderStatus.PARTIALLY_FILLED.value

        side = OrderSide.BUY if order["side"] == OrderSide.BUY.value else OrderSide.SELL
        update_position(order["symbol"], side, fill_qty, fill_price)
        mark_to_market(order["symbol"], fill_price)

        log_audit("ORDER_FILLED", {
            "order_id": order_id,
            "fill_qty": fill_qty,
            "fill_price": fill_price,
            "status": order["status"],
            "total_filled": new_filled
        })

        return True, "Filled"


def simulate_market_execution(order_id):
    """Simulate immediate execution at best available price from order book."""
    with _global_lock:
        order = execution_state.get(order_id)
        if not order:
            return False, "Order not found"

        if not market_status["is_open"]:
            return False, "Market closed"

        if order["symbol"] in market_status["halted_symbols"]:
            return False, "Symbol halted"

        bid, ask = get_best_bid_ask(order["symbol"])
        if bid is None or ask is None:
            return False, "No liquidity available"

        exec_price = ask if order["side"] == OrderSide.BUY.value else bid
        remaining = order["qty"] - order["filled_qty"]

        return execute_fill(order_id, remaining, exec_price)


def process_execution_queue(order_ids):
    with _global_lock:
        results = {}
        for oid in order_ids:
            success, msg = simulate_market_execution(oid)
