def set_strategy_parameters(strategy_name, **params):
    with _global_lock:
        if strategy_name not in strategy_parameters:
            strategy_parameters[strategy_name] = {}
        strategy_parameters[strategy_name].update(params)
        log_audit("STRATEGY_PARAMS_UPDATE", {"strategy": strategy_name, "params": params})


def get_strategy_parameters(strategy_name):
    with _global_lock:
        return strategy_parameters.get(strategy_name, strategy_parameters["default"])


def init_risk_exposure(symbol, limit=None):
    with _global_lock:
        if symbol not in risk_exposure:
            risk_exposure[symbol] = {
                "gross": 0.0,
                "net": 0.0,
                "limit": limit if limit is not None else 100000.0
            }


def update_risk_exposure(symbol, qty_delta, price):
    with _global_lock:
        init_risk_exposure(symbol)
        exposure = qty_delta * price
        risk_exposure[symbol]["net"] += exposure
        risk_exposure[symbol]["gross"] += abs(exposure)
        log_audit("RISK_EXPOSURE_UPDATE", {
            "symbol": symbol,
            "qty_delta": qty_delta,
            "price": price,
            "net": risk_exposure[symbol]["net"],
            "gross": risk_exposure[symbol]["gross"]
        })


def check_risk_limits(symbol, side, qty, price, strategy_name="default"):
    with _global_lock:
        params = get_strategy_parameters(strategy_name)
        max_order_size = params.get("max_order_size", 1000)
        risk_limit = params.get("risk_limit", 100000)

        if qty > max_order_size:
            log_audit("RISK_CHECK_FAILED", {
                "reason": "max_order_size_exceeded",
                "symbol": symbol, "qty": qty
            })
            return False, "Order size exceeds max_order_size"

        init_risk_exposure(symbol, limit=risk_limit)
        signed_qty = qty if side == OrderSide.BUY else -qty
        projected_exposure = risk_exposure[symbol]["gross"] + abs(signed_qty * price)

        if projected_exposure > risk_limit:
            log_audit("RISK_CHECK_FAILED", {
                "reason": "risk_limit_exceeded",
                "symbol": symbol,
                "projected_exposure": projected_exposure,
                "limit": risk_limit
            })
            return False, "Projected exposure exceeds risk limit"

        if symbol in market_status["halted_symbols"]:
            log_audit("RISK_CHECK_FAILED", {
                "reason": "symbol_halted", "symbol": symbol
            })
            return False, "Symbol is halted"

        if not market_status["is_open"]:
            log_audit("RISK_CHECK_FAILED", {"reason": "market_closed"})
            return False, "Market is closed"

        return True, "OK"


def get_risk_summary():
    with _global_lock:
        return {sym: dict(data) for sym, data in risk_exposure.items()}


# ============================================================
# POSITION / PNL MODULE
# ============================================================

def init_position(symbol):
    with _global_lock:
        if symbol not in position_state:
            position_state[symbol] = {"qty": 0.0, "avg_price": 0.0}
        if symbol not in pnl_tracker["by_symbol"]:
            pnl_tracker["by_symbol"][symbol] = {"realized": 0.0, "unrealized": 0.0}


def update_position(symbol, side, fill_qty, fill_price):
    with _global_lock:
        init_position(symbol)
        pos = position_state[symbol]
        signed_qty = fill_qty if side == OrderSide.BUY else -fill_qty

        current_qty = pos["qty"]
        current_avg = pos["avg_price"]
        new_qty = current_qty + signed_qty

        realized_pnl = 0.0

        if current_qty == 0 or (current_qty > 0) == (signed_qty > 0):
            # Increasing position (same direction) or opening from flat
            if new_qty != 0:
                pos["avg_price"] = (
                    (current_avg * abs(current_qty)) + (fill_price * abs(signed_qty))
                ) / abs(new_qty)
            pos["qty"] = new_qty
        else:
            # Reducing or flipping position
            closing_qty = min(abs(signed_qty), abs(current_qty))
            direction = 1 if current_qty > 0 else -1
            realized_pnl = closing_qty * (fill_price - current_avg) * direction

            remaining_signed = signed_qty + current_qty  # net after offset
            if abs(signed_qty) > abs(current_qty):
                # Flipped direction
                pos["qty"] = new_qty
                pos["avg_price"] = fill_price
            else:
                pos["qty"] = new_qty
                if pos["qty"] == 0:
                    pos["avg_price"] = 0.0
                # avg_price stays same if reducing but not flat/flipped

        update_pnl(symbol, realized_delta=realized_pnl)
        update_risk_exposure(symbol, signed_qty, fill_price)

        log_audit("POSITION_UPDATE", {
            "symbol": symbol,
            "side": side.value,
            "fill_qty": fill_qty,
            "fill_price": fill_price,
            "new_qty": pos["qty"],
            "new_avg_price": pos["avg_price"],
            "realized_pnl_delta": realized_pnl
        })

        return pos


def update_pnl(symbol, realized_delta=0.0):
    with _global_lock:
        init_position(symbol)
        pnl_tracker["realized"] += realized_delta
        pnl_tracker["by_symbol"][symbol]["realized"] += realized_delta
        recompute_unrealized_pnl(symbol)


def recompute_unrealized_pnl(symbol):
    with _global_lock:
        pos = position_state.get(symbol)
        if not pos or pos["qty"] == 0:
            old_unrealized = pnl_tracker["by_symbol"].get(symbol, {}).get("unrealized", 0.0)
            pnl_tracker["unrealized"] -= old_unrealized
            if symbol in pnl_tracker["by_symbol"]:
                pnl_tracker["by_symbol"][symbol]["unrealized"] = 0.0
            return

        last_price = market_status["last_prices"].get(symbol, pos["avg_price"])
        new_unrealized = (last_price - pos["avg_price"]) * pos["qty"]

        old_unrealized = pnl_tracker["by_symbol"][symbol]["unrealized"]
        pnl_tracker["unrealized"] += (new_unrealized - old_unrealized)
        pnl_tracker["by_symbol"][symbol]["unrealized"] = new_unrealized


def mark_to_market(symbol, price):
    with _global_lock:
        market_status["last_prices"][symbol] = price
        recompute_unrealized_pnl(symbol)
        log_audit("MARK_TO_MARKET", {"symbol": symbol, "price": price})


def get_pnl_summary():
    with _global_lock:
        return {
            "realized": pnl_tracker["realized"],
            "unrealized": pnl_tracker["unrealized"],
            "total": pnl_tracker["realized"] + pnl_tracker["unrealized"],
            "by_symbol": {k: dict(v) for k, v in pnl_tracker["by_symbol"].items()}
        }


def get_position(symbol):
    with _global_lock:
        init_position(symbol)
        return dict(position_state[symbol])


# ============================================================
# ORDER MANAGEMENT MODULE
# ============================================================

def create_order(symbol, side, qty, price, strategy_name="default"):
    with _global_lock:
        order_id = str(uuid.uuid4())

        ok, reason = check_risk_limits(symbol, side, qty, price, strategy_name)
        if not ok:
            execution_state[order_id] = {
                "symbol": symbol,
                "side": side.value,
                "qty": qty,
                "price": price,
                "status": OrderStatus.REJECTED.value,
                "filled_qty": 0.0,
                "avg_fill_price": 0.0,
                "reject_reason": reason,
                "strategy": strategy_name,
                "created_at": time.time()
            }
            log_audit("ORDER_REJECTED", {"order_id": order_id, "reason": reason})
            return order_id

        execution_state[order_id] = {
            "symbol": symbol,
            "side": side.value,
            "qty": qty,
            "price": price,
            "status": OrderStatus.NEW.value,
            "filled_qty": 0.0,
            "avg_fill_price": 0.0,
            "strategy": strategy_name,
            "created_at": time.time()
        }

        init_position(symbol)
        init_risk_exposure(symbol)

        log_audit("ORDER_CREATED", {
            "order_id": order_id,
            "symbol": symbol,
            "side": side.value,
            "qty": qty,
            "price": price,
            "strategy": strategy_name
        })

        return order_id


def cancel_order(order_id):
    with _global_lock:
        order = execution_state.get(order_id)
        if not order:
            return False, "Order not found"

        if order["status"] in (OrderStatus.FILLED.value, OrderStatus.CANCELLED.value,
                                OrderStatus.REJECTED.value):
            return False, f"Cannot cancel order in status {order['status']}"

        order["status"] = OrderStatus.CANCELLED.value
        log_audit("ORDER_CANCELLED", {"order_id": order_id})
        return True, "Cancelled"


def get_order_status(order_id):
    with _global_lock:
        return execution_state.get(order_id)


def list_open_orders(symbol=None):
    with _global_lock:
        open_statuses = (OrderStatus.NEW.value, OrderStatus.PARTIALLY_FILLED.value)
        results = []
        for oid, order in execution_state.items():
            if order["status"] in open_statuses:
                if symbol is None or order["symbol"] == symbol:
                    results.append({"order_id": oid, **order})
        return results


# ============================================================
# EXECUTION MODULE
# ============================================================

def execute_fill(order_id, fill_qty, fill_price):
    with _global_lock:
        order = execution_state.get(order_id)
        if not order:
            return False, "Order not found"

        if order["status"] in (OrderStatus.CANCELLED.value, OrderStatus.REJECTED.value,
                                OrderStatus.FILLED.value):
            return False, f"Cannot fill order in status {order['status']}"

        remaining = order["qty"] - order["filled_qty"]
        if fill_qty > remaining:
            fill_qty = remaining

        if fill_qty <= 0:
            return False, "No remaining quantity to fill"

        prev_filled = order["filled_qty"]
        prev_avg = order["avg_fill_price"]

        new_filled = prev_filled + fill_qty
        new_avg = ((prev_avg * prev_filled) + (fill_price * fill_qty)) / new_filled

        order["filled_qty"] = new_filled
        order["avg_fill_price"] = new_avg

        if new_filled >= order["qty"]:
            order["status"] = OrderStatus.FILLED.value
        else:
            order["status"] = OrderStatus.PARTIALLY_FILLED.value

        side = OrderSide.BUY if order["side"] == OrderSide.BUY.value else OrderSide.SELL
        update_position(order["symbol"], side, fill_qty, fill_price)
        mark_to_market(order["symbol"], fill_price)

        log_audit("ORDER_FILLED", {
            "order_id": order_id,
            "fill_qty": fill_qty,
            "fill_price": fill_price,
            "status": order["status"],
            "total_filled": new_filled
        })

        return True, "Filled"


def simulate_market_execution(order_id):
    """Simulate immediate execution at best available price from order book."""
    with _global_lock:
        order = execution_state.get(order_id)
        if not order:
            return False, "Order not found"

        if not market_status["is_open"]:
            return False, "Market closed"

        if order["symbol"] in market_status["halted_symbols"]:
            return False, "Symbol halted"

        bid, ask = get_best_bid_ask(order["symbol"])
        if bid is None or ask is None:
            return False, "No liquidity available"

        exec_price = ask if order["side"] == OrderSide.BUY.value else bid
        remaining = order["qty"] - order["filled_qty"]

        return execute_fill(order_id, remaining, exec_price)


def process_execution_queue(order_ids):
    with _global_lock:
        results = {}
        for oid in order_ids:
            success, msg = simulate_market_execution(oid)
            results[oid] = {"success": success, "message": msg}
        return results


# ============================================================
# REPORTING MODULE
# ============================================================

def generate_position_report():
    with _global_lock:
        report = {}
        for symbol, pos in position_state.items():
            report[symbol] = {
                "qty": pos["qty"],
                "avg_price": pos["avg_price"],
                "last_price": market_status["last_prices"].get(symbol),
                "pnl": pnl_tracker["by_symbol"].get(symbol, {})
            }
        return report


def generate_risk_report():
    with _global_lock:
        report = {}
        for symbol, exposure in risk_exposure.items():
            utilization = (exposure["gross"] / exposure["limit"]) if exposure["limit"] else 0
            report[symbol] = {
                **exposure,
                "utilization_pct": utilization * 100
            }
        return report


def generate_execution_report(strategy_name=None):
    with _global_lock:
        report = []
        for oid, order in execution_state.items():
            if strategy_name is None or order.get("strategy") == strategy_name:
                report.append({"order_id": oid, **order})
        return report


def generate_full_report():
    with _global_lock:
        return {
            "timestamp": time.time(),
            "market_status": {
                "is_open": market_status["is_open"],
                "halted_symbols": list(market_status["halted_symbols"])
            },
            "positions": generate_position_report(),
            "pnl": get_pnl_summary(),
            "risk": generate_risk_report(),
            "orders": generate_execution_report(),
            "connections": {cid: dict(info) for cid, info in connection_pool.items()},
            "subscriptions": {sym: list(subs) for sym, subs in subscription_state.items()},
            "recent_audit": get_audit_trail(limit=50)
        }


def print_summary_report():
    report = generate_full_report()
    print("=" * 60)
    print(f"TRADING SYSTEM REPORT - {time.ctime(report['timestamp'])}")
    print("=" * 60)
    print(f"Market Open: {report['market_status']['is_open']}")
    print(f"Halted Symbols: {report['market_status']['halted_symbols']}")
    print("-" * 60)
    print("PnL Summary:")
    print(f"  Realized:   {report['pnl']['realized']:.2f}")
    print(f"  Unrealized: {report['pnl']['unrealized']:.2f}")
    print(f"  Total:      {report['pnl']['total']:.2f}")
    print("-" * 60)
    print("Positions:")
    for symbol, pos in report["positions"].items():
        print(f"  {symbol}: qty={pos['qty']}, avg_price={pos['avg_price']:.2f}, "
              f"last_price={pos['last_price']}")
    print("-" * 60)
    print("Risk Exposure:")
    for symbol, risk in report["risk"].items():
        print(f"  {symbol}: net={risk['net']:.2f}, gross={risk['gross']:.2f}, "
              f"limit={risk['limit']:.2f}, util={risk['utilization_pct']:.1f}%")
    print("=" * 60)


# ============================================================
# EXAMPLE USAGE / DEMO
# ============================================================

if __name__ == "__main__":
    set_strategy_parameters("momentum", max_order_size=500, risk_limit=50000)

    register_connection("conn_1")
    heartbeat("conn_1")

