"""
Clinical Vital Signs System

Adding a NEW vital sign requires updates in exactly these places:
  1. Measurement model      -> VitalSignType enum + Measurement subclass
  2. DataCapture             -> capture handler registration
  3. Validation rules        -> validator registration
  4. Clinical displays       -> display formatter registration
  5. Trending charts         -> chart config registration
  6. Alerts                  -> alert rule registration
  7. Documentation           -> doc template registration
  8. Billing codes           -> billing code mapping
  9. Quality measures        -> quality measure registration
  10. Research exports       -> export schema registration

Each concern is implemented as its own registry so that adding a vital
sign is a matter of registering into each subsystem explicitly and
deliberately -- there is no hidden magic, and each layer must be
touched, mirroring real-world clinical system change-management.
"""

from __future__ import annotations

import csv
import io
import statistics
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from datetime import datetime
from enum import Enum
from typing import Any, Callable, Dict, List, Optional, Tuple


# ---------------------------------------------------------------------------
# 1. MEASUREMENT MODEL
# ---------------------------------------------------------------------------

class VitalSignType(Enum):
    HEART_RATE = "heart_rate"
    BLOOD_PRESSURE = "blood_pressure"
    TEMPERATURE = "temperature"
    RESPIRATORY_RATE = "respiratory_rate"
    OXYGEN_SATURATION = "oxygen_saturation"


@dataclass
class Measurement(ABC):
    """Base class for all vital sign measurements."""
    patient_id: str
    timestamp: datetime
    vital_type: VitalSignType
    source: str = "manual"
    metadata: Dict[str, Any] = field(default_factory=dict)

    @abstractmethod
    def primary_value(self) -> float:
        """Return the primary numeric value for trending/quality checks."""
        raise NotImplementedError

    @abstractmethod
    def display_values(self) -> Dict[str, Any]:
        """Return dict of labeled values for display purposes."""
        raise NotImplementedError


@dataclass
class HeartRateMeasurement(Measurement):
    bpm: float = 0.0

    def primary_value(self) -> float:
        return self.bpm

    def display_values(self) -> Dict[str, Any]:
        return {"HR": f"{self.bpm:.0f} bpm"}


@dataclass
class BloodPressureMeasurement(Measurement):
