MEASUREMENT_CLASS_REGISTRY: Dict[VitalSignType, type] = {
    VitalSignType.HEART_RATE: HeartRateMeasurement,
    VitalSignType.BLOOD_PRESSURE: BloodPressureMeasurement,
    VitalSignType.TEMPERATURE: TemperatureMeasurement,
    VitalSignType.RESPIRATORY_RATE: RespiratoryRateMeasurement,
