# ---------------------------------------------------------------------------
# 2. DATA CAPTURE
# ---------------------------------------------------------------------------

class DataCaptureError(Exception):
    pass


CaptureHandler = Callable[[str, datetime, Dict[str, Any], str], Measurement]


class DataCapture:
    """Handles ingestion of raw vital sign readings into Measurement objects."""

    _handlers: Dict[VitalSignType, CaptureHandler] = {}

    @classmethod
    def register_handler(cls, vital_type: VitalSignType, handler: CaptureHandler) -> None:
        cls._handlers[vital_type] = handler

    @classmethod
    def capture(
        cls,
        vital_type: VitalSignType,
        patient_id: str,
        raw_data: Dict[str, Any],
        source: str = "manual",
        timestamp: Optional[datetime] = None,
