def _capture_heart_rate(patient_id, timestamp, raw, source) -> Measurement:
    return HeartRateMeasurement(
        patient_id=patient_id, timestamp=timestamp,
        vital_type=VitalSignType.HEART_RATE, source=source,
        bpm=float(raw["bpm"]),
