class AlertSeverity(Enum):
    INFO = "info"
    WARNING = "warning"
    CRITICAL = "critical"


@dataclass
class Alert:
    patient_id: str
    vital_type: VitalSignType
    message: str
    severity: AlertSeverity
    timestamp: datetime


AlertRule = Callable[[Measurement], Optional[Alert]]


class Alerts:
    """Registry of alert rules that inspect a measurement and may fire an alert."""

    _rules: Dict[VitalSignType, AlertRule] = {}

    @classmethod
    def register_rule(cls, vital_type: VitalSignType, rule: AlertRule) -> None:
        cls._rules[vital_type] = rule

    @classmethod
    def check(cls, measurement: Measurement) -> Optional[Alert]:
        rule = cls._rules.get(measurement.vital_type)
        if rule is None:
            return None
        return rule(measurement)


def _alert_heart_rate(m: HeartRateMeasurement) -> Optional[Alert]:
    if m.bpm < 40 or m.bpm > 150:
        return Alert(m.patient_id, m.vital_type, f"Critical HR: {m.bpm} bpm",
                      AlertSeverity.CRITICAL, m.timestamp)
    if m.bpm < 50 or m.bpm > 120:
        return Alert(m.patient_id, m.vital_type, f"Abnormal HR: {m.bpm} bpm",
                      AlertSeverity.WARNING, m.timestamp)
    return None


def _alert_blood_pressure(m: BloodPressureMeasurement) -> Optional[Alert]:
    if m.systolic >= 180 or m.diastolic >= 120:
        return Alert(m.patient_id, m.vital_type,
                      f"Hypertensive crisis: {m.systolic}/{m.diastolic}",
                      AlertSeverity.CRITICAL, m.timestamp)
    if m.systolic < 90 or m.diastolic < 60:
        return Alert(m.patient_id, m.vital_type,
                      f"Hypotension: {m.systolic}/{m.diastolic}",
                      AlertSeverity.WARNING, m.timestamp)
    return None


def _alert_temperature(m: TemperatureMeasurement) -> Optional[Alert]:
    if m.celsius >= 40.0 or m.celsius <= 35.0:
        return Alert(m.patient_id, m.vital_type, f"Critical temp: {m.celsius}C",
                      AlertSeverity.CRITICAL, m.timestamp)
    if m.celsius >= 38.0:
        return Alert(m.patient_id, m.vital_type, f"Fever: {m.celsius}C",
                      AlertSeverity.WARNING, m.timestamp)
    return None


def _alert_respiratory_rate(m: RespiratoryRateMeasurement) -> Optional[Alert]:
    if m.breaths_per_min < 8 or m.breaths_per_min > 30:
        return Alert(m.patient_id, m.vital_type,
                      f"Critical RR: {m.breaths_per_min}/min",
                      AlertSeverity.CRITICAL, m.timestamp)
    if m.breaths_per_min < 12 or m.breaths_per_min > 20:
        return Alert(m.patient_id, m.vital_type,
                      f"Abnormal RR: {m.breaths_per_min}/min",
                      AlertSeverity.WARNING, m.timestamp)
    return None


def _alert_oxygen_saturation(m: OxygenSaturationMeasurement) -> Optional[Alert]:
    if m.spo2_percent < 88:
        return Alert(m.patient_id, m.vital_type, f"Critical hypoxia: {m.spo2_percent}%",
                      AlertSeverity.CRITICAL, m.timestamp)
    if m.spo2_percent < 92:
        return Alert(m.patient_id, m.vital_type, f"Low SpO2: {m.spo2_percent}%",
                      AlertSeverity.WARNING, m.timestamp)
    return None


Alerts.register_rule(VitalSignType.HEART_RATE, _alert_heart_rate)
Alerts.register_rule(VitalSignType.BLOOD_PRESSURE, _alert_blood_pressure)
Alerts.register_rule(VitalSignType.TEMPERATURE, _alert_temperature)
Alerts.register_rule(VitalSignType.RESPIRATORY_RATE, _alert_respiratory_rate)
Alerts.register_rule(VitalSignType.OXYGEN_SATURATION, _alert_oxygen_saturation)


