QualityMeasureFn = Callable[[List[Measurement]], Dict[str, Any]]


class QualityMeasures:
    """Registry of quality measure calculators per vital sign type."""

    _measures: Dict[VitalSignType, QualityMeasureFn] = {}

    @classmethod
    def register_measure(cls, vital_type: VitalSignType, measure_fn: QualityMeasureFn) -> None:
        cls._measures[vital_type] = measure_fn

    @classmethod
    def evaluate(cls, vital_type: VitalSignType, measurements: List[Measurement]) -> Dict[str, Any]:
        fn = cls._measures.get(vital_type)
        if fn is None:
            raise KeyError(f"No quality measure registered for {vital_type}")
        return fn([m for m in measurements if m.vital_type == vital_type])


def _qm_heart_rate(measurements: List[Measurement]) -> Dict[str, Any]:
    if not measurements:
        return {"measure": "HR_within_range_rate", "compliant": 0, "total": 0, "rate": None}
    compliant = sum(1 for m in measurements if 60 <= m.primary_value() <= 100)
    total = len(measurements)
    return {"measure": "HR_within_range_rate", "compliant": compliant, "total": total,
            "rate": compliant / total}


def _qm_blood_pressure(measurements: List[Measurement]) -> Dict[str, Any]:
    if not measurements:
        return {"measure": "BP_controlled_rate", "compliant": 0, "total": 0, "rate": None}
    compliant = sum(
        1 for m in measurements
        if isinstance(m, BloodPressureMeasurement) and m.systolic < 140 and m.diastolic < 90
    )
    total = len(measurements)
    return {"measure": "BP_controlled_rate", "compliant": compliant, "total": total,
            "rate": compliant / total}


def _qm_temperature(measurements: List[Measurement]) -> Dict[str, Any]:
    if not measurements:
        return {"measure": "afebrile_rate", "compliant": 0, "total": 0, "rate": None}
    compliant = sum(1 for m in measurements if m.primary_value() < 38.0)
    total = len(measurements)
    return {"measure": "afebrile_rate", "compliant": compliant, "total": total,
            "rate": compliant / total}


def _qm_respiratory_rate(measurements: List[Measurement]) -> Dict[str, Any]:
    if not measurements:
        return {"measure": "RR_within_range_rate", "compliant": 0, "total": 0, "rate": None}
    compliant = sum(1 for m in measurements if 12 <= m.primary_value() <= 20)
    total = len(measurements)
    return {"measure": "RR_within_range_rate", "compliant": compliant, "total": total,
            "rate": compliant / total}


def _qm_oxygen_saturation(measurements: List[Measurement]) -> Dict[str, Any]:
    if not measurements:
        return {"measure": "SpO2_adequate_rate", "compliant": 0, "total": 0, "rate": None}
    compliant = sum(1 for m in measurements if m.primary_value() >= 92)
    total = len(measurements)
    return {"measure": "SpO2_adequate_rate", "compliant": compliant, "total": total,
            "rate": compliant / total}


