ExportSchemaFn = Callable[[Measurement], Dict[str, Any]]


class ResearchExport:
    """Registry of de-identified export row builders per vital sign type."""

    _schemas: Dict[VitalSignType, ExportSchemaFn] = {}

    @classmethod
    def register_schema(cls, vital_type: VitalSignType, schema_fn: ExportSchemaFn) -> None:
        cls._schemas[vital_type] = schema_fn

    @classmethod
    def to_row(cls, measurement: Measurement) -> Dict[str, Any]:
        fn = cls._schemas.get(measurement.vital_type)
        if fn is None:
            raise KeyError(f"No export schema registered for {measurement.vital_type}")
        return fn(measurement)

    @classmethod
    def export_csv(cls, measurements: List[Measurement]) -> str:
        rows = [cls.to_row(m) for m in measurements]
        if not rows:
            return ""
        fieldnames = sorted({key for row in rows for key in row.keys()})
        buf = io.StringIO()
        writer = csv.DictWriter(buf, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)
        return buf.getvalue()


