# ORCHESTRATION LAYER: Patient Vitals Store
# ---------------------------------------------------------------------------

class VitalSignsCompletionError(Exception):
    """Raised at startup if a vital type is missing a registration in any subsystem."""
    pass


class PatientVitalsStore:
    """
    High-level API that ties together all ten subsystems for capturing,
    validating, and using vital sign data in a clinical workflow.
    """

    def __init__(self):
        self._measurements: Dict[str, List[Measurement]] = {}
        self._alerts: List[Alert] = []

    def record_vital(
        self,
        vital_type: VitalSignType,
        patient_id: str,
        raw_data: Dict[str, Any],
        source: str = "manual",
        timestamp: Optional[datetime] = None,
    ) -> Measurement:
        measurement = DataCapture.capture(vital_type, patient_id, raw_data, source, timestamp)
        Validation.validate(measurement)
        self._measurements.setdefault(patient_id, []).append(measurement)

        alert = Alerts.check(measurement)
        if alert:
            self._alerts.append(alert)

        return measurement

    def get_measurements(self, patient_id: str,
                          vital_type: Optional[VitalSignType] = None) -> List[Measurement]:
        all_meas = self._measurements.get(patient_id, [])
        if vital_type is None:
            return list(all_meas)
        return [m for m in all_meas if m.vital_type == vital_type]

    def get_alerts(self, patient_id: Optional[str] = None) -> List[Alert]:
        if patient_id is None:
            return list(self._alerts)
        return [a for a in self._alerts if a.patient_id == patient_id]

    def clinical_summary(self, patient_id: str) -> str:
        return ClinicalDisplay.render_patient_summary(self.get_measurements(patient_id))

    def trend_chart(self, patient_id: str, vital_type: VitalSignType) -> Dict[str, Any]:
        return TrendingCharts.build_series(self.get_measurements(patient_id, vital_type))

    def encounter_documentation(self, patient_id: str) -> str:
        return Documentation.generate_encounter_note(self.get_measurements(patient_id))

    def billing_lines(self, patient_id: str) -> List[Dict[str, str]]:
        return [Billing.generate_billing_line(m) for m in self.get_measurements(patient_id)]

    def quality_report(self, patient_id: str) -> Dict[str, Dict[str, Any]]:
        report = {}
        measurements = self.get_measurements(patient_id)
        present_types = {m.vital_type for m in measurements}
        for vt in present_types:
            report[vt.value] = QualityMeasures.evaluate(vt, measurements)
        return report

    def research_export_csv(self, patient_id: Optional[str] = None) -> str:
        if patient_id is None:
            all_meas: List[Measurement] = []
            for meas_list in self._measurements.values():
                all_meas.extend(meas_list)
        else:
            all_meas = self.get_measurements(patient_id)
        return ResearchExport.export_csv(all_meas)


# ---------------------------------------------------------------------------
# STARTUP INTEGRITY CHECK
# ---------------------------------------------------------------------------

def verify_full_registration() -> None:
    """
    Ensures every VitalSignType is fully wired through all ten subsystems.
    Call this at application startup (or in CI) to catch incomplete additions.
    """
    registries: Dict[str, Dict[VitalSignType, Any]] = {
        "Measurement model": MEASUREMENT_CLASS_REGISTRY,
        "DataCapture": DataCapture._handlers,
        "Validation": Validation._validators,
        "ClinicalDisplay": ClinicalDisplay._formatters,
        "TrendingCharts": TrendingCharts._configs,
        "Alerts": Alerts._rules,
        "Documentation": Documentation._templates,
        "Billing": Billing._codes,
        "QualityMeasures": QualityMeasures._measures,
        "ResearchExport": ResearchExport._schemas,
    }

    missing: List[str] = []
    for vital_type in VitalSignType:
        for subsystem_name, registry in registries.items():
            if vital_type not in registry:
                missing.append(f"{subsystem_name} is missing registration for {vital_type.value}")

    if missing:
        raise VitalSignsCompletionError(
            "Incomplete vital sign registration detected:\n" + "\n".join(missing)
        )


