class DataCaptureError(Exception):
    pass


CaptureHandler = Callable[[str, datetime, Dict[str, Any], str], Measurement]


class DataCapture:
    """Handles ingestion of raw vital sign readings into Measurement objects."""

    _handlers: Dict[VitalSignType, CaptureHandler] = {}

    @classmethod
    def register_handler(cls, vital_type: VitalSignType, handler: CaptureHandler) -> None:
        cls._handlers[vital_type] = handler

    @classmethod
    def capture(
        cls,
        vital_type: VitalSignType,
        patient_id: str,
        raw_data: Dict[str, Any],
        source: str = "manual",
        timestamp: Optional[datetime] = None,
    ) -> Measurement:
        if vital_type not in cls._handlers:
            raise DataCaptureError(f"No capture handler registered for {vital_type}")
        timestamp = timestamp or datetime.utcnow()
        return cls._handlers[vital_type](patient_id, timestamp, raw_data, source)


def _capture_heart_rate(patient_id, timestamp, raw, source) -> Measurement:
    return HeartRateMeasurement(
        patient_id=patient_id, timestamp=timestamp,
        vital_type=VitalSignType.HEART_RATE, source=source,
        bpm=float(raw["bpm"]),
    )


def _capture_blood_pressure(patient_id, timestamp, raw, source) -> Measurement:
    return BloodPressureMeasurement(
        patient_id=patient_id, timestamp=timestamp,
        vital_type=VitalSignType.BLOOD_PRESSURE, source=source,
        systolic=float(raw["systolic"]), diastolic=float(raw["diastolic"]),
    )


def _capture_temperature(patient_id, timestamp, raw, source) -> Measurement:
    return TemperatureMeasurement(
        patient_id=patient_id, timestamp=timestamp,
        vital_type=VitalSignType.TEMPERATURE, source=source,
        celsius=float(raw["celsius"]),
    )


def _capture_respiratory_rate(patient_id, timestamp, raw, source) -> Measurement:
    return RespiratoryRateMeasurement(
        patient_id=patient_id, timestamp=timestamp,
        vital_type=VitalSignType.RESPIRATORY_RATE, source=source,
        breaths_per_min=float(raw["breaths_per_min"]),
    )


def _capture_oxygen_saturation(patient_id, timestamp, raw, source) -> Measurement:
    return OxygenSaturationMeasurement(
        patient_id=patient_id, timestamp=timestamp,
        vital_type=VitalSignType.OXYGEN_SATURATION, source=source,
        spo2_percent=float(raw["spo2_percent"]),
    )


DataCapture.register_handler(VitalSignType.HEART_RATE, _capture_heart_rate)
DataCapture.register_handler(VitalSignType.BLOOD_PRESSURE, _capture_blood_pressure)
DataCapture.register_handler(VitalSignType.TEMPERATURE, _capture_temperature)
DataCapture.register_handler(VitalSignType.RESPIRATORY_RATE, _capture_respiratory_rate)
DataCapture.register_handler(VitalSignType.OXYGEN_SATURATION, _capture_oxygen_saturation)


# ---------------------------------------------------------------------------
# 3. VALIDATION RULES
# ---------------------------------------------------------------------------

class ValidationError(Exception):
    pass


Validator = Callable[[Measurement], None]


class Validation:
    """Registry of validation rules per vital sign type."""

    _validators: Dict[VitalSignType, Validator] = {}

    @classmethod
    def register_validator(cls, vital_type: VitalSignType, validator: Validator) -> None:
        cls._validators[vital_type] = validator

    @classmethod
    def validate(cls, measurement: Measurement) -> None:
        validator = cls._validators.get(measurement.vital_type)
        if validator is None:
            raise ValidationError(f"No validator registered for {measurement.vital_type}")
        validator(measurement)


def _validate_heart_rate(m: HeartRateMeasurement) -> None:
    if not (0 < m.bpm <= 300):
        raise ValidationError(f"Heart rate {m.bpm} out of physiological range (0-300)")


def _validate_blood_pressure(m: BloodPressureMeasurement) -> None:
    if not (20 <= m.systolic <= 300):
        raise ValidationError(f"Systolic {m.systolic} out of range (20-300)")
    if not (10 <= m.diastolic <= 200):
        raise ValidationError(f"Diastolic {m.diastolic} out of range (10-200)")
    if m.diastolic >= m.systolic:
        raise ValidationError("Diastolic must be less than systolic")


def _validate_temperature(m: TemperatureMeasurement) -> None:
    if not (25.0 <= m.celsius <= 45.0):
        raise ValidationError(f"Temperature {m.celsius}C out of range (25-45)")


def _validate_respiratory_rate(m: RespiratoryRateMeasurement) -> None:
    if not (0 < m.breaths_per_min <= 100):
        raise ValidationError(f"Respiratory rate {m.breaths_per_min} out of range (0-100)")


def _validate_oxygen_saturation(m: OxygenSaturationMeasurement) -> None:
    if not (0 <= m.spo2_percent <= 100):
        raise ValidationError(f"SpO2 {m.spo2_percent}% out of range (0-100)")


Validation.register_validator(VitalSignType.HEART_RATE, _validate_heart_rate)
Validation.register_validator(VitalSignType.BLOOD_PRESSURE, _validate_blood_pressure)
Validation.register_validator(VitalSignType.TEMPERATURE, _validate_temperature)
Validation.register_validator(VitalSignType.RESPIRATORY_RATE, _validate_respiratory_rate)
Validation.register_validator(VitalSignType.OXYGEN_SATURATION, _validate_oxygen_saturation)


