DisplayFormatter = Callable[[Measurement], str]


class ClinicalDisplay:
    """Registry mapping vital sign types to human-readable display strings."""

    _formatters: Dict[VitalSignType, DisplayFormatter] = {}

    @classmethod
    def register_formatter(cls, vital_type: VitalSignType, formatter: DisplayFormatter) -> None:
        cls._formatters[vital_type] = formatter

    @classmethod
    def format(cls, measurement: Measurement) -> str:
        formatter = cls._formatters.get(measurement.vital_type)
        if formatter is None:
            raise KeyError(f"No display formatter registered for {measurement.vital_type}")
        return formatter(measurement)

    @classmethod
