@dataclass
class ChartConfig:
    y_label: str
    y_min: float
    y_max: float
    unit: str
    color: str = "blue"


class TrendingCharts:
    """Registry of chart configurations and trend computation per vital type."""

    _configs: Dict[VitalSignType, ChartConfig] = {}

    @classmethod
    def register_config(cls, vital_type: VitalSignType, config: ChartConfig) -> None:
        cls._configs[vital_type] = config

    @classmethod
    def get_config(cls, vital_type: VitalSignType) -> ChartConfig:
        if vital_type not in cls._configs:
            raise KeyError(f"No chart config registered for {vital_type}")
        return cls._configs[vital_type]

    @classmethod
    def build_series(cls, measurements: List[Measurement]) -> Dict[str, Any]:
        if not measurements:
            return {"points": [], "config": None}
        vital_type = measurements[0].vital_type
        config = cls.get_config(vital_type)
        points = [
            {"t": m.timestamp.isoformat(), "value": m.primary_value()}
            for m in sorted(measurements, key=lambda x: x.timestamp)
        ]
        return {
            "points": points,
            "config": {
                "y_label": config.y_label,
                "y_min": config.y_min,
                "y_max": config.y_max,
                "unit": config.unit,
                "color": config.color,
            },
        }


