        self.price = price
        self.order_type = order_type
        self.filled_quantity = 0.0
        self.remaining_quantity = quantity
        self.avg_fill_price = 0.0
        self.status = OrderStatus.NEW
        self.fills = []
        self.timestamp = datetime.datetime.utcnow()

    def apply_fill(self, fill_qty, fill_price):
        if fill_qty <= 0:
            return
        fill_qty = min(fill_qty, self.remaining_quantity)
        total_cost = self.avg_fill_price * self.filled_quantity + fill_price * fill_qty
        self.filled_quantity += fill_qty
        self.remaining_quantity = round(self.quantity - self.filled_quantity, 8)
        self.avg_fill_price = total_cost / self.filled_quantity if self.filled_quantity else 0.0
        self.fills.append({
            "qty": fill_qty,
            "price": fill_price,
            "time": datetime.datetime.utcnow()
        })
        if self.remaining_quantity <= 1e-9:
            self.status = OrderStatus.FILLED
        else:
