                self.avg_price = total_cost / new_qty if new_qty != 0 else 0.0
            else:
                closing_qty = min(fill_qty, abs(self.quantity))
                self.realized_pnl += closing_qty * (self.avg_price - fill_price)
                remaining = fill_qty - closing_qty
                if remaining > 0:
                    self.avg_price = fill_price
            self.quantity = new_qty
        else:
            new_qty = self.quantity - fill_qty
            if self.quantity <= 0:
