    # ---------------- Indicators ----------------
    def sma(self, symbol, period=14):
        prices = self._get_prices(symbol)
        if len(prices) < period:
            return None
        return sum(prices[-period:]) / period

    def ema(self, symbol, period=14):
        prices = self._get_prices(symbol)
        if len(prices) < period:
            return None
        k = 2 / (period + 1)
        ema_val = prices[0]
        for p in prices[1:]:
            ema_val = p * k + ema_val * (1 - k)
        return ema_val

    def rsi(self, symbol, period=14):
        prices = self._get_prices(symbol)
        if len(prices) < period + 1:
            return None
        gains, losses = [], []
        for i in range(-period, 0):
            change = prices[i] - prices[i - 1]
            if change >= 0:
                gains.append(change)
            else:
                losses.append(abs(change))
        avg_gain = sum(gains) / period if gains else 0.0
        avg_loss = sum(losses) / period if losses else 0.0
        if avg_loss == 0:
            return 100.0
        rs = avg_gain / avg_loss
        return 100 - (100 / (1 + rs))

    def macd(self, symbol, fast=12, slow=26, signal=9):
        prices = self._get_prices(symbol)
        if len(prices) < slow + signal:
            return None
        def ema_series(data, period):
            k = 2 / (period + 1)
            ema_vals = [data[0]]
            for p in data[1:]:
                ema_vals.append(p * k + ema_vals[-1] * (1 - k))
            return ema_vals

        fast_ema = ema_series(prices, fast)
        slow_ema = ema_series(prices, slow)
        macd_line = [f - s for f, s in zip(fast_ema, slow_ema)]
        signal_line = ema_series(macd_line, signal)
        histogram = macd_line[-1] - signal_line[-1]
        return {
            "macd": macd_line[-1],
            "signal": signal_line[-1],
            "histogram": histogram
        }

    def bollinger_bands(self, symbol, period=20, num_std=2):
        prices = self._get_prices(symbol)
        if len(prices) < period:
