                reasons.append("RSI_OVERBOUGHT")

        if macd_data is not None:
            if macd_data["histogram"] > 0:
                score += 1
                reasons.append("MACD_BULLISH")
            else:
                score -= 1
                reasons.append("MACD_BEARISH")

        if sma_14 is not None and sma_50 is not None:
            if sma_14 > sma_50:
                score += 1
                reasons.append("GOLDEN_CROSS")
            else:
                score -= 1
                reasons.append("DEATH_CROSS")

        if bollinger is not None:
            if price <= bollinger["lower"]:
                score += 1
                reasons.append("BB_LOWER_TOUCH")
            elif price >= bollinger["upper"]:
                score -= 1
                reasons.append("BB_UPPER_TOUCH")

        if score >= 2:
            signal = "BUY"
        elif score <= -2:
            signal = "SELL"
        else:
            signal = "HOLD"

        result = {
            "signal": signal,
            "score": score,
            "reasons": reasons,
            "indicators": indicators,
            "price": price,
            "timestamp": datetime.datetime.utcnow()
