        errors = []
        position = self._get_position(symbol)

        if quantity <= 0:
            errors.append("INVALID_QUANTITY")

        if quantity > self.risk_limits.max_order_size:
            errors.append("ORDER_SIZE_EXCEEDS_LIMIT")

        projected_qty = position.quantity + quantity if side == OrderSide.BUY else position.quantity - quantity
        if abs(projected_qty) > self.risk_limits.max_position:
            errors.append("POSITION_LIMIT_EXCEEDED")

        notional = quantity * price
        if notional > self.risk_limits.max_notional:
            errors.append("NOTIONAL_LIMIT_EXCEEDED")

        if self.daily_realized_pnl < -abs(self.risk_limits.max_daily_loss):
            errors.append("DAILY_LOSS_LIMIT_BREACHED")

        passed = len(errors) == 0
        self._log_compliance(
