        position.update(order.side, fill_qty, fill_price)
        pnl_delta = position.realized_pnl - pnl_before
        self.daily_realized_pnl += pnl_delta

        commission = fill_qty * fill_price * self.commission_rate

        self._log_compliance("FILL", order.symbol, {
