        Returns discrepancy report.
        """
        discrepancies = []
        all_symbols = set(self.positions.keys()) | set(external_positions.keys())

        for symbol in all_symbols:
            internal = self.positions.get(symbol)
            internal_qty = internal.quantity if internal else 0.0
            internal_avg = internal.avg_price if internal else 0.0

            external = external_positions.get(symbol, {"quantity": 0.0, "avg_price": 0.0})
            ext_qty = external.get("quantity", 0.0)
            ext_avg = external.get("avg_price", 0.0)

            qty_diff = round(internal_qty - ext_qty, 8)
            avg_diff = round(internal_avg - ext_avg, 8)

            if abs(qty_diff) > 1e-6 or abs(avg_diff) > 1e-6:
                discrepancy = {
                    "symbol": symbol,
                    "internal_qty": internal_qty,
                    "external_qty": ext_qty,
                    "qty_diff": qty_diff,
                    "internal_avg_price": internal_avg,
                    "external_avg_price": ext_avg,
                    "avg_price_diff": avg_diff
                }
                discrepancies.append(discrepancy)
                self._log_compliance("RECONCILIATION_DISCREPANCY", symbol, discrepancy)

        report = {
            "timestamp": datetime.datetime.utcnow(),
            "total_symbols_checked": len(all_symbols),
            "discrepancies_found": len(discrepancies),
            "discrepancies": discrepancies,
            "status": "CLEAN" if not discrepancies else "DISCREPANCIES_FOUND"
        }
        return report

    # ---------------- Compliance ----------------
    def _log_compliance(self, event_type, symbol, details):
        entry = {
            "event_id": str(uuid.uuid4()),
            "event_type": event_type,
            "symbol": symbol,
            "details": details,
            "timestamp": datetime.datetime.utcnow()
        }
        self.compliance_log.append(entry)
        return entry

    def generate_compliance_report(self, start_time=None, end_time=None):
        filtered = self.compliance_log
        if start_time:
            filtered = [e for e in filtered if e["timestamp"] >= start_time]
        if end_time:
            filtered = [e for e in filtered if e["timestamp"] <= end_time]

        event_counts = defaultdict(int)
        for e in filtered:
            event_counts[e["event_type"]] += 1

        total_orders = sum(1 for e in filtered if e["event_type"] == "ORDER_SUBMITTED")
        total_rejected = sum(1 for e in filtered if e["event_type"] == "ORDER_REJECTED")
        total_fills = sum(1 for e in filtered if e["event_type"] == "FILL")
        total_cancelled = sum(1 for e in filtered if e["event_type"] == "ORDER_CANCELLED")

        risk_breaches = [
            e for e in filtered
            if e["event_type"] == "RISK_CHECK" and not e["details"].get("passed", True)
        ]

        report = {
            "report_id": str(uuid.uuid4()),
            "generated_at": datetime.datetime.utcnow(),
            "period_start": start_time,
            "period_end": end_time,
            "total_events": len(filtered),
            "event_breakdown": dict(event_counts),
            "total_orders_submitted": total_orders,
