                }
                for symbol, pos in self.positions.items() if pos is not None
            },
            "events": filtered
        }
        return report

    # ---------------- Full Pipeline ----------------
    def process_market_tick(self, symbol, price, volume=0, timestamp=None, order_quantity=100):
        self.ingest_market_data(symbol, price, volume, timestamp)
        signal_result = self.generate_signal(symbol)

