        return dt.strftime("%Y%m%d")

    @staticmethod
    def to_fhir_datetime(dt: Union[datetime.date, datetime.datetime]) -> str:
        """Convert to FHIR-compliant ISO 8601 datetime string."""
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return dt.isoformat()

    @staticmethod
    def validate_encounter_window(
        admit: Union[str, datetime.datetime],
        discharge: Union[str, datetime.datetime],
    ) -> bool:
        """Validate that discharge occurs after admit and within plausible bounds."""
        admit_dt = ClinicalDateTime.parse(admit)
        discharge_dt = ClinicalDateTime.parse(discharge)
        if discharge_dt < admit_dt:
            return False
        max_stay = datetime.timedelta(days=365 * 2)
        if (discharge_dt - admit_dt) > max_stay:
            return False
        return True


# ---------------------------------------------------------------------------
# Clinical Validators
# ---------------------------------------------------------------------------

class ClinicalValidationError(Exception):
    """Raised when clinical data fails validation rules."""


class ClinicalValidators:
    """Healthcare-specific field validation utilities."""

    MRN_PATTERN = re.compile(r"^[A-Z0-9]{6,12}$")
    NPI_PATTERN = re.compile(r"^\d{10}$")
    ICD10_PATTERN = re.compile(r"^[A-TV-Z][0-9][0-9A-Z](\.[0-9A-Z]{1,4})?$")
    LOINC_PATTERN = re.compile(r"^\d{1,7}-\d$")
    SSN_PATTERN = re.compile(r"^\d{3}-\d{2}-\d{4}$")

    VITAL_RANGES = {
        "heart_rate": (30, 250),
        "systolic_bp": (40, 300),
        "diastolic_bp": (20, 200),
        "respiratory_rate": (4, 60),
        "temperature_c": (25.0, 45.0),
        "spo2": (0, 100),
        "bmi": (5.0, 100.0),
    }

    @classmethod
    def validate_mrn(cls, mrn: str) -> bool:
        return bool(mrn) and bool(cls.MRN_PATTERN.match(mrn.strip().upper()))

    @classmethod
    def validate_npi(cls, npi: str) -> bool:
        """Validate NPI using Luhn checksum with the 24-digit prefix trick."""
        if not npi or not cls.NPI_PATTERN.match(npi):
            return False
        prefixed = "80840" + npi
        total = 0
        for i, ch in enumerate(reversed(prefixed)):
            digit = int(ch)
            if i % 2 == 0:
                digit *= 2
                if digit > 9:
                    digit -= 9
            total += digit
        return total % 10 == 0

    @classmethod
    def validate_icd10(cls, code: str) -> bool:
        if not code:
            return False
        return bool(cls.ICD10_PATTERN.match(code.strip().upper()))

    @classmethod
    def validate_loinc(cls, code: str) -> bool:
        if not code:
            return False
        return bool(cls.LOINC_PATTERN.match(code.strip()))

    @classmethod
    def validate_ssn(cls, ssn: str) -> bool:
        if not ssn:
            return False
        return bool(cls.SSN_PATTERN.match(ssn.strip()))

    @classmethod
    def validate_vital_sign(cls, vital_name: str, value: Union[int, float]) -> bool:
        """Check whether a vital sign value falls within physiologically valid range."""
        key = vital_name.strip().lower()
        if key not in cls.VITAL_RANGES:
            raise ClinicalValidationError(f"Unknown vital sign type: {vital_name}")
        low, high = cls.VITAL_RANGES[key]
        try:
            value = float(value)
        except (TypeError, ValueError):
            return False
        return low <= value <= high

    @classmethod
    def validate_dosage(cls, dose: float, weight_kg: float, max_mg_per_kg: float) -> bool:
        """Weight-based dosage safety check."""
        if weight_kg <= 0 or dose < 0:
            return False
        return (dose / weight_kg) <= max_mg_per_kg

    @classmethod
    def validate_lab_result(
        cls,
        value: float,
        reference_low: float,
        reference_high: float,
        critical_low: Optional[float] = None,
        critical_high: Optional[float] = None,
    ) -> str:
        """Categorize a lab result as normal, abnormal, or critical."""
        if critical_low is not None and value <= critical_low:
            return "critical_low"
        if critical_high is not None and value >= critical_high:
            return "critical_high"
        if value < reference_low:
            return "low"
        if value > reference_high:
            return "high"
        return "normal"


# ---------------------------------------------------------------------------
# Pandas Extensions (accessor-based)
# ---------------------------------------------------------------------------

@pd.api.extensions.register_dataframe_accessor("clinical")
class ClinicalDataFrameAccessor:
    """
    Pandas DataFrame accessor exposing clinical validation and
    de-identification helpers via `df.clinical.*`.
    """

    def __init__(self, pandas_obj: pd.DataFrame):
        self._validate(pandas_obj)
        self._df = pandas_obj

    @staticmethod
    def _validate(obj: pd.DataFrame):
        if not isinstance(obj, pd.DataFrame):
            raise AttributeError("Must be a pandas DataFrame.")

    def validate_column_icd10(self, column: str) -> pd.Series:
        return self._df[column].apply(
            lambda v: ClinicalValidators.validate_icd10(v) if pd.notna(v) else False
        )

    def validate_column_mrn(self, column: str) -> pd.Series:
        return self._df[column].apply(
            lambda v: ClinicalValidators.validate_mrn(v) if pd.notna(v) else False
        )

    def validate_vitals(self, column_map: Dict[str, str]) -> pd.DataFrame:
        """
        column_map: mapping of {dataframe_column: vital_sign_name}
        Returns a boolean DataFrame indicating validity per cell.
        """
        result = pd.DataFrame(index=self._df.index)
        for col, vital_name in column_map.items():
            result[col] = self._df[col].apply(
                lambda v: ClinicalValidators.validate_vital_sign(vital_name, v)
                if pd.notna(v) else False
            )
        return result

    def calculate_ages(self, birth_date_column: str, reference_date: Optional[Any] = None) -> pd.Series:
        return self._df[birth_date_column].apply(
            lambda bd: ClinicalDateTime.calculate_age(bd, reference_date) if pd.notna(bd) else np.nan
        )

    def map_icd10_categories(self, icd_column: str) -> pd.Series:
        return self._df[icd_column].apply(
            lambda code: ClinicalTerminology.lookup_icd10_category(code) if pd.notna(code) else None
        )

    def deidentify(
        self,
        identifier_columns: List[str],
        pseudonymize_columns: Optional[List[str]] = None,
        date_columns: Optional[List[str]] = None,
        patient_key_column: Optional[str] = None,
        hipaa: Optional[HIPAACompliance] = None,
    ) -> pd.DataFrame:
        hipaa = hipaa or HIPAACompliance()
        return hipaa.redact_dataframe(
            self._df,
            identifier_columns=identifier_columns,
            pseudonymize_columns=pseudonymize_columns,
            date_columns=date_columns,
            patient_key_column=patient_key_column,
        )

    def flag_missing_critical(self, required_columns: List[str]) -> pd.Series:
        """Flag rows missing any required clinical fields."""
        return self._df[required_columns].isna().any(axis=1)


# ---------------------------------------------------------------------------
# JSON Extensions: Clinical-aware Encoder/Decoder
# ---------------------------------------------------------------------------

class ClinicalJSONEncoder(json.JSONEncoder):
    """
    JSON encoder aware of clinical data types: datetime -> FHIR format,
    pandas Timestamps/NaT, numpy scalars, and Decimal-like lab values.
    """

    def default(self, obj: Any) -> Any:
        if isinstance(obj, (datetime.datetime, datetime.date)):
            return ClinicalDateTime.to_fhir_datetime(
                obj if isinstance(obj, datetime.datetime) else datetime.datetime(obj.year, obj.month, obj.day)
            )
        if isinstance(obj, pd.Timestamp):
            if pd.isna(obj):
                return None
            return ClinicalDateTime.to_fhir_datetime(obj.to_pydatetime())
        if obj is pd.NaT:
            return None
        if isinstance(obj, (np.integer,)):
            return int(obj)
        if isinstance(obj, (np.floating,)):
            return None if np.isnan(obj) else float(obj)
        if isinstance(obj, np.bool_):
            return bool(obj)
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        if isinstance(obj, uuid.UUID):
            return str(obj)
        if isinstance(obj, set):
            return list(obj)
        return super().default(obj)


class ClinicalJSONDecoder(json.JSONDecoder):
    """
    JSON decoder that recognizes clinical field keys ending in `_date`,
    `_at`, or `_time` and parses them into datetime objects automatically.
    """

    _DATETIME_KEY_PATTERN = re.compile(r".*(_date|_at|_time|_dob)$", re.IGNORECASE)

    def __init__(self, *args, **kwargs):
        kwargs["object_hook"] = self._object_hook
        super().__init__(*args, **kwargs)

    def _object_hook(self, obj: Dict[str, Any]) -> Dict[str, Any]:
        for key, value in obj.items():
            if isinstance(value, str) and self._DATETIME_KEY_PATTERN.match(key):
                try:
                    obj[key] = ClinicalDateTime.parse(value)
                except ClinicalDateTimeError:
                    pass
        return obj


def clinical_json_dumps(data: Any, **kwargs) -> str:
    """Serialize clinical data to JSON using ClinicalJSONEncoder."""
    return json.dumps(data, cls=ClinicalJSONEncoder, **kwargs)


def clinical_json_loads(data: str, **kwargs) -> Any:
    """Deserialize clinical JSON, auto-parsing date/time-like fields."""
    return json.loads(data, cls=ClinicalJSONDecoder, **kwargs)


# ---------------------------------------------------------------------------
# FHIR-style Resource Helpers
# ---------------------------------------------------------------------------

class FHIRResourceBuilder:
    """Helper for building minimal FHIR-compliant resource dictionaries."""

    @staticmethod
    def build_patient_resource(
        patient_id: str,
        birth_date: Union[str, datetime.date],
        gender_code: str,
        mrn: Optional[str] = None,
    ) -> Dict[str, Any]:
        bd = ClinicalDateTime.parse(birth_date)
        resource = {
            "resourceType": "Patient",
            "id": patient_id,
            "birthDate": bd.date().isoformat(),
            "gender": ClinicalTerminology.lookup_gender(gender_code) or "unknown",
        }
        if mrn:
            resource["identifier"] = [
                {"system": "urn:oid:2.16.840.1.113883.19.5", "value": mrn}
            ]
        return resource

    @staticmethod
    def build_observation_resource(
        patient_id: str,
        loinc_code: str,
        value: Union[int, float],
        unit: str,
        effective_datetime: Union[str, datetime.datetime],
    ) -> Dict[str, Any]:
        if not ClinicalValidators.validate_loinc(loinc_code):
            raise ClinicalValidationError(f"Invalid LOINC code: {loinc_code}")
        dt = ClinicalDateTime.parse(effective_datetime)
        return {
            "resourceType": "Observation",
            "status": "final",
            "code": {
                "coding": [
                    {
                        "system": "http://loinc.org",
                        "code": loinc_code,
                        "display": ClinicalTerminology.lookup_loinc(loinc_code),
                    }
                ]
            },
            "subject": {"reference": f"Patient/{patient_id}"},
            "effectiveDateTime": ClinicalDateTime.to_fhir_datetime(dt),
            "valueQuantity": {"value": value, "unit": unit},
        }


