class ClinicalTerminology:
    """Namespace for clinical terminology lookups and mappings."""

    @staticmethod
    def lookup_icd10_category(code: str) -> Optional[str]:
        if not code:
            return None
        code = code.strip().upper()
        letter = code[0]
        try:
            number = int(re.sub(r"[^0-9]", "", code[1:3]))
        except (ValueError, IndexError):
            return None
        for range_key, description in ICD10_CATEGORY_MAP.items():
            start, end = range_key.split("-")
            if letter == start[0] and letter == end[0]:
                start_num = int(start[1:])
                end_num = int(end[1:])
                if start_num <= number <= end_num:
                    return description
        return None

    @staticmethod
    def lookup_loinc(code: str) -> Optional[str]:
        return LOINC_COMMON_CODES.get(code)

    @staticmethod
