    def lookup_admit_type(code: str) -> Optional[str]:
        return HL7_ADMIT_TYPE_MAP.get(code.upper()) if code else None

    @staticmethod
    def normalize_icd10(code: str) -> str:
        """Normalize ICD-10 code formatting (e.g., E119 -> E11.9)."""
        if not code:
            return code
        code = code.strip().upper().replace(" ", "")
        if "." in code:
            return code
        if len(code) > 3:
            return f"{code[:3]}.{code[3:]}"
        return code


