class PHIRedactionError(Exception):
    """Raised when PHI redaction cannot be safely performed."""


class HIPAACompliance:
    """
    Utilities for HIPAA-compliant transformations: de-identification,
    pseudonymization, date-shifting, and safe-harbor scrubbing.
    """

    _DEFAULT_SECRET = b"clinical-module-default-secret-change-me"

    def __init__(self, secret_key: Optional[bytes] = None):
        self.secret_key = secret_key or self._DEFAULT_SECRET

    # -- Pseudonymization ---------------------------------------------------

    def pseudonymize_identifier(self, identifier: str) -> str:
        """Deterministically pseudonymize an identifier via HMAC-SHA256."""
        if identifier is None:
            raise PHIRedactionError("Cannot pseudonymize a None identifier.")
        digest = hmac.new(
            self.secret_key, str(identifier).encode("utf-8"), hashlib.sha256
        ).hexdigest()
        return f"PSN-{digest[:16].upper()}"

    def generate_research_id(self, seed: Optional[str] = None) -> str:
        """Generate a random or deterministic research identifier."""
        if seed:
            return self.pseudonymize_identifier(seed)
        return f"RID-{uuid.uuid4().hex[:12].upper()}"

    # -- Date shifting -------------------------------------------------------

    def date_shift(
        self,
        date_value: Union[datetime.date, datetime.datetime, str],
        patient_key: str,
        max_shift_days: int = 365,
    ) -> datetime.datetime:
        """
        Shift a date by a consistent, patient-specific pseudo-random offset
        (common HIPAA de-identification technique preserving intervals).
        """
        dt = ClinicalDateTime.parse(date_value)
        digest = hmac.new(
            self.secret_key, patient_key.encode("utf-8"), hashlib.sha256
        ).digest()
        offset_seed = int.from_bytes(digest[:4], "big")
        shift_days = (offset_seed % (2 * max_shift_days)) - max_shift_days
        return dt + datetime.timedelta(days=shift_days)

    # -- Safe Harbor scrubbing ----------------------------------------------

    def is_over_89(self, birth_date: Union[datetime.date, str], reference: Optional[datetime.date] = None) -> bool:
        """HIPAA requires ages over 89 to be aggregated into a single category."""
        bd = ClinicalDateTime.parse(birth_date).date()
        ref = reference or datetime.date.today()
        age = ClinicalDateTime.calculate_age(bd, ref)
        return age > 89

    def redact_age_over_89(self, age: int) -> Union[int, str]:
        return "90+" if age > 89 else age

