class ClinicalDateTime:
    """Healthcare-specific datetime parsing, validation, and calculations."""

    HL7_DATETIME_FORMATS = [
        "%Y%m%d%H%M%S",
        "%Y%m%d%H%M",
        "%Y%m%d",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%dT%H:%M:%S%z",
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d",
        "%m/%d/%Y",
        "%m/%d/%Y %H:%M:%S",
    ]

    @classmethod
    def parse(cls, value: Union[str, datetime.date, datetime.datetime]) -> datetime.datetime:
        """Parse a clinical date/time string in common HL7/EHR formats."""
        if isinstance(value, datetime.datetime):
            return value
        if isinstance(value, datetime.date):
            return datetime.datetime(value.year, value.month, value.day)
        if pd.isna(value):
            raise ClinicalDateTimeError("Cannot parse null date value.")

        value = str(value).strip()
        for fmt in cls.HL7_DATETIME_FORMATS:
            try:
                return datetime.datetime.strptime(value, fmt)
            except ValueError:
                continue

        try:
            return pd.to_datetime(value).to_pydatetime()
        except Exception as exc:
            raise ClinicalDateTimeError(f"Unable to parse clinical datetime: {value!r}") from exc

    @staticmethod
    def calculate_age(
        birth_date: Union[datetime.date, datetime.datetime, str],
        reference_date: Optional[Union[datetime.date, datetime.datetime, str]] = None,
    ) -> int:
        """Calculate age in whole years."""
        bd = ClinicalDateTime.parse(birth_date).date() if not isinstance(birth_date, datetime.date) else (
            birth_date.date() if isinstance(birth_date, datetime.datetime) else birth_date
        )
        if reference_date is None:
            ref = datetime.date.today()
        elif isinstance(reference_date, datetime.datetime):
            ref = reference_date.date()
        elif isinstance(reference_date, datetime.date):
            ref = reference_date
        else:
            ref = ClinicalDateTime.parse(reference_date).date()

        if bd > ref:
            raise ClinicalDateTimeError("Birth date cannot be after reference date.")

        age = ref.year - bd.year - ((ref.month, ref.day) < (bd.month, bd.day))
        return age

    @staticmethod
    def calculate_age_in_months(
        birth_date: Union[datetime.date, datetime.datetime, str],
        reference_date: Optional[Union[datetime.date, datetime.datetime, str]] = None,
    ) -> int:
        """Age in months, useful for pediatric dosing calculations."""
        bd = ClinicalDateTime.parse(birth_date)
        ref = ClinicalDateTime.parse(reference_date) if reference_date else datetime.datetime.today()
        months = (ref.year - bd.year) * 12 + (ref.month - bd.month)
        if ref.day < bd.day:
            months -= 1
        return max(months, 0)

