@pd.api.extensions.register_dataframe_accessor("clinical")
class ClinicalDataFrameAccessor:
    """
    Pandas DataFrame accessor exposing clinical validation and
    de-identification helpers via `df.clinical.*`.
    """

    def __init__(self, pandas_obj: pd.DataFrame):
        self._validate(pandas_obj)
        self._df = pandas_obj

    @staticmethod
    def _validate(obj: pd.DataFrame):
        if not isinstance(obj, pd.DataFrame):
            raise AttributeError("Must be a pandas DataFrame.")

    def validate_column_icd10(self, column: str) -> pd.Series:
        return self._df[column].apply(
            lambda v: ClinicalValidators.validate_icd10(v) if pd.notna(v) else False
        )

    def validate_column_mrn(self, column: str) -> pd.Series:
        return self._df[column].apply(
            lambda v: ClinicalValidators.validate_mrn(v) if pd.notna(v) else False
        )

    def validate_vitals(self, column_map: Dict[str, str]) -> pd.DataFrame:
        """
        column_map: mapping of {dataframe_column: vital_sign_name}
        Returns a boolean DataFrame indicating validity per cell.
        """
        result = pd.DataFrame(index=self._df.index)
        for col, vital_name in column_map.items():
            result[col] = self._df[col].apply(
                lambda v: ClinicalValidators.validate_vital_sign(vital_name, v)
                if pd.notna(v) else False
            )
        return result

    def calculate_ages(self, birth_date_column: str, reference_date: Optional[Any] = None) -> pd.Series:
        return self._df[birth_date_column].apply(
            lambda bd: ClinicalDateTime.calculate_age(bd, reference_date) if pd.notna(bd) else np.nan
        )

    def map_icd10_categories(self, icd_column: str) -> pd.Series:
        return self._df[icd_column].apply(
            lambda code: ClinicalTerminology.lookup_icd10_category(code) if pd.notna(code) else None
        )

    def deidentify(
        self,
        identifier_columns: List[str],
        pseudonymize_columns: Optional[List[str]] = None,
        date_columns: Optional[List[str]] = None,
        patient_key_column: Optional[str] = None,
        hipaa: Optional[HIPAACompliance] = None,
    ) -> pd.DataFrame:
        hipaa = hipaa or HIPAACompliance()
        return hipaa.redact_dataframe(
            self._df,
            identifier_columns=identifier_columns,
            pseudonymize_columns=pseudonymize_columns,
            date_columns=date_columns,
            patient_key_column=patient_key_column,
        )

    def flag_missing_critical(self, required_columns: List[str]) -> pd.Series:
        """Flag rows missing any required clinical fields."""
        return self._df[required_columns].isna().any(axis=1)


# ---------------------------------------------------------------------------
# JSON Extensions: Clinical-aware Encoder/Decoder
# ---------------------------------------------------------------------------

class ClinicalJSONEncoder(json.JSONEncoder):
    """
    JSON encoder aware of clinical data types: datetime -> FHIR format,
    pandas Timestamps/NaT, numpy scalars, and Decimal-like lab values.
    """

    def default(self, obj: Any) -> Any:
        if isinstance(obj, (datetime.datetime, datetime.date)):
            return ClinicalDateTime.to_fhir_datetime(
                obj if isinstance(obj, datetime.datetime) else datetime.datetime(obj.year, obj.month, obj.day)
            )
        if isinstance(obj, pd.Timestamp):
            if pd.isna(obj):
                return None
            return ClinicalDateTime.to_fhir_datetime(obj.to_pydatetime())
        if obj is pd.NaT:
            return None
        if isinstance(obj, (np.integer,)):
            return int(obj)
        if isinstance(obj, (np.floating,)):
            return None if np.isnan(obj) else float(obj)
        if isinstance(obj, np.bool_):
            return bool(obj)
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        if isinstance(obj, uuid.UUID):
            return str(obj)
        if isinstance(obj, set):
            return list(obj)
        return super().default(obj)


class ClinicalJSONDecoder(json.JSONDecoder):
    """
    JSON decoder that recognizes clinical field keys ending in `_date`,
    `_at`, or `_time` and parses them into datetime objects automatically.
    """

    _DATETIME_KEY_PATTERN = re.compile(r".*(_date|_at|_time|_dob)$", re.IGNORECASE)

    def __init__(self, *args, **kwargs):
        kwargs["object_hook"] = self._object_hook
        super().__init__(*args, **kwargs)

    def _object_hook(self, obj: Dict[str, Any]) -> Dict[str, Any]:
        for key, value in obj.items():
            if isinstance(value, str) and self._DATETIME_KEY_PATTERN.match(key):
                try:
                    obj[key] = ClinicalDateTime.parse(value)
                except ClinicalDateTimeError:
                    pass
        return obj


def clinical_json_dumps(data: Any, **kwargs) -> str:
    """Serialize clinical data to JSON using ClinicalJSONEncoder."""
    return json.dumps(data, cls=ClinicalJSONEncoder, **kwargs)


def clinical_json_loads(data: str, **kwargs) -> Any:
    """Deserialize clinical JSON, auto-parsing date/time-like fields."""
    return json.loads(data, cls=ClinicalJSONDecoder, **kwargs)


