            order.discount = round(order.subtotal * discount_pct, 2)

        order.shipping_cost = self._calculate_shipping_cost(order)
        order.calculate_total()

        self.orders[order_id] = order

        payment = self._process_payment(order, payment_method)
        order.payment = payment

        for product_id, item in cart.items.items():
            inv = self.get_inventory(product_id)
            inv.deduct(item.quantity)
