class InventoryItem:
    def __init__(self, product_id, quantity, warehouse_location="default", reorder_threshold=10):
        self.product_id = product_id
        self.quantity = quantity
        self.reserved = 0
        self.warehouse_location = warehouse_location
        self.reorder_threshold = reorder_threshold

    @property
    def available(self):
        return self.quantity - self.reserved

    def reserve(self, qty):
        if self.available < qty:
            raise InsufficientInventoryError(
                f"Only {self.available} units available for product {self.product_id}"
            )
        self.reserved += qty

    def release(self, qty):
        self.reserved = max(0, self.reserved - qty)

    def deduct(self, qty):
        if self.reserved >= qty:
            self.reserved -= qty
        self.quantity = max(0, self.quantity - qty)

    def restock(self, qty):
        self.quantity += qty


