        self.analytics["revenue_by_date"][today] += order.total
        self.analytics["orders_by_date"][today] += 1
        self.analytics["completed_checkouts"] += 1

        if cart.customer_id in self.customers:
            self.customers[cart.customer_id].add_order(order_id)

        shipment = self._create_shipment(order)
        order.shipment = shipment

        cart.clear()
        return order

    def _process_payment(self, order, payment_method):
        payment_id = str(uuid.uuid4())
        payment = Payment(payment_id, order.order_id, order.total, payment_method)
        try:
            payment.process()
        except PaymentError:
            order.set_status(OrderStatus.CANCELLED)
            raise
        self.payments[payment_id] = payment
        return payment

    def _calculate_shipping_cost(self, order):
        total_items = sum(item.quantity for item in order.items.values())
        base_cost = 5.0
        return round(base_cost + total_items * 0.5, 2)

    def _create_shipment(self, order):
        shipment_id = str(uuid.uuid4())
        shipment = Shipment(shipment_id, order.order_id, order.shipping_address)
        self.shipments[shipment_id] = shipment
        return shipment

    def get_order(self, order_id):
        if order_id not in self.orders:
            raise OrderNotFoundError(f"Order {order_id} not found")
        return self.orders[order_id]

    def cancel_order(self, order_id):
        order = self.get_order(order_id)
        if order.status in (OrderStatus.SHIPPED, OrderStatus.DELIVERED):
            raise ECommerceEngineError("Cannot cancel an order that has already shipped")
        for product_id, item in order.items.items():
            inv = self.get_inventory(product_id)
            inv.restock(item.quantity)
        if order.payment and order.payment.status == PaymentStatus.SUCCESS:
            order.payment.refund()
        order.set_status(OrderStatus.CANCELLED)
        return order

    def refund_order(self, order_id):
        order = self.get_order(order_id)
        if not order.payment or order.payment.status != PaymentStatus.SUCCESS:
            raise PaymentError("Order has no successful payment to refund")
        order.payment.refund()
        order.set_status(OrderStatus.REFUNDED)
        return order

