    def ship_order(self, order_id):
        order = self.get_order(order_id)
        if order.status != OrderStatus.PAID:
            raise ECommerceEngineError("Order must be paid before shipping")
        if not order.shipment:
            raise ECommerceEngineError("No shipment associated with this order")
        order.shipment.ship()
        order.set_status(OrderStatus.SHIPPED)
        return order.shipment

    def deliver_order(self, order_id):
        order = self.get_order(order_id)
        if order.status != OrderStatus.SHIPPED:
            raise ECommerceEngineError("Order must be shipped before delivery")
        order.shipment.deliver()
        order.set_status(OrderStatus.DELIVERED)
        return order.shipment

