    def respond_to_ticket(self, ticket_id, sender, message):
        ticket = self.get_ticket(ticket_id)
        ticket.add_message(sender, message)
        if ticket.status == TicketStatus.OPEN:
            ticket.update_status(TicketStatus.IN_PROGRESS)
