    def get_top_selling_products(self, limit=10):
        sorted_products = sorted(
            self.analytics["sales_by_product"].items(),
            key=lambda x: x[1],
            reverse=True,
        )
        return [
            {"product_id": pid, "revenue": rev, "name": self.products[pid].name if pid in self.products else "Unknown"}
            for pid, rev in sorted_products[:limit]
        ]

