            "revenue_by_date": {},
        }
        for date_str, revenue in self.analytics["revenue_by_date"].items():
            date_obj = datetime.date.fromisoformat(date_str)
            if start_date and date_obj < start_date:
                continue
            if end_date and date_obj > end_date:
                continue
            report["revenue_by_date"][date_str] = revenue
            report["total_revenue"] += revenue
            report["total_orders"] += self.analytics["orders_by_date"].get(date_str, 0)

        if report["total_orders"] > 0:
