                for symbol in self.symbols:
                    change_pct = random.uniform(-0.01, 0.01)
                    self._prices[symbol] = max(0.01, self._prices[symbol] * (1 + change_pct))
            for symbol in self.symbols:
                price = self._prices[symbol]
                for callback in self._subscribers:
                    try:
                        callback(symbol, price)
                    except Exception:
                        logger.exception("Market data subscriber callback failed")
            time.sleep(self.tick_interval)


class RiskLimits:
    """Active, current risk configuration used by the execution engine."""

    def __init__(self, max_order_qty: float = 10_000, max_position: float = 50_000,
                 max_notional: float = 1_000_000, max_orders_per_symbol: int = 1000):
        self.max_order_qty = max_order_qty
        self.max_position = max_position
        self.max_notional = max_notional
        self.max_orders_per_symbol = max_orders_per_symbol


class RiskManager:
    """Active pre-trade risk checks used in the live execution path."""

    def __init__(self, limits: RiskLimits):
        self.limits = limits
        self.positions: Dict[str, float] = defaultdict(float)
        self.order_counts: Dict[str, int] = defaultdict(int)
        self._lock = threading.Lock()

    def check_order(self, order: Order, reference_price: float) -> Tuple[bool, str]:
        with self._lock:
            if order.quantity <= 0:
                return False, "Order quantity must be positive"

            if order.quantity > self.limits.max_order_qty:
                return False, f"Order quantity {order.quantity} exceeds max {self.limits.max_order_qty}"

            notional = order.quantity * reference_price
            if notional > self.limits.max_notional:
                return False, f"Order notional {notional:.2f} exceeds max {self.limits.max_notional}"

            projected_position = self.positions[order.symbol] + (
                order.quantity if order.side == OrderSide.BUY else -order.quantity
            )
            if abs(projected_position) > self.limits.max_position:
                return False, f"Projected position {projected_position} exceeds max {self.limits.max_position}"

            if self.order_counts[order.symbol] >= self.limits.max_orders_per_symbol:
                return False, f"Max orders per symbol reached for {order.symbol}"

            return True, "OK"

    def register_order(self, order: Order) -> None:
        with self._lock:
            self.order_counts[order.symbol] += 1

    def register_fill(self, fill: Fill) -> None:
        with self._lock:
            delta = fill.quantity if fill.side == OrderSide.BUY else -fill.quantity
            self.positions[fill.symbol] += delta

    def get_position(self, symbol: str) -> float:
        with self._lock:
            return self.positions[symbol]


class ExecutionVenue(ABC):
    """Abstract execution venue / broker gateway interface."""

    @abstractmethod
    def send_order(self, order: Order, reference_price: float) -> List[Fill]:
        ...

    @abstractmethod
    def cancel_order(self, order: Order) -> bool:
        ...


class SimulatedExecutionVenue(ExecutionVenue):
    """
    Simulated live execution venue. Fills market orders immediately at
    reference price (with small slippage); fills limit orders only if
    marketable.
    """

    def __init__(self, slippage_bps: float = 2.0, partial_fill_prob: float = 0.15):
        self.slippage_bps = slippage_bps
        self.partial_fill_prob = partial_fill_prob

    def send_order(self, order: Order, reference_price: float) -> List[Fill]:
        fills: List[Fill] = []

        if order.order_type == OrderType.MARKET:
            slippage = reference_price * (self.slippage_bps / 10_000.0)
            fill_price = reference_price + slippage if order.side == OrderSide.BUY else reference_price - slippage
            fills.extend(self._generate_fills(order, fill_price))

        elif order.order_type == OrderType.LIMIT:
            is_marketable = (
                (order.side == OrderSide.BUY and order.limit_price >= reference_price) or
                (order.side == OrderSide.SELL and order.limit_price <= reference_price)
            )
            if is_marketable:
                fills.extend(self._generate_fills(order, order.limit_price))
            else:
                order.status = OrderStatus.PENDING

        elif order.order_type == OrderType.STOP:
            is_triggered = (
                (order.side == OrderSide.BUY and reference_price >= order.stop_price) or
                (order.side == OrderSide.SELL and reference_price <= order.stop_price)
            )
            if is_triggered:
                fills.extend(self._generate_fills(order, reference_price))
            else:
                order.status = OrderStatus.PENDING

        return fills

    def _generate_fills(self, order: Order, price: float) -> List[Fill]:
        fills = []
        remaining = order.remaining_quantity

        if random.random() < self.partial_fill_prob and remaining > 1:
            partial_qty = round(remaining * random.uniform(0.3, 0.7), 4)
            fills.append(Fill(order.order_id, order.symbol, order.side, partial_qty, price))
            order.filled_quantity += partial_qty
            order.status = OrderStatus.PARTIALLY_FILLED
        else:
            fills.append(Fill(order.order_id, order.symbol, order.side, remaining, price))
            order.filled_quantity += remaining
            order.status = OrderStatus.FILLED

        if fills:
            total_value = order.avg_fill_price * (order.filled_quantity - fills[-1].quantity)
            total_value += fills[-1].price * fills[-1].quantity
            order.avg_fill_price = total_value / order.filled_quantity if order.filled_quantity else 0.0

        return fills

    def cancel_order(self, order: Order) -> bool:
        if order.status in (OrderStatus.FILLED, OrderStatus.CANCELLED, OrderStatus.REJECTED):
            return False
        order.status = OrderStatus.CANCELLED
        return True


class OrderExecutionEngine:
    """
    The ACTIVE component of this platform. Wires together market data,
    risk checks, and the execution venue to process orders in real time.
    """

    def __init__(self, market_data: LiveMarketDataFeed, risk_manager: RiskManager,
                 venue: ExecutionVenue):
        self.market_data = market_data
        self.risk_manager = risk_manager
        self.venue = venue
        self.orders: Dict[str, Order] = {}
        self.fills: List[Fill] = []
        self.pending_orders: deque = deque()
        self._lock = threading.Lock()
        self._fill_listeners: List[Callable[[Fill], None]] = []

    def on_fill(self, callback: Callable[[Fill], None]) -> None:
        self._fill_listeners.append(callback)

    def submit_order(self, order: Order) -> Order:
        reference_price = self.market_data.get_price(order.symbol)

        passed, reason = self.risk_manager.check_order(order, reference_price)
        if not passed:
            order.status = OrderStatus.REJECTED
            logger.warning("Order REJECTED: %s | reason=%s", order, reason)
            return order

        with self._lock:
            self.orders[order.order_id] = order
            self.risk_manager.register_order(order)

        logger.info("Order SUBMITTED: %s", order)
        fills = self.venue.send_order(order, reference_price)

        for fill in fills:
            self._process_fill(fill)

        if order.status == OrderStatus.PENDING:
            self.pending_orders.append(order.order_id)

        return order

    def cancel_order(self, order_id: str) -> bool:
        order = self.orders.get(order_id)
        if order is None:
            logger.warning("Cancel failed, unknown order_id=%s", order_id)
            return False
        success = self.venue.cancel_order(order)
        if success:
            logger.info("Order CANCELLED: %s", order)
        return success

    def process_pending_orders(self) -> None:
        """Re-evaluate pending (unfilled) limit/stop orders against latest prices."""
        still_pending = deque()
        while self.pending_orders:
            order_id = self.pending_orders.popleft()
            order = self.orders.get(order_id)
            if order is None or order.status in (
                OrderStatus.FILLED, OrderStatus.CANCELLED, OrderStatus.REJECTED
            ):
                continue

            reference_price = self.market_data.get_price(order.symbol)
            fills = self.venue.send_order(order, reference_price)
            for fill in fills:
                self._process_fill(fill)

            if order.status == OrderStatus.PENDING:
                still_pending.append(order_id)

        self.pending_orders = still_pending

    def _process_fill(self, fill: Fill) -> None:
        with self._lock:
            self.fills.append(fill)
            self.risk_manager.register_fill(fill)
        logger.info("FILL: order=%s %s %s@%.4f price=%.4f",
                    fill.order_id[:8], fill.side.value, fill.quantity, fill.price, fill.price)
        for listener in self._fill_listeners:
            try:
                listener(fill)
            except Exception:
                logger.exception("Fill listener raised an exception")

    def get_order(self, order_id: str) -> Optional[Order]:
        return self.orders.get(order_id)

    def get_open_orders(self) -> List[Order]:
        return [o for o in self.orders.values()
                if o.status in (OrderStatus.NEW, OrderStatus.PENDING, OrderStatus.PARTIALLY_FILLED)]


