@dataclass
class HistoricalBar:
    timestamp: float
    open: float
    high: float
    low: float
    close: float
    volume: float


class HistoricalDataSource(ABC):
    @abstractmethod
    def get_bars(self, symbol: str, start: float, end: float) -> List[HistoricalBar]:
        ...


class SyntheticHistoricalDataSource(HistoricalDataSource):
    """Generates synthetic OHLCV bars for backtesting purposes."""

    def __init__(self, seed: int = 42):
        self.rng = random.Random(seed)

    def get_bars(self, symbol: str, start: float, end: float, interval: float = 86400) -> List[HistoricalBar]:
        bars = []
        price = 100.0
        t = start
        while t < end:
            open_price = price
            change = self.rng.uniform(-0.02, 0.02)
            close_price = max(0.01, open_price * (1 + change))
            high = max(open_price, close_price) * (1 + abs(self.rng.uniform(0, 0.01)))
            low = min(open_price, close_price) * (1 - abs(self.rng.uniform(0, 0.01)))
            volume = self.rng.uniform(1000, 100000)
            bars.append(HistoricalBar(t, open_price, high, low, close_price, volume))
            price = close_price
            t += interval
        return bars


class BacktestPortfolio:
    """Tracks cash, positions, and equity curve during a backtest run."""

    def __init__(self, starting_cash: float = 100_000):
        self.cash = starting_cash
        self.starting_cash = starting_cash
        self.positions: Dict[str, float] = defaultdict(float)
        self.avg_cost: Dict[str, float] = defaultdict(float)
        self.equity_curve: List[Tuple[float, float]] = []
        self.trade_log: List[Dict] = []

    def market_value(self, prices: Dict[str, float]) -> float:
        return self.cash + sum(self.positions[s] * prices.get(s, 0.0) for s in self.positions)

    def execute(self, symbol: str, side: OrderSide, quantity: float, price: float, timestamp: float) -> None:
        cost = quantity * price
        if side == OrderSide.BUY:
            total_cost = self.avg_cost[symbol] * self.positions[symbol] + cost
            self.positions[symbol] += quantity
            self.avg_cost[symbol] = total_cost / self.positions[symbol] if self.positions[symbol] else 0.0
            self.cash -= cost
        else:
            self.positions[symbol] -= quantity
            self.cash += cost

        self.trade_log.append({
            "timestamp": timestamp, "symbol": symbol, "side": side.value,
            "quantity": quantity, "price": price
        })

    def record_equity(self, timestamp: float, prices: Dict[str, float]) -> None:
        self.equity_curve.append((timestamp, self.market_value(prices)))


class BacktestStrategy(ABC):
    """Interface for pluggable backtest strategies."""

    @abstractmethod
    def on_bar(self, symbol: str, bar: HistoricalBar, history: List[HistoricalBar],
               portfolio: BacktestPortfolio) -> Optional[Tuple[OrderSide, float]]:
        """Return (side, quantity) to trade, or None to do nothing."""
        ...


class MovingAverageCrossoverBacktestStrategy(BacktestStrategy):
    """Classic fast/slow SMA crossover strategy, backtest-only."""

    def __init__(self, fast_period: int = 10, slow_period: int = 30, trade_qty: float = 10):
        self.fast_period = fast_period
        self.slow_period = slow_period
        self.trade_qty = trade_qty
        self._last_signal: Dict[str, str] = {}

    def _sma(self, bars: List[HistoricalBar], period: int) -> Optional[float]:
        if len(bars) < period:
            return None
        return sum(b.close for b in bars[-period:]) / period

    def on_bar(self, symbol, bar, history, portfolio):
        fast = self._sma(history, self.fast_period)
        slow = self._sma(history, self.slow_period)
        if fast is None or slow is None:
            return None

        prev_signal = self._last_signal.get(symbol)
        signal = "bullish" if fast > slow else "bearish"
        self._last_signal[symbol] = signal

        if signal == "bullish" and prev_signal != "bullish":
            return OrderSide.BUY, self.trade_qty
        if signal == "bearish" and prev_signal != "bearish":
            return OrderSide.SELL, self.trade_qty
        return None


class MeanReversionBacktestStrategy(BacktestStrategy):
    """Bollinger-band style mean reversion strategy, backtest-only."""

    def __init__(self, lookback: int = 20, num_std: float = 2.0, trade_qty: float = 10):
        self.lookback = lookback
        self.num_std = num_std
        self.trade_qty = trade_qty

    def on_bar(self, symbol, bar, history, portfolio):
        if len(history) < self.lookback:
            return None
        window = [b.close for b in history[-self.lookback:]]
        mean = statistics.mean(window)
        stdev = statistics.pstdev(window) or 1e-9
        upper = mean + self.num_std * stdev
        lower = mean - self.num_std * stdev

        if bar.close < lower:
            return OrderSide.BUY, self.trade_qty
        if bar.close > upper:
            return OrderSide.SELL, self.trade_qty
        return None


class BacktestEngine:
    """Full-featured but unused backtesting engine."""

    def __init__(self, data_source: HistoricalDataSource, strategy: BacktestStrategy,
                 starting_cash: float = 100_000, commission_per_trade: float = 1.0):
        self.data_source = data_source
        self.strategy = strategy
        self.portfolio = BacktestPortfolio(starting_cash)
        self.commission_per_trade = commission_per_trade

    def run(self, symbols: List[str], start: float, end: float) -> Dict:
        all_bars: Dict[str, List[HistoricalBar]] = {
            s: self.data_source.get_bars(s, start, end) for s in symbols
        }
        max_len = max(len(bars) for bars in all_bars.values()) if all_bars else 0

        for i in range(max_len):
            prices_now = {}
            for symbol, bars in all_bars.items():
                if i >= len(bars):
                    continue
                bar = bars[i]
                history = bars[: i + 1]
                prices_now[symbol] = bar.close

                decision = self.strategy.on_bar(symbol, bar, history, self.portfolio)
                if decision is not None:
                    side, qty = decision
                    self.portfolio.execute(symbol, side, qty, bar.close, bar.timestamp)
                    self.portfolio.cash -= self.commission_per_trade

            if prices_now:
                timestamp = next(iter(all_bars.values()))[i].timestamp if i < max_len else time.time()
                self.portfolio.record_equity(timestamp, prices_now)

        return self.generate_report()

    def generate_report(self) -> Dict:
        equity_values = [e for _, e in self.portfolio.equity_curve]
        returns = []
        for i in range(1, len(equity_values)):
            prev = equity_values[i - 1]
            if prev != 0:
                returns.append((equity_values[i] - prev) / prev)

        total_return = (
            (equity_values[-1] - self.portfolio.starting_cash) / self.portfolio.starting_cash
            if equity_values else 0.0
        )
        sharpe = 0.0
        if returns and statistics.pstdev(returns) > 0:
            sharpe = (statistics.mean(returns) / statistics.pstdev(returns)) * (252 ** 0.5)

        max_drawdown = self._max_drawdown(equity_values)

        return {
            "total_return": total_return,
            "sharpe_ratio": sharpe,
            "max_drawdown": max_drawdown,
            "final_equity": equity_values[-1] if equity_values else self.portfolio.starting_cash,
            "num_trades": len(self.portfolio.trade_log),
        }

    @staticmethod
    def _max_drawdown(equity_values: List[float]) -> float:
        if not equity_values:
            return 0.0
        peak = equity_values[0]
        max_dd = 0.0
        for value in equity_values:
            peak = max(peak, value)
            drawdown = (peak - value) / peak if peak else 0.0
            max_dd = max(max_dd, drawdown)
        return max_dd


class WalkForwardBacktestOptimizer:
    """Unused walk-forward parameter optimizer for backtest strategies."""

    def __init__(self, data_source: HistoricalDataSource, strategy_factory: Callable[..., BacktestStrategy]):
        self.data_source = data_source
        self.strategy_factory = strategy_factory

    def optimize(self, symbols: List[str], start: float, end: float,
                 param_grid: List[Dict], window_size: float, step_size: float) -> Dict:
        best_params = None
        best_score = float("-inf")
        results = []

        t = start
        while t + window_size <= end:
            window_end = t + window_size
            for params in param_grid:
                strategy = self.strategy_factory(**params)
                engine = BacktestEngine(self.data_source, strategy)
                report = engine.run(symbols, t, window_end)
                score = report["sharpe_ratio"]
                results.append({"params": params, "window": (t, window_end), "report": report})
                if score > best_score:
                    best_score = score
                    best_params = params
            t += step_size

        return {"best_params": best_params, "best_score": best_score, "all_results": results}


