    DEPRECATED (v0.3): Simple momentum strategy replaced by
    MeanReversionBacktestStrategy due to poor performance in choppy markets.
    """

    def __init__(self, lookback: int = 5, trade_qty: float = 10):
        self.lookback = lookback
        self.trade_qty = trade_qty
        self.price_history: Dict[str, deque] = defaultdict(lambda: deque(maxlen=lookback))

    def update_and_evaluate(self, symbol: str, price: float) -> Optional[Tuple[OrderSide, float]]:
        history = self.price_history[symbol]
        history.append(price)
        if len(history) < self.lookback:
            return None
        momentum = history[-1] - history[0]
        if momentum > 0:
            return OrderSide.BUY, self.trade_qty
        elif momentum < 0:
            return OrderSide.SELL, self.trade_qty
        return None


