class LegacyPollingMarketDataHandler:
    """
    LEGACY: Polling-based market data handler from platform v1.
    Superseded by the push-based LiveMarketDataFeed. Retained for
    compatibility with old integration tests only.
    """

    def __init__(self, symbols: List[str], poll_interval: float = 1.0):
        self.symbols = symbols
        self.poll_interval = poll_interval
        self._prices: Dict[str, float] = {s: 100.0 for s in symbols}
        self._running = False

    def poll_once(self) -> Dict[str, float]:
        for symbol in self.symbols:
            drift = random.uniform(-1, 1)
            self._prices[symbol] = max(0.01, self._prices[symbol] + drift)
        return dict(self._prices)

    def run_blocking(self, iterations: int = 10) -> List[Dict[str, float]]:
        snapshots = []
        for _ in range(iterations):
            snapshots.append(self.poll_once())
            time.sleep(self.poll_interval)
        return snapshots


class LegacyCsvMarketDataHandler:
    """
    LEGACY: Reads a pipe-delimited legacy CSV exchange feed format.
    Format: TIMESTAMP|SYMBOL|PRICE|VOLUME
    Superseded by structured HistoricalDataSource implementations.
    """

    def __init__(self, filepath: str):
        self.filepath = filepath

    def parse_line(self, line: str) -> Optional[Dict]:
        parts = line.strip().split("|")
        if len(parts) != 4:
            return None
        try:
            return {
                "timestamp": float(parts[0]),
                "symbol": parts[1],
                "price": float(parts[2]),
                "volume": float(parts[3]),
            }
        except ValueError:
            return None

    def load_all(self) -> List[Dict]:
        records = []
        try:
            with open(self.filepath, "r") as f:
                for line in f:
                    record = self.parse_line(line)
                    if record:
                        records.append(record)
        except FileNotFoundError:
            logger.warning("Legacy CSV file not found: %s", self.filepath)
        return records


class LegacyTickAggregator:
    """
    LEGACY: Aggregates raw tick data into minute bars using an
    old, inefficient O(n^2) approach. Superseded by vectorized
    aggregation in newer (also unused) modules.
    """

    def __init__(self):
        pass

    def aggregate_to_minute_bars(self, ticks: List[Dict]) -> List[HistoricalBar]:
        if not ticks:
            return []

        buckets: Dict[int, List[Dict]] = defaultdict(list)
        for tick in ticks:
            minute_bucket = int(tick["timestamp"] // 60) * 60
            buckets[minute_bucket].append(tick)

        bars = []
        for bucket_ts in sorted(buckets.keys()):
            bucket_ticks = buckets[bucket_ts]
            prices = [t["price"] for t in bucket_ticks]
            volumes = [t["volume"] for t in bucket_ticks]
            bars.append(HistoricalBar(
                timestamp=bucket_ts,
                open=prices[0],
                high=max(prices),
                low=min(prices),
                close=prices[-1],
                volume=sum(volumes),
            ))
        return bars


