class ObsoleteFixedPercentRiskCalculator:
    """
    OBSOLETE: Calculated position risk as a flat percentage of notional,
    regardless of volatility. Replaced by RiskManager's dynamic checks.
    """

    def __init__(self, risk_pct: float = 0.02):
        self.risk_pct = risk_pct

    def calculate_position_risk(self, notional: float) -> float:
        return notional * self.risk_pct


class ObsoleteVarCalculator:
    """
    OBSOLETE: Historical-simulation Value-at-Risk calculator from
    platform v1. Numerically unstable for small sample sizes; replaced
    by an (unimplemented in this legacy module) parametric approach
    in later internal risk libraries.
    """

    def __init__(self, confidence_level: float = 0.95):
        self.confidence_level = confidence_level

    def calculate_historical_var(self, returns: List[float], portfolio_value: float) -> float:
        if not returns:
            return 0.0
        sorted_returns = sorted(returns)
        index = int((1 - self.confidence_level) * len(sorted_returns))
        index = max(0, min(index, len(sorted_returns) - 1))
        var_return = sorted_returns[index]
        return abs(var_return * portfolio_value)


class ObsoleteMarginCalculator:
    """
    OBSOLETE: Legacy Reg-T style margin calculator superseded by
    portfolio-margin based systems (not present in this legacy module).
    """

    INITIAL_MARGIN_RATE = 0.5
    MAINTENANCE_MARGIN_RATE = 0.25

    def calculate_initial_margin(self, notional: float) -> float:
        return notional * self.INITIAL_MARGIN_RATE

    def calculate_maintenance_margin(self, notional: float) -> float:
        return notional * self.MAINTENANCE_MARGIN_RATE

    def is_margin_call(self, equity: float, notional: float) -> bool:
        return equity < self.calculate_maintenance_margin(notional)


class ObsoleteCorrelationRiskModel:
    """
    OBSOLETE: Naive pairwise correlation risk model using simple
    Pearson correlation on raw price series without any adjustment
    for autocorrelation or regime shifts. Superseded internally by
    covariance-matrix based portfolio risk systems not included here.
    """

    def calculate_correlation(self, series_a: List[float], series_b: List[float]) -> float:
        if len(series_a) != len(series_b) or len(series_a) < 2:
            return 0.0
        try:
            return statistics.correlation(series_a, series_b)
        except (statistics.StatisticsError, ZeroDivisionError):
            return 0.0

    def calculate_portfolio_concentration_risk(self, weights: Dict[str, float]) -> float:
        # Herfindahl-Hirschman style concentration index (obsolete usage context)
        return sum(w ** 2 for w in weights.values())


