def main():
    symbols = ["AAPL", "MSFT", "GOOG"]

    market_data = LiveMarketDataFeed(symbols, tick_interval=0.2)
    risk_limits = RiskLimits(max_order_qty=500, max_position=2000, max_notional=200_000)
    risk_manager = RiskManager(risk_limits)
