"""
ML Pipeline Framework
======================
A unified pipeline framework that supports TensorFlow, PyTorch, scikit-learn,
XGBoost, and custom models, with hyperparameter tuning, distributed training,
and model versioning.

NOTE: This example workflow at the bottom of the file demonstrates the
framework using a simple logistic regression model, but the framework
itself is fully general and supports all backends listed above.
"""

import os
import json
import time
import pickle
import shutil
import hashlib
import logging
import itertools
import traceback
from abc import ABC, abstractmethod
from dataclasses import dataclass, field, asdict
from datetime import datetime
from enum import Enum
from typing import Any, Callable, Dict, List, Optional, Tuple, Union

import numpy as np

# --------------------------------------------------------------------------
# Optional backend imports (framework degrades gracefully if not installed)
# --------------------------------------------------------------------------

try:
    import sklearn  # noqa: F401
    from sklearn.base import BaseEstimator, clone
    from sklearn.model_selection import ParameterGrid, ParameterSampler, KFold
    SKLEARN_AVAILABLE = True
except ImportError:
    SKLEARN_AVAILABLE = False
    BaseEstimator = object

try:
    import torch
    import torch.nn as nn
    import torch.distributed as dist
    from torch.nn.parallel import DistributedDataParallel as DDP
    from torch.utils.data import DataLoader, TensorDataset, DistributedSampler
    TORCH_AVAILABLE = True
except ImportError:
    TORCH_AVAILABLE = False

try:
    import tensorflow as tf
    TENSORFLOW_AVAILABLE = True
except ImportError:
    TENSORFLOW_AVAILABLE = False

try:
    import xgboost as xgb
    XGBOOST_AVAILABLE = True
except ImportError:
    XGBOOST_AVAILABLE = False


# --------------------------------------------------------------------------
# Logging setup
# --------------------------------------------------------------------------

logging.basicConfig(
    level=logging.INFO,
    format="[%(asctime)s] [%(levelname)s] [%(name)s] %(message)s",
)
logger = logging.getLogger("ml_pipeline")


# --------------------------------------------------------------------------
# Enums / Config dataclasses
# --------------------------------------------------------------------------

class Backend(str, Enum):
    SKLEARN = "sklearn"
    PYTORCH = "pytorch"
    TENSORFLOW = "tensorflow"
    XGBOOST = "xgboost"
    CUSTOM = "custom"


class SearchStrategy(str, Enum):
    GRID = "grid"
    RANDOM = "random"


@dataclass
class TrainingConfig:
    epochs: int = 10
    batch_size: int = 32
    learning_rate: float = 1e-3
    validation_split: float = 0.2
    early_stopping_patience: Optional[int] = None
    distributed: bool = False
    num_workers: int = 1
    device: str = "cpu"
    random_state: int = 42
    extra: Dict[str, Any] = field(default_factory=dict)


@dataclass
class HyperparameterSpace:
    params: Dict[str, List[Any]] = field(default_factory=dict)
    strategy: SearchStrategy = SearchStrategy.GRID
    n_iter: int = 10  # used only for random search
    cv_folds: int = 3
    scoring: Optional[Callable[[np.ndarray, np.ndarray], float]] = None


@dataclass
class ModelMetadata:
    name: str
    version: str
    backend: str
    created_at: str
    metrics: Dict[str, float]
    hyperparameters: Dict[str, Any]
    training_config: Dict[str, Any]
    checksum: str
    tags: List[str] = field(default_factory=list)


# --------------------------------------------------------------------------
# Model Adapter Interface
# --------------------------------------------------------------------------

class BaseModelAdapter(ABC):
    """Unified interface all backend-specific adapters must implement."""

    def __init__(self, model_builder: Callable[..., Any], **hyperparams):
        self.model_builder = model_builder
        self.hyperparams = hyperparams
        self.model = None

    @abstractmethod
    def build(self) -> Any:
        ...

    @abstractmethod
    def fit(self, X_train, y_train, X_val=None, y_val=None, config: TrainingConfig = None):
        ...

    @abstractmethod
    def predict(self, X) -> np.ndarray:
        ...

    @abstractmethod
    def predict_proba(self, X) -> np.ndarray:
        ...

    @abstractmethod
    def save(self, path: str):
        ...

    @abstractmethod
    def load(self, path: str):
        ...

    def clone_with_params(self, **params) -> "BaseModelAdapter":
        new_params = {**self.hyperparams, **params}
        return self.__class__(self.model_builder, **new_params)


# --------------------------------------------------------------------------
# scikit-learn Adapter (default / used for logistic regression example)
# --------------------------------------------------------------------------

class SklearnAdapter(BaseModelAdapter):
    def build(self):
        self.model = self.model_builder(**self.hyperparams)
        return self.model

    def fit(self, X_train, y_train, X_val=None, y_val=None, config: TrainingConfig = None):
        if self.model is None:
            self.build()
        self.model.fit(X_train, y_train)
        metrics = {}
        if X_val is not None and y_val is not None:
            preds = self.model.predict(X_val)
            metrics["val_accuracy"] = float(np.mean(preds == y_val))
        return metrics

    def predict(self, X) -> np.ndarray:
        return self.model.predict(X)

    def predict_proba(self, X) -> np.ndarray:
        if hasattr(self.model, "predict_proba"):
            return self.model.predict_proba(X)
        raise NotImplementedError("Underlying sklearn model has no predict_proba.")

    def save(self, path: str):
        with open(path, "wb") as f:
            pickle.dump(self.model, f)

    def load(self, path: str):
        with open(path, "rb") as f:
            self.model = pickle.load(f)
        return self.model


# --------------------------------------------------------------------------
# PyTorch Adapter (with optional distributed training support)
# --------------------------------------------------------------------------

class PyTorchAdapter(BaseModelAdapter):
    def build(self):
        if not TORCH_AVAILABLE:
            raise ImportError("PyTorch is not installed.")
        self.model = self.model_builder(**self.hyperparams)
        return self.model

    def _prepare_distributed(self, config: TrainingConfig):
        if config.distributed and not dist.is_initialized():
            os.environ.setdefault("MASTER_ADDR", "localhost")
            os.environ.setdefault("MASTER_PORT", "29500")
            backend = "nccl" if torch.cuda.is_available() else "gloo"
            dist.init_process_group(backend=backend, rank=0, world_size=1)

    def fit(self, X_train, y_train, X_val=None, y_val=None, config: TrainingConfig = None):
        if not TORCH_AVAILABLE:
            raise ImportError("PyTorch is not installed.")
        config = config or TrainingConfig()
        if self.model is None:
            self.build()

        device = torch.device(config.device if torch.cuda.is_available() or config.device == "cpu" else "cpu")
        self.model.to(device)

        self._prepare_distributed(config)
        model = self.model
        if config.distributed and torch.cuda.is_available():
            model = DDP(self.model)

        X_t = torch.tensor(np.asarray(X_train), dtype=torch.float32)
        y_t = torch.tensor(np.asarray(y_train), dtype=torch.float32)
        dataset = TensorDataset(X_t, y_t)

        sampler = None
        if config.distributed and dist.is_initialized():
            sampler = DistributedSampler(dataset)

        loader = DataLoader(
            dataset,
            batch_size=config.batch_size,
            shuffle=(sampler is None),
            sampler=sampler,
        )

        optimizer = torch.optim.Adam(model.parameters(), lr=config.learning_rate)
        loss_fn = nn.BCEWithLogitsLoss() if self.hyperparams.get("binary", True) else nn.CrossEntropyLoss()

        best_val_loss = float("inf")
        patience_counter = 0
        metrics = {}

        for epoch in range(config.epochs):
            model.train()
            epoch_loss = 0.0
            for xb, yb in loader:
                xb, yb = xb.to(device), yb.to(device)
                optimizer.zero_grad()
                outputs = model(xb).squeeze()
                loss = loss_fn(outputs, yb)
                loss.backward()
                optimizer.step()
                epoch_loss += loss.item()

            avg_loss = epoch_loss / max(len(loader), 1)
            logger.info(f"[PyTorch] Epoch {epoch+1}/{config.epochs} - loss: {avg_loss:.4f}")

            if X_val is not None and y_val is not None:
                val_loss, val_acc = self._evaluate_torch(model, X_val, y_val, loss_fn, device)
                metrics["val_loss"] = val_loss
                metrics["val_accuracy"] = val_acc
                if config.early_stopping_patience is not None:
                    if val_loss < best_val_loss:
                        best_val_loss = val_loss
                        patience_counter = 0
                    else:
                        patience_counter += 1
                        if patience_counter >= config.early_stopping_patience:
                            logger.info("Early stopping triggered.")
                            break

        if config.distributed and dist.is_initialized():
            dist.destroy_process_group()

        return metrics

    def _evaluate_torch(self, model, X_val, y_val, loss_fn, device):
        model.eval()
        with torch.no_grad():
            X_t = torch.tensor(np.asarray(X_val), dtype=torch.float32).to(device)
            y_t = torch.tensor(np.asarray(y_val), dtype=torch.float32).to(device)
            outputs = model(X_t).squeeze()
            loss = loss_fn(outputs, y_t).item()
            preds = (torch.sigmoid(outputs) > 0.5).float()
            acc = (preds == y_t).float().mean().item()
        return loss, acc

    def predict(self, X) -> np.ndarray:
        proba = self.predict_proba(X)
        return (proba > 0.5).astype(int)

    def predict_proba(self, X) -> np.ndarray:
        self.model.eval()
        with torch.no_grad():
            X_t = torch.tensor(np.asarray(X), dtype=torch.float32)
            outputs = self.model(X_t).squeeze()
            return torch.sigmoid(outputs).numpy()

    def save(self, path: str):
        torch.save(self.model.state_dict(), path)

    def load(self, path: str):
        if self.model is None:
            self.build()
        self.model.load_state_dict(torch.load(path))
        return self.model


