class TensorFlowAdapter(BaseModelAdapter):
    def build(self):
        if not TENSORFLOW_AVAILABLE:
            raise ImportError("TensorFlow is not installed.")
        self.model = self.model_builder(**self.hyperparams)
        return self.model

    def fit(self, X_train, y_train, X_val=None, y_val=None, config: TrainingConfig = None):
        if not TENSORFLOW_AVAILABLE:
            raise ImportError("TensorFlow is not installed.")
        config = config or TrainingConfig()
        if self.model is None:
            self.build()

        strategy = tf.distribute.MirroredStrategy() if config.distributed else None

        callbacks = []
        if config.early_stopping_patience is not None:
            callbacks.append(
                tf.keras.callbacks.EarlyStopping(
                    patience=config.early_stopping_patience, restore_best_weights=True
                )
            )

        validation_data = (X_val, y_val) if X_val is not None else None

        history = self.model.fit(
            X_train,
            y_train,
            epochs=config.epochs,
            batch_size=config.batch_size,
            validation_data=validation_data,
            callbacks=callbacks,
            verbose=0,
        )

        metrics = {}
        for key, values in history.history.items():
            metrics[key] = float(values[-1])
        return metrics

    def predict(self, X) -> np.ndarray:
        proba = self.predict_proba(X)
        return (proba > 0.5).astype(int)

    def predict_proba(self, X) -> np.ndarray:
        preds = self.model.predict(X, verbose=0)
        return np.squeeze(preds)

    def save(self, path: str):
        self.model.save(path)

    def load(self, path: str):
        self.model = tf.keras.models.load_model(path)
        return self.model


