# --------------------------------------------------------------------------
# Adapter Factory
# --------------------------------------------------------------------------

class AdapterFactory:
    _registry = {
        Backend.SKLEARN: SklearnAdapter,
        Backend.PYTORCH: PyTorchAdapter,
        Backend.TENSORFLOW: TensorFlowAdapter,
        Backend.XGBOOST: XGBoostAdapter,
        Backend.CUSTOM: CustomModelAdapter,
    }

    @classmethod
    def create(cls, backend: Union[str, Backend], model_builder: Callable, **hyperparams) -> BaseModelAdapter:
        backend = Backend(backend)
        adapter_cls = cls._registry.get(backend)
        if adapter_cls is None:
            raise ValueError(f"Unsupported backend: {backend}")
        return adapter_cls(model_builder, **hyperparams)

    @classmethod
    def register(cls, backend: Backend, adapter_cls: type):
        cls._registry[backend] = adapter_cls


# --------------------------------------------------------------------------
# Hyperparameter Tuner
# --------------------------------------------------------------------------

class HyperparameterTuner:
    def __init__(
        self,
        backend: Union[str, Backend],
        model_builder: Callable,
        search_space: HyperparameterSpace,
        training_config: Optional[TrainingConfig] = None,
    ):
        self.backend = backend
        self.model_builder = model_builder
        self.search_space = search_space
        self.training_config = training_config or TrainingConfig()
        self.results_: List[Dict[str, Any]] = []
        self.best_params_: Optional[Dict[str, Any]] = None
        self.best_score_: float = -np.inf
        self.best_adapter_: Optional[BaseModelAdapter] = None

    def _generate_candidates(self) -> List[Dict[str, Any]]:
        if not self.search_space.params:
            return [{}]
        if self.search_space.strategy == SearchStrategy.GRID:
            keys = list(self.search_space.params.keys())
            values = list(self.search_space.params.values())
            return [dict(zip(keys, combo)) for combo in itertools.product(*values)]
        else:  # RANDOM
            rng = np.random.RandomState(self.training_config.random_state)
            candidates = []
            keys = list(self.search_space.params.keys())
            for _ in range(self.search_space.n_iter):
                candidate = {k: rng.choice(self.search_space.params[k]) for k in keys}
                candidates.append(candidate)
            return candidates

    def _default_scorer(self, y_true, y_pred) -> float:
        return float(np.mean(np.asarray(y_true) == np.asarray(y_pred)))

    def _cross_validate(self, params: Dict[str, Any], X, y) -> float:
        scorer = self.search_space.scoring or self._default_scorer
        n_splits = self.search_space.cv_folds
        n = len(X)
        indices = np.arange(n)
        rng = np.random.RandomState(self.training_config.random_state)
        rng.shuffle(indices)
        fold_sizes = np.full(n_splits, n // n_splits, dtype=int)
        fold_sizes[: n % n_splits] += 1
        scores = []
        current = 0
        for fold_size in fold_sizes:
            start, stop = current, current + fold_size
            val_idx = indices[start:stop]
            train_idx = np.concatenate([indices[:start], indices[stop:]])
            current = stop

            X_train, X_val = X[train_idx], X[val_idx]
            y_train, y_val = y[train_idx], y[val_idx]

            adapter = AdapterFactory.create(self.backend, self.model_builder, **params)
            adapter.build()
            adapter.fit(X_train, y_train, X_val, y_val, self.training_config)
            preds = adapter.predict(X_val)
            score = scorer(y_val, preds)
            scores.append(score)
        return float(np.mean(scores))

    def search(self, X, y) -> Dict[str, Any]:
        X = np.asarray(X)
        y = np.asarray(y)
        candidates = self._generate_candidates()
        logger.info(f"Starting hyperparameter search with {len(candidates)} candidates.")

        for i, params in enumerate(candidates):
            try:
                score = self._cross_validate(params, X, y)
                self.results_.append({"params": params, "score": score})
                logger.info(f"[{i+1}/{len(candidates)}] params={params} -> score={score:.4f}")
                if score > self.best_score_:
                    self.best_score_ = score
                    self.best_params_ = params
            except Exception as e:
                logger.warning(f"Candidate {params} failed: {e}")
                self.results_.append({"params": params, "score": None, "error": str(e)})

        if self.best_params_ is None:
            raise RuntimeError("Hyperparameter search failed for all candidates.")

        logger.info(f"Best params: {self.best_params_} with score {self.best_score_:.4f}")

        best_adapter = AdapterFactory.create(self.backend, self.model_builder, **self.best_params_)
        best_adapter.build()
        best_adapter.fit(X, y, config=self.training_config)
        self.best_adapter_ = best_adapter

        return self.best_params_


# --------------------------------------------------------------------------
# Model Registry / Versioning
# --------------------------------------------------------------------------

class ModelRegistry:
    def __init__(self, root_dir: str = "./model_registry"):
        self.root_dir = root_dir
        os.makedirs(self.root_dir, exist_ok=True)

    def _model_dir(self, name: str) -> str:
        path = os.path.join(self.root_dir, name)
        os.makedirs(path, exist_ok=True)
        return path

    def _next_version(self, name: str) -> str:
        model_dir = self._model_dir(name)
        existing = [d for d in os.listdir(model_dir) if d.startswith("v")]
        version_numbers = []
        for d in existing:
            try:
                version_numbers.append(int(d[1:]))
            except ValueError:
                continue
        next_version = max(version_numbers, default=0) + 1
        return f"v{next_version}"

    @staticmethod
    def _checksum_of_file(path: str) -> str:
        hasher = hashlib.sha256()
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(8192), b""):
                hasher.update(chunk)
        return hasher.hexdigest()

    def save_model(
        self,
        adapter: BaseModelAdapter,
        name: str,
        backend: Union[str, Backend],
        metrics: Dict[str, float],
        hyperparameters: Dict[str, Any],
        training_config: TrainingConfig,
        tags: Optional[List[str]] = None,
        artifact_filename: str = "model.bin",
    ) -> ModelMetadata:
        version = self._next_version(name)
        version_dir = os.path.join(self._model_dir(name), version)
        os.makedirs(version_dir, exist_ok=True)

        artifact_path = os.path.join(version_dir, artifact_filename)
        adapter.save(artifact_path)

        if os.path.isdir(artifact_path):
            checksum = self._checksum_of_dir(artifact_path)
        else:
            checksum = self._checksum_of_file(artifact_path)

        metadata = ModelMetadata(
            name=name,
            version=version,
            backend=str(Backend(backend).value),
            created_at=datetime.utcnow().isoformat(),
            metrics=metrics,
            hyperparameters=hyperparameters,
            training_config=asdict(training_config),
            checksum=checksum,
            tags=tags or [],
        )

        metadata_path = os.path.join(version_dir, "metadata.json")
        with open(metadata_path, "w") as f:
            json.dump(asdict(metadata), f, indent=2, default=str)

        logger.info(f"Saved model '{name}' version '{version}' to {version_dir}")
        return metadata

    def _checksum_of_dir(self, path: str) -> str:
        hasher = hashlib.sha256()
        for root, _, files in os.walk(path):
            for fname in sorted(files):
                fpath = os.path.join(root, fname)
                with open(fpath, "rb") as f:
                    for chunk in iter(lambda: f.read(8192), b""):
                        hasher.update(chunk)
        return hasher.hexdigest()

    def load_model(
        self,
        adapter: BaseModelAdapter,
        name: str,
        version: Optional[str] = None,
        artifact_filename: str = "model.bin",
    ) -> Tuple[BaseModelAdapter, ModelMetadata]:
        model_dir = self._model_dir(name)
        if version is None:
            version = self.get_latest_version(name)
        version_dir = os.path.join(model_dir, version)
        if not os.path.exists(version_dir):
            raise FileNotFoundError(f"No such model version: {name}/{version}")

        artifact_path = os.path.join(version_dir, artifact_filename)
        adapter.load(artifact_path)

        metadata_path = os.path.join(version_dir, "metadata.json")
        with open(metadata_path, "r") as f:
            metadata_dict = json.load(f)
        metadata = ModelMetadata(**metadata_dict)

        return adapter, metadata

    def get_latest_version(self, name: str) -> str:
        model_dir = self._model_dir(name)
        versions = [d for d in os.listdir(model_dir) if d.startswith("v")]
        if not versions:
            raise FileNotFoundError(f"No versions found for model '{name}'.")
        version_numbers = sorted(int(v[1:]) for v in versions)
        return f"v{version_numbers[-1]}"

    def list_versions(self, name: str) -> List[str]:
        model_dir = self._model_dir(name)
        return sorted(
            [d for d in os.listdir(model_dir) if d.startswith("v")],
            key=lambda x: int(x[1:]),
        )

    def delete_version(self, name: str, version: str):
        version_dir = os.path.join(self._model_dir(name), version)
        if os.path.exists(version_dir):
            shutil.rmtree(version_dir)
            logger.info(f"Deleted model version {name}/{version}")


# --------------------------------------------------------------------------
# Pipeline Steps
# --------------------------------------------------------------------------

class PipelineStep(ABC):
    @abstractmethod
    def run(self, context: Dict[str, Any]) -> Dict[str, Any]:
        ...


class DataSplitStep(PipelineStep):
    def __init__(self, validation_split: float = 0.2, random_state: int = 42):
        self.validation_split = validation_split
        self.random_state = random_state

    def run(self, context: Dict[str, Any]) -> Dict[str, Any]:
        X, y = context["X"], context["y"]
        rng = np.random.RandomState(self.random_state)
        n = len(X)
        indices = np.arange(n)
        rng.shuffle(indices)
        split_point = int(n * (1 - self.validation_split))
        train_idx, val_idx = indices[:split_point], indices[split_point:]

        context["X_train"] = X[train_idx]
        context["y_train"] = y[train_idx]
        context["X_val"] = X[val_idx]
        context["y_val"] = y[val_idx]
        return context


class PreprocessingStep(PipelineStep):
    def __init__(self, transform_fn: Optional[Callable[[np.ndarray], np.ndarray]] = None):
        self.transform_fn = transform_fn
        self.mean_ = None
        self.std_ = None

    def run(self, context: Dict[str, Any]) -> Dict[str, Any]:
        X_train = context["X_train"]
        if self.transform_fn is not None:
            context["X_train"] = self.transform_fn(X_train)
            if "X_val" in context:
                context["X_val"] = self.transform_fn(context["X_val"])
            if "X_test" in context:
                context["X_test"] = self.transform_fn(context["X_test"])
        else:
            self.mean_ = X_train.mean(axis=0)
            self.std_ = X_train.std(axis=0) + 1e-8
            context["X_train"] = (X_train - self.mean_) / self.std_
            if "X_val" in context:
                context["X_val"] = (context["X_val"] - self.mean_) / self.std_
            if "X_test" in context:
                context["X_test"] = (context["X_test"] - self.mean_) / self.std_
        return context


class TrainingStep(PipelineStep):
    def __init__(
        self,
        backend: Union[str, Backend],
        model_builder: Callable,
        hyperparams: Dict[str, Any],
        training_config: Optional[TrainingConfig] = None,
    ):
        self.backend = backend
        self.model_builder = model_builder
        self.hyperparams = hyperparams
        self.training_config = training_config or TrainingConfig()

    def run(self, context: Dict[str, Any]) -> Dict[str, Any]:
        adapter = AdapterFactory.create(self.backend, self.model_builder, **self.hyperparams)
        adapter.build()
        metrics = adapter.fit(
            context["X_train"],
            context["y_train"],
            context.get("X_val"),
            context.get("y_val"),
            self.training_config,
        )
        context["adapter"] = adapter
        context["metrics"] = metrics
        return context


class TuningStep(PipelineStep):
    def __init__(
        self,
        backend: Union[str, Backend],
        model_builder: Callable,
        search_space: HyperparameterSpace,
        training_config: Optional[TrainingConfig] = None,
    ):
        self.backend = backend
        self.model_builder = model_builder
        self.search_space = search_space
        self.training_config = training_config or TrainingConfig()

    def run(self, context: Dict[str, Any]) -> Dict[str, Any]:
        tuner = HyperparameterTuner(
            self.backend, self.model_builder, self.search_space, self.training_config
        )
        best_params = tuner.search(context["X_train"], context["y_train"])
        context["best_params"] = best_params
        context["adapter"] = tuner.best_adapter_
        context["tuning_results"] = tuner.results_
        return context


class EvaluationStep(PipelineStep):
    def __init__(self, scorer: Optional[Callable[[np.ndarray, np.ndarray], float]] = None):
        self.scorer = scorer or (lambda y_true, y_pred: float(np.mean(y_true == y_pred)))

    def run(self, context: Dict[str, Any]) -> Dict[str, Any]:
        adapter = context["adapter"]
        if "X_val" in context and context["X_val"] is not None:
            preds = adapter.predict(context["X_val"])
            score = self.scorer(context["y_val"], preds)
            context.setdefault("metrics", {})["eval_score"] = score
            logger.info(f"Evaluation score: {score:.4f}")
        return context


class VersioningStep(PipelineStep):
    def __init__(
        self,
        registry: ModelRegistry,
        model_name: str,
        backend: Union[str, Backend],
        tags: Optional[List[str]] = None,
    ):
        self.registry = registry
        self.model_name = model_name
        self.backend = backend
        self.tags = tags or []

    def run(self, context: Dict[str, Any]) -> Dict[str, Any]:
        adapter = context["adapter"]
        metrics = context.get("metrics", {})
        hyperparams = context.get("best_params", context.get("hyperparams", {}))
        training_config = context.get("training_config", TrainingConfig())

        metadata = self.registry.save_model(
            adapter,
            name=self.model_name,
            backend=self.backend,
            metrics=metrics,
            hyperparameters=hyperparams,
            training_config=training_config,
            tags=self.tags,
        )
        context["model_metadata"] = metadata
        return context


# --------------------------------------------------------------------------
# Main Pipeline Orchestrator
# --------------------------------------------------------------------------

class MLPipeline:
    def __init__(self, steps: Optional[List[PipelineStep]] = None):
        self.steps = steps or []
        self.context: Dict[str, Any] = {}

    def add_step(self, step: PipelineStep) -> "MLPipeline":
        self.steps.append(step)
        return self

    def run(self, X: np.ndarray, y: np.ndarray, **initial_context) -> Dict[str, Any]:
        self.context = {"X": np.asarray(X), "y": np.asarray(y), **initial_context}
        for step in self.steps:
            step_name = step.__class__.__name__
            logger.info(f"Running pipeline step: {step_name}")
            try:
                self.context = step.run(self.context)
            except Exception as e:
                logger.error(f"Step {step_name} failed: {e}")
                logger.debug(traceback.format_exc())
                raise
        return self.context


# --------------------------------------------------------------------------
# Example: Logistic Regression Workflow (demonstration)
# --------------------------------------------------------------------------

def build_logistic_regression(**kwargs):
    """Model builder function used with the sklearn adapter."""
    if not SKLEARN_AVAILABLE:
        raise ImportError("scikit-learn is required for this example.")
    from sklearn.linear_model import LogisticRegression
    return LogisticRegression(**kwargs)


def run_logistic_regression_example():
    if not SKLEARN_AVAILABLE:
        logger.warning("scikit-learn not available, skipping example.")
        return

    np.random.seed(42)
    n_samples, n_features = 500, 5
    X = np.random.randn(n_samples, n_features)
    true_weights = np.random.randn(n_features)
    logits = X @ true_weights
    probs = 1 / (1 + np.exp(-logits))
    y = (probs > 0.5).astype(int)

    training_config = TrainingConfig(random_state=42, validation_split=0.2)

    search_space = HyperparameterSpace(
        params={
            "C": [0.01, 0.1, 1.0, 10.0],
            "penalty": ["l2"],
            "solver": ["lbfgs"],
            "max_iter": [200],
        },
        strategy=SearchStrategy.GRID,
        cv_folds=3,
    )

    registry = ModelRegistry(root_dir="./model_registry")

    pipeline = MLPipeline(
        steps=[
            DataSplitStep(validation_split=0.2, random_state=42),
            PreprocessingStep(),
            TuningStep(
                backend=Backend.SKLEARN,
                model_builder=build_logistic_regression,
                search_space=search_space,
                training_config=training_config,
            ),
            EvaluationStep(),
            VersioningStep(
                registry=registry,
                model_name="logistic_regression_demo",
                backend=Backend.SKLEARN,
                tags=["baseline", "logistic_regression"],
            ),
        ]
    )

    result_context = pipeline.run(X, y, training_config=training_config)

    logger.info(f"Final metrics: {result_context.get('metrics')}")
    logger.info(f"Best hyperparameters: {result_context.get('best_params')}")
    logger.info(f"Model metadata: {result_context.get('model_metadata')}")

    return result_context


if __name__ == "__main__":
    run_logistic_regression_example()
