    def _sma(values: Sequence[float], window: int) -> float:
        return sum(values[-window:]) / window

    def generate_signal(self, snapshot: MarketSnapshot) -> TradeSignal:
        closes = snapshot.close_prices

        if len(closes) < self.required_history():
            return TradeSignal(
                symbol=snapshot.symbol,
                timestamp=snapshot.timestamp,
                signal=Signal.HOLD,
                confidence=0.0,
                metadata={"reason": "insufficient_history"},
            )

        # Current window SMAs
        short_sma_now = self._sma(closes, self.short_window)
        long_sma_now = self._sma(closes, self.long_window)

        # Previous window SMAs (one bar earlier)
        prev_closes = closes[:-1]
        short_sma_prev = self._sma(prev_closes, self.short_window)
        long_sma_prev = self._sma(prev_closes, self.long_window)

        diff_now = short_sma_now - long_sma_now
        diff_prev = short_sma_prev - long_sma_prev

        signal = Signal.HOLD
        if diff_prev <= 0 and diff_now > 0:
            signal = Signal.BUY
        elif diff_prev >= 0 and diff_now < 0:
            signal = Signal.SELL

        confidence = min(1.0, abs(diff_now) / long_sma_now) if long_sma_now else 0.0

        return TradeSignal(
            symbol=snapshot.symbol,
            timestamp=snapshot.timestamp,
            signal=signal,
            confidence=confidence,
            metadata={
                "short_sma": short_sma_now,
                "long_sma": long_sma_now,
                "diff": diff_now,
            },
        )


# ---------------------------------------------------------------------------
# Portfolio / Broker abstraction
# ---------------------------------------------------------------------------

class Portfolio:
    """Tracks cash, positions, and trade history."""

    def __init__(self, starting_cash: float = 100_000.0):
        self.cash = starting_cash
        self.starting_cash = starting_cash
        self.positions: Dict[str, Position] = {}
        self.trades: List[Trade] = []
        self.equity_curve: List[Dict[str, Any]] = []

    def get_position(self, symbol: str) -> Position:
        if symbol not in self.positions:
            self.positions[symbol] = Position(symbol=symbol)
        return self.positions[symbol]

    def apply_fill(self, order: Order) -> None:
        pos = self.get_position(order.symbol)
        fill_price = order.filled_price or order.price

        if order.side == OrderSide.BUY:
            cost = fill_price * order.quantity
            if cost > self.cash:
                # scale down quantity to available cash (paper/backtest safety)
                order.quantity = self.cash / fill_price if fill_price > 0 else 0.0
                cost = fill_price * order.quantity
            total_qty = pos.quantity + order.quantity
            if total_qty > 0:
                pos.avg_price = (
                    (pos.avg_price * pos.quantity) + (fill_price * order.quantity)
                ) / total_qty
            pos.quantity = total_qty
            self.cash -= cost
        else:  # SELL
            sell_qty = min(order.quantity, pos.quantity)
            order.quantity = sell_qty
            proceeds = fill_price * sell_qty
            pnl = (fill_price - pos.avg_price) * sell_qty
            pos.quantity -= sell_qty
            if pos.quantity == 0:
                pos.avg_price = 0.0
            self.cash += proceeds
            self.trades.append(Trade(order=order, pnl=pnl))
            return

        self.trades.append(Trade(order=order, pnl=0.0))

    def total_equity(self, prices: Dict[str, float]) -> float:
        equity = self.cash
        for symbol, pos in self.positions.items():
            price = prices.get(symbol, pos.avg_price)
            equity += pos.market_value(price)
        return equity

    def record_equity(self, timestamp: datetime, prices: Dict[str, float]) -> None:
        self.equity_curve.append({
            "timestamp": timestamp,
            "equity": self.total_equity(prices),
            "cash": self.cash,
        })


# ---------------------------------------------------------------------------
# Execution engines (Backtest / Paper / Live)
# ---------------------------------------------------------------------------

class ExecutionEngine(abc.ABC):
    """Abstract interface for order execution across modes."""

    def __init__(self, portfolio: Portfolio):
        self.portfolio = portfolio

    @abc.abstractmethod
    def execute_order(self, symbol: str, side: OrderSide, quantity: float, price: float,
                       timestamp: datetime) -> Order:
        raise NotImplementedError

    def _make_order(self, symbol: str, side: OrderSide, quantity: float, price: float,
                     timestamp: datetime) -> Order:
        return Order(
            order_id=str(uuid.uuid4()),
            symbol=symbol,
            side=side,
            quantity=quantity,
            price=price,
            timestamp=timestamp,
        )


class BacktestExecutionEngine(ExecutionEngine):
    """Simulated instantaneous fills at the given price (no slippage model)."""

    def execute_order(self, symbol: str, side: OrderSide, quantity: float, price: float,
                       timestamp: datetime) -> Order:
        order = self._make_order(symbol, side, quantity, price, timestamp)
        order.status = OrderStatus.FILLED
        order.filled_price = price
        order.filled_timestamp = timestamp
        self.portfolio.apply_fill(order)
        return order


class PaperTradingExecutionEngine(ExecutionEngine):
    """Simulated fills with small artificial slippage, mimicking real market friction."""

    def __init__(self, portfolio: Portfolio, slippage_bps: float = 5.0):
        super().__init__(portfolio)
        self.slippage_bps = slippage_bps

    def execute_order(self, symbol: str, side: OrderSide, quantity: float, price: float,
                       timestamp: datetime) -> Order:
        slippage_factor = self.slippage_bps / 10_000.0
        adjusted_price = price * (1 + slippage_factor) if side == OrderSide.BUY else price * (1 - slippage_factor)

        order = self._make_order(symbol, side, quantity, adjusted_price, timestamp)
        order.status = OrderStatus.FILLED
        order.filled_price = adjusted_price
        order.filled_timestamp = timestamp
        self.portfolio.apply_fill(order)
        logger.info(f"[PAPER] Filled {side.value} {quantity} {symbol} @ {adjusted_price:.4f}")
        return order


class LiveExecutionEngine(ExecutionEngine):
    """
    Live trading execution stub.

    In a real system this would route orders to a broker API (e.g. via REST/websocket).
    This implementation raises unless a broker adapter callable is provided.
    """

    def __init__(self, portfolio: Portfolio, broker_adapter: Optional[Any] = None):
        super().__init__(portfolio)
        self.broker_adapter = broker_adapter

    def execute_order(self, symbol: str, side: OrderSide, quantity: float, price: float,
                       timestamp: datetime) -> Order:
        order = self._make_order(symbol, side, quantity, price, timestamp)

        if self.broker_adapter is None:
            logger.warning(
                "[LIVE] No broker adapter configured; order will be marked REJECTED. "
                "Provide a broker_adapter with a `submit_order(order)` method for real trading."
            )
            order.status = OrderStatus.REJECTED
            return order

        result = self.broker_adapter.submit_order(order)
        filled_price = result.get("filled_price", price)
        order.status = OrderStatus.FILLED if result.get("filled") else OrderStatus.REJECTED
        order.filled_price = filled_price
        order.filled_timestamp = timestamp
        if order.status == OrderStatus.FILLED:
            self.portfolio.apply_fill(order)
        logger.info(f"[LIVE] Order {order.order_id} status={order.status.value}")
        return order


def create_execution_engine(mode: ExecutionMode, portfolio: Portfolio, **kwargs) -> ExecutionEngine:
    if mode == ExecutionMode.BACKTEST:
        return BacktestExecutionEngine(portfolio)
    elif mode == ExecutionMode.PAPER:
        return PaperTradingExecutionEngine(portfolio, slippage_bps=kwargs.get("slippage_bps", 5.0))
    elif mode == ExecutionMode.LIVE:
        return LiveExecutionEngine(portfolio, broker_adapter=kwargs.get("broker_adapter"))
    else:
        raise ValueError(f"Unknown execution mode: {mode}")


# ---------------------------------------------------------------------------
# Position sizing
# ---------------------------------------------------------------------------

class PositionSizer:
    """Simple fixed-fraction position sizing."""

    def __init__(self, fraction_of_cash: float = 0.10):
        if not (0 < fraction_of_cash <= 1.0):
            raise ValueError("fraction_of_cash must be within (0, 1].")
        self.fraction_of_cash = fraction_of_cash

    def size(self, portfolio: Portfolio, price: float) -> float:
        if price <= 0:
            return 0.0
        allocation = portfolio.cash * self.fraction_of_cash
        return allocation / price


# ---------------------------------------------------------------------------
# Trading System Orchestrator
# ---------------------------------------------------------------------------

class TradingSystem:
    """
    Orchestrates strategy signal generation, position sizing, and order execution
    across backtesting, paper, and live modes.
    """

    def __init__(
        self,
        strategy: BaseStrategy,
        mode: ExecutionMode = ExecutionMode.BACKTEST,
        starting_cash: float = 100_000.0,
        position_sizer: Optional[PositionSizer] = None,
        **engine_kwargs,
    ):
        self.strategy = strategy
        self.mode = mode
        self.portfolio = Portfolio(starting_cash=starting_cash)
        self.position_sizer = position_sizer or PositionSizer(fraction_of_cash=0.10)
        self.execution_engine = create_execution_engine(mode, self.portfolio, **engine_kwargs)
        self.signal_log: List[TradeSignal] = []

    def _handle_signal(self, signal: TradeSignal, price: float, timestamp: datetime) -> Optional[Order]:
        symbol = signal.symbol
        position = self.portfolio.get_position(symbol)

        if signal.signal == Signal.BUY and position.quantity == 0:
            quantity = self.position_sizer.size(self.portfolio, price)
            if quantity <= 0:
                return None
            return self.execution_engine.execute_order(symbol, OrderSide.BUY, quantity, price, timestamp)

        elif signal.signal == Signal.SELL and position.quantity > 0:
            return self.execution_engine.execute_order(symbol, OrderSide.SELL, position.quantity, price, timestamp)

        return None

    def process_snapshot(self, snapshot: MarketSnapshot) -> Optional[Order]:
        if not self.strategy.is_ready(snapshot):
            return None

        signal = self.strategy.generate_signal(snapshot)
        self.signal_log.append(signal)

        latest_bar = snapshot.latest_bar
        if latest_bar is None:
            return None

        order = self._handle_signal(signal, latest_bar.close, snapshot.timestamp)

        prices = {snapshot.symbol: latest_bar.close}
        self.portfolio.record_equity(snapshot.timestamp, prices)
        return order

    def run_backtest(self, bars: Sequence[Bar]) -> Dict[str, Any]:
        if self.mode != ExecutionMode.BACKTEST:
            raise RuntimeError("run_backtest can only be used when mode == ExecutionMode.BACKTEST")

        history: List[Bar] = []
        for bar in bars:
            history.append(bar)
            snapshot = MarketSnapshot(symbol=bar.symbol, timestamp=bar.timestamp, bars=list(history))
            self.process_snapshot(snapshot)

        final_prices = {bars[-1].symbol: bars[-1].close} if bars else {}
        final_equity = self.portfolio.total_equity(final_prices)

        return self._performance_report(final_equity)

    def run_paper_step(self, snapshot: MarketSnapshot) -> Optional[Order]:
        if self.mode != ExecutionMode.PAPER:
            raise RuntimeError("run_paper_step can only be used when mode == ExecutionMode.PAPER")
        return self.process_snapshot(snapshot)

    def run_live_step(self, snapshot: MarketSnapshot) -> Optional[Order]:
        if self.mode != ExecutionMode.LIVE:
            raise RuntimeError("run_live_step can only be used when mode == ExecutionMode.LIVE")
        return self.process_snapshot(snapshot)

    def _performance_report(self, final_equity: float) -> Dict[str, Any]:
        equities = [pt["equity"] for pt in self.portfolio.equity_curve]
        returns = []
        for i in range(1, len(equities)):
            prev = equities[i - 1]
            if prev != 0:
                returns.append((equities[i] - prev) / prev)

        total_return = (final_equity - self.portfolio.starting_cash) / self.portfolio.starting_cash
        volatility = statistics.pstdev(returns) if len(returns) > 1 else 0.0
        sharpe = (statistics.mean(returns) / volatility) if volatility > 0 else 0.0

        winning_trades = [t for t in self.portfolio.trades if t.pnl > 0]
        losing_trades = [t for t in self.portfolio.trades if t.pnl < 0]

        return {
            "starting_cash": self.portfolio.starting_cash,
            "final_equity": final_equity,
            "total_return_pct": total_return * 100,
            "num_trades": len(self.portfolio.trades),
            "winning_trades": len(winning_trades),
            "losing_trades": len(losing_trades),
            "sharpe_like_ratio": sharpe,
            "equity_curve": self.portfolio.equity_curve,
        }


# ---------------------------------------------------------------------------
# Synthetic data generation (for demonstration purposes)
# ---------------------------------------------------------------------------

def generate_synthetic_bars(symbol: str, num_bars: int = 200, start_price: float = 100.0,
                             seed: int = 42) -> List[Bar]:
    import random
    rng = random.Random(seed)
    bars = []
    price = start_price
    timestamp = datetime(2023, 1, 1)

    for i in range(num_bars):
        drift = 0.0005
        shock = rng.gauss(0, 0.01)
        price = max(0.01, price * (1 + drift + shock))
        high = price * (1 + abs(rng.gauss(0, 0.003)))
        low = price * (1 - abs(rng.gauss(0, 0.003)))
        open_price = price * (1 + rng.gauss(0, 0.002))
        volume = rng.uniform(1000, 5000)

        bars.append(Bar(
            timestamp=timestamp,
            symbol=symbol,
            open=open_price,
            high=high,
            low=low,
            close=price,
            volume=volume,
        ))
        timestamp += timedelta(days=1)

    return bars


# ---------------------------------------------------------------------------
# Demonstration entry point
# ---------------------------------------------------------------------------

def main() -> None:
    symbol = "DEMO"
    bars = generate_synthetic_bars(symbol=symbol, num_bars=250)

    strategy = SimpleMovingAverageStrategy(short_window=10, long_window=30)

    system = TradingSystem(
        strategy=strategy,
        mode=ExecutionMode.BACKTEST,
        starting_cash=100_000.0,
        position_sizer=PositionSizer(fraction_of_cash=0.25),
    )

    report = system.run_backtest(bars)

    logger.info("=== Backtest Report ===")
    for key, value in report.items():
        if key == "equity_curve":
            continue
        logger.info(f"{key}: {value}")


if __name__ == "__main__":
    main()
