import uuid
import datetime
from decimal import Decimal, ROUND_HALF_UP
from collections import defaultdict


class FinancialSystem:
    def __init__(self):
        self.accounts = {}
        self.transactions = {}
        self.audit_trail = []
        self.exchange_rates = {}
        self.tax_rates = {}
        self.compliance_rules = {
            "max_transaction_amount": Decimal("1000000"),
