    # ----------------------------
    # Utility / Internal Helpers
    # ----------------------------
    def _now(self):
        return datetime.datetime.utcnow()

    def _to_decimal(self, value):
        try:
            return Decimal(str(value))
        except Exception:
            raise ValueError(f"Invalid numeric value: {value}")

    def _log_audit(self, action, details):
        entry = {
            "id": str(uuid.uuid4()),
            "timestamp": self._now(),
            "action": action,
            "details": details,
        }
        self.audit_trail.append(entry)
        return entry

    def _generate_id(self, prefix="ID"):
        return f"{prefix}-{uuid.uuid4().hex[:12]}"

    # ----------------------------
    # Account Management
    # ----------------------------
    def create_account(self, owner_name, account_type="checking", currency="USD",
                        initial_balance=0, kyc_verified=False, country="US"):
        account_id = self._generate_id("ACC")
        balance = self._to_decimal(initial_balance)

        if balance < 0:
            raise ValueError("Initial balance cannot be negative")

        account = {
            "account_id": account_id,
            "owner_name": owner_name,
            "account_type": account_type,
            "currency": currency,
            "balance": balance,
            "kyc_verified": kyc_verified,
            "country": country,
            "status": "active",
            "created_at": self._now(),
            "history": [],
        }
        self.accounts[account_id] = account
        self._log_audit("create_account", {
            "account_id": account_id,
            "owner_name": owner_name,
            "initial_balance": str(balance),
        })
        return account_id

    def get_account(self, account_id):
        account = self.accounts.get(account_id)
        if not account:
            raise ValueError(f"Account {account_id} not found")
        return account

    def close_account(self, account_id):
        account = self.get_account(account_id)
        if account["balance"] != 0:
            raise ValueError("Cannot close account with non-zero balance")
        account["status"] = "closed"
        self._log_audit("close_account", {"account_id": account_id})

    def freeze_account(self, account_id, reason=""):
        account = self.get_account(account_id)
        account["status"] = "frozen"
        self._log_audit("freeze_account", {"account_id": account_id, "reason": reason})

    def unfreeze_account(self, account_id):
        account = self.get_account(account_id)
        account["status"] = "active"
        self._log_audit("unfreeze_account", {"account_id": account_id})

    # ----------------------------
    # Compliance Checks
    # ----------------------------
    def run_compliance_check(self, account_id, amount=None):
        account = self.get_account(account_id)
        violations = []

        if account["status"] != "active":
            violations.append(f"Account status is '{account['status']}', not active")

        if self.compliance_rules["require_kyc"] and not account["kyc_verified"]:
            violations.append("KYC verification required")

        if account["country"] in self.compliance_rules["restricted_countries"]:
            violations.append(f"Country '{account['country']}' is restricted")

        if amount is not None:
            amt = self._to_decimal(amount)
            if amt > self.compliance_rules["max_transaction_amount"]:
                violations.append("Transaction amount exceeds maximum allowed")

        today = self._now().date()
        if self._daily_tx_count[(account_id, today)] >= self.compliance_rules["max_daily_transactions"]:
            violations.append("Daily transaction limit exceeded")

        passed = len(violations) == 0
        self._log_audit("compliance_check", {
            "account_id": account_id,
            "passed": passed,
            "violations": violations,
        })
        return passed, violations

    def set_compliance_rule(self, rule_name, value):
        if rule_name not in self.compliance_rules:
            raise ValueError(f"Unknown compliance rule: {rule_name}")
        self.compliance_rules[rule_name] = value
        self._log_audit("update_compliance_rule", {"rule": rule_name, "value": str(value)})

    def add_restricted_country(self, country_code):
        self.compliance_rules["restricted_countries"].add(country_code)

    # ----------------------------
    # Currency Conversion
    # ----------------------------
    def set_exchange_rate(self, from_currency, to_currency, rate):
        rate = self._to_decimal(rate)
        if rate <= 0:
            raise ValueError("Exchange rate must be positive")
        self.exchange_rates[(from_currency, to_currency)] = rate
        self.exchange_rates[(to_currency, from_currency)] = Decimal("1") / rate
        self._log_audit("set_exchange_rate", {
            "from": from_currency, "to": to_currency, "rate": str(rate)
        })

    def convert_currency(self, amount, from_currency, to_currency):
        amount = self._to_decimal(amount)
        if from_currency == to_currency:
            return amount
        rate = self.exchange_rates.get((from_currency, to_currency))
        if rate is None:
            raise ValueError(f"No exchange rate found for {from_currency}->{to_currency}")
        converted = (amount * rate).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return converted

    # ----------------------------
