        account["balance"] += amount
        tx_id = self._record_transaction(
            account_id, "deposit", amount, description, account["currency"]
        )
        account["history"].append(tx_id)
        return tx_id

    def withdraw(self, account_id, amount, description="Withdrawal"):
        account = self.get_account(account_id)
        amount = self._to_decimal(amount)
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")
        if amount > account["balance"]:
            raise ValueError("Insufficient funds")

        passed, violations = self.run_compliance_check(account_id, amount)
        if not passed:
            raise PermissionError(f"Compliance check failed: {violations}")

        account["balance"] -= amount
        tx_id = self._record_transaction(
            account_id, "withdrawal", -amount, description, account["currency"]
        )
        account["history"].append(tx_id)
        return tx_id

    def transfer(self, from_account_id, to_account_id, amount, description="Transfer"):
        from_account = self.get_account(from_account_id)
        to_account = self.get_account(to_account_id)
        amount = self._to_decimal(amount)

        if amount <= 0:
            raise ValueError("Transfer amount must be positive")
        if amount > from_account["balance"]:
            raise ValueError("Insufficient funds")

        for acc_id in (from_account_id, to_account_id):
            passed, violations = self.run_compliance_check(acc_id, amount)
            if not passed:
                raise PermissionError(f"Compliance check failed for {acc_id}: {violations}")

        converted_amount = amount
        if from_account["currency"] != to_account["currency"]:
            converted_amount = self.convert_currency(
                amount, from_account["currency"], to_account["currency"]
            )

        from_account["balance"] -= amount
        to_account["balance"] += converted_amount

        out_tx = self._record_transaction(
            from_account_id, "transfer_out", -amount, description,
            from_account["currency"], related_account=to_account_id
        )
        in_tx = self._record_transaction(
            to_account_id, "transfer_in", converted_amount, description,
            to_account["currency"], related_account=from_account_id
        )
        from_account["history"].append(out_tx)
        to_account["history"].append(in_tx)
        return out_tx, in_tx

    def _record_transaction(self, account_id, tx_type, amount, description, currency, related_account=None):
        tx_id = self._generate_id("TXN")
        today = self._now().date()
        self._daily_tx_count[(account_id, today)] += 1

        transaction = {
            "transaction_id": tx_id,
            "account_id": account_id,
            "type": tx_type,
            "amount": amount,
            "currency": currency,
            "description": description,
            "timestamp": self._now(),
            "related_account": related_account,
