    def reconcile_account(self, account_id, external_balance):
        account = self.get_account(account_id)
        external_balance = self._to_decimal(external_balance)
        internal_balance = account["balance"]
        difference = internal_balance - external_balance

        result = {
            "account_id": account_id,
