                f"cash {account['cash_balance']:.2f}, buying power {account['buying_power']:.2f}"
            )
    elif side == "SELL_TO_OPEN":
        if not is_covered:
            underlying_price = market["last_price"]
            naked_margin_requirement = (underlying_price * 0.20 * contracts * contract_multiplier)
            if naked_margin_requirement > account["margin_balance"]:
                result.add_error(
                    f"Insufficient margin for naked option write: required "
                    f"{naked_margin_requirement:.2f}, available {account['margin_balance']:.2f}"
                )
            if not account["margin_account"]:
                result.add_error("Account is not approved for margin trading (required for naked writes)")

    # ---------------- Risk assessment ----------------
    volatility = market["volatility"]
    if account["risk_tolerance"] == "LOW" and (volatility > 0.25 or (side == "SELL_TO_OPEN" and not is_covered)):
