        }
        fields = [
            "GS", code_map.get(doc_type, "XX"),
            self.sender_id, self.receiver_id,
            datetime.now().strftime("%Y%m%d"),
            datetime.now().strftime("%H%M"),
            control_number, "X", "004010",
        ]
        return self.ELEMENT_SEP.join(fields) + self.SEGMENT_TERM

    def encode(self, document: dict, doc_type: DocumentType, control_number: str) -> str:
        """Transform a business document dict into an EDI X12 string."""
        ts_code = self.TRANSACTION_SET_MAP.get(doc_type)
        if not ts_code:
            raise DocumentTransformError(
                f"No X12 transaction set mapping for document type {doc_type}",
                code="EDI_UNSUPPORTED_DOC_TYPE",
            )

        segments = [self.build_isa_segment(control_number)]
        segments.append(self.build_gs_segment(doc_type, control_number))
        segments.append(
            self.ELEMENT_SEP.join(["ST", ts_code, control_number.zfill(4)]) + self.SEGMENT_TERM
        )

        segments.append(self._build_bx_or_beg(document, ts_code))

        for idx, line in enumerate(document.get("line_items", []), start=1):
            segments.append(self._build_line_segment(line, idx))

        total = document.get("total_amount")
        if total is not None:
            segments.append(
                self.ELEMENT_SEP.join(["TDS", str(int(round(float(total) * 100)))]) + self.SEGMENT_TERM
            )

        segment_count = len(segments) - 2  # excluding ISA/GS
        segments.append(
            self.ELEMENT_SEP.join(["SE", str(segment_count + 1), control_number.zfill(4)]) + self.SEGMENT_TERM
        )
        segments.append(
            self.ELEMENT_SEP.join(["GE", "1", control_number]) + self.SEGMENT_TERM
        )
        segments.append(
            self.ELEMENT_SEP.join(["IEA", "1", control_number.zfill(9)]) + self.SEGMENT_TERM
        )

        return "".join(segments)

    def _build_bx_or_beg(self, document: dict, ts_code: str) -> str:
        doc_number = str(document.get("document_number", ""))
        doc_date = document.get("document_date", datetime.now().strftime("%Y%m%d"))
        if ts_code == "850":
            fields = ["BEG", "00", "SA", doc_number, "", doc_date]
        elif ts_code == "810":
            fields = ["BIG", doc_date, doc_number]
        elif ts_code == "856":
            fields = ["BSN", "00", doc_number, doc_date]
        else:
            fields = ["BEG", "00", "SA", doc_number, "", doc_date]
        return self.ELEMENT_SEP.join(fields) + self.SEGMENT_TERM

    def _build_line_segment(self, line: dict, index: int) -> str:
        qty = line.get("quantity", 0)
        unit = line.get("unit_of_measure", "EA")
        price = line.get("unit_price", 0)
        sku = line.get("sku", line.get("item_id", ""))
        fields = ["PO1", str(index), str(qty), unit, f"{float(price):.2f}", "PE", "IN", str(sku)]
        return self.ELEMENT_SEP.join(fields) + self.SEGMENT_TERM

    def decode(self, edi_string: str) -> dict:
        """Parse an EDI X12 string into a structured dictionary."""
        if not edi_string or not edi_string.strip():
            raise EDIParsingError("Empty EDI payload", code="EDI_EMPTY")

        raw = edi_string.strip()
        segments = [s for s in raw.split(self.SEGMENT_TERM) if s.strip()]

        result: Dict[str, Any] = {
            "isa": None,
            "gs": None,
            "st": None,
            "line_items": [],
            "total_amount": None,
            "document_number": None,
            "document_date": None,
        }

        try:
            for seg in segments:
                elements = seg.split(self.ELEMENT_SEP)
                seg_id = elements[0]

                if seg_id == "ISA":
                    result["isa"] = {
                        "sender_id": elements[6].strip() if len(elements) > 6 else None,
                        "receiver_id": elements[8].strip() if len(elements) > 8 else None,
                        "control_number": elements[13] if len(elements) > 13 else None,
                    }
                elif seg_id == "GS":
                    result["gs"] = {
                        "functional_id": elements[1] if len(elements) > 1 else None,
                        "sender_id": elements[2] if len(elements) > 2 else None,
                        "receiver_id": elements[3] if len(elements) > 3 else None,
                    }
                elif seg_id == "ST":
                    result["st"] = {
                        "transaction_set": elements[1] if len(elements) > 1 else None,
                        "control_number": elements[2] if len(elements) > 2 else None,
                    }
                elif seg_id in ("BEG", "BIG", "BSN"):
                    if seg_id == "BEG" and len(elements) > 3:
                        result["document_number"] = elements[3]
                        result["document_date"] = elements[5] if len(elements) > 5 else None
                    elif seg_id == "BIG" and len(elements) > 2:
                        result["document_date"] = elements[1]
                        result["document_number"] = elements[2]
                    elif seg_id == "BSN" and len(elements) > 3:
                        result["document_number"] = elements[2]
                        result["document_date"] = elements[3]
                elif seg_id == "PO1":
                    result["line_items"].append({
                        "line_number": elements[1] if len(elements) > 1 else None,
                        "quantity": _safe_float(elements[2]) if len(elements) > 2 else None,
                        "unit_of_measure": elements[3] if len(elements) > 3 else None,
                        "unit_price": _safe_float(elements[4]) if len(elements) > 4 else None,
                        "sku": elements[7] if len(elements) > 7 else None,
                    })
                elif seg_id == "TDS":
                    if len(elements) > 1:
                        try:
                            result["total_amount"] = int(elements[1]) / 100.0
                        except ValueError:
                            pass
        except (IndexError, ValueError) as exc:
            raise EDIParsingError(f"Malformed EDI segment: {exc}", code="EDI_PARSE_ERROR")

        return result


def _safe_float(value: str) -> Optional[float]:
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


