class ERPXmlHandler:
    """Handles conversion between XML and dict/business documents."""

    def __init__(self, root_tag: str = "Document", namespace: Optional[str] = None):
        self.root_tag = root_tag
        self.namespace = namespace

    def _qualify(self, tag: str) -> str:
        if self.namespace:
            return f"{{{self.namespace}}}{tag}"
        return tag

    def dict_to_xml(self, data: dict, root_tag: Optional[str] = None) -> ET.Element:
        root = ET.Element(self._qualify(root_tag or self.root_tag))
        self._build_element(root, data)
        return root

    def _build_element(self, parent: ET.Element, value: Any):
        if isinstance(value, dict):
            for key, val in value.items():
                if isinstance(val, list):
                    for item in val:
                        child = ET.SubElement(parent, self._qualify(str(key)))
                        self._build_element(child, item)
                else:
                    child = ET.SubElement(parent, self._qualify(str(key)))
                    self._build_element(child, val)
        elif isinstance(value, list):
            for item in value:
                child = ET.SubElement(parent, self._qualify("Item"))
                self._build_element(child, item)
        else:
            parent.text = "" if value is None else str(value)

    def to_string(self, element: ET.Element, encoding: str = "unicode", xml_declaration: bool = False) -> str:
        try:
            if xml_declaration:
                return ET.tostring(element, encoding="utf-8", xml_declaration=True).decode("utf-8")
            return ET.tostring(element, encoding=encoding)
        except Exception as exc:
            raise DocumentTransformError(f"Failed to serialize XML: {exc}", code="XML_SERIALIZE_ERROR")

    def xml_to_dict(self, element: ET.Element) -> dict:
        def strip_ns(tag: str) -> str:
            return tag.split("}")[-1] if "}" in tag else tag

        def parse(el: ET.Element) -> Any:
            children = list(el)
            if not children:
                return el.text.strip() if el.text and el.text.strip() else None

            result: Dict[str, Any] = {}
            for child in children:
                tag = strip_ns(child.tag)
                parsed = parse(child)
                if tag in result:
                    if not isinstance(result[tag], list):
                        result[tag] = [result[tag]]
                    result[tag].append(parsed)
                else:
                    result[tag] = parsed
            return result

        return {strip_ns(element.tag): parse(element)}

    def parse_string(self, xml_string: str) -> ET.Element:
        try:
            return ET.fromstring(xml_string)
        except ET.ParseError as exc:
            raise EDIParsingError(f"Invalid XML document: {exc}", code="XML_PARSE_ERROR")


