class BusinessDocumentTransformer:
    """Transforms canonical business documents between formats."""

    REQUIRED_FIELDS = {
        DocumentType.PURCHASE_ORDER: ["document_number", "line_items"],
        DocumentType.INVOICE: ["document_number", "total_amount", "line_items"],
        DocumentType.SHIPMENT_NOTICE: ["document_number", "line_items"],
        DocumentType.ACKNOWLEDGMENT: ["document_number"],
        DocumentType.REMITTANCE_ADVICE: ["document_number", "total_amount"],
        DocumentType.INVENTORY_UPDATE: ["line_items"],
    }

    def __init__(self, sender_id: str, receiver_id: str):
        self.sender_id = sender_id
        self.receiver_id = receiver_id
        self.edi_formatter = EDIX12Formatter(sender_id, receiver_id)
        self.xml_handler = ERPXmlHandler(root_tag="BusinessDocument")

    def validate(self, document: dict, doc_type: DocumentType):
        required = self.REQUIRED_FIELDS.get(doc_type, [])
        missing = [f for f in required if f not in document or document[f] in (None, [], "")]
        if missing:
            raise ERPValidationError(
                f"Document missing required fields: {', '.join(missing)}",
                code="VALIDATION_MISSING_FIELDS",
                details={"missing_fields": missing, "document_type": doc_type.value},
            )

        for idx, line in enumerate(document.get("line_items", []) or []):
            if "quantity" in line and _safe_float(str(line["quantity"])) is None:
                raise ERPValidationError(
                    f"Invalid quantity in line item {idx}",
                    code="VALIDATION_INVALID_LINE",
                    details={"line_index": idx},
                )

    def to_format(self, document: dict, doc_type: DocumentType, fmt: MessageFormat,
                  control_number: Optional[str] = None) -> str:
        self.validate(document, doc_type)
        control_number = control_number or _new_control_number()

        if fmt == MessageFormat.JSON:
            return json.dumps(document, default=str)
        elif fmt == MessageFormat.XML:
            root_tag = self._doc_type_root_tag(doc_type)
            element = self.xml_handler.dict_to_xml(document, root_tag=root_tag)
            return self.xml_handler.to_string(element, xml_declaration=True)
        elif fmt == MessageFormat.EDI_X12:
            return self.edi_formatter.encode(document, doc_type, control_number)
        elif fmt == MessageFormat.FLAT_FILE:
            return self._to_flat_file(document)
        else:
            raise DocumentTransformError(
                f"Unsupported output format: {fmt}", code="TRANSFORM_UNSUPPORTED_FORMAT"
            )

    def from_format(self, raw: str, fmt: MessageFormat) -> dict:
        if fmt == MessageFormat.JSON:
            try:
                return json.loads(raw)
            except json.JSONDecodeError as exc:
                raise ERPValidationError(f"Invalid JSON payload: {exc}", code="JSON_PARSE_ERROR")
        elif fmt == MessageFormat.XML:
            element = self.xml_handler.parse_string(raw)
            parsed = self.xml_handler.xml_to_dict(element)
            return next(iter(parsed.values())) if parsed else {}
        elif fmt == MessageFormat.EDI_X12:
            return self.edi_formatter.decode(raw)
        elif fmt == MessageFormat.FLAT_FILE:
            return self._from_flat_file(raw)
        else:
            raise DocumentTransformError(
                f"Unsupported input format: {fmt}", code="TRANSFORM_UNSUPPORTED_FORMAT"
            )

    def _doc_type_root_tag(self, doc_type: DocumentType) -> str:
        mapping = {
            DocumentType.PURCHASE_ORDER: "PurchaseOrder",
            DocumentType.INVOICE: "Invoice",
            DocumentType.SHIPMENT_NOTICE: "ShipmentNotice",
            DocumentType.ACKNOWLEDGMENT: "Acknowledgment",
            DocumentType.REMITTANCE_ADVICE: "RemittanceAdvice",
            DocumentType.INVENTORY_UPDATE: "InventoryUpdate",
        }
        return mapping.get(doc_type, "BusinessDocument")

    def _to_flat_file(self, document: dict, delimiter: str = "|") -> str:
        lines = []
        header_fields = {k: v for k, v in document.items() if k != "line_items"}
        header = delimiter.join(f"{k}={v}" for k, v in header_fields.items())
        lines.append(f"H{delimiter}{header}")
        for line in document.get("line_items", []):
            row = delimiter.join(f"{k}={v}" for k, v in line.items())
            lines.append(f"D{delimiter}{row}")
        return "\n".join(lines)

    def _from_flat_file(self, raw: str) -> dict:
        document: Dict[str, Any] = {"line_items": []}
        for line in raw.splitlines():
            if not line.strip():
                continue
            parts = line.split("|")
            record_type = parts[0]
            fields = {}
            for kv in parts[1:]:
                if "=" in kv:
                    k, v = kv.split("=", 1)
                    fields[k] = v
            if record_type == "H":
                document.update(fields)
            elif record_type == "D":
                document["line_items"].append(fields)
            else:
                raise EDIParsingError(
                    f"Unknown flat file record type: {record_type}", code="FLATFILE_UNKNOWN_RECORD"
                )
        return document


