class ERPIntegrationClient:
    """
    Primary client for enterprise ERP integration. Handles outbound and
    inbound business document transactions, including EDI/XML/JSON
    transformation, message envelopes, and error handling.
    """

    def __init__(self, config: ERPConnectionConfig, partner_id: str = "PARTNER",
                 own_id: str = "SELF"):
        self.config = config
        self.session = build_session(config)
        self.partner_id = partner_id
        self.own_id = own_id
        self.transformer = BusinessDocumentTransformer(own_id, partner_id)
        self._message_log: List[MessageEnvelope] = []

    # -- Envelope management -------------------------------------------------

    def _create_envelope(self, doc_type: DocumentType, fmt: MessageFormat,
                          correlation_id: Optional[str] = None) -> MessageEnvelope:
        envelope = MessageEnvelope(
            message_id=_new_message_id(),
            sender_id=self.own_id,
            receiver_id=self.partner_id,
            document_type=doc_type,
            format=fmt,
            created_at=_now_iso(),
            control_number=_new_control_number(),
            correlation_id=correlation_id,
        )
        self._message_log.append(envelope)
        return envelope

    def get_message_history(self) -> List[dict]:
        return [m.to_dict() for m in self._message_log]

    # -- Core send/receive ---------------------------------------------------

    def send_document(self, document: dict, doc_type: DocumentType,
                       endpoint: str, fmt: Optional[MessageFormat] = None,
                       method: str = "POST",
                       correlation_id: Optional[str] = None) -> dict:
        """Transform and send a business document to the ERP endpoint."""
        fmt = fmt or self.config.default_format
        envelope = self._create_envelope(doc_type, fmt, correlation_id)

        try:
            payload = self.transformer.to_format(
                document, doc_type, fmt, control_number=envelope.control_number
            )
        except ERPIntegrationError:
            envelope.status = MessageStatus.FAILED
            raise
        except Exception as exc:
            envelope.status = MessageStatus.FAILED
            raise DocumentTransformError(f"Failed to build document: {exc}", code="TRANSFORM_ERROR")

        content_type = self._content_type_for(fmt)
        url = self._build_url(endpoint)

        headers = {
            "Content-Type": content_type,
            "X-Message-Id": envelope.message_id,
            "X-Control-Number": envelope.control_number,
            "X-Document-Type": doc_type.value,
        }

        try:
            response = self._request(method, url, data=payload if fmt != MessageFormat.JSON else None,
                                      json_body=document if fmt == MessageFormat.JSON else None,
                                      headers=headers)
        except ERPIntegrationError:
            envelope.status = MessageStatus.FAILED
            raise

        envelope.status = MessageStatus.SENT
        result = self._parse_response(response)
        result["envelope"] = envelope.to_dict()
        return result

    def fetch_document(self, endpoint: str, doc_type: DocumentType,
                        fmt: Optional[MessageFormat] = None,
                        params: Optional[dict] = None) -> dict:
        """Fetch a document from the ERP and transform it into canonical form."""
        fmt = fmt or self.config.default_format
        url = self._build_url(endpoint)

        response = self._request("GET", url, params=params)

        raw_text = response.text
        try:
            document = self.transformer.from_format(raw_text, fmt)
        except ERPIntegrationError:
            raise
        except Exception as exc:
            raise DocumentTransformError(f"Failed to parse fetched document: {exc}", code="PARSE_ERROR")

        envelope = self._create_envelope(doc_type, fmt)
        envelope.status = MessageStatus.ACKNOWLEDGED
        return {"document": document, "envelope": envelope.to_dict()}

    def acknowledge_message(self, message_id: str, endpoint: str,
                             accepted: bool = True, notes: Optional[str] = None) -> dict:
        """Send an acknowledgment (997/855-style) back for a received message."""
        ack_doc = {
            "document_number": message_id,
            "status": "accepted" if accepted else "rejected",
            "notes": notes or "",
            "acknowledged_at": _now_iso(),
        }
        return self.send_document(
            ack_doc, DocumentType.ACKNOWLEDGMENT, endpoint,
            fmt=MessageFormat.JSON, correlation_id=message_id,
        )

    # -- Convenience wrappers for common documents ---------------------------

    def send_purchase_order(self, po_data: dict, endpoint: str = "/purchase-orders",
                             fmt: Optional[MessageFormat] = None) -> dict:
        return self.send_document(po_data, DocumentType.PURCHASE_ORDER, endpoint, fmt=fmt)

    def send_invoice(self, invoice_data: dict, endpoint: str = "/invoices",
                      fmt: Optional[MessageFormat] = None) -> dict:
        return self.send_document(invoice_data, DocumentType.INVOICE, endpoint, fmt=fmt)

    def send_shipment_notice(self, asn_data: dict, endpoint: str = "/shipment-notices",
                              fmt: Optional[MessageFormat] = None) -> dict:
        return self.send_document(asn_data, DocumentType.SHIPMENT_NOTICE, endpoint, fmt=fmt)

    def send_inventory_update(self, inventory_data: dict, endpoint: str = "/inventory",
                               fmt: Optional[MessageFormat] = None) -> dict:
        return self.send_document(inventory_data, DocumentType.INVENTORY_UPDATE, endpoint, fmt=fmt)

    # -- Internal HTTP helpers ------------------------------------------------

    def _build_url(self, endpoint: str) -> str:
        base = self.config.base_url.rstrip("/")
        ep = endpoint if endpoint.startswith("/") else f"/{endpoint}"
        return f"{base}{ep}"

    def _content_type_for(self, fmt: MessageFormat) -> str:
        mapping = {
            MessageFormat.JSON: "application/json",
            MessageFormat.XML: "application/xml",
            MessageFormat.EDI_X12: "application/edi-x12",
            MessageFormat.EDIFACT: "application/edifact",
            MessageFormat.FLAT_FILE: "text/plain",
        }
        return mapping.get(fmt, "application/octet-stream")

    def _request(self, method: str, url: str, data: Optional[str] = None,
                  json_body: Optional[dict] = None, headers: Optional[dict] = None,
                  params: Optional[dict] = None) -> requests.Response:
        try:
            response = self.session.request(
                method=method,
                url=url,
                data=data,
                json=json_body,
                headers=headers,
                params=params,
                timeout=self.config.timeout,
            )
        except requests.exceptions.Timeout as exc:
            raise ERPConnectionError(f"ERP request timed out: {exc}", code="TIMEOUT")
        except requests.exceptions.ConnectionError as exc:
            raise ERPConnectionError(f"ERP connection failed: {exc}", code="CONNECTION_ERROR")
        except requests.exceptions.RequestException as exc:
            raise ERPConnectionError(f"ERP request failed: {exc}", code="REQUEST_ERROR")

        self._check_response_status(response)
        return response

    def _check_response_status(self, response: requests.Response):
        if response.status_code in (401, 403):
            raise ERPAuthenticationError(
                f"Authentication failed with status {response.status_code}",
                code="AUTH_FAILED",
                details={"status_code": response.status_code, "body": _safe_body(response)},
            )
        if response.status_code == 422 or response.status_code == 400:
            raise ERPValidationError(
                f"ERP rejected the request with status {response.status_code}",
                code="ERP_VALIDATION_FAILED",
                details={"status_code": response.status_code, "body": _safe_body(response)},
            )
        if response.status_code >= 500:
            raise ERPConnectionError(
                f"ERP server error: {response.status_code}",
                code="ERP_SERVER_ERROR",
                details={"status_code": response.status_code, "body": _safe_body(response)},
            )
        if response.status_code >= 400:
            raise ERPIntegrationError(
                f"Unexpected ERP error status: {response.status_code}",
                code="ERP_UNEXPECTED_ERROR",
                details={"status_code": response.status_code, "body": _safe_body(response)},
            )

    def _parse_response(self, response: requests.Response) -> dict:
        content_type = response.headers.get("Content-Type", "")
        try:
            if "json" in content_type:
                return {"status_code": response.status_code, "data": response.json()}
            elif "xml" in content_type:
                element = ET.fromstring(response.text)
                parsed = self.transformer.xml_handler.xml_to_dict(element)
                return {"status_code": response.status_code, "data": parsed}
            else:
                return {"status_code": response.status_code, "data": response.text}
        except (ValueError, ET.ParseError) as exc:
            logger.warning("Failed to parse ERP response body: %s", exc)
            return {"status_code": response.status_code, "data": response.text}


def _safe_body(response: requests.Response) -> Any:
    try:
        return response.json()
    except ValueError:
        return response.text[:2000]


