# Batch processing helper
# ---------------------------------------------------------------------------

class BatchDocumentProcessor:
    """Processes multiple business documents with per-item error isolation."""

    def __init__(self, client: ERPIntegrationClient):
        self.client = client

    def process_batch(self, documents: List[dict], doc_type: DocumentType,
                       endpoint: str, fmt: Optional[MessageFormat] = None) -> dict:
        results = []
        errors = []
        for idx, doc in enumerate(documents):
            try:
                result = self.client.send_document(doc, doc_type, endpoint, fmt=fmt)
                results.append({"index": idx, "result": result})
            except ERPIntegrationError as exc:
                errors.append({"index": idx, "error": exc.to_dict()})
            except Exception as exc:  # unexpected failure
                errors.append({
                    "index": idx,
                    "error": {"message": str(exc), "code": "UNEXPECTED_ERROR"},
                })

        return {
            "total": len(documents),
            "succeeded": len(results),
            "failed": len(errors),
            "results": results,
            "errors": errors,
        }

