logger.addHandler(logging.NullHandler())


# ---------------------------------------------------------------------------
# Exceptions
# ---------------------------------------------------------------------------

class ERPIntegrationError(Exception):
    """Base exception for ERP integration errors."""

    def __init__(self, message: str, code: Optional[str] = None, details: Optional[dict] = None):
        super().__init__(message)
        self.message = message
        self.code = code or "ERP_ERROR"
        self.details = details or {}

    def to_dict(self) -> dict:
        return {"message": self.message, "code": self.code, "details": self.details}


class ERPConnectionError(ERPIntegrationError):
    pass


class ERPAuthenticationError(ERPIntegrationError):
    pass


class ERPValidationError(ERPIntegrationError):
    pass


class EDIParsingError(ERPIntegrationError):
    pass


class DocumentTransformError(ERPIntegrationError):
    pass


# ---------------------------------------------------------------------------
# Enums
# ---------------------------------------------------------------------------

class MessageFormat(Enum):
    JSON = "json"
    XML = "xml"
    EDI_X12 = "edi_x12"
    EDIFACT = "edifact"
    FLAT_FILE = "flat_file"


class DocumentType(Enum):
    PURCHASE_ORDER = "purchase_order"
    INVOICE = "invoice"
    SHIPMENT_NOTICE = "shipment_notice"
    ACKNOWLEDGMENT = "acknowledgment"
    INVENTORY_UPDATE = "inventory_update"
    REMITTANCE_ADVICE = "remittance_advice"


class MessageStatus(Enum):
    PENDING = "pending"
    SENT = "sent"
    ACKNOWLEDGED = "acknowledged"
    FAILED = "failed"
    REJECTED = "rejected"


# ---------------------------------------------------------------------------
# Config
# ---------------------------------------------------------------------------

@dataclass
class ERPConnectionConfig:
    base_url: str
    api_key: Optional[str] = None
    username: Optional[str] = None
    password: Optional[str] = None
    timeout: int = 30
    max_retries: int = 3
    backoff_factor: float = 0.5
    verify_ssl: bool = True
    tenant_id: Optional[str] = None
    partner_id: Optional[str] = None
    default_format: MessageFormat = MessageFormat.JSON
    extra_headers: Dict[str, str] = field(default_factory=dict)


# ---------------------------------------------------------------------------
# Envelope / Message metadata
# ---------------------------------------------------------------------------

@dataclass
class MessageEnvelope:
    message_id: str
    sender_id: str
    receiver_id: str
    document_type: DocumentType
    format: MessageFormat
    created_at: str
    control_number: str
    status: MessageStatus = MessageStatus.PENDING
    correlation_id: Optional[str] = None

    def to_dict(self) -> dict:
        return {
            "message_id": self.message_id,
            "sender_id": self.sender_id,
            "receiver_id": self.receiver_id,
            "document_type": self.document_type.value,
            "format": self.format.value,
            "created_at": self.created_at,
            "control_number": self.control_number,
            "status": self.status.value,
            "correlation_id": self.correlation_id,
        }


def _new_message_id() -> str:
    return str(uuid.uuid4())


def _new_control_number() -> str:
    return str(int(time.time() * 1000) % 1000000000).zfill(9)


def _now_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


# ---------------------------------------------------------------------------
# EDI X12 Formatter
# ---------------------------------------------------------------------------

class EDIX12Formatter:
    """Formats and parses simplified ANSI X12 EDI documents."""

    SEGMENT_TERM = "~"
    ELEMENT_SEP = "*"
    SUBELEMENT_SEP = ":"

    TRANSACTION_SET_MAP = {
        DocumentType.PURCHASE_ORDER: "850",
        DocumentType.INVOICE: "810",
        DocumentType.SHIPMENT_NOTICE: "856",
        DocumentType.ACKNOWLEDGMENT: "855",
        DocumentType.REMITTANCE_ADVICE: "820",
        DocumentType.INVENTORY_UPDATE: "846",
    }

    def __init__(self, sender_id: str, receiver_id: str):
        self.sender_id = sender_id
        self.receiver_id = receiver_id

    def build_isa_segment(self, control_number: str) -> str:
        fields = [
            "ISA",
            "00", " " * 10,
            "00", " " * 10,
            "ZZ", self.sender_id.ljust(15)[:15],
            "ZZ", self.receiver_id.ljust(15)[:15],
            datetime.now().strftime("%y%m%d"),
            datetime.now().strftime("%H%M"),
            "U", "00401",
            control_number.zfill(9),
            "0", "P", self.SUBELEMENT_SEP,
        ]
        return self.ELEMENT_SEP.join(fields) + self.SEGMENT_TERM

    def build_gs_segment(self, doc_type: DocumentType, control_number: str) -> str:
        code_map = {
            DocumentType.PURCHASE_ORDER: "PO",
            DocumentType.INVOICE: "IN",
            DocumentType.SHIPMENT_NOTICE: "SH",
            DocumentType.ACKNOWLEDGMENT: "PR",
            DocumentType.REMITTANCE_ADVICE: "RA",
            DocumentType.INVENTORY_UPDATE: "IB",
        }
        fields = [
            "GS", code_map.get(doc_type, "XX"),
            self.sender_id, self.receiver_id,
            datetime.now().strftime("%Y%m%d"),
            datetime.now().strftime("%H%M"),
            control_number, "X", "004010",
        ]
        return self.ELEMENT_SEP.join(fields) + self.SEGMENT_TERM

    def encode(self, document: dict, doc_type: DocumentType, control_number: str) -> str:
        """Transform a business document dict into an EDI X12 string."""
        ts_code = self.TRANSACTION_SET_MAP.get(doc_type)
        if not ts_code:
            raise DocumentTransformError(
                f"No X12 transaction set mapping for document type {doc_type}",
                code="EDI_UNSUPPORTED_DOC_TYPE",
            )

        segments = [self.build_isa_segment(control_number)]
        segments.append(self.build_gs_segment(doc_type, control_number))
        segments.append(
            self.ELEMENT_SEP.join(["ST", ts_code, control_number.zfill(4)]) + self.SEGMENT_TERM
        )

        segments.append(self._build_bx_or_beg(document, ts_code))

        for idx, line in enumerate(document.get("line_items", []), start=1):
            segments.append(self._build_line_segment(line, idx))

        total = document.get("total_amount")
        if total is not None:
            segments.append(
                self.ELEMENT_SEP.join(["TDS", str(int(round(float(total) * 100)))]) + self.SEGMENT_TERM
            )

        segment_count = len(segments) - 2  # excluding ISA/GS
        segments.append(
            self.ELEMENT_SEP.join(["SE", str(segment_count + 1), control_number.zfill(4)]) + self.SEGMENT_TERM
        )
        segments.append(
            self.ELEMENT_SEP.join(["GE", "1", control_number]) + self.SEGMENT_TERM
        )
        segments.append(
            self.ELEMENT_SEP.join(["IEA", "1", control_number.zfill(9)]) + self.SEGMENT_TERM
        )

        return "".join(segments)

    def _build_bx_or_beg(self, document: dict, ts_code: str) -> str:
        doc_number = str(document.get("document_number", ""))
        doc_date = document.get("document_date", datetime.now().strftime("%Y%m%d"))
        if ts_code == "850":
            fields = ["BEG", "00", "SA", doc_number, "", doc_date]
        elif ts_code == "810":
            fields = ["BIG", doc_date, doc_number]
        elif ts_code == "856":
            fields = ["BSN", "00", doc_number, doc_date]
        else:
            fields = ["BEG", "00", "SA", doc_number, "", doc_date]
        return self.ELEMENT_SEP.join(fields) + self.SEGMENT_TERM

    def _build_line_segment(self, line: dict, index: int) -> str:
        qty = line.get("quantity", 0)
        unit = line.get("unit_of_measure", "EA")
        price = line.get("unit_price", 0)
        sku = line.get("sku", line.get("item_id", ""))
        fields = ["PO1", str(index), str(qty), unit, f"{float(price):.2f}", "PE", "IN", str(sku)]
        return self.ELEMENT_SEP.join(fields) + self.SEGMENT_TERM

    def decode(self, edi_string: str) -> dict:
        """Parse an EDI X12 string into a structured dictionary."""
        if not edi_string or not edi_string.strip():
            raise EDIParsingError("Empty EDI payload", code="EDI_EMPTY")

        raw = edi_string.strip()
        segments = [s for s in raw.split(self.SEGMENT_TERM) if s.strip()]

        result: Dict[str, Any] = {
            "isa": None,
            "gs": None,
            "st": None,
            "line_items": [],
            "total_amount": None,
            "document_number": None,
            "document_date": None,
        }

        try:
            for seg in segments:
                elements = seg.split(self.ELEMENT_SEP)
                seg_id = elements[0]

                if seg_id == "ISA":
                    result["isa"] = {
                        "sender_id": elements[6].strip() if len(elements) > 6 else None,
                        "receiver_id": elements[8].strip() if len(elements) > 8 else None,
                        "control_number": elements[13] if len(elements) > 13 else None,
                    }
                elif seg_id == "GS":
                    result["gs"] = {
                        "functional_id": elements[1] if len(elements) > 1 else None,
                        "sender_id": elements[2] if len(elements) > 2 else None,
                        "receiver_id": elements[3] if len(elements) > 3 else None,
                    }
                elif seg_id == "ST":
                    result["st"] = {
                        "transaction_set": elements[1] if len(elements) > 1 else None,
                        "control_number": elements[2] if len(elements) > 2 else None,
                    }
                elif seg_id in ("BEG", "BIG", "BSN"):
                    if seg_id == "BEG" and len(elements) > 3:
                        result["document_number"] = elements[3]
                        result["document_date"] = elements[5] if len(elements) > 5 else None
                    elif seg_id == "BIG" and len(elements) > 2:
                        result["document_date"] = elements[1]
                        result["document_number"] = elements[2]
                    elif seg_id == "BSN" and len(elements) > 3:
                        result["document_number"] = elements[2]
                        result["document_date"] = elements[3]
                elif seg_id == "PO1":
                    result["line_items"].append({
                        "line_number": elements[1] if len(elements) > 1 else None,
                        "quantity": _safe_float(elements[2]) if len(elements) > 2 else None,
                        "unit_of_measure": elements[3] if len(elements) > 3 else None,
                        "unit_price": _safe_float(elements[4]) if len(elements) > 4 else None,
                        "sku": elements[7] if len(elements) > 7 else None,
                    })
                elif seg_id == "TDS":
                    if len(elements) > 1:
                        try:
                            result["total_amount"] = int(elements[1]) / 100.0
                        except ValueError:
                            pass
        except (IndexError, ValueError) as exc:
            raise EDIParsingError(f"Malformed EDI segment: {exc}", code="EDI_PARSE_ERROR")

        return result


def _safe_float(value: str) -> Optional[float]:
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


# ---------------------------------------------------------------------------
# XML Handling
# ---------------------------------------------------------------------------

class ERPXmlHandler:
    """Handles conversion between XML and dict/business documents."""

    def __init__(self, root_tag: str = "Document", namespace: Optional[str] = None):
        self.root_tag = root_tag
        self.namespace = namespace

    def _qualify(self, tag: str) -> str:
        if self.namespace:
            return f"{{{self.namespace}}}{tag}"
        return tag

    def dict_to_xml(self, data: dict, root_tag: Optional[str] = None) -> ET.Element:
        root = ET.Element(self._qualify(root_tag or self.root_tag))
        self._build_element(root, data)
        return root

    def _build_element(self, parent: ET.Element, value: Any):
        if isinstance(value, dict):
            for key, val in value.items():
                if isinstance(val, list):
                    for item in val:
                        child = ET.SubElement(parent, self._qualify(str(key)))
                        self._build_element(child, item)
                else:
                    child = ET.SubElement(parent, self._qualify(str(key)))
                    self._build_element(child, val)
        elif isinstance(value, list):
            for item in value:
                child = ET.SubElement(parent, self._qualify("Item"))
                self._build_element(child, item)
        else:
            parent.text = "" if value is None else str(value)

    def to_string(self, element: ET.Element, encoding: str = "unicode", xml_declaration: bool = False) -> str:
        try:
            if xml_declaration:
                return ET.tostring(element, encoding="utf-8", xml_declaration=True).decode("utf-8")
            return ET.tostring(element, encoding=encoding)
        except Exception as exc:
            raise DocumentTransformError(f"Failed to serialize XML: {exc}", code="XML_SERIALIZE_ERROR")

    def xml_to_dict(self, element: ET.Element) -> dict:
        def strip_ns(tag: str) -> str:
            return tag.split("}")[-1] if "}" in tag else tag

        def parse(el: ET.Element) -> Any:
            children = list(el)
            if not children:
                return el.text.strip() if el.text and el.text.strip() else None

            result: Dict[str, Any] = {}
            for child in children:
                tag = strip_ns(child.tag)
                parsed = parse(child)
                if tag in result:
                    if not isinstance(result[tag], list):
                        result[tag] = [result[tag]]
                    result[tag].append(parsed)
                else:
                    result[tag] = parsed
            return result

        return {strip_ns(element.tag): parse(element)}

    def parse_string(self, xml_string: str) -> ET.Element:
        try:
            return ET.fromstring(xml_string)
        except ET.ParseError as exc:
            raise EDIParsingError(f"Invalid XML document: {exc}", code="XML_PARSE_ERROR")


# ---------------------------------------------------------------------------
# Business Document Transformer
# ---------------------------------------------------------------------------

class BusinessDocumentTransformer:
    """Transforms canonical business documents between formats."""

    REQUIRED_FIELDS = {
        DocumentType.PURCHASE_ORDER: ["document_number", "line_items"],
        DocumentType.INVOICE: ["document_number", "total_amount", "line_items"],
        DocumentType.SHIPMENT_NOTICE: ["document_number", "line_items"],
        DocumentType.ACKNOWLEDGMENT: ["document_number"],
        DocumentType.REMITTANCE_ADVICE: ["document_number", "total_amount"],
        DocumentType.INVENTORY_UPDATE: ["line_items"],
    }

    def __init__(self, sender_id: str, receiver_id: str):
        self.sender_id = sender_id
        self.receiver_id = receiver_id
        self.edi_formatter = EDIX12Formatter(sender_id, receiver_id)
        self.xml_handler = ERPXmlHandler(root_tag="BusinessDocument")

    def validate(self, document: dict, doc_type: DocumentType):
        required = self.REQUIRED_FIELDS.get(doc_type, [])
        missing = [f for f in required if f not in document or document[f] in (None, [], "")]
        if missing:
            raise ERPValidationError(
                f"Document missing required fields: {', '.join(missing)}",
                code="VALIDATION_MISSING_FIELDS",
                details={"missing_fields": missing, "document_type": doc_type.value},
            )

        for idx, line in enumerate(document.get("line_items", []) or []):
            if "quantity" in line and _safe_float(str(line["quantity"])) is None:
                raise ERPValidationError(
                    f"Invalid quantity in line item {idx}",
                    code="VALIDATION_INVALID_LINE",
                    details={"line_index": idx},
                )

    def to_format(self, document: dict, doc_type: DocumentType, fmt: MessageFormat,
                  control_number: Optional[str] = None) -> str:
        self.validate(document, doc_type)
        control_number = control_number or _new_control_number()

        if fmt == MessageFormat.JSON:
            return json.dumps(document, default=str)
        elif fmt == MessageFormat.XML:
            root_tag = self._doc_type_root_tag(doc_type)
            element = self.xml_handler.dict_to_xml(document, root_tag=root_tag)
            return self.xml_handler.to_string(element, xml_declaration=True)
        elif fmt == MessageFormat.EDI_X12:
            return self.edi_formatter.encode(document, doc_type, control_number)
        elif fmt == MessageFormat.FLAT_FILE:
            return self._to_flat_file(document)
        else:
            raise DocumentTransformError(
                f"Unsupported output format: {fmt}", code="TRANSFORM_UNSUPPORTED_FORMAT"
            )

    def from_format(self, raw: str, fmt: MessageFormat) -> dict:
        if fmt == MessageFormat.JSON:
            try:
                return json.loads(raw)
            except json.JSONDecodeError as exc:
                raise ERPValidationError(f"Invalid JSON payload: {exc}", code="JSON_PARSE_ERROR")
        elif fmt == MessageFormat.XML:
            element = self.xml_handler.parse_string(raw)
            parsed = self.xml_handler.xml_to_dict(element)
            return next(iter(parsed.values())) if parsed else {}
        elif fmt == MessageFormat.EDI_X12:
            return self.edi_formatter.decode(raw)
        elif fmt == MessageFormat.FLAT_FILE:
            return self._from_flat_file(raw)
        else:
            raise DocumentTransformError(
                f"Unsupported input format: {fmt}", code="TRANSFORM_UNSUPPORTED_FORMAT"
            )

    def _doc_type_root_tag(self, doc_type: DocumentType) -> str:
        mapping = {
            DocumentType.PURCHASE_ORDER: "PurchaseOrder",
            DocumentType.INVOICE: "Invoice",
            DocumentType.SHIPMENT_NOTICE: "ShipmentNotice",
            DocumentType.ACKNOWLEDGMENT: "Acknowledgment",
            DocumentType.REMITTANCE_ADVICE: "RemittanceAdvice",
            DocumentType.INVENTORY_UPDATE: "InventoryUpdate",
        }
        return mapping.get(doc_type, "BusinessDocument")

    def _to_flat_file(self, document: dict, delimiter: str = "|") -> str:
        lines = []
        header_fields = {k: v for k, v in document.items() if k != "line_items"}
        header = delimiter.join(f"{k}={v}" for k, v in header_fields.items())
        lines.append(f"H{delimiter}{header}")
        for line in document.get("line_items", []):
            row = delimiter.join(f"{k}={v}" for k, v in line.items())
            lines.append(f"D{delimiter}{row}")
        return "\n".join(lines)

    def _from_flat_file(self, raw: str) -> dict:
        document: Dict[str, Any] = {"line_items": []}
        for line in raw.splitlines():
            if not line.strip():
                continue
            parts = line.split("|")
            record_type = parts[0]
            fields = {}
            for kv in parts[1:]:
                if "=" in kv:
                    k, v = kv.split("=", 1)
                    fields[k] = v
            if record_type == "H":
                document.update(fields)
            elif record_type == "D":
                document["line_items"].append(fields)
            else:
                raise EDIParsingError(
                    f"Unknown flat file record type: {record_type}", code="FLATFILE_UNKNOWN_RECORD"
                )
        return document


# ---------------------------------------------------------------------------
# HTTP Session / Transport
# ---------------------------------------------------------------------------

def build_session(config: ERPConnectionConfig) -> requests.Session:
    session = requests.Session()

    if Retry is not None:
        retry = Retry(
            total=config.max_retries,
            backoff_factor=config.backoff_factor,
            status_forcelist=(500, 502, 503, 504),
            allowed_methods=frozenset(["GET", "POST", "PUT", "DELETE", "PATCH"]),
        )
        adapter = HTTPAdapter(max_retries=retry)
        session.mount("http://", adapter)
        session.mount("https://", adapter)

    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json, application/xml, text/plain",
        "User-Agent": "ERPIntegrationModule/1.0",
    }
    if config.api_key:
        headers["Authorization"] = f"Bearer {config.api_key}"
    if config.tenant_id:
        headers["X-Tenant-Id"] = config.tenant_id
    if config.partner_id:
        headers["X-Partner-Id"] = config.partner_id
    headers.update(config.extra_headers)

    session.headers.update(headers)
    session.verify = config.verify_ssl

    if config.username and config.password:
        session.auth = (config.username, config.password)

    return session


# ---------------------------------------------------------------------------
# Main Integration Client
# ---------------------------------------------------------------------------

class ERPIntegrationClient:
    """
    Primary client for enterprise ERP integration. Handles outbound and
    inbound business document transactions, including EDI/XML/JSON
    transformation, message envelopes, and error handling.
    """

    def __init__(self, config: ERPConnectionConfig, partner_id: str = "PARTNER",
                 own_id: str = "SELF"):
        self.config = config
        self.session = build_session(config)
        self.partner_id = partner_id
        self.own_id = own_id
        self.transformer = BusinessDocumentTransformer(own_id, partner_id)
        self._message_log: List[MessageEnvelope] = []

    # -- Envelope management -------------------------------------------------

    def _create_envelope(self, doc_type: DocumentType, fmt: MessageFormat,
                          correlation_id: Optional[str] = None) -> MessageEnvelope:
        envelope = MessageEnvelope(
            message_id=_new_message_id(),
            sender_id=self.own_id,
            receiver_id=self.partner_id,
            document_type=doc_type,
            format=fmt,
            created_at=_now_iso(),
            control_number=_new_control_number(),
            correlation_id=correlation_id,
        )
        self._message_log.append(envelope)
        return envelope

    def get_message_history(self) -> List[dict]:
        return [m.to_dict() for m in self._message_log]

    # -- Core send/receive ---------------------------------------------------

    def send_document(self, document: dict, doc_type: DocumentType,
                       endpoint: str, fmt: Optional[MessageFormat] = None,
                       method: str = "POST",
                       correlation_id: Optional[str] = None) -> dict:
        """Transform and send a business document to the ERP endpoint."""
        fmt = fmt or self.config.default_format
        envelope = self._create_envelope(doc_type, fmt, correlation_id)

        try:
            payload = self.transformer.to_format(
                document, doc_type, fmt, control_number=envelope.control_number
            )
        except ERPIntegrationError:
            envelope.status = MessageStatus.FAILED
            raise
        except Exception as exc:
            envelope.status = MessageStatus.FAILED
            raise DocumentTransformError(f"Failed to build document: {exc}", code="TRANSFORM_ERROR")

        content_type = self._content_type_for(fmt)
        url = self._build_url(endpoint)

        headers = {
            "Content-Type": content_type,
            "X-Message-Id": envelope.message_id,
            "X-Control-Number": envelope.control_number,
            "X-Document-Type": doc_type.value,
        }

        try:
            response = self._request(method, url, data=payload if fmt != MessageFormat.JSON else None,
                                      json_body=document if fmt == MessageFormat.JSON else None,
                                      headers=headers)
        except ERPIntegrationError:
            envelope.status = MessageStatus.FAILED
            raise

        envelope.status = MessageStatus.SENT
        result = self._parse_response(response)
        result["envelope"] = envelope.to_dict()
        return result

    def fetch_document(self, endpoint: str, doc_type: DocumentType,
                        fmt: Optional[MessageFormat] = None,
                        params: Optional[dict] = None) -> dict:
        """Fetch a document from the ERP and transform it into canonical form."""
        fmt = fmt or self.config.default_format
        url = self._build_url(endpoint)

        response = self._request("GET", url, params=params)

        raw_text = response.text
        try:
            document = self.transformer.from_format(raw_text, fmt)
        except ERPIntegrationError:
            raise
        except Exception as exc:
            raise DocumentTransformError(f"Failed to parse fetched document: {exc}", code="PARSE_ERROR")

        envelope = self._create_envelope(doc_type, fmt)
        envelope.status = MessageStatus.ACKNOWLEDGED
        return {"document": document, "envelope": envelope.to_dict()}

    def acknowledge_message(self, message_id: str, endpoint: str,
                             accepted: bool = True, notes: Optional[str] = None) -> dict:
        """Send an acknowledgment (997/855-style) back for a received message."""
        ack_doc = {
            "document_number": message_id,
            "status": "accepted" if accepted else "rejected",
            "notes": notes or "",
            "acknowledged_at": _now_iso(),
        }
        return self.send_document(
            ack_doc, DocumentType.ACKNOWLEDGMENT, endpoint,
            fmt=MessageFormat.JSON, correlation_id=message_id,
        )

    # -- Convenience wrappers for common documents ---------------------------

    def send_purchase_order(self, po_data: dict, endpoint: str = "/purchase-orders",
                             fmt: Optional[MessageFormat] = None) -> dict:
        return self.send_document(po_data, DocumentType.PURCHASE_ORDER, endpoint, fmt=fmt)

    def send_invoice(self, invoice_data: dict, endpoint: str = "/invoices",
                      fmt: Optional[MessageFormat] = None) -> dict:
        return self.send_document(invoice_data, DocumentType.INVOICE, endpoint, fmt=fmt)

    def send_shipment_notice(self, asn_data: dict, endpoint: str = "/shipment-notices",
                              fmt: Optional[MessageFormat] = None) -> dict:
        return self.send_document(asn_data, DocumentType.SHIPMENT_NOTICE, endpoint, fmt=fmt)

    def send_inventory_update(self, inventory_data: dict, endpoint: str = "/inventory",
                               fmt: Optional[MessageFormat] = None) -> dict:
        return self.send_document(inventory_data, DocumentType.INVENTORY_UPDATE, endpoint, fmt=fmt)

    # -- Internal HTTP helpers ------------------------------------------------

    def _build_url(self, endpoint: str) -> str:
