def _dim_str(d: Dimension) -> str:
    parts = []
    for name, exp in zip(_BASE_DIMS, d):
        if exp != 0:
            if exp == 1:
                parts.append(name)
            else:
                exp_str = f"{exp:g}"
                parts.append(f"{name}^{exp_str}")
    return " ".join(parts) if parts else "dimensionless"


class UnitError(Exception):
    """Raised on incompatible unit operations."""


@dataclass
class Quantity:
    """
    A physical quantity: a numeric value (scalar or numpy array) tagged with
    a physical dimension, stored internally in SI base units.
    """

    magnitude: Union[float, np.ndarray]
    dimension: Dimension = field(default_factory=_dim)
    _display_unit: Optional[str] = None  # preferred unit for display

    # -- Construction -----------------------------------------------------
    @classmethod
    def from_unit(cls, value: Union[float, np.ndarray, Sequence[float]], unit: str) -> "Quantity":
        """Create a Quantity from a value expressed in the given unit."""
        dim, factor = cls._resolve_unit(unit)
        mag = np.asarray(value, dtype=float) if not np.isscalar(value) else float(value)
        si_value = mag * factor
        return cls(si_value, dim, unit)

    @staticmethod
    def _resolve_unit(unit: str) -> Tuple[Dimension, float]:
        if unit in _UNIT_REGISTRY:
            return _UNIT_REGISTRY[unit]
        raise UnitError(f"Unknown unit: {unit!r}")

    @staticmethod
    def register_unit(name: str, dimension: Dimension, factor_to_si: float) -> None:
        """Register a custom unit in the global registry."""
        _UNIT_REGISTRY[name] = (dimension, factor_to_si)

    # -- Conversion ---------------------------------------------------------
    def to(self, unit: str) -> "Quantity":
        """Return a new Quantity expressed with `unit` as the display unit,
        verifying dimensional compatibility."""
        dim, factor = self._resolve_unit(unit)
        if dim != self.dimension:
            raise UnitError(
                f"Cannot convert quantity with dimension "
                f"[{_dim_str(self.dimension)}] to unit '{unit}' "
                f"with dimension [{_dim_str(dim)}]"
            )
        return Quantity(self.magnitude, self.dimension, unit)

    def value_in(self, unit: str) -> Union[float, np.ndarray]:
        """Return the numeric magnitude expressed in `unit`."""
        dim, factor = self._resolve_unit(unit)
        if dim != self.dimension:
            raise UnitError(
                f"Cannot express quantity with dimension "
                f"[{_dim_str(self.dimension)}] in unit '{unit}' "
                f"with dimension [{_dim_str(dim)}]"
            )
        return self.magnitude / factor

    # -- Representation -------------------------------------------------
    def __repr__(self):
        unit_label = self._display_unit if self._display_unit else _dim_str(self.dimension)
        if self._display_unit:
            try:
                val = self.value_in(self._display_unit)
            except UnitError:
                val = self.magnitude
        else:
            val = self.magnitude
        return f"Quantity({val}, '{unit_label}')"

    def __str__(self):
        return self.__repr__()

    # -- Arithmetic -----------------------------------------------------
    def _check_same_dim(self, other: "Quantity", op: str):
        if self.dimension != other.dimension:
            raise UnitError(
                f"Cannot {op} quantities with different dimensions: "
                f"[{_dim_str(self.dimension)}] vs [{_dim_str(other.dimension)}]"
            )

    def __add__(self, other):
        if not isinstance(other, Quantity):
            if self.dimension == _dim():
                other = Quantity(other, _dim())
            else:
                raise UnitError("Cannot add a plain number to a dimensioned Quantity")
        self._check_same_dim(other, "add")
        return Quantity(self.magnitude + other.magnitude, self.dimension, self._display_unit)

    __radd__ = __add__

    def __sub__(self, other):
        if not isinstance(other, Quantity):
            if self.dimension == _dim():
                other = Quantity(other, _dim())
            else:
                raise UnitError("Cannot subtract a plain number from a dimensioned Quantity")
        self._check_same_dim(other, "subtract")
        return Quantity(self.magnitude - other.magnitude, self.dimension, self._display_unit)

    def __rsub__(self, other):
        if not isinstance(other, Quantity):
            if self.dimension == _dim():
                other = Quantity(other, _dim())
            else:
                raise UnitError("Cannot subtract from a plain number using a dimensioned Quantity")
        other._check_same_dim(self, "subtract")
        return Quantity(other.magnitude - self.magnitude, self.dimension, self._display_unit)

    def __mul__(self, other):
        if isinstance(other, Quantity):
            return Quantity(self.magnitude * other.magnitude,
                             _add_dims(self.dimension, other.dimension))
        else:
            return Quantity(self.magnitude * other, self.dimension, self._display_unit)

    __rmul__ = __mul__

    def __truediv__(self, other):
        if isinstance(other, Quantity):
            return Quantity(self.magnitude / other.magnitude,
                             _sub_dims(self.dimension, other.dimension))
        else:
            return Quantity(self.magnitude / other, self.dimension, self._display_unit)

    def __rtruediv__(self, other):
        if isinstance(other, Quantity):
            return Quantity(other.magnitude / self.magnitude,
                             _sub_dims(other.dimension, self.dimension))
        else:
            return Quantity(other / self.magnitude, _scale_dims(self.dimension, -1))

    def __pow__(self, power: float):
        if not isinstance(power, numbers.Number):
            raise UnitError("Exponent must be a plain number")
        return Quantity(self.magnitude ** power, _scale_dims(self.dimension, power))

    def __neg__(self):
        return Quantity(-self.magnitude, self.dimension, self._display_unit)

    def __abs__(self):
        return Quantity(np.abs(self.magnitude) if isinstance(self.magnitude, np.ndarray)
                         else abs(self.magnitude), self.dimension, self._display_unit)

    def __eq__(self, other):
        if not isinstance(other, Quantity):
            return NotImplemented
        return self.dimension == other.dimension and np.all(self.magnitude == other.magnitude)

    def __lt__(self, other):
        self._check_same_dim(other, "compare")
        return self.magnitude < other.magnitude

    def __le__(self, other):
        self._check_same_dim(other, "compare")
        return self.magnitude <= other.magnitude

    def __gt__(self, other):
        self._check_same_dim(other, "compare")
        return self.magnitude > other.magnitude

    def __ge__(self, other):
        self._check_same_dim(other, "compare")
        return self.magnitude >= other.magnitude

    def sqrt(self) -> "Quantity":
        return self.__pow__(0.5)

    @property
    def is_dimensionless(self) -> bool:
        return self.dimension == _dim()


def convert(value: Union[float, np.ndarray], from_unit: str, to_unit: str) -> Union[float, np.ndarray]:
    """Convenience function to convert a plain numeric value between compatible units."""
    q = Quantity.from_unit(value, from_unit)
    return q.value_in(to_unit)


def units_compatible(unit_a: str, unit_b: str) -> bool:
    """Check whether two unit strings share the same physical dimension."""
    try:
        dim_a, _ = Quantity._resolve_unit(unit_a)
        dim_b, _ = Quantity._resolve_unit(unit_b)
    except UnitError:
        return False
    return dim_a == dim_b


