"""
scipy_ext.py

A scientific module that extends numpy with domain-specific operations for:
  1. Signal processing (filtering, spectral analysis, windowing)
  2. Uncertainty propagation (values with associated errors and error algebra)
  3. Unit handling (physical quantities with units, conversion, and dimensional analysis)

This module is self-contained and only depends on numpy.
"""

from __future__ import annotations

import cmath
import math
import numbers
from dataclasses import dataclass, field
from typing import Dict, Iterable, Optional, Sequence, Tuple, Union

import numpy as np


# =============================================================================
# 1. SIGNAL PROCESSING
# =============================================================================

class SignalProcessing:
    """
    A collection of signal processing routines built on top of numpy.
    All methods are static so the class acts as a namespace.
    """

    # ---------------------------------------------------------------
    # Windowing
    # ---------------------------------------------------------------
    @staticmethod
    def window(n: int, kind: str = "hann") -> np.ndarray:
        """
        Generate a window function of length n.

        Parameters
        ----------
        n : int
            Length of the window.
        kind : str
            One of 'hann', 'hamming', 'blackman', 'rectangular', 'bartlett'.

        Returns
        -------
        np.ndarray
            The window values.
        """
        if n <= 0:
            return np.array([])
        idx = np.arange(n)
        kind = kind.lower()
        if kind == "hann":
            return 0.5 - 0.5 * np.cos(2 * np.pi * idx / (n - 1 if n > 1 else 1))
        elif kind == "hamming":
            return 0.54 - 0.46 * np.cos(2 * np.pi * idx / (n - 1 if n > 1 else 1))
        elif kind == "blackman":
            return (0.42 - 0.5 * np.cos(2 * np.pi * idx / (n - 1 if n > 1 else 1))
                    + 0.08 * np.cos(4 * np.pi * idx / (n - 1 if n > 1 else 1)))
        elif kind == "bartlett":
            return 1 - np.abs((idx - (n - 1) / 2) / ((n - 1) / 2 if n > 1 else 1))
        elif kind == "rectangular":
            return np.ones(n)
        else:
            raise ValueError(f"Unknown window kind: {kind}")

    # ---------------------------------------------------------------
    # Filtering
    # ---------------------------------------------------------------
    @staticmethod
    def moving_average(x: np.ndarray, window_size: int, mode: str = "same") -> np.ndarray:
        """Simple moving average filter."""
        x = np.asarray(x, dtype=float)
        if window_size < 1:
            raise ValueError("window_size must be >= 1")
        kernel = np.ones(window_size) / window_size
        return np.convolve(x, kernel, mode=mode)

    @staticmethod
    def fir_lowpass(x: np.ndarray, cutoff: float, fs: float, numtaps: int = 101) -> np.ndarray:
        """
        Apply a simple windowed-sinc FIR low-pass filter.

        Parameters
        ----------
        x : np.ndarray
            Input signal.
        cutoff : float
            Cutoff frequency in Hz.
        fs : float
            Sampling frequency in Hz.
        numtaps : int
            Number of filter taps (should be odd).
        """
        x = np.asarray(x, dtype=float)
        if numtaps % 2 == 0:
            numtaps += 1
        nyq = fs / 2.0
        normalized_cutoff = cutoff / nyq
        m = np.arange(numtaps) - (numtaps - 1) / 2.0
        h = normalized_cutoff * np.sinc(normalized_cutoff * m)
        h *= SignalProcessing.window(numtaps, "hamming")
        h /= np.sum(h)
        return np.convolve(x, h, mode="same")

    @staticmethod
    def iir_ema(x: np.ndarray, alpha: float) -> np.ndarray:
        """Exponential moving average (simple IIR filter)."""
        x = np.asarray(x, dtype=float)
        if not (0 < alpha <= 1):
            raise ValueError("alpha must be in (0, 1]")
        y = np.empty_like(x)
        y[0] = x[0]
        for i in range(1, len(x)):
            y[i] = alpha * x[i] + (1 - alpha) * y[i - 1]
        return y

    @staticmethod
    def median_filter(x: np.ndarray, kernel_size: int = 3) -> np.ndarray:
        """Simple median filter for 1D signals."""
        x = np.asarray(x, dtype=float)
        if kernel_size % 2 == 0:
            raise ValueError("kernel_size must be odd")
        half = kernel_size // 2
        n = len(x)
        padded = np.pad(x, half, mode="edge")
        out = np.empty(n)
        for i in range(n):
            out[i] = np.median(padded[i:i + kernel_size])
        return out

    # ---------------------------------------------------------------
    # Spectral analysis
    # ---------------------------------------------------------------
    @staticmethod
    def power_spectrum(x: np.ndarray, fs: float = 1.0,
                        window_kind: Optional[str] = "hann") -> Tuple[np.ndarray, np.ndarray]:
        """
        Compute the one-sided power spectral density estimate via FFT.

        Returns
        -------
        freqs : np.ndarray
        psd : np.ndarray
        """
        x = np.asarray(x, dtype=float)
        n = len(x)
        if window_kind is not None:
            w = SignalProcessing.window(n, window_kind)
            x = x * w
            scale = np.sum(w ** 2)
        else:
            scale = n

        spec = np.fft.rfft(x)
        freqs = np.fft.rfftfreq(n, d=1.0 / fs)
        psd = (np.abs(spec) ** 2) / (fs * scale)
        if n % 2 == 0:
            psd[1:-1] *= 2
        else:
            psd[1:] *= 2
        return freqs, psd

    @staticmethod
    def spectrogram(x: np.ndarray, fs: float = 1.0, nperseg: int = 256,
                     noverlap: Optional[int] = None,
                     window_kind: str = "hann") -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        """
        Compute a simple spectrogram using STFT.

        Returns
        -------
        freqs : np.ndarray
        times : np.ndarray
        Sxx : np.ndarray  (freqs x times)
        """
        x = np.asarray(x, dtype=float)
        if noverlap is None:
            noverlap = nperseg // 2
        step = nperseg - noverlap
        if step <= 0:
            raise ValueError("noverlap must be less than nperseg")

        window = SignalProcessing.window(nperseg, window_kind)
        n_segments = max(0, (len(x) - nperseg) // step + 1)
        freqs = np.fft.rfftfreq(nperseg, d=1.0 / fs)
        Sxx = np.zeros((len(freqs), n_segments))
        times = np.zeros(n_segments)

        for i in range(n_segments):
            start = i * step
            seg = x[start:start + nperseg] * window
            spec = np.fft.rfft(seg)
            Sxx[:, i] = (np.abs(spec) ** 2) / (fs * np.sum(window ** 2))
            times[i] = (start + nperseg / 2) / fs

        return freqs, times, Sxx

    @staticmethod
    def autocorrelation(x: np.ndarray, max_lag: Optional[int] = None) -> np.ndarray:
        """Compute the (biased) autocorrelation of a 1D signal."""
        x = np.asarray(x, dtype=float)
        x = x - np.mean(x)
        n = len(x)
        if max_lag is None:
            max_lag = n - 1
        full = np.correlate(x, x, mode="full")
        mid = len(full) // 2
        ac = full[mid:mid + max_lag + 1]
        return ac / ac[0] if ac[0] != 0 else ac

    @staticmethod
    def detrend(x: np.ndarray, kind: str = "linear") -> np.ndarray:
        """Remove trend (constant or linear) from a signal."""
        x = np.asarray(x, dtype=float)
        n = len(x)
        if kind == "constant":
            return x - np.mean(x)
        elif kind == "linear":
            t = np.arange(n)
            A = np.vstack([t, np.ones(n)]).T
            coeffs, *_ = np.linalg.lstsq(A, x, rcond=None)
            trend = A @ coeffs
            return x - trend
        else:
            raise ValueError("kind must be 'constant' or 'linear'")

    @staticmethod
    def resample(x: np.ndarray, num: int) -> np.ndarray:
        """Resample signal to `num` samples using FFT-based method."""
        x = np.asarray(x, dtype=float)
        return np.real(np.fft.irfft(np.fft.rfft(x), n=num) * (num / len(x)))

    @staticmethod
    def snr(signal: np.ndarray, noise: np.ndarray) -> float:
        """Compute signal-to-noise ratio in dB."""
        signal = np.asarray(signal, dtype=float)
        noise = np.asarray(noise, dtype=float)
        p_signal = np.mean(signal ** 2)
        p_noise = np.mean(noise ** 2)
        if p_noise == 0:
            return float("inf")
        return 10 * np.log10(p_signal / p_noise)


