# 2. UNCERTAINTY PROPAGATION
# =============================================================================

class UFloat:
    """
    A scalar value with an associated standard uncertainty (error), supporting
    linear error propagation through arithmetic operations, assuming
    independent Gaussian errors unless correlation is explicitly tracked.
    """

    __slots__ = ("value", "std")

    def __init__(self, value: float, std: float = 0.0):
        self.value = float(value)
        self.std = float(abs(std))

    # -- Representation ------------------------------------------------
    def __repr__(self):
        return f"UFloat({self.value:.6g}, {self.std:.6g})"

    def __str__(self):
        return f"{self.value:.6g} \u00b1 {self.std:.6g}"

    # -- Helpers ---------------------------------------------------------
    @staticmethod
    def _coerce(other) -> "UFloat":
        if isinstance(other, UFloat):
            return other
        elif isinstance(other, numbers.Number):
            return UFloat(other, 0.0)
        else:
            raise TypeError(f"Cannot coerce {type(other)} to UFloat")

    # -- Arithmetic (assumes independence between operands) --------------
    def __add__(self, other):
        o = self._coerce(other)
        val = self.value + o.value
        std = math.hypot(self.std, o.std)
        return UFloat(val, std)

    __radd__ = __add__

    def __sub__(self, other):
        o = self._coerce(other)
        val = self.value - o.value
        std = math.hypot(self.std, o.std)
        return UFloat(val, std)

    def __rsub__(self, other):
        o = self._coerce(other)
        return o.__sub__(self)

    def __mul__(self, other):
        o = self._coerce(other)
        val = self.value * o.value
        # partial derivatives: d(val)/dx = o.value, d(val)/dy = self.value
        std = math.hypot(o.value * self.std, self.value * o.std)
        return UFloat(val, std)

    __rmul__ = __mul__

    def __truediv__(self, other):
        o = self._coerce(other)
        if o.value == 0:
            raise ZeroDivisionError("division by UFloat with zero value")
        val = self.value / o.value
        # d(val)/dx = 1/o.value, d(val)/dy = -self.value/o.value**2
        dstd_x = self.std / o.value
        dstd_y = self.value * o.std / (o.value ** 2)
        std = math.hypot(dstd_x, dstd_y)
        return UFloat(val, std)

    def __rtruediv__(self, other):
        o = self._coerce(other)
        return o.__truediv__(self)

    def __neg__(self):
        return UFloat(-self.value, self.std)

    def __pos__(self):
        return UFloat(self.value, self.std)

    def __abs__(self):
        return UFloat(abs(self.value), self.std)

    def __pow__(self, power):
        if isinstance(power, UFloat):
            # f = x^y ; general case
            x, y = self.value, power.value
            if x == 0 and y <= 0:
                raise ValueError("Cannot raise zero to non-positive power with uncertainty")
            val = x ** y
            df_dx = y * x ** (y - 1) if x != 0 else 0.0
            df_dy = val * math.log(x) if x > 0 else 0.0
            std = math.hypot(df_dx * self.std, df_dy * power.std)
            return UFloat(val, std)
        else:
            x = self.value
            y = float(power)
            val = x ** y
            df_dx = y * x ** (y - 1) if x != 0 else 0.0
            std = abs(df_dx) * self.std
            return UFloat(val, std)

    def __eq__(self, other):
        o = self._coerce(other)
        return self.value == o.value and self.std == o.std

    def __lt__(self, other):
        o = self._coerce(other)
        return self.value < o.value

    def __le__(self, other):
        o = self._coerce(other)
        return self.value <= o.value

    def __gt__(self, other):
        o = self._coerce(other)
        return self.value > o.value

    def __ge__(self, other):
        o = self._coerce(other)
        return self.value >= o.value

    def __float__(self):
        return self.value

    def __hash__(self):
        return hash((self.value, self.std))

    # -- Common math functions --------------------------------------------
    def sqrt(self) -> "UFloat":
        if self.value < 0:
            raise ValueError("sqrt of negative UFloat")
        val = math.sqrt(self.value)
        std = self.std / (2 * val) if val != 0 else 0.0
        return UFloat(val, std)

    def exp(self) -> "UFloat":
        val = math.exp(self.value)
        std = val * self.std
        return UFloat(val, std)

    def log(self) -> "UFloat":
        if self.value <= 0:
            raise ValueError("log of non-positive UFloat")
        val = math.log(self.value)
        std = self.std / self.value
        return UFloat(val, std)

    def sin(self) -> "UFloat":
        val = math.sin(self.value)
        std = abs(math.cos(self.value)) * self.std
        return UFloat(val, std)

    def cos(self) -> "UFloat":
        val = math.cos(self.value)
        std = abs(math.sin(self.value)) * self.std
        return UFloat(val, std)

    def tan(self) -> "UFloat":
        val = math.tan(self.value)
        std = abs(1 / math.cos(self.value) ** 2) * self.std
        return UFloat(val, std)


class UArray:
    """
    Array-valued version of UFloat, storing values and standard deviations
    as numpy arrays and supporting vectorized independent-error propagation.
    """

    def __init__(self, values: Union[Sequence[float], np.ndarray],
                 stds: Union[Sequence[float], np.ndarray, float] = 0.0):
        self.values = np.asarray(values, dtype=float)
        if np.isscalar(stds):
            self.stds = np.full_like(self.values, float(stds))
        else:
            self.stds = np.asarray(stds, dtype=float)
            if self.stds.shape != self.values.shape:
                raise ValueError("values and stds must have the same shape")

    def __repr__(self):
        return f"UArray(values={self.values}, stds={self.stds})"

    def __len__(self):
        return len(self.values)

    def __getitem__(self, idx):
        return UFloat(self.values[idx], self.stds[idx])

    @staticmethod
    def _coerce(other) -> "UArray":
        if isinstance(other, UArray):
            return other
        elif isinstance(other, UFloat):
            return UArray(np.array([other.value]), np.array([other.std]))
        elif isinstance(other, np.ndarray) or isinstance(other, numbers.Number) or isinstance(other, (list, tuple)):
            arr = np.asarray(other, dtype=float)
            return UArray(arr, np.zeros_like(arr))
        else:
            raise TypeError(f"Cannot coerce {type(other)} to UArray")

    def __add__(self, other):
        o = self._coerce(other)
        val = self.values + o.values
        std = np.hypot(self.stds, o.stds)
        return UArray(val, std)

    __radd__ = __add__

    def __sub__(self, other):
        o = self._coerce(other)
        val = self.values - o.values
        std = np.hypot(self.stds, o.stds)
        return UArray(val, std)

    def __rsub__(self, other):
        o = self._coerce(other)
        return o.__sub__(self)

    def __mul__(self, other):
        o = self._coerce(other)
        val = self.values * o.values
        std = np.hypot(o.values * self.stds, self.values * o.stds)
        return UArray(val, std)

    __rmul__ = __mul__

    def __truediv__(self, other):
        o = self._coerce(other)
        val = self.values / o.values
        dstd_x = self.stds / o.values
        dstd_y = self.values * o.stds / (o.values ** 2)
        std = np.hypot(dstd_x, dstd_y)
        return UArray(val, std)

    def __neg__(self):
        return UArray(-self.values, self.stds)

    def mean(self) -> UFloat:
        """Weighted mean assuming independent Gaussian errors."""
        n = len(self.values)
        std_of_mean = math.sqrt(np.sum(self.stds ** 2)) / n if n > 0 else 0.0
        return UFloat(np.mean(self.values), std_of_mean)

    def sum(self) -> UFloat:
        return UFloat(np.sum(self.values), math.sqrt(np.sum(self.stds ** 2)))

    def to_ufloats(self) -> list:
        return [UFloat(v, s) for v, s in zip(self.values, self.stds)]


def propagate(func, *args: UFloat, h: float = 1e-6) -> UFloat:
    """
    Generic numerical uncertainty propagation for an arbitrary scalar function
    of several UFloat arguments, using finite-difference partial derivatives
    (assumes independence between arguments).

    Parameters
    ----------
    func : callable
        Function taking len(args) plain floats and returning a float.
    args : UFloat
        Input values with uncertainty.
    h : float
        Relative step size for finite differences.

    Returns
    -------
    UFloat
        Result with propagated uncertainty.
    """
    values = [a.value for a in args]
    stds = [a.std for a in args]
    f0 = func(*values)

    variance = 0.0
    for i in range(len(args)):
        step = h * (abs(values[i]) if values[i] != 0 else 1.0)
        if step == 0:
            step = h
        params_plus = list(values)
        params_minus = list(values)
        params_plus[i] += step
        params_minus[i] -= step
        deriv = (func(*params_plus) - func(*params_minus)) / (2 * step)
        variance += (deriv * stds[i]) ** 2

    return UFloat(f0, math.sqrt(variance))


def covariance_propagate(func, values: Sequence[float], cov: np.ndarray,
                          h: float = 1e-6) -> UFloat:
    """
    Propagate uncertainty through `func` given a full covariance matrix
    of the inputs (handles correlated errors).

    Parameters
    ----------
    func : callable
        Function taking n floats, returning a float.
    values : sequence of float
        Central values of the n inputs.
    cov : np.ndarray, shape (n, n)
        Covariance matrix of the inputs.
    h : float
        Relative finite-difference step.

    Returns
    -------
    UFloat
    """
    values = list(values)
    n = len(values)
    cov = np.asarray(cov, dtype=float)
    if cov.shape != (n, n):
        raise ValueError("cov must be an n x n matrix matching len(values)")

    f0 = func(*values)
    grad = np.zeros(n)
    for i in range(n):
        step = h * (abs(values[i]) if values[i] != 0 else 1.0)
        if step == 0:
            step = h
        params_plus = list(values)
        params_minus = list(values)
        params_plus[i] += step
        params_minus[i] -= step
        grad[i] = (func(*params_plus) - func(*params_minus)) / (2 * step)

    variance = grad @ cov @ grad
    return UFloat(f0, math.sqrt(max(variance, 0.0)))


# =============================================================================
# 3. UNIT HANDLING
# =============================================================================

# Base SI dimensions: (length, mass, time, current, temperature, amount, luminous intensity)
_BASE_DIMS = ("m", "kg", "s", "A", "K", "mol", "cd")

Dimension = Tuple[float, float, float, float, float, float, float]


def _dim(**kwargs) -> Dimension:
    d = [0.0] * 7
    for k, v in kwargs.items():
        idx = _BASE_DIMS.index(k)
        d[idx] = v
    return tuple(d)


def _add_dims(a: Dimension, b: Dimension) -> Dimension:
    return tuple(x + y for x, y in zip(a, b))


def _sub_dims(a: Dimension, b: Dimension) -> Dimension:
    return tuple(x - y for x, y in zip(a, b))


def _scale_dims(a: Dimension, k: float) -> Dimension:
    return tuple(x * k for x in a)


# Registry of known units -> (dimension, factor_to_SI)
_UNIT_REGISTRY: Dict[str, Tuple[Dimension, float]] = {
    # dimensionless
    "": (_dim(), 1.0),
    "rad": (_dim(), 1.0),
    "dimensionless": (_dim(), 1.0),
    # length
    "m": (_dim(m=1), 1.0),
    "km": (_dim(m=1), 1e3),
    "cm": (_dim(m=1), 1e-2),
    "mm": (_dim(m=1), 1e-3),
    "um": (_dim(m=1), 1e-6),
    "nm": (_dim(m=1), 1e-9),
    "in": (_dim(m=1), 0.0254),
    "ft": (_dim(m=1), 0.3048),
    "mi": (_dim(m=1), 1609.344),
    # mass
    "kg": (_dim(kg=1), 1.0),
    "g": (_dim(kg=1), 1e-3),
    "mg": (_dim(kg=1), 1e-6),
    "lb": (_dim(kg=1), 0.45359237),
    # time
    "s": (_dim(s=1), 1.0),
    "ms": (_dim(s=1), 1e-3),
    "us": (_dim(s=1), 1e-6),
    "min": (_dim(s=1), 60.0),
    "h": (_dim(s=1), 3600.0),
    "day": (_dim(s=1), 86400.0),
    # current
    "A": (_dim(A=1), 1.0),
    "mA": (_dim(A=1), 1e-3),
    # temperature (only Kelvin-linear units are handled here; C/F need offsets)
    "K": (_dim(K=1), 1.0),
    # amount
    "mol": (_dim(mol=1), 1.0),
    # luminous intensity
    "cd": (_dim(cd=1), 1.0),
    # derived units
    "Hz": (_dim(s=-1), 1.0),
    "N": (_dim(kg=1, m=1, s=-2), 1.0),
    "Pa": (_dim(kg=1, m=-1, s=-2), 1.0),
    "J": (_dim(kg=1, m=2, s=-2), 1.0),
    "W": (_dim(kg=1, m=2, s=-3), 1.0),
    "V": (_dim(kg=1, m=2, s=-3, A=-1), 1.0),
    "C": (_dim(s=1, A=1), 1.0),
    "ohm": (_dim(kg=1, m=2, s=-3, A=-2), 1.0),
    "F": (_dim(kg=-1, m=-2, s=4, A=2), 1.0),
    "T": (_dim(kg=1, s=-2, A=-1), 1.0),
    "m/s": (_dim(m=1, s=-1), 1.0),
    "m/s^2": (_dim(m=1, s=-2), 1.0),
}


def _dim_str(d: Dimension) -> str:
    parts = []
    for name, exp in zip(_BASE_DIMS, d):
        if exp != 0:
            if exp == 1:
                parts.append(name)
            else:
                exp_str = f"{exp:g}"
                parts.append(f"{name}^{exp_str}")
    return " ".join(parts) if parts else "dimensionless"


class UnitError(Exception):
    """Raised on incompatible unit operations."""


@dataclass
class Quantity:
    """
    A physical quantity: a numeric value (scalar or numpy array) tagged with
    a physical dimension, stored internally in SI base units.
    """

    magnitude: Union[float, np.ndarray]
    dimension: Dimension = field(default_factory=_dim)
    _display_unit: Optional[str] = None  # preferred unit for display

    # -- Construction -----------------------------------------------------
    @classmethod
    def from_unit(cls, value: Union[float, np.ndarray, Sequence[float]], unit: str) -> "Quantity":
        """Create a Quantity from a value expressed in the given unit."""
        dim, factor = cls._resolve_unit(unit)
        mag = np.asarray(value, dtype=float) if not np.isscalar(value) else float(value)
        si_value = mag * factor
        return cls(si_value, dim, unit)

    @staticmethod
    def _resolve_unit(unit: str) -> Tuple[Dimension, float]:
        if unit in _UNIT_REGISTRY:
            return _UNIT_REGISTRY[unit]
        raise UnitError(f"Unknown unit: {unit!r}")

    @staticmethod
    def register_unit(name: str, dimension: Dimension, factor_to_si: float) -> None:
        """Register a custom unit in the global registry."""
        _UNIT_REGISTRY[name] = (dimension, factor_to_si)

    # -- Conversion ---------------------------------------------------------
    def to(self, unit: str) -> "Quantity":
        """Return a new Quantity expressed with `unit` as the display unit,
        verifying dimensional compatibility."""
        dim, factor = self._resolve_unit(unit)
        if dim != self.dimension:
            raise UnitError(
                f"Cannot convert quantity with dimension "
                f"[{_dim_str(self.dimension)}] to unit '{unit}' "
                f"with dimension [{_dim_str(dim)}]"
            )
        return Quantity(self.magnitude, self.dimension, unit)

    def value_in(self, unit: str) -> Union[float, np.ndarray]:
        """Return the numeric magnitude expressed in `unit`."""
        dim, factor = self._resolve_unit(unit)
        if dim != self.dimension:
            raise UnitError(
                f"Cannot express quantity with dimension "
                f"[{_dim_str(self.dimension)}] in unit '{unit}' "
                f"with dimension [{_dim_str(dim)}]"
            )
        return self.magnitude / factor

    # -- Representation -------------------------------------------------
    def __repr__(self):
        unit_label = self._display_unit if self._display_unit else _dim_str(self.dimension)
        if self._display_unit:
            try:
                val = self.value_in(self._display_unit)
            except UnitError:
                val = self.magnitude
        else:
            val = self.magnitude
        return f"Quantity({val}, '{unit_label}')"

    def __str__(self):
        return self.__repr__()

    # -- Arithmetic -----------------------------------------------------
    def _check_same_dim(self, other: "Quantity", op: str):
        if self.dimension != other.dimension:
            raise UnitError(
                f"Cannot {op} quantities with different dimensions: "
                f"[{_dim_str(self.dimension)}] vs [{_dim_str(other.dimension)}]"
            )

    def __add__(self, other):
        if not isinstance(other, Quantity):
            if self.dimension == _dim():
                other = Quantity(other, _dim())
            else:
                raise UnitError("Cannot add a plain number to a dimensioned Quantity")
        self._check_same_dim(other, "add")
        return Quantity(self.magnitude + other.magnitude, self.dimension, self._display_unit)

    __radd__ = __add__

    def __sub__(self, other):
        if not isinstance(other, Quantity):
            if self.dimension == _dim():
                other = Quantity(other, _dim())
            else:
                raise UnitError("Cannot subtract a plain number from a dimensioned Quantity")
        self._check_same_dim(other, "subtract")
        return Quantity(self.magnitude - other.magnitude, self.dimension, self._display_unit)

    def __rsub__(self, other):
        if not isinstance(other, Quantity):
            if self.dimension == _dim():
                other = Quantity(other, _dim())
            else:
                raise UnitError("Cannot subtract from a plain number using a dimensioned Quantity")
        other._check_same_dim(self, "subtract")
        return Quantity(other.magnitude - self.magnitude, self.dimension, self._display_unit)

    def __mul__(self, other):
        if isinstance(other, Quantity):
            return Quantity(self.magnitude * other.magnitude,
                             _add_dims(self.dimension, other.dimension))
        else:
            return Quantity(self.magnitude * other, self.dimension, self._display_unit)

    __rmul__ = __mul__

    def __truediv__(self, other):
        if isinstance(other, Quantity):
            return Quantity(self.magnitude / other.magnitude,
                             _sub_dims(self.dimension, other.dimension))
        else:
            return Quantity(self.magnitude / other, self.dimension, self._display_unit)

    def __rtruediv__(self, other):
        if isinstance(other, Quantity):
            return Quantity(other.magnitude / self.magnitude,
                             _sub_dims(other.dimension, self.dimension))
        else:
            return Quantity(other / self.magnitude, _scale_dims(self.dimension, -1))

    def __pow__(self, power: float):
        if not isinstance(power, numbers.Number):
            raise UnitError("Exponent must be a plain number")
        return Quantity(self.magnitude ** power, _scale_dims(self.dimension, power))

    def __neg__(self):
        return Quantity(-self.magnitude, self.dimension, self._display_unit)

    def __abs__(self):
        return Quantity(np.abs(self.magnitude) if isinstance(self.magnitude, np.ndarray)
                         else abs(self.magnitude), self.dimension, self._display_unit)

    def __eq__(self, other):
        if not isinstance(other, Quantity):
            return NotImplemented
        return self.dimension == other.dimension and np.all(self.magnitude == other.magnitude)

    def __lt__(self, other):
        self._check_same_dim(other, "compare")
        return self.magnitude < other.magnitude

    def __le__(self, other):
        self._check_same_dim(other, "compare")
        return self.magnitude <= other.magnitude

    def __gt__(self, other):
        self._check_same_dim(other, "compare")
        return self.magnitude > other.magnitude

    def __ge__(self, other):
        self._check_same_dim(other, "compare")
        return self.magnitude >= other.magnitude

    def sqrt(self) -> "Quantity":
        return self.__pow__(0.5)

    @property
    def is_dimensionless(self) -> bool:
        return self.dimension == _dim()


def convert(value: Union[float, np.ndarray], from_unit: str, to_unit: str) -> Union[float, np.ndarray]:
    """Convenience function to convert a plain numeric value between compatible units."""
    q = Quantity.from_unit(value, from_unit)
    return q.value_in(to_unit)


def units_compatible(unit_a: str, unit_b: str) -> bool:
    """Check whether two unit strings share the same physical dimension."""
    try:
        dim_a, _ = Quantity._resolve_unit(unit_a)
        dim_b, _ = Quantity._resolve_unit(unit_b)
    except UnitError:
        return False
    return dim_a == dim_b


# =============================================================================
# Module-level convenience exports
# =============================================================================

__all__ = [
    "SignalProcessing",
    "UFloat",
    "UArray",
    "propagate",
    "covariance_propagate",
    "Quantity",
    "UnitError",
    "convert",
    "units_compatible",
]
